  \begin{description}
  \item[\negphantom{1\&}1\&2] \namedlabel{pc-upd-labeling}{1\&2}
    Determine the edges of $T$ that are consistent with neither~$A$ nor~$L(T) \setminus A$; see \Cref{fig:pc-init,fig:pc-upd-steps}.
    If these edges do not form a path, the so-called \emph{terminal path}, then $T$ does not represent any cyclic order where~$A$ is consecutive, and we return the null-tree.

  \item[3] \namedlabel{pc-upd-reorder}{3}
    Reorder the edges around the nodes on the terminal path so that
    all subtrees that have all their leaves in $A$, which we will call \emph{full}, lie on one side and
    all subtrees with leaves in $L(T) \setminus A$, which we will call \emph{empty}, lie on the other side; see \Cref{fig:pc-upd-A}.
    If this is not possible, then this is due to a C-node around which edges consistent with~$A$ and edges consistent with $L(T) \setminus A$ alternate.
    It follows that $T$ does not represent a cyclic order where $A$ is consecutive, and we return the null-tree.

  \item[4] \namedlabel{pc-upd-split}{4}
    Split each P-node~$\mu$ on the terminal path twice, once to move all edges to full subtrees adjacent to $\mu$ to a new P-node~$\mu^F$
    and a second time to move all edges to empty subtrees to a new P-node~$\mu^E$.
    Add edges to the new nodes, making the remainder of $\mu$ adjacent to $\mu^F,\mu^E,$ and up to two edges of the terminal path; see \Cref{fig:pc-upd-B}.
    Convert this remaining part into a C-node $\mu^M$ and choose its embedding such that the two terminal edges are not adjacent to each other if it has degree 4,
    and flip it so that all full subtrees again lie on the same side of the terminal path.

  \item[\negphantom{5\&}5\&6] \namedlabel{pc-upd-contract}{5\&6}
    Contract all nodes of the terminal path (which are now all C-nodes) into a single, central C-node.
    Finally, smooth degree-2 vertices and remove degree-1 vertices that are not leaves of the original tree $T$; see \Cref{fig:pc-upd-C}.
  \end{description}

  Hsu and McConnell~\cite{hm-pta-03, hm-ptp-04} show that each of these steps can be implemented to run in time proportional to $|A|$ plus the length of the terminal path.
  This leads to amortized linear time in the size of the set $A$ as all terminal edges disappear through the update.

\item[\Intersect] Let~$T_1,T_2$ be two PC-trees with the same set of leaves.
  Then the operation {\Intersect} produces a new PC-tree $T$ with~$\Ord(T) = \Ord(T_1) \cap \Ord(T_2)$.
  Booth~\cite{boo-pta-75} describes a linear-time algorithm for computing the intersection of two PQ-trees; the same algorithm can be applied for PC-trees \cite{pfr-alt-20}.
  The general idea is to convert $T_1$ into a set of consecutivity constraints and to then update $T_2$ with these sets so that it represents only the orders that are represented by both trees.
  The key to achieve linear running time is to contract maximal subtrees that are already consecutive in both trees into single nodes.
\end{description}
\end{statelater}

\enlargethispage{1em}
  We will need the following well-known basic operations of PC-trees; see also \Cref{fig:pc-ops}.
  We only shortly define them here and give more in-depth explanations in \iftoggle{long}{\Cref{sec:pc-tree-details}}{the full version \cite{}}.
  We also point the interested reader to \cite{fpr-eco-21}, where PC-trees are described extensively in terms of pseudo-code and are also evaluated via a practical, open-source C++ implementation.

  \begin{description}
  \item[\Merge]
  Let~$T_1,T_2$ be two PC-trees with $|L(T_1)|, |L(T_2)|\geq2$ and $|L(T_1)| \cap |L(T_2)| = \ell$; see \Cref{fig:pc-split}.
  The {\Merge} of $T_1,T_2$, denoted as $\merge{T_1}{T_2}$, is the PC-tree $T$ with $\Ord(T) = \{ \sigma_1 \otimes_{\ell} \sigma_2 \mid \sigma_i \in \Ord(T_i)$ for $i\in\{1,2\}\}$
  obtained by identifying $\ell$ in $T_1, T_2$; see \Cref{fig:pc-merge}.

  \item[\Split]
  Let~$T$ be a PC-tree and let set~$A$ with $\emptyset \neq A \subsetneq L(T)$ be consecutive with respect to~$T$.
  The operation {\Split} separates $T$ into two new PC-trees $T'$ and~$T''$, with
  $\Ord(T') = \{ \sigma[A \to \ell] \mid \sigma \in \Ord(T)\}$ and
  $\Ord(T'') = \{ \sigma[A^c \to \ell] \mid \sigma \in \Ord(T)\}$, where $\ell\notin L(T)$ is a new leaf.
  Note that this may split a C-node $\mu\in T$ into two halves $\mu'\in T',\mu''\in T''$ as shown in \Cref{fig:pc-split}.
  We also write $\setto{T}{A}[\ell]$ for $T'$ and $\setto{T}{A^c}[\ell]$ for $T''$.

  \item[\Update]
  Let~$T$ be a PC-tree and let \emph{restriction} $A \subseteq L(T)$ be a set of leaves.
  The operation {\Update}, denoted as $\update{T}{A}$, produces a new PC-tree $T'$ with~$\Ord(T') = \{ \sigma \in \Ord(T) \mid A$ is consecutive in $\sigma\}$ in time linear in $|A|$ \cite{hm-pta-03,hm-ptp-04,fpr-eco-21}; see \Cref{fig:pc-update}.
  We call a restriction \emph{impossible} if there is no admissible order of $L$ where the leaves in $R$ are consecutive, i.e., $\update{T}{A}$ is the null-tree.

  \item[\Intersect]
  Let~$T_1,T_2$ be two PC-trees with the same leaf set, i.e., $L(T_1)=L(T_2)$.
  Operation {\Intersect} yields a new PC-tree $T$ with~$\Ord(T) = \Ord(T_1) \cap \Ord(T_2)$ in linear time~\cite{boo-pta-75,pfr-alt-20}.
  \end{description}


Note that, unlike for individual cyclic orders where splitting and merging are converse operations, the same does not always hold for PC-trees; see \Cref{fig:pc-merge} for an example.
Here, only certain orders $\sigma_1\in \Ord(T')$ and $\sigma_2\in \Ord(T'')$ can be merged to an admissible order of the original $T$.
We call such pair, that is where $\merge{\sigma_1}{\sigma_2}\in\Ord(T)$ holds, \emph{compatible}.
The following lemma shows that an incompatibility arises only from the two halves $\mu'\in T',\mu''\in T''$ a C-node $\mu\in T$ can be split into; see \Cref{fig:pc-split}.
See \iftoggle{long}{\Cref{sec:pc-tree-details}}{the full version \cite{}} for the full proof.

\begin{restatable}\restateref{lem:merge-splits}{lemma}{lemMergeSplits}
  \label{lem:merge-splits}
  Let set $A$ be consecutive in PC-tree $T$, let $T'=\setto{T}{A}$ and $T''=\setto{T}{A^c}$ and let $\sigma_1\in \Ord(T')$ and $\sigma_2\in \Ord(T'')$.
  If $E(T,A)$ is a single edge $e$, then $T=\merge{T'}{T''}$ and $\merge{\sigma_1}{\sigma_2}\in\Ord(T)$, that is any pair of $\sigma_1$ and $\sigma_2$ is compatible.
  Otherwise, $E(T,A)$ is a set of edges consecutive around a C-node $\mu$ of~$T$, and we have $T\neq\merge{T'}{T''}$ and $\Ord(T)\subsetneq\Ord(\merge{T'}{T''})$.
  In this case, $\sigma_1$ and $\sigma_2$ are compatible if and only if they induce the same flip of the split halves of $\mu$ in $T'$ and~$T''$.
  If $\sigma_1$ is not compatible with $\sigma_2$, it is instead compatible with $\overline{\sigma_2}$.
\end{restatable}
\begin{prooflater}{proofMergeSplits}
If $E(T,A)$ is a single edge $e$, tree $T$ is split by splitting $e$.
It can thus be reobtained by merging at $e$ again, that is $T=\merge{T'}{T''}$.
As the embeddings that~$\sigma_1$ and~$\sigma_2$ induce on~$T'$ and~$T''$, respectively, can also be joined at~$e$ to obtain an embedding of~$T$, we always have $\merge{\sigma_1}{\sigma_2}\in\Ord(T)$.


Otherwise, $E(T,A)$ is a set of edges consecutive around a C-node~$\mu$ of~$T$.
Splitting~$T$ into two trees $T', T''$ also splits~$\mu$ into two respective C-nodes $\mu',\mu''$, where~$\mu''$ is incident to the edges in $E(T,A)$ plus~$\ell$ and~$\mu'$ gets the remaining edges of~$\mu$ plus another copy of~$\ell$; see \Cref{fig:pc-merge}.
Merging $T'$ and $T''$ now does not yield $T$ again, as $\mu'$ and $\mu''$ are still separate C-nodes connected by the edge $\ell$ in $T^*=\merge{T'}{T''}$.
We have $\Ord(T^*)\supsetneq\Ord(T)$ as $\mu'$ and $\mu''$ can be flipped independently and thus in total allow four different orders for their incident edges in $T^*$, while $\mu$ in $T$ only allows two.
The embeddings $\sigma_1$ and $\sigma_2$ induce on $T'$ and $T''$ can thus only be merged to an embedding of $T$
if the rotations of $\mu'$ and $\mu''$ they induce can be merged to form an admissible rotation of $\mu$.
As the C-nodes have two admissible embeddings, either~$\sigma_1$ and $\sigma_2$ are compatible or $\sigma_1$ and $\overline{\sigma_2}$ are compatible.
\end{prooflater}


\section{Partially Embedded Planarity}\label{sec:partial}\label{sec:peplan}
\enlargethispage{1em}
Recall that for \peplan, we are given an instance $(G,H,\mathcal H)$ where $G$ is a graph with subgraph $H$ and $\mathcal H$ is an embedding of $H$.
We seek a planar embedding~$\mathcal G$ of $G$ whose restriction to~$H$ coincides with~$\mathcal H$.
In their solution, Angelini et al.~\cite[Lemma 3.9]{abf-tpo-15} ensure this condition by enforcing that
(i) around each vertex~$v$ of $H$ the cyclic order of the edges of $H$ is the same in~$\mathcal G$ and in~$\mathcal H$ and
(ii) for each (directed) facial cycle of~$\mathcal H$, the vertices of $H$ that are embedded left and right of it coincide in~$\mathcal G$ and in~$\mathcal H$.
It is the second condition, also referred to as having correct \emph{relative positions}, that is relatively complicated to handle efficiently.
We will show how to do this in the remainder of this section, which is organized as follows.
In \Cref{sec:cc-verts}, we show how the condition of having correct relative positions can be translated to color-coded constraints on the order of edges incident to individual vertices.
\Cref{sec:cc-pc} shows how such constraints can be represented using augmented PC-trees and how to update such PC-trees with new consecutivity restrictions.
In \Cref{sec:peplan-bicon}, we describe how substituting our augmented PC-trees in the Booth-Lueker planarity test for biconnected graphs can be used to test \peplan.
\Cref{sec:peplan-nonbic} lifts the biconnectivity requirement using the Haeupler-Tarjan generalization of the Booth-Lueker test to not-necessarily biconnected graphs.


\subsection{Color-Constrained Vertices}\label{sec:cc-verts}
Observe that, if $G$ is connected, the embedding of~$G$ and also the induced relative positioning of the connected components of $H$ can be expressed solely in terms of the rotation system of~$G$.
Angelini et al.~\cite[Theorem 4.14]{abf-tpo-15} give a straight-forward linear-time reduction from the case of a non-connected $G$ to solving the components of $G$ independently.
We can thus for now limit our attention to the case where~$G$ is connected.

\begin{figure}[t]
  \centering
  \includegraphics[page=3]{fig/bridges}
  \caption{
    A positive instance of \peplan. The graph $H$ is shown with black edges.
    The graph $G-H$ is divided into 5 bridges $A,B,C,D$ and $E$.
    Bridges $B$ and $C$ have all their attachments in a single block and are thus not restricted to a face.
    Bridges $A, D,$ and $E$ have attachments in different blocks and are thus restricted to a face.
    Adding the dashed edge to $H$ as shown would turn the instance negative, as the attachments of $E$ would no longer share a face.
  }
  \label{fig:peplan-bridges}
\end{figure}

Now consider two distinct connected components $C_1, C_2$ of $H$ connected by a path $p$ whose inner vertices belong to $V(G)\setminus V(H)$.
The fact that~$p$ does not contain vertices of $H$ except for its endpoints already ensures that $C_1, C_2$ are embedded on the same side of any facial cycle of any other component of $\mathcal H$.
It remains to ensure that $C_2$ is embedded in the correct face of~$C_1$ and vice versa.
Thanks to the connectivity of $G$, ensuring this for each pair $C_1, C_2$ of components of $H$ connected by such a path $p$ is sufficient to ensure correct relative positions.
Note that not only $p$ has to be in a certain face of~$\mathcal H$, but this also applies to the whole connected component of $G - V(H)$ that contains $p$, which we call an $H$-bridge.
Formally, an \emph{$H$-bridge} $B$ is either a single edge $e \in E(G)\setminus E(H)$ with both end-vertices in $H$ or a connected component $B$ of $G - V(H)$; see \Cref{fig:peplan-bridges}.
The \emph{attachments} of a component $B$ are the vertices of $H$ whose removal disconnects $B$ from the remaining graph or, in the case of a single edge $B$, its endpoints.
Note that each $H$-bridge of $G$ has to lie in exactly one face of $\mathcal H$ as it contains no vertices of $H$.
If an $H$-bridge $B$ has attachments in at least two distinct blocks of $H$, then that face is uniquely determined; see \cite[Section 2.3]{abf-tpo-15} and \Cref{fig:peplan-bridges}.
Thus, we can color each edge $e\in E(G)\setminus E(H)$ with the unique face $f(e)$ of $\mathcal H$ in which $e$ must be embedded, or $e$ is uncolored as this face is arbitrary and we set $f(e)=\bot$.
Angelini et al.\ give a simple linear-time algorithm computing this coloring \cite[Lemma 2.2]{abf-tpo-15}.
To ensure correct relative positions, we now need to ensure that, at every vertex, all edges to incident $H$-bridges are embedded in the correct face of $\mathcal H$.
Furthermore, we need to respect the cyclic order of incident edges of $H$ as given in $\mathcal H$, where each angle between two consecutive edges corresponds to a face of $\mathcal H$.
We will express both requirements as constraints on vertex~rotations.

\enlargethispage{1em}
Let~$v$ be a vertex of~$G$.
A \emph{color-constraint}~$C_v=(F_v,R_v,U_v,\rho_v,f)$ for~$v$ partitions the edges incident to $v$ into a set~$F_v=E(v)\cap E(H)$ of \emph{fixed edges}, a set~$R_v=\{ e\in E(v)\setminus E(H) \mid f(e) \neq \bot \}$ of \emph{restricted edges}, and a set~$U_v=\{ e\in E(v)\setminus E(H) \mid f(e) = \bot \}$ of \emph{unrestricted edges}; see \Cref{fig:color-constraint}.
The fixed edges have a fixed counter-clockwise order~$\rho_v=\mathcal H(v)$, in which we want to insert the remaining edges to find a rotation for $v$.
We additionally constrain where the restricted edges can be inserted.
For each fixed edge $h$, $\mathcal H$ defines a face $f_v(h)$ which is incident to $h$ in counter-clockwise direction around $v$.
We call a pair of fixed edges~$(h_1,h_2)$ that are consecutive in~$\rho_v$ an \emph{angle}; see \Cref{fig:color-constraint}. A \emph{valid cyclic order}~$\sigma$ (i.e., one that \emph{satisfies} $C_v$) of the edges incident to~$v$ is obtained by arbitrarily inserting the restricted and unrestricted edges of~$v$ into~$\rho_v$ in such a way that, for each restricted edge~$e$ with (in counter-clockwise order) preceding fixed edge $h$, $f(e) = f_v(h)$ holds.
If $F_v=\emptyset$, any order of $R_v\cup U_v$ is valid.
\Cref{fig:color-constraint} shows an example color-constraint, where the restricted edge $e$ with label 5 and the fixed edge $h$ with label~4 have $f(e) = f_v(h)$, represented through purple color.
Observe that any planar embedding that satisfies all color-constraints satisfies both conditions~(i) and~(ii) from the beginning of this section, therefore yielding a solution to our problem.
Note that while we derive the color-constraint $C_v$ from $\mathcal H$, its definition does not rely on $\mathcal H$ as we can interpret $f$ as a coloring with arbitrary, opaque values.
\enlargethispage{1em}

