Then, the exact magnetic field model $B(r)$ [T] \cite{schweighart2006electromagnetic, tajima2023study} using the well-known Biot-Savart law is
\begin{equation}
    \label{exact_magnetic_field}
B(r)=\frac{\mu_0 c}{4 \pi} \oint \frac{{\mathrm{d}l} \times \hat{r}}{|\vec{r}|^2}\in\mathbb{R}^3.
\end{equation}
where the magnetic permeability $\mu_0$, the coil element $\mathrm{d}l\in\mathbb{R}^3$, and the distance between coil elements $r\in\mathbb{R}^3$. Then, the electromagnetic force and torque experienced by the $b$th 1-axis coil due to the magnetic field generated by the $a$th 1-axis coil is
\begin{equation}
    \label{near_field_interaction_model}
\begin{aligned}
f^{\mathrm{coil}}_{b\leftarrow a}&=\frac{\mu_0 \mu_{a0}\mu_{b0}}{4 \pi A^2} \oint\left[\oint \frac{\mathsf{e}_{r_{ab}} \times {\mathrm{d}l}_a}{\|r_{ab}\|^2}\right] \times {\mathrm{d}l}_b\\
\tau^{\mathrm{coil}}_{b\leftarrow a}&=\frac{\mu_0 \mu_{a0}\mu_{b0}}{4 \pi A^2} \oint R_b \times\left[\oint \frac{\mathsf{e}_{r_{ab}} \times {\mathrm{d}l}_a}{\|r_{ab}\|^2}\right] \times {\mathrm{d}l}_b.
\end{aligned}
\end{equation}
where $\mathsf{e}_{r_{ab}}$ is unit vector along with $r_{ab}$.
