\section{Learning-based Coil Geometry Approximation}
\label{Learning_based_Coil_Specific_Geometry_Approximation}
This section designs an approximate exact magnetic field model using a multilayer perceptron (MLP) model that captures coil-specific geometric features and calculates in real-time during the control. The $j$-th electromagnetic force and torque due to the magnetic field generated by the $k$th satellite is in Eq.~(\ref{jth_force_torque}) and this includes the circulant integration term in Eq.~(\ref{circulant_integration_term}). This integration term consists of the relative position, relative attitude, and coil geometry. Since an obvious drawback is a heavy computational load, we approximate these coil-specific geometry terms using a multi-layer perceptron (MLP). 

We first mention the sampling input and label data for the $j,k$th satellites. For the $k$th satellite, let $C^{A/B_k}(\sigma_k)$ be defined as the coordinate transformation matrix from $k$th body-fixed frame into the arbitrary reference frame and this is derived by arbitrary attitude parameter $\sigma_k$. We define $\bm n_{k(x,y,z)}$ as the unit vectors along with $x,y,z$ axes such that
\begin{equation*}
{^a}n_{k_{x}},{^a}n_{k_{y}},{^a}n_{k_{z}}\triangleq\left\{C^{A/B_k}(\sigma_k)=
\begin{bmatrix}
    {^a}n_{k_{x}}&{^a}n_{k_{y}}&{^a}n_{k_{z}}
\end{bmatrix}\right\}
\end{equation*}
Our goal is to reduce the input sample space by deriving a two coordinate transformation matrix such that 1) one coil lies within the $x–y$ plane and 2) the other coil lies within the $x–z$ plane, as illustrated in Figure \ref{fig:circulant_integration} (b). Then, we fisrt define three type coordinate frame $B_{k(x,y,z)}$ such that each $n_{k(x,y,z)}$ corresponds to its z-axis and its transformation matrixes $C^{A/B_{k(x,y,z)}}\in\mathbb{R}^{3\times 3}$ is defined as 
\begin{equation}
\label{Bjxyz2A}
C^{A/B_{k_{(z,x,y)}}}\triangleq
\begin{bmatrix}
    {^a}n_{k_{(x,y,z)}}&{^a}n_{k_{(y,z,x)}}&{^a}n_{k_{(z,x,y)}}
\end{bmatrix}
\end{equation}
where $C^{A/B_k}(\sigma_k)=C^{A/B_{k_{z}}}$. This achieves the first goal, and the following transformation achieves the second goal:
\begin{equation}
\label{Bjxyz2D}
\begin{aligned}
C^{D_{j\leftarrow k_{w}}/B_{k_{w}}}&\triangleq
\begin{bmatrix}
\cos_{\theta_0}&\sin_{\theta_0}&0\\
-\sin_{\theta_0}&\cos_{\theta_0}&0\\
0&0&\mathrm{sgn}({^{b_{k_{w}}}}r_{j\leftarrow k(z)})
\end{bmatrix}\\
\theta_0=\theta_{b_{k_{w}}}&\triangleq \tan^{-1}\left({^{b_{k_{w}}}}r_{j\leftarrow k(y)},{^{b_{k_{w}}}}r_{j\leftarrow k(x)}\right)
\end{aligned}
\end{equation}
These two coordinate transformation defines $C^{D_{j\leftarrow k_{w}}/A}=C^{D_{j\leftarrow k_{w}}/B_{k_{w}}}C^{B_{k_{w}}/A}$ for $w=(x,y,z)$:
$$
\begin{aligned}
\begin{bmatrix}
    {^{d}}r_{j\leftarrow k}&{^{d}}n_{j_w}
\end{bmatrix}&=C^{D_{j\leftarrow k_{w}}/A}
\begin{bmatrix}
   {^a}r_{j\leftarrow k}& {^a}n_{j_w} 
\end{bmatrix}\\
\begin{bmatrix}
{^{d}}{I}_{j_{w}\leftarrow k_w}&{^{d}}{J}_{j_{w}\leftarrow k_w}
\end{bmatrix}
&=C^{D_{j\leftarrow k_{w}}/A}
\begin{bmatrix}
    {^{a}}{I}_{j_{w}\leftarrow k_w}&{^{a}}{I}_{j_{w}\leftarrow k_w}
\end{bmatrix}%\left[\right],\  %\int_{\theta=0}^{\theta=2 \pi}\left[\int_{\varphi=0}^{\varphi=2 \pi} \frac{\mathsf{e}_{{r}_{j\leftarrow k}} \times {\mathrm{d}l}_{k_{w}}}{\|r_{j\leftarrow k}\|^2}\right] \times {\mathrm{d}l}_{j_{w}}\\
%=C^{D_{j\leftarrow k_{w}}/A}\left[\right]\\% \int_{\theta=0}^{\theta=2 \pi} R_{j_{w}} \times\left[\int_{\varphi=0}^{\varphi=2 \pi} \frac{\mathsf{e}_{{r}_{j\leftarrow k}}\times {\mathrm{d}l}_{k_{w}}}{\|r_{j\leftarrow k}\|^2}\right] \times {\mathrm{d}l}_{j_{w}}.
\begin{comment}
&\left\{
\begin{aligned}
C^{D_{j\leftarrow k_{x}}/A}=&C^{D_{j\leftarrow k_{x}}/B_{k_{x}}}C^{B_{k_{x}}/A}\\
C^{D_{j\leftarrow k_{y}}/A}=&C^{D_{j\leftarrow k_{y}}/B_{k_{y}}}C^{B_{k_{y}}/A}\\
C^{D_{j\leftarrow k_{z}}/A}=&C^{D_{j\leftarrow k_{z}}/B_{k_{z}}}C^{B_{k_{z}}/A}
\end{aligned}
\right.
\end{comment}
\end{aligned}
$$
Note that coordinate transfomrtion $C^{D_{j\leftarrow k_{w}}/B_{k_{w}}}$ imposes ${^{d_{k_{w}}}}r_{j\leftarrow k(1)}=0$ and, thus, we reduce this component for input data as ${^{d_{k_{w}}}}\hat{r}_{j\leftarrow k}=
[{^{d_{k_{w}}}}r_{j\leftarrow k(1)};
{^{d_{k_{w}}}}r_{j\leftarrow k(3)}]$. The spherical coordinate system using azimuth $\phi_{(1)}\in[-\pi,\pi]$ and elevation $\phi_{(2)}\in[0,\pi]$ reduces the 3-dimentinal information into $\phi\in\mathbb{R}^2$ such that
$$
\phi\triangleq 
\begin{bmatrix}
\tan^{-1}({^{d}}n_{j_w(2)},{^{d}}n_{j_w(1)})\\
\cos^{-1}({^{d}}n_{j_w(3)})\\
\end{bmatrix}
=\left\{\phi\left|{^{d}}n_{j_w}\triangleq
\begin{bmatrix}
c_{\phi_{(1)}}s_{\phi_{(2)}}\\
s_{\phi_{(1)}}s_{\phi_{(2)}}\\
c_{\phi_{(2)}}
\end{bmatrix}
\right\}\right.
$$
As a result, our sampling datas $X=[\boldsymbol{r},\boldsymbol{\phi}]\in\mathbb{R}^{N_s\times 4}$ and $Y\in\mathbb{R}^{N_s\times 6}$ are stuck as follows:
$$
\boldsymbol{r}=
\begin{bmatrix}
{^{d}}\hat{r}_{j\leftarrow k}^{(1)\top}\\
\vdots \\
{^{d}}\hat{r}_{j\leftarrow k}^{(N_s)\top}
\end{bmatrix}
,\boldsymbol{\phi}=
\begin{bmatrix}
\phi^{(1)\top}\\
\vdots \\
\phi^{(N_s)\top}
\end{bmatrix}
,\boldsymbol{Y}=
\begin{bmatrix}
\left[{^{d}}I_{j_z\leftarrow k_z}^{(1)\top}, {^{d}}J_{j_z\leftarrow k_z}^{(1)\top}\right]\\
\vdots \\
\left[{^{d}}I_{j_z\leftarrow k_z}^{(N_s)\top}, {^{d}}J_{j_z\leftarrow k_z}^{(N_s)\top}\right]
\end{bmatrix}
$$
where $N_s$ is the number of samples. Our MLP represents the functional mapping from given inputs $x$ into some outputs $\mathcal{Y}^{(j)}_{(\bm{X}, \bm{\theta})}$ such as a ($L$+1)-layer neural network and we train to minimize arbitrary loss function $f(\cdot)$:
\begin{equation}
    \label{MLP_near_field}
\begin{aligned}
\theta_{w}^*,\theta_{b}^*&= \mathrm{argmin}\sum_{j=1}^{N_s}f\left(\left\|\bm{Y}^{(j)\top}-\mathcal{C}^{\top}{(X^{(j)},\bm\theta)}\right\|\right)\\
\mathcal{C}{(\bm{X}^{(j)}, \bm{\theta})}&= W^{L+1}\phi(\cdots\phi(W^1 X^{(j)}+b^1)\cdots)+b^{L+1}\\
\end{aligned}
\end{equation}
where the activation function $\phi(\cdot)$ and the MLP paramters $\theta$ include the MLP weights $\theta_w = W^1,\ldots, W^{L+1}$ and the MLP bias $\theta_b = b^1,\ldots, b^{L+1}$, and $\mathcal{C}{(\bm{X}^{(j)}, \bm{\theta})}$ is a estimated value. 

We can generalize these coil geometry learning results, i.e., . The pseudocode for offline training and online inference is presented in Algorithm~\ref{pseudocode_of_coil_geometry_learning}.
\begin{corollary}
Let $\mathcal{C}{(\bm{X}, \bm{\theta})}$ be a function mapping in Eq.~(\ref{MLP_near_field}) for given coil radius $R_{[1]}$ using a training data set $\mathcal{T}_{R_{[1]}}=\{(X_{[1]}^{(i)}=[r_{[1]}^{(i)},\phi^{(i)}],Y_{[1]}^{(i)}(X_{[1]}^{(i)}))\}_{i=1}^N$ sampled in sample region of given compact set $\mathcal{S}_{R^{[1]}}$:
$$
\mathcal{S}_{R_{[1]}}=\left\{
\begin{aligned}
r_{[1]}&\in\mathbb{R}^2\\    
\phi&\in\mathbb{R}^2
\end{aligned}
\left|2R_{[1]}<\underline{r} \leq \|r_{[1]}\|\leq \overline{r},\ 
\begin{aligned}
&\phi_{(1)}\in[-\pi,\pi]\\ 
&\phi_{(2)}\in[0,\pi]
\end{aligned}
\right\}\right..
$$
Consider the coil whose radius is $R_{[2]}$ and and the new data
$$
R_{[2]}\triangleq \gamma R_{[1]},\ \left\{{X}_{[2]}^{(i)}=[r_{[2]}^{(i)},\phi^{(i)}],Y_{[2]}^{(i)}\left(X_{[2]}^{(i)}\right)\right\}_{i=1}^N
$$
in sample region of given compact set $\mathcal{S}_{R_{[2]}}$ that bounded by constants of $\mathcal{S}_{R_{[1]}}$:
$$
\mathcal{S}_{R_{[2]}}=\left\{
\begin{aligned}
r_{[2]}&\in\mathbb{R}^2\\    
\phi&\in\mathbb{R}^2
\end{aligned}
\left|
2R_{[1]}<\underline{r} \leq \frac{\|r_{[2]}\|}{\gamma}\leq \overline{r},\ 
\begin{aligned}
&\phi_{(1)}\in[-\pi,\pi]\\ 
&\phi_{(2)}\in[0,\pi]
\end{aligned}
\right\}\right..
$$
Then, $\mathcal{C}{(\bm{X}^{[1]}, \bm{\theta})}$ for $R_{[1]}$ coil can be applied to obtain the coil geometry information of $R_{[2]}$ in Eq.~(\ref{circulant_integration_term}) as
\begin{equation}
\label{mutual_relationship}
%\mathcal{C}_{(R^{[2]},\bm{r}^{[2]},\bm{\phi}^{[2]}, \bm{\theta}^{[2]})}
Y_{[2]}^{(i)}\left(X_{[2]}^{(i)}\right)= \begin{bmatrix}
 \bm{I}_{[2]j\leftarrow k}\\
 \bm{J}_{[2]j\leftarrow k}
\end{bmatrix}
=\mathcal{C}{\left(\bm{r}^{(i)}_{[2]}/\gamma,\bm{\phi}^{(i)}_{[2]}, \bm{\theta}\right)}
\begin{bmatrix}
    I&O\\
    O&\gamma I
\end{bmatrix}
\end{equation}
where $\mathcal{C}{(\bm{X}, \bm{\theta})} = \mathcal{C}{\left([\bm{r},\bm{\phi}], \bm{\theta}\right)}$.
\end{corollary}
\begin{comment}
\begin{equation*}
\begin{bmatrix}
