\end{bmatrix}=\mathcal{C}{\left([\bm{r},\bm{\phi}], \bm{\theta}\right)}
\end{equation*}    
\end{comment}
\begin{proof}
For given $R_{[1]}$ and $R_{[2]}$, recall and redefine $r_{[k]ij}$, $R_{[k]i(\varphi)}$, and ${d l}_{{[k]}{i}(\varphi)}=(\mathrm{d} {{R}}_{{{[k]}i}(\varphi)}/{\mathrm{d} \varphi})\mathrm{d} \varphi$ in Eq.~(\ref{near_field_interaction_model}) for $k=1,2$. Then, we concludes Eq.~(\ref{mutual_relationship}) by
$$
%\left\{
