%\int_{\theta=0}^{\theta=2 \pi}\left[\int_{\varphi=0}^{\varphi=2 \pi} \frac{\mathsf{e}_{{r}_{j\leftarrow k}} \times {\mathrm{d}l}_{[2]k}}{\|r_{[2]j\leftarrow k}\|^2}\right] \times {\mathrm{d}l}_{[2]j}\\
\int_{\theta=0}^{\theta=2 \pi}\left[\int_{\varphi=0}^{\varphi=2 \pi} \frac{\mathsf{e}_{{r}_{j\leftarrow k}} \times {\mathrm{d}l}_{[1]k}}{\|r_{[2]j\leftarrow k}/\gamma\|^2}\right] \times {\mathrm{d}l}_{[1]j}\\
\end{aligned}
$$
$$
\begin{aligned}
&\bm{J}_{[2]j\leftarrow k}
%=\int_{\theta=0}^{\theta=2 \pi} R_{[2]j} \times\left[\int_{\varphi=0}^{\varphi=2 \pi} \frac{\mathsf{e}_{{r}_{j\leftarrow k}}\times {\mathrm{d}l}_{[2]k}}{\|r_{[2]j\leftarrow k}\|^2}\right] \times {\mathrm{d}l}_{[2]j}\\
=\int_{\theta=0}^{\theta=2 \pi}\frac{R_{[1]j} }{\gamma} \times\left[\int_{\varphi=0}^{\varphi=2 \pi} \frac{\mathsf{e}_{{r}_{j\leftarrow k}}\times {\mathrm{d}l}_{[1]k}}{\|r_{[2]j\leftarrow k}/\gamma\|^2}\right] \times {\mathrm{d}l}_{[1]j}
