\paragraph{Petri nets} Petri nets can be used to represent, validate, and verify workflow processes to provide insights into how a process behaves~\cite{peterson1981petri}. Process activities are described by labels from alphabet $\Sigma$. Invisible, silent activities are shown with $\tau$-labels. We define $\Sigma^\tau$ as $\Sigma \cup \{\tau\}$.

\begin{definition}{(Labeled Petri net)}\label{def:petri_net}
    A \emph{labeled Petri net}~\cite{murata1989petri} is a tuple $N = (P, T, \F, \ell)$, with sets of places and transitions $P$ and $T$, respectively, such that $P \cap T = \emptyset$, and a multiset of arcs $\F: (P \times T) \cup (T \times P) \rightarrow \Nat$ defining the flow of the net. $\ell: T \rightarrow \Sigma^\tau$  is a \emph{labeling} function, assigning  a label $\ell(t)$ to a transition $t$.

    Given an element $x \in P \cup T$, its \emph{pre- and post-set}, $\pre{x}$ and $\post{x}$, are sets defined by $\pre{x} = \sset{y \in P \cup T \mid \F((y, x)) \geq 1}$ and $\post{x} = \sset{y \in P \cup T \mid \F((x, y)) \geq 1}$ respectively.
\end{definition}

\begin{definition}{(Marking, Enabling and firing of transitions, Reachable markings)}\label{def:marking}
A \emph{marking} $m \in P^\oplus$ of a labeled Petri net $N = (P, T, \F, \ell)$ defines the state of $N$ by assigning a number of tokens to each place.

A transition $t \in T$ is \emph{enabled} for firing in a marking $m$ of net $N$ iff $m \geq \pre{t}$. We denote the \emph{firing} of $t$ in marking $m$  by $m \xrightarrow{t} m'$, where $m'$ is the resulting marking after firing $t$ defined as $m' = m - \pre{t} + \post{t}$. For a transition sequence $\sigma = \seq{t_1,\dots,t_n}$ we write $m \xrightarrow{\sigma} m'$ to denote the consecutive firing of $t_1,\ldots,t_n$. We say that $m'$ is reachable from $m$ and write $m \xrightarrow{*} m'$ if there is some $\sigma \in T^*$ such that $m \xrightarrow{\sigma} m'$.

$\M(N)=P^\oplus$ denotes the set of all markings in net $N$, while $\R(N,m)$ denotes the \emph{set of  markings reachable} in net $N$ from marking $m$.
\end{definition}
