At this stage, we are equipped to present our optimization problem along with the complete control strategy for the CAVs, which is defined in Algorithm~1. Following this, we prove that our proposed control policy is always feasible.
\\
\textbf{Problem 1:} At each time, each CAV $i$ applies the control action
that satisfies,
\begin{align}\label{Time_optimal}
 \underset{u_i}{\min}& \quad \bigg(\phi(v_i^d-v_i)-u_i)\bigg)^2  \nonumber\\
\text{subject to}& \nonumber\\ \nonumber
\text{control bounds:}&\;\eqref{eq:contro_bounds},\nonumber\\
\text{speed constraints:}&\;\eqref{speed_CBF_1},\;\eqref{speed_CBF_2}, \nonumber\\ 
\text{rear-end constraints:}&\;\eqref{CBF_rear_end},\nonumber\\ 
\text{crossing time constraints:}&\;\eqref{boundary1},\;\eqref{boundary2}, \nonumber \\
\text{given:}&\; [\underline{t}_i^k, \overline{t}_i^k], v_i^d, \phi. \nonumber 
\end{align}


%\textcolor{red}{See really carefully the following result!}
\begin{theorem}[Solution existence]   \label{thm:feasibility}
%Let Algorithm 1 be executed in every time step along the trajectory of a CAV. Consider that if there exists a preceding HDV, it cannot decelerate faster than $-u_{\max}$.\label{as:hdv}
%Then for every CAV~$i$ and for all $t\in[t_i^0,t_i^\mathrm f]$ the admissible-control set
For a large value of $\kappa_s$ in the speed barrier conditions \eqref{speed_CBF_1}, \eqref{speed_CBF_2},
the set of control inputs,
\[
\mathcal{U}_i(t)\; :=\;
      \underbrace{[-u_{\max},u_{\max}]}_{\mathcal{U}_{\text{ctrl}}}
      \cap\
      \underbrace{\mathcal{U}_{\mathrm{speed}}}_{\text{\eqref{speed_CBF_1}--\eqref{speed_CBF_2}}}
      \cap\
      \underbrace{\mathcal{U}_{\mathrm{rear}}(t)}_{\text{\eqref{CBF_rear_end}}}
      \cap\
      \underbrace{\mathcal{U}_{\mathrm{cross}}(t)}_{\text{\eqref{boundary1},\eqref{boundary2}}}
\]
is a non-empty interval; consequently a solution to Problem 1, and the control action $u_i$, always exists.
\end{theorem}

\begin{proof}
We prove existence by computing the set intersections from left to right.
\paragraph{Control bounds}
By \eqref{eq:contro_bounds}, $\mathcal U_{\mathrm{ctrl}}=[-u_{\max},u_{\max}]$ is a non-empty interval by definition.

\paragraph{Speed limits}
For large values of $\kappa_s$, the speed barrier conditions \eqref{speed_CBF_1}–\eqref{speed_CBF_2} approximate a step function with the feasible space,
\[
\mathcal U_{\mathrm{ctrl}}\cap\mathcal U_{\mathrm{speed}}=
\begin{cases}
[-u_{\max},0], & v_i=v_{\max},\\[2pt]
[0,u_{\max}], & v_i=0,\\[2pt]
[-u_{\max},u_{\max}], & \text{else},
\end{cases}
\]
which is always non-empty because $0\in[-u_{\max},u_{\max}]$.


\paragraph{Rear-end safety}
The rear-end safety barrier condition \eqref{CBF_rear_end} imposes an upper bound $u_{rear} \geq -u_{\max}$ by design of \eqref{CBF_rear_end}.
When $v_i = 0$, by construction $u_{rear} \geq 0$ x, which implies,
\begin{equation*}
    \mathcal U_{\mathrm{ctrl}}\cap\mathcal U_{\mathrm{speed}}
      \cap\mathcal U_{\mathrm{rear}}(t)
      =[0,\,\min\{0,u_{\mathrm{rear}}\}]=\{0\}.
\end{equation*}
When $v_i \geq 0$,
\begin{equation}
    \mathcal U_{\mathrm{ctrl}}\cap\mathcal U_{\mathrm{speed}}      \cap\mathcal U_{\mathrm{rear}}(t)
      =[-u_{\max},\,\min\{0,u_{\mathrm{rear}}\}],
\end{equation}
which is a non-empty interval.

\paragraph{Crossing-time window} %\textcolor{red}{Not extrmely confident here if the extreme case is enough}
%We continue with the extreme case where the CAV follows the speed limit.
The crossing time barrier conditions \eqref{boundary1}, \eqref{boundary2} yield a non-empty interval
\begin{equation}
\mathcal{U}_{\mathrm{cross}}(t)=
      [\underline u_{\mathrm{cross}}(t),\overline u_{\mathrm{cross}}(t)].
\end{equation}
The overall feasible set can only become infeasible in two cases.
First, if
\begin{align} \label{eq:cond-1}
    \underline{u}_{\mathrm{cross}}(t) > \min\{0, u_{rear}(t)\},
\end{align}
we select a later crossing interval, which always exists under Assumption 4.
That is, we decrease $\Delta t_{i,1}$, and therefore $\underline{u}_{\mathrm{cross}}(t)$, until \eqref{eq:cond-1} no longer holds.
Second, if
\begin{align} \label{eq:cond-2}
    \overline{u}_{\mathrm{cross}}(t) < 
    \begin{cases}
        0 &\text{ if } v_i = 0, \\
        -u_{\max} &\text{ otherwise}.
    \end{cases}
\end{align}
then there is no feasible solution.
By Theorem \ref{thm:no-overshoot}, we switch braking strategies and set $u_{\mathrm{cross}}(t)$ to the rear-end stopping constraint when $\Delta t_{i,1}$ satisfies \eqref{thm:no-overshoot}.
This implies $u_{\mathrm{cross}}(t)\geq u_{\mathrm{rear}}(t)$, where equality is strict if there is no preceding vehicle.
By definition, this does not satisfy \eqref{eq:cond-2}, and thus a feasible action exists.
\end{proof}



\begin{algorithm}[ht]
\caption{CAV control algorithm}
\label{alg:cav_control}
\DontPrintSemicolon

Find the smallest $k$ such that $[\underline t_i^k,\overline t_i^k]$ satisfies \eqref{condition1}\;

\While{$p_i\le p_i^{\mathrm{tr}}\; \&\; t\geq t_i^0$}{
    Compute distance $\Delta p_i$\;
    Compute $\Delta t_{i,1}$ and $\Delta t_{i,2}$\;

    \If{condition \eqref{eq:cross-time-limit} is \emph{not} satisfied}{
        $k \leftarrow k+1$\;
        Update $[\underline t_i^k,\overline t_i^k]$ until condition~\eqref{eq:cross-time-limit} holds\;
    }

    \If{$\Delta t_{i,2} > \sqrt{2\Delta p_i/u_{\max}}$}{
        Replace \eqref{boundary2} with \eqref{CBF_rear_end} and substitute $\delta_i(t)=p_i^{\mathrm{tr}}$\;
    }

    \If{\textbf{Problem~1} is feasible}{
        Apply \textbf{Problem~1}\;
    }
    \Else{
        $k \leftarrow k+1$\;
        Update $[\underline t_i^k,\overline t_i^k]$
    }
}
    Apply \textbf{Problem~1} \emph{excluding} crossing-time constraints
        \eqref{boundary1}–\eqref{boundary2}\;
\end{algorithm}

\subsection{Human Driven Vehicles} \label{HDVs}
In order to incorporate human driver behavior in our scenario, we utilized a well-known car following model of the literature, the Intelligent Driver Model (IDM) model; see \cite{albeaik2022limitations}. The acceleration $u_i$ of a vehicle based on IDM is given by,
\begin{equation}
u_i = u_{\max} \left[ 1 - \left( \frac{v_i}{v_{\text{des}}} \right)^{\xi} - \left( \frac{s^*(v_i, \Delta v_i)}{s_i(t)} \right)^2 \right]
\end{equation}
where: $v_i$ is the current speed of the vehicle, $v_{\text{des}}$ is the desired speed, $\xi$ is a model parameter, $s_i(t)$ is the gap to the leading vehicle, $\Delta v_i = v_i - v_{\text{lead}}(t)$ is the speed difference between the vehicle and the vehicle ahead. The desired minimum gap \( s^*(v_i, \Delta v) \) is given by: $s^*(v_i, \Delta v_i) = \gamma_i + v T + \frac{v_i \Delta v_i}{2 \sqrt{u_{\max} \beta}}$, $T$ is the desired time headway, and $\beta$ is the comfortable deceleration.\



