\begin{figure}[t]
    \centering
    \includegraphics[width=0.99\linewidth]{Figure/motivation.pdf}
    \caption{(a) The combined CSV2S architecture comprises independently trained CSR and TTS systems. (b) Our unified framework (UniCUE) that integrates understanding capabilities of CSR into V2S training by transferring the visual processor of CSR into CSV2S. }
    \label{fig:motivation}
