\subsubsection{UPNG}
If there is no guard time between the channel estimation phase and the uplink transmission phase, then the interference term after MF at AP $r$ is
%\allowdisplaybreaks
\begin{gather*}
        \hspace*{-2in}\boldsymbol{h}_{ru'}\boldsymbol{x}_{u',r,\rm aug}\boldsymbol{\phi}_{u,r,\rm MF}^H = 
        \\
        \begin{cases}
        \begin{aligned}
            \boldsymbol{h}_{ru'}\omega^{m(\tau_{\rm p} - \tau_{uu',r})}\frac{\omega^{(m-n)(\tau_{uu',r})} - 1}{\omega^{m-n}-1}
        \end{aligned}
        \hspace{0.2in} , \text{$t_{u,r} \leq t_{u',r}$}
            \\
        \begin{aligned}
            \boldsymbol{h}_{ru'}\omega^{m(\tau_{\rm p} - \tau_{uu',r})}\frac{\omega^{(m-n)(\tau_{uu',r})} - 1}{\omega^{m-n}-1} + \boldsymbol{h}_{ru'}\!\!\!
            \sum_{i = 0}^{\tau_{\rm p} - \tau_{uu',r} - 1}
            \!\!\! e^{j\eta_i}
        \end{aligned}
        \\ \hspace*{2in}  ,\text{$t_{u,r} > t_{u',r}$}
        \end{cases}
        \\
        \hspace{-0.2in}
        \text{where~~} 
        \eta_i \sim U\{0,...,{\rm lcm}(N_{\rm DFT}^m,N)\}\times\frac{2\pi}{{\rm lcm}(N_{\rm DFT}^m,N)}\\
        \hspace{0in}N_{\rm DFT}^m = \begin{cases}
            \begin{aligned}
        \frac{\tau_{\rm p}}{\mathrm{gcd}\left(m,\tau_{\rm p}\right)}
    \end{aligned}
    ~,~\text{$\frac{m}{\tau_{\rm p}}$ is rational}
    \\
    \begin{aligned}
        \tau_{\rm p}
    \end{aligned}
    \hspace{0.55in}~,~\text{$\frac{m}{\tau_{\rm p}}$ is irrational}
        \end{cases}\numberthis
\end{gather*}
Here, ${\rm lcm}(a,b)$ and ${\rm gcd}(a,b)$ represents the least common multiple and the greatest common divisor of $a$ and $b$, respectively. The power of the interference can be calculated as follows,
\allowdisplaybreaks
\begin{gather*}
    \hspace*{-0.5in}(\boldsymbol{h}_{ru'}\boldsymbol{x}_{u',r,\rm aug}\boldsymbol{\phi}_{u,r,\rm MF}^H)^H(\boldsymbol{h}_{ru'}\boldsymbol{x}_{u',r,\rm aug}\boldsymbol{\phi}_{u,r,\rm MF}^H) =
    \\
    \begin{cases}
        M\beta_{ru'}\psi_{ru'}\biggl(\frac{\sin(\pi(m-n)\tau_{uu',r}/\tau_{\rm p})}{\sin(\pi(m-n)/\tau_{\rm p})}\biggl)^2 \hspace*{0.2in}
        \text{$t_{u,r} \leq t_{u',r}$}\\
        M\beta_{ru'}\psi_{ru'}\biggl(\frac{\sin(\pi(m-n)\tau_{uu',r}/\tau_{\rm p})}{\sin(\pi(m-n)/\tau_{\rm p})}\biggl)^2\\
		\hspace*{0.4in}+ M\beta_{ru'}\psi_{ru'}(t_{u'r} - t_{u,r}) \hspace{0.4in} \text{$t_{u,r} > t_{u',r}$}\numberthis
    \end{cases}
\end{gather*}

\subsection{Extended DFT}
Theoretical analysis of the previous two methods reveals that with asynchronous reception, interference from all UEs persists after matched filtering, whereas in the synchronous case, only co-pilot UEs cause interference. Consequently, using these methods results in significantly lower channel estimation accuracy compared to the synchronous scenario.

%The theoretical analysis of the previous two methods shows that, due to asynchronous reception, interference from all UEs still exists after matched filtering. In the synchronous case, this interference is eliminated except for the co-pilot UEs. Therefore, if we employ the previous two methods, channel estimation accuracy will be much worse than that obtained by the synchronous case.% due to the huge interference increment.% In other words, if we can go back to synchronous reception, the performance should exhibit a significant improvement.



To cope with this, we propose using DFT sequences with a cyclic extension. Assume that the DFT pilot sequence assigned to the user $u$ is $\boldsymbol{\phi}_u = [\boldsymbol{\Phi}]_m\in\mathbb{C}^{1\times \tau_{\rm p}}$. Then, assume the extended length is $\tau_{\rm ex}$, the pilot sequence being transmitted by the UE $u$ is $\boldsymbol{\phi}_u\in\mathbb{C}^{1\times(\tau_{\rm p} + \tau_{\rm ex})}$ which can be expressed as,
\begin{align}\label{eqn: extended DFT}
	&\boldsymbol{\phi}_{u,\rm DFT_{\rm ex}} = [\boldsymbol{\zeta}_u[0],...,\boldsymbol{\zeta}_u[\tau_{\rm p} - 1],\boldsymbol{\zeta}_u[0],...,\boldsymbol{\zeta}_u[\tau_{\rm ex} - 1]]
	\nonumber\\
	& =
	[\boldsymbol{\zeta}_u[0],...,\boldsymbol{\zeta}_u[\tau_{\rm p} - 1],\boldsymbol{\zeta}_u[\tau_{\rm p}],...,\boldsymbol{\zeta}_u[\tau_{\rm p}+\tau_{\rm ex} - 1]]
\end{align}
where
\begin{align}
\boldsymbol{\zeta}_u[n] = \boldsymbol{\phi}_u[n]
=
e^{j\frac{2\pi m (n)}{\tau_{\rm p}}}
\end{align}
%
%
%
%\begin{align}\label{eqn: extended DFT}
%\begin{split}
%     \boldsymbol{\phi}_{u,\rm DFT_{\rm ex}} &= [\boldsymbol{\zeta}_u[0],...,\boldsymbol{\zeta}_u[\tau_{\rm p} - 1],\boldsymbol{\zeta}_u[0],...,\boldsymbol{\zeta}_u[\tau_{\rm ex} - 1]]\\
%    & \hspace*{-0.3in}= \left[e^{j\frac{2\pi m(0)}{\tau_{\rm p}}},...,e^{j\frac{2\pi m(\tau_{\rm p} - 1)}{\tau_{\rm p}}},e^{j\frac{2\pi m(0)}{\tau_{\rm p}}},...,e^{j\frac{2\pi m(\tau_{\rm ex} - 1)}{\tau_{\rm p}}}\right]\\
%    &\hspace*{-0.5in} = \left[e^{j\frac{2\pi m(0)}{\tau_{\rm p}}},...,e^{j\frac{2\pi m(\tau_{\rm p} - 1)}{\tau_{\rm p}}},e^{j\frac{2\pi m(\tau_{\rm p})}{\tau_{\rm p}}},...,e^{j\frac{2\pi m(\tau_{\rm p} + \tau_{\rm ex} - 1)}{\tau_{\rm p}}}\right]
%\end{split}
%\end{align}
For DFT sequences, it has a special property that the step size between any two adjacent entries is always $e^{j\frac{2\pi m}{\tau_{\rm p}}}$. Therefore, the second equality of~\eqref{eqn: extended DFT} is always true.

