	% 74Q05\marginpar{Homogenization in equilibrium problems}, 35B27\marginpar{Homogenization; equations in media with periodic structure}, 65N30\marginpar{Finite elements, Rayleigh-Ritz and Galerkin methods, finite methods}, 65N06\marginpar{Finite difference methods}, 74Q15\marginpar{Effective constitutive equations}
	\end{AMS}
