With a slight abuse of notation, the shrinkage operator $\phi_{L,m,\nu}$ can apply to a vector $x=\left(x_{1},\dots,x_{d}\right)$ in a component-wise manner
\[
\phi_{L,m,\nu}\left(x\right):=\left(\phi_{L,m,\nu}\left(x_{1}\right),\dots,\phi_{L,m,\nu}\left(x_{d}\right)\right).
\]
Thus, Eqn. \ref{eq:dilation-operator-def} has a concise form $\left(\cD_{L,m}B\right)\left(x\right)=B\left(\phi_{L,m}\left(x\right)\right)$. In the following paragraphs, we omit $L$, $m$, and $\nu$ when there is no ambiguity on parameters. We provide an estimate of the distance between $\phi\left(x\right)$ and $x$.
\begin{lem}
\label{lem:shrinkage-difference-estimate}For given $L$, $m$, and $\nu$, $\abs{\phi\left(x\right)-x}\le dL$ holds for any $x\in\Omega$.
\end{lem}
\begin{proof}
We first relax the vector 2-norm by $\abs{\phi\left(x\right)-x}\le\sum_{i=1}^{d}\abs{\phi\left(x_{i}\right)-x_{i}}$. Then, for each index $1\le i\le d$, by definition of the anchor function and shrinkage mapping,
\[
\abs{\phi\left(x_{i}\right)-x_{i}}=\abs{\left(1-\frac{1}{m}\right)\left(x_{i}-\Phi\left(x_{i}\right)\right)}=\frac{m-1}{m}L\abs{\left\{ \frac{x_{i}}{L}\right\} -\nu}.
\]
Since $m>1$, $0\le x_{i}/L<1$, and $0\le\nu\le1$, the RHS above shall be smaller than $L$, leading to $\abs{\phi\left(x\right)-x}\le\sum_{i=1}^{d}\abs{\phi\left(x_{i}\right)-x_{i}}\le dL.$
\end{proof}
\begin{rem*}
\sepia{Lem. \ref{lem:shrinkage-difference-estimate} provides the best estimate of $\phi\left(x\right)-x$ in terms of the exponent of $L$, regardless of the choice of $\nu$. However, the convergence rate of the overall dilation solver might improve with a symmetry-motivated choice of $\nu=\frac{1}{2}$ (see discussion in Par. \ref{par:numerical-dilation-error}).}
\end{rem*}

\subsubsection{Dilated system}

With the aforementioned notations, we propose to solve the following dilated problem
\begin{align}
-\nabla\cdot\left[\cD A^{\epsilon}\left(x\right)\nabla u_{D}^{\epsilon}\left(x\right)\right] & =f\left(x\right) & \text{in}\ \Omega,\label{eq:dilation-solver-dilated-pde}\\
u_{D}^{\epsilon} & =0 & \text{on}\ \partial\Omega
\end{align}
under a proper set of parameters $L$, $m$, and $\nu$. We point out that $\cD A^{\epsilon}\in\cT^{\epsilon}$ if $\Omega$ has a nice geometric structure.
\begin{lem}
\label{lem:DAeps-representation}For given $A\in C^{1}\left(\Omega\times\bT^{d}\right)^{d\times d}$ on $\Omega=\left[0,1\right]^{d}$, let $A^{\epsilon}:=\iota^{\epsilon}A$ denote the wrapped oscillatory coefficient. Then, for a given dilation operator $\cD_{L,m,\nu}$, there exists $\widetilde{A}\in\cS$ s.t. $\cD_{L,m,\nu}A^{\epsilon}=\iota^{m\epsilon}\widetilde{A}$. Furthermore, $\widetilde{A}$ is a $C^{1}\left(T_{k}\times\bT^{d};M^{d\times d}\right)$ matrix-valued function if restricted in $T_{k}$, where $T_{k}:=\prod_{i=1}^{d}\left[\left(k_{i}-1\right)L,k_{i}L\right)$ is a $d$-dimensional cube and $k=\left(k_{1},k_{2},\dots,k_{d}\right)$ is a multi-index with $1\le k_{i}\le\frac{1}{L}$ for $1\le i\le d$.
\end{lem}
\begin{proof}
Let $\widetilde{\epsilon}:=m\epsilon$ denote the relaxed scale parameter. Notice that the family of cubes $\left\{ T_{k}\right\} $ forms a partition of $\Omega$. The difference in the fast variable reads
\[
\frac{\phi\left(x\right)}{\epsilon}-\frac{x}{\widetilde{\epsilon}}=\frac{1}{\epsilon}\left[\frac{1}{m}\left(x-\Phi\left(x\right)\right)+\Phi\left(x\right)\right]-\frac{x}{m\epsilon}=\frac{1}{\epsilon}\left(1-\frac{1}{m}\right)\Phi\left(x\right)
\]
where $\Phi\left(x\right)=\left(\left\lfloor \frac{x}{L}\right\rfloor +\nu\right)L$ is a constant function within each cube $T_{k}$, so the multi-index $k$ is associated to $\varphi_{k}:=\frac{1}{\epsilon}\left(1-\frac{1}{m}\right)\left(k+\nu\right)L$. Then, the dilated coefficient reads
\[
\left(\cD A^{\epsilon}\right)\left(x\right)=A\left(\phi\left(x\right),\frac{\phi\left(x\right)}{\epsilon}\right)=A\left(\phi\left(x\right),\frac{x}{\widetilde{\epsilon}}+\varphi_{k}\right)\ \text{for}\ x\in T_{k}
\]
which naturally leads to $\widetilde{A}\left(x,\lambda\right):=A\left(\phi\left(x\right),\lambda+\varphi_{k}\right)$ for $x\in T_{k}$. $\widetilde{A}$ is 1-periodic in $\lambda$ due to $1$-periodicity of $A$, so $\widetilde{A}\in\cS$ and one can verify that $\cD A^{\epsilon}=\iota^{m\epsilon}\widetilde{A}$. In each $T_{k}$, since $A$ is $C^{1}$ and $\phi|_{T_{k}}$ is affine, $\widetilde{A}|_{T_{k}}$ is $C^{1}$ as well.
\end{proof}
%
\begin{rem*}
In the context of Lem. \ref{lem:DAeps-representation}, since $\widetilde{A}\in\cS$, we can apply the homogenization operator $\cH$ on it, leading to the homogenized dilated system
\begin{align}
-\nabla\cdot\left[\cH\widetilde{A}\left(x\right)\nabla u_{0,D}\left(x\right)\right] & =f\left(x\right) & \text{in}\ \Omega,\label{eq:dilation-solver-homogenized-dilated-pde}\\
u_{0,D} & =0 & \text{on}\ \partial\Omega.
\end{align}
\end{rem*}
We point out that $\cH$ and $\cD$ are interchangeable in the following sense.

\begin{lem}
\label{lem:interchangability}In the context of Lem. \ref{lem:DAeps-representation}, the dilation of homogenized tensor $\overline{A}:=\cH A$ coincides with the homogenization of $\widetilde{A}$, i.e. 
\[
\cH\left(\iota^{m\epsilon}\right)^{-1}\cD A^{\epsilon}=\cH\widetilde{A}=\cD\overline{A}=\cD\cH\left(\iota^{\epsilon}\right)^{-1}A^{\epsilon}.
\]
\end{lem}
\begin{proof}
To begin with, we apply the homogenization formula in Def. \ref{eq:homogenization-operator-def} to $\widetilde{A}$:
\begin{equation}
\cH\widetilde{A}\left(x\right)=\int_{\bT^{d}}\widetilde{A}\left(x,\lambda\right)+\widetilde{A}\left(x,\lambda\right)\nabla\widetilde{\chi}\left(\lambda;x\right)^{T}\d{\lambda}\label{eq:interchangability-exposition}
\end{equation}
where $\widetilde{\chi}$ solves the cell problem $-\nabla_{\lambda}\cdot\left(\nabla_{\lambda}\widetilde{\chi}\ \widetilde{A}^{T}\right)=\nabla_{\lambda}\cdot\widetilde{A}^{T}$. Since $\widetilde{A}\left(x,\lambda\right)=A\left(\phi\left(x\right),\lambda+\varphi_{k}\right)$ in $T_{k}$ and the cell problem does not contain partial differentials in $x$, one can easily verify that the solution reads $\widetilde{\chi}\left(\lambda;x\right)=\chi\left(\lambda+\varphi_{k};\phi\left(x\right)\right)$. Thus, with a change in the variable $\widetilde{\lambda}:=\lambda+\varphi_{k}$, Eqn. \ref{eq:interchangability-exposition} leads to%
\begin{comment}
\begin{align*}
\cH\widetilde{A}\left(x\right) & =\int_{\bT^{d}}A\left(\phi\left(x\right),\lambda+\varphi_{k}\right)+A\left(\phi\left(x\right),\lambda+\varphi_{k}\right)\nabla\chi\left(\lambda+\varphi_{k};\phi\left(x\right)\right)^{T}\d{\lambda}\\
 & =\int_{\bT^{d}}A\left(\phi\left(x\right),\widetilde{\lambda}\right)+A\left(\phi\left(x\right),\widetilde{\lambda}\right)\nabla\chi\left(\widetilde{\lambda};\phi\left(x\right)\right)^{T}\d{\widetilde{\lambda}}\\
 & =\overline{A}\left(\phi\left(x\right)\right)\\
 & =\cD\overline{A}\left(x\right).
\end{align*}
\end{comment}
\[
\cH\widetilde{A}\left(x\right)=\int_{\bT^{d}}A\left(\phi\left(x\right),\widetilde{\lambda}\right)+A\left(\phi\left(x\right),\widetilde{\lambda}\right)\nabla\chi\left(\widetilde{\lambda};\phi\left(x\right)\right)^{T}\d{\widetilde{\lambda}}=\cD\overline{A}\left(x\right).
\]
\end{proof}
%
