\subsubsection{Error decomposition}

So far, we have defined $u_{D}^{\epsilon}$ as the solution to the dilated oscillatory problem (Eqn. \ref{eq:dilation-solver-dilated-pde}) and $u_{0}$ as the solution to the homogenized problem (Eqn. \ref{eq:intro-homogenized-pde}). We may also introduce $u_{D,h}^{\epsilon}$ as the numerical solution to the dilated system (Eqn. \ref{eq:dilation-solver-dilated-pde}) where the mesh size is specified by $h$. In this section, we aim to build a set of error estimates on $u_{D,h}^{\epsilon}-u_{0}$ and find out how it depends on the parameters $L,m,$ and $\nu$. To this end, we can utilize the solution $u_{0,D}$ to Eqn. \ref{eq:dilation-solver-homogenized-dilated-pde}. By the triangle inequality,
\begin{equation}
\norm{u_{D,h}^{\epsilon}-u_{0}}\le\underbrace{\norm{u_{D,h}^{\epsilon}-u_{D}^{\epsilon}}}_{\text{discretization error}}+\underbrace{\norm{u_{D}^{\epsilon}-u_{0,D}}}_{\text{homogenization error}}+\underbrace{\norm{u_{0,D}-u_{0}}}_{\text{dilation error}}.\label{eq:full-error-estimate-tri}
\end{equation}
The homogenization error is treated similarly as in the section on partial dilation. According to Thm. \ref{thm:homogenization-error-Lp-estimate}, there exist constants $C\left(\Omega,r,M,d\right)$ and $r_{0}\left(\Omega,r,M,d\right)$ s.t. 
\begin{equation}
\norm{u_{D}^{\epsilon}-u_{0,D}}_{L^{2}\left(\Omega\right)}\le Cm\epsilon\ln\left(\frac{r_{0}}{m\epsilon}\right)\norm f_{L^{2}\left(\Omega\right)}.\label{eq:dilated-system-homogenization-error}
\end{equation}
The dilation error is addressed in Sec. \ref{subsec:Perturbation-analysis} by using a standard perturbation analysis approach. The discretization error of the FEM solution is analyzed in Sec. \ref{subsec:Discretization-error-fem}.

\subsubsection{Dilation error and regularity\label{subsec:Perturbation-analysis}}

According to the perturbation analysis \cite[Theorem 2.1]{Bonito2013}, the dilation error depends on the $L^{\infty}$-norm difference of the homogenized coefficients, i.e.

\[
\norm{u_{0}-u_{0,D}}_{H_{0}^{1}\left(\Omega\right)}\apprle\norm{\nabla u_{0}}_{L^{2}\left(\Omega\right)}\norm{\overline{A}-\cH\widetilde{A}}_{L^{\infty}\left(\Omega\right)}.
\]
Since $\left(\cH\widetilde{A}\right)\left(x\right)=\left(\cD\overline{A}\right)\left(x\right)=\overline{A}\left(\phi\left(x\right)\right)$ and $\phi\left(x\right)-x=\cO\left(L\right)$ (Lem. \ref{lem:shrinkage-difference-estimate}), the $L^{\infty}$-norm difference can be easily derived if $\overline{A}$ is smooth. To show the regularity of $\overline{A}$, we need to prepare a few key concepts and lemmas.
\begin{defn}
\label{def:spectral norm}For a matrix $B\in\bR^{d\times d}$, let $\norm B_{2}:=\sup_{\xi\neq0}\frac{\abs{B\xi}}{\abs{\xi}}$ denote the matrix norm induced by the vector 2-norm and $\norm B_{\max}:=\max_{i,j}\abs{B_{ij}}$ denote the max norm. The $L^{p}$ norm of a matrix-valued function $\cB\left(x\right)$ is defined as the $L^{p}$ norm of the point-wise spectral norm, i.e. $\norm{\cB}_{L^{p}\left(\Omega\right)}:=\norm{\norm{\cB\left(x\right)}_{2}}_{L^{p}\left(\Omega\right)}$.
\end{defn}

We now derive the regularity of the homogenized tensor $\overline{A}$.
\begin{lem}
\label{lem:HA regularity}We assume that a given $A\in\cS$ satisfies 
\begin{itemize}
\item $A\in C^{1}\left(\Omega\times\bT^{d};M^{d\times d}\right)$ and $A\left(x\right)$ is symmetric,
\item there exists $r>0$ s.t. $r\le\lambda_{\min}\left(A\left(x\right)\right)$ holds for any $x\in\Omega$, and
\item there exists a uniform bound $Q>0$ on $A_{ij}$, $\nabla_{x}A_{ij}$, $\nabla_{\lambda}A_{ij}$, $\nabla_{x}\nabla_{\lambda}A_{ij}$ for $1\le i,j\le d$ and $\left(x,\lambda\right)\in\Omega\times\bT^{d}$.
\end{itemize}
Then $\overline{A}=\cH A$ is Lipschitz in terms of the spectral norm, i.e. there exists a constant $C\left(\Omega,r,Q,d\right)$ s.t.
\[
\norm{\overline{A}\left(x\right)-\overline{A}\left(\widehat{x}\right)}_{2}\le C\left(\Omega,r,Q,d\right)\abs{x-\widehat{x}}
\]
holds for any $x,\widehat{x}\in\Omega$.
\end{lem}
\begin{proof}
We first need to establish a few estimates on the first order corrector field $\chi\left(\cdot;x\right)$. Let $a_{l}$ denote the $l$-th column of $A$. Since $\chi\left(\cdot;x\right),\chi\left(\cdot;\widehat{x}\right)\in\overline{H}^{1}\left(\bT^{d}\right)$ solve the cell problems
\begin{align*}
-\nabla_{\lambda}\cdot\left(A\left(x,\lambda\right)\nabla_{\lambda}\chi_{l}\left(\lambda;x\right)\right) & =\nabla_{\lambda}\cdot a_{l}\left(x,\lambda\right),\\
-\nabla_{\lambda}\cdot\left(A\left(\widehat{x},\lambda\right)\nabla_{\lambda}\chi_{l}\left(\lambda;\widehat{x}\right)\right) & =\nabla_{\lambda}\cdot a_{l}\left(\widehat{x},\lambda\right),
\end{align*}
by the perturbation theory for PDEs with periodic boundary conditions  (as an extension of \cite[Theorem 2.1]{Bonito2013}), the difference can be estimated by
\begin{multline}
\norm{\chi_{l}\left(\lambda;x\right)-\chi_{l}\left(\lambda;\widehat{x}\right)}_{\overline{H}^{1}\left(\bT^{d}\right)}\le\frac{1}{r}\norm{\nabla_{\lambda}\cdot\left(a_{l}\left(x,\lambda\right)-a_{l}\left(\widehat{x},\lambda\right)\right)}_{H^{-1}\left(\bT^{d}\right)}+\\
+\frac{1}{r}\norm{\nabla_{\lambda}\chi_{l}\left(\lambda;x\right)}_{L^{2}\left(\bT^{d}\right)}\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{L^{\infty}\left(\bT^{d}\right)}\label{eq:dilation-chi-property-perturbation}
\end{multline}
where the $\overline{H}^{1}\left(\Pi\right)$ semi-norm is defined as $\abs v_{\overline{H}^{1}\left(\Pi\right)}:=\norm{\nabla v}_{L^{2}\left(\Pi\right)}$. For the first term, we apply mean value theorem and bound the partial derivative
\begin{equation}
\norm{\nabla_{\lambda}\cdot\left(a_{l}\left(x,\lambda\right)-a_{l}\left(\widehat{x},\lambda\right)\right)}_{L^{2}\left(\bT^{d}\right)}\le\sum_{j=1}^{d}\left[\abs{\partial_{\lambda_{j}}\partial_{x}A_{jl}\left(\xi_{j},\lambda\right)}\abs{x_{j}-\widehat{x}_{j}}\right]\le dQ\abs{x-\widehat{x}}.\label{eq:dilation-chi-property-da}
\end{equation}
For the term involving $\chi$, we can apply a standard estimate in the Lax-Milgram theorem to conclude that
\begin{equation}
\norm{\nabla_{\lambda}\chi_{l}\left(\lambda;x\right)}_{L^{2}\left(\bT^{d}\right)}\le\frac{1}{r}\norm{\nabla_{\lambda}\cdot a_{l}\left(x,\lambda\right)}_{\overline{H}^{-1}\left(\bT^{d}\right)}\le\frac{C_{2}Q\sqrt{d}}{r}.\label{eq:dilation-chi-property-dchi}
\end{equation}
For the difference term in $A$ , we simply utilize the fact that each entry of $A$ is $C^{1}$ and that all matrix norms are equivalent:
\begin{equation}
\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{L^{\infty}\left(\bT^{d}\right)}\le C_{1}\left(d\right)dQ\abs{x-\widehat{x}}\label{eq:dilation-chi-property-diffA}
\end{equation}
where $C_{1}\left(d\right)$ is a constant s.t. $\frac{1}{C_{1}}\norm B_{2}\le\norm B_{\max}\le C_{1}\norm B_{2}$ holds for any matrix $B\in\bR^{d\times d}$.%
\begin{comment}
\begin{itemize}
\item By the continuous embedding of the $L^{2}\left(\bT^{d}\right)$ space into the $\overline{H}^{-1}\left(\bT^{d}\right)$ space (see remarks following Thm. \ref{thm:pde-perturbation-estimate-per}), we relax all $\overline{H}^{-1}\left(\Omega\right)$ norms to $L^{2}\left(\Omega\right)$ norms with a constant $C_{2}$. For the $\norm{\nabla_{\lambda}\cdot\left(a_{l}\left(x,\lambda\right)-a_{l}\left(\widehat{x},\lambda\right)\right)}_{L^{2}\left(\bT^{d}\right)}$ term, we use the intermediate value theorem and the bound on $\nabla_{x}\nabla_{\lambda}A$ to obtain
\begin{align}
\norm{\nabla_{\lambda}\cdot\left(a_{l}\left(x,\lambda\right)-a_{l}\left(\widehat{x},\lambda\right)\right)}_{L^{2}\left(\bT^{d}\right)} & \le\sup_{\lambda\in\bT^{d}}\sum_{j=1}^{d}\left[\sup_{\xi}\abs{\partial_{\lambda_{j}}\partial_{x}A_{jl}\left(\xi,\lambda\right)}\abs{x_{j}-\widehat{x}_{j}}\right]\nonumber \\
 & \le\sum_{j=1}^{d}\norm{\nabla_{x}\nabla_{\lambda}A_{jl}}_{L^{\infty}\left(\Omega\times\bT^{d}\right)}\abs{x-\widehat{x}}\nonumber \\
 & \le dQ\abs{x-\widehat{x}}.\label{eq:dilation-chi-property-da-bak}
\end{align}
\item Applying $\chi_{l}$ as a test function on Eqn. \ref{eq:dilation-cell-problem-weak-form} yields
\begin{equation}
\int_{\bT^{d}}\left(A\nabla_{\lambda}\chi_{l}\right)\cdot\nabla_{\lambda}\chi_{l}\d{\lambda}=\int_{\bT^{d}}\left(\nabla_{\lambda}\cdot a_{l}\right)\cdot\nabla_{\lambda}\chi_{l}\d{\lambda}.\label{eq:dilation-chi-property-dchi-weak-form-bak}
\end{equation}
By the uniform ellipticity property of $A$, Eqn. \ref{eq:dilation-chi-property-dchi-weak-form-bak} implies that 
\[
r\norm{\chi_{l}\left(\lambda;x\right)}_{\overline{H}^{1}\left(\bT^{d}\right)}^{2}\le\norm{\nabla_{\lambda}\cdot a_{l}\left(x,\lambda\right)}_{\overline{H}^{-1}\left(\bT^{d}\right)}\norm{\chi_{l}\left(\lambda;x\right)}_{\overline{H}^{1}\left(\bT^{d}\right)}.
\]
Thus the norm of the gradient $\nabla_{\lambda}\chi_{l}$ satisfies 
\begin{align}
\norm{\nabla_{\lambda}\chi_{l}\left(\lambda;x\right)}_{L^{2}\left(\bT^{d}\right)}=\norm{\chi_{l}\left(\lambda;x\right)}_{\overline{H}^{1}\left(\bT^{d}\right)} & \le\frac{1}{r}\norm{\nabla_{\lambda}\cdot a_{l}\left(x,\lambda\right)}_{\overline{H}^{-1}\left(\bT^{d}\right)}\nonumber \\
 & \le\frac{C_{2}}{r}\norm{\nabla_{\lambda}\cdot a_{l}\left(x,\lambda\right)}_{L^{2}\left(\bT^{d}\right)}\nonumber \\
 & \le\frac{C_{2}\sqrt{d}}{r}\norm{\norm{\nabla_{\lambda}A}_{\max}}_{L^{\infty}\left(\bT^{d}\right)}\nonumber \\
 & \le\frac{C_{2}Q\sqrt{d}}{r}.\label{eq:dilation-chi-property-dchi-bak}
\end{align}
\item For the difference term in $A$ , we simply utilize the fact that each entry of $A$ is $C^{1}$:
\begin{align}
\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{L^{\infty}\left(\bT^{d}\right)} & \le C_{1}\norm{\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{\max}}_{L^{\infty}\left(\bT^{d}\right)}\nonumber \\
 & \le C_{1}\sup_{\lambda\in\bT^{d}}\max_{i,j}\sup_{\xi}\abs{\nabla_{x}A_{ij}\left(\xi,\lambda\right)}\abs{x-\widehat{x}}\nonumber \\
 & \le C_{1}dQ\abs{x-\widehat{x}}.\label{eq:dilation-chi-property-diffA-bak}
\end{align}
\end{itemize}
\end{comment}
{} We combine Eqn. \ref{eq:dilation-chi-property-perturbation}, \ref{eq:dilation-chi-property-da}, \ref{eq:dilation-chi-property-dchi}, and \ref{eq:dilation-chi-property-diffA} to argue that
\begin{equation}
\norm{\chi_{l}\left(\lambda;x\right)-\chi_{l}\left(\lambda;\widehat{x}\right)}_{\overline{H}^{1}\left(\bT^{d}\right)}\le C_{\chi}\abs{x-\widehat{x}},C_{\chi}:=\frac{C_{2}dQ}{r}+\frac{C_{1}C_{2}d^{3/2}Q^{2}}{r^{2}},\label{eq:dilation-chi-property-Hbar1}
\end{equation}
which implies that $\chi_{l}$ is a Lipschitz function w.r.t. the parameter $x$ in terms of the $\overline{H}^{1}\left(\bT^{d}\right)$ norm.

Now we move on to the homogenized coefficient. %
\begin{comment}
Due to $\norm{\int_{\bT^{d}}B\d{\lambda}}_{2}\le\int_{\bT^{d}}\norm B_{2}\d{\lambda}$ and the fact that $\norm{\cdot}_{2}$ is sub-multiplicative, we decompose
\begin{align}
\norm{\overline{A}\left(x\right)-\overline{A}\left(\widehat{x}\right)}_{2} & \le\int_{\bT^{d}}\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{2}\d{\lambda}\nonumber \\
 & \quad+\int_{\bT^{d}}\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{2}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)}_{2}\d{\lambda}\nonumber \\
 & \quad+\int_{\bT^{d}}\norm{A\left(\widehat{x},\lambda\right)}_{2}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)-\nabla_{\lambda}\chi\left(\lambda;\widehat{x}\right)}_{2}\d{\lambda}\nonumber \\
 & =:I_{1}+I_{2}+I_{3}.\label{eq:dilation-homogenized-split}
\end{align}

\begin{itemize}
\item For $I_{1}$, since $\nabla_{x}A$ is uniformly bounded, we have
\begin{align*}
\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{2} & \le C_{1}\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{\max}\\
 & \le C_{1}\max_{i,j}\abs{\sup_{\xi}\nabla_{x}A_{ij}\left(\xi,\lambda\right)}\abs{x-\widehat{x}}\\
 & \le C_{1}Q\abs{x-\widehat{x}}.
\end{align*}
As a consequence,
\[
\int_{\bT^{d}}\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{2}\d{\lambda}\le\int_{\bT^{d}}C_{1}Q\abs{x-\widehat{x}}\d{\lambda}\le C_{1}Q\abs{x-\widehat{x}}.
\]
\item For $I_{2}$, use Eqn. \ref{eq:dilation-chi-property-dchi-bak} to obtain that $\norm{\nabla_{\lambda_{k}}\chi_{j}}_{L^{1}\left(\bT^{d}\right)}\le\norm{\nabla_{\lambda_{k}}\chi_{j}}_{L^{2}\left(\bT^{d}\right)}\le\frac{C_{2}Q\sqrt{d}}{r}$, leading to 
\begin{align*}
 & \int_{\bT^{d}}\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{2}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)}_{2}\d{\lambda}\\
\le & \int_{\bT^{d}}C_{1}^{2}Q\abs{x-\widehat{x}}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)}_{\max}\d{\lambda}\\
\le & C_{1}^{2}Q\abs{x-\widehat{x}}\int_{\bT^{d}}\max_{k,j}\abs{\nabla_{\lambda_{k}}\chi_{j}\left(\lambda;x\right)}\d{\lambda}\\
\le & \frac{C_{1}^{2}C_{2}\sqrt{d}Q^{2}}{r}\abs{x-\widehat{x}}.
\end{align*}
\item For $I_{3}$, we utilize Eqn. \ref{eq:dilation-chi-property-Hbar1} to bound the difference in $\nabla_{\lambda}\chi$ 
\begin{align*}
 & \int_{\bT^{d}}\norm{A\left(\widehat{x},\lambda\right)}_{2}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)-\nabla_{\lambda}\chi\left(\lambda;\widehat{x}\right)}_{2}\d{\lambda}\\
\le & C_{1}\int_{\bT^{d}}\norm{A\left(\widehat{x},\lambda\right)}_{\max}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)-\nabla_{\lambda}\chi\left(\lambda;\widehat{x}\right)}_{2}\d{\lambda}\\
\le & C_{1}Q\left[\int_{\bT^{d}}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)-\nabla_{\lambda}\chi\left(\lambda;\widehat{x}\right)}_{2}^{2}\d{\lambda}\right]^{1/2}\\
= & C_{1}Q\norm{\chi_{l}\left(\lambda;x\right)-\chi_{l}\left(\lambda;\widehat{x}\right)}_{\overline{H}^{1}\left(\bT^{d}\right)}\\
\le & C_{1}QC_{\chi}\abs{x-\widehat{x}}.
\end{align*}
\end{itemize}
\end{comment}
Due to the fact that $\norm{\cdot}_{2}$ is sub-multiplicative and $\norm{\int_{\bT^{d}}B\d{\lambda}}_{2}\le\int_{\bT^{d}}\norm B_{2}\d{\lambda}$, it suffices to estimate the pointwise difference between $A\left(x,\cdot\right)$ and $A\left(\widehat{x},\cdot\right)$. Using the Lipschitz continuity of $A$, we have
\begin{equation}
\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{2}\le C_{1}\max_{i,j}\abs{\sup_{\xi}\nabla_{x}A_{ij}\left(\xi,\lambda\right)}\abs{x-\widehat{x}}\le C_{1}Q\abs{x-\widehat{x}}\label{eq:dilation-homogenized-I1}
\end{equation}
which implies that
\begin{equation}
\norm{A\left(x,\lambda\right)-A\left(\widehat{x},\lambda\right)}_{2}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)}_{2}\le\frac{C_{1}^{2}C_{2}\sqrt{d}Q^{2}}{r}\abs{x-\widehat{x}}.\label{eq:dilation-homogenized-I2}
\end{equation}
Meanwhile, Eqn. \ref{eq:dilation-chi-property-Hbar1} implies 
\begin{equation}
\norm{A\left(\widehat{x},\lambda\right)}_{2}\norm{\nabla_{\lambda}\chi\left(\lambda;x\right)-\nabla_{\lambda}\chi\left(\lambda;\widehat{x}\right)}_{2}\le C_{1}QC_{\chi}\abs{x-\widehat{x}}.\label{eq:dilation-homogenized-I3}
\end{equation}
Thus, a combination of triangular inequality and Eqn. \ref{eq:homogenization-operator-def}, \ref{eq:dilation-homogenized-I1}, \ref{eq:dilation-homogenized-I2}, and \ref{eq:dilation-homogenized-I3} leads to
\[
\norm{\overline{A}\left(x\right)-\overline{A}\left(\widehat{x}\right)}_{2}\le C_{1}Q\left(1+C_{\chi}+C_{1}C_{2}\sqrt{d}Q/r\right)\abs{x-\widehat{x}}
\]
for any $x,\widehat{x}\in\Omega$.
\end{proof}
%
\begin{prop}
\label{prop:dilation error estimate}Given $A\in\cS$ that satisfies the conditions in Lem. \ref{lem:HA regularity}, there exists a constant $C\left(\Omega,r,Q,d\right)$ s.t. the dilation error is controlled by
\begin{equation}
\norm{u_{0,D}-u_{0}}_{L^{2}\left(\Omega\right)}\le C\left(\Omega,r,Q,d\right)L\norm{\nabla u_{0}}_{L^{2}\left(\Omega\right)}.\label{eq:dilation-error-estimate}
\end{equation}
\end{prop}
\begin{proof}
By the perturbation analysis (see \cite[Theorem 2.1]{Bonito2013}), we have
\begin{equation}
\norm{\nabla\left(u_{0,D}-u_{0}\right)}_{L^{2}\left(\Omega\right)}\le\frac{1}{r}\norm{\nabla u_{0}}_{L^{2}\left(\Omega\right)}\norm{\overline{A}-\cD\overline{A}}_{L^{\infty}\left(\Omega\right)}.\label{eq:nabla error bound}
\end{equation}
By definition of the dilation operator and the estimate in Lem. \ref{lem:HA regularity}, we have%
\begin{comment}
\begin{align*}
\norm{\overline{A}-\cD\overline{A}}_{L^{\infty}\left(\Omega\right)} & =\max_{x\in\Omega}\norm{\overline{A}\left(x\right)-\cD\overline{A}\left(x\right)}_{2}\\
 & =\max_{x\in\Omega}\norm{\overline{A}\left(x\right)-\overline{A}\left(\phi\left(x\right)\right)}_{2}\\
 & \le\max_{x\in\Omega}C\left(\Omega,r,Q,d\right)\abs{x-\phi\left(x\right)}\\
 & \le C\left(\Omega,r,Q,d\right)dL.
\end{align*}
\end{comment}
\begin{equation}
\norm{\overline{A}-\cD\overline{A}}_{L^{\infty}\left(\Omega\right)}=\max_{x\in\Omega}\norm{\overline{A}\left(x\right)-\overline{A}\left(\phi\left(x\right)\right)}_{2}\le C\left(\Omega,r,Q,d\right)dL.\label{eq:ADA estimate}
\end{equation}
Then, Eqn. \ref{eq:dilation-error-estimate} is established by combining Eqn. \ref{eq:nabla error bound} and \ref{eq:ADA estimate} and applying the Poincare inequality to $u_{0,D}-u_{0}$.
\end{proof}
%
\begin{rem*}
We have shown that the dilation error scales linearly with the mesoscopic length $L$ in Prop. \ref{prop:dilation error estimate}. Nevertheless, this bound is not optimal since a faster convergence is observed for $\nu=1/2$ from the numerical experiments; we refer the readers to Sec. \ref{par:numerical-dilation-error} for more details.
\end{rem*}

\subsection{Numerical aspects\label{subsec:numerical-aspects-and-concerns}}

\subsubsection{Finite element approach\label{subsec:Finite-element-approach}}

The finite element method is applied to these problems. We use the PDE Toolbox in MATLAB to generate meshes and solve for the solution. It is worth pointing out that there is a natural restriction on the parameters. First, the mesh size shall resolve the effective parameter $\widetilde{\epsilon}=m\epsilon$, i.e. $h\ll m\epsilon$. Meanwhile, the mesoscopic length $L$ usually needs to accommodate at least one oscillation before the dilation operator ``resets'', which implies $m\epsilon<L$. We call $h\ll m\epsilon<L$ as the scale condition.

\subsubsection{A priori estimate on discretization error (1D case)\label{subsec:Discretization-error-fem}}

In general, the dilated coefficient $\cD A^{\epsilon}$ has discontinuities on the mesoscopic scale $L$ and thus the classical FEM/FDM error estimate no longer applies. Non-continuous coefficients are usually a challenge, but for the case of one dimensional problems, we can utilize the closed form of the solution in an integral form. In fact, we can show a first order convergence with respect to the mesh size $h$. We study the second order problem 
\begin{equation}
-\left(a\,u'\right)'=f,x\in\Omega=\left[0,1\right]\label{eq:1d-proof-strong}
\end{equation}
under the following assumption.
\begin{assumption}
The domain $\Omega$ is partitioned by an evenly-spaced mesh $\left\{ x_{i}\right\} $, $x_{i}:=i\,h$ with mesh size $h$ and an evenly-spaced meso-mesh $\left\{ X_{j}\right\} ,X_{j}:=j\,L$ with length $L$; we assume $1/h,1/L\in\bZ^{+}$. The coefficient function $a$ is piecewise-$C^{1}$ on $\Omega_{j}:=\left[X_{j-1},X_{j}\right]$ for $j=1,\dots,1/L$. Moreover, there exist $M,\epsilon>0$ s.t. $M^{-1}\le a\le M,\ \abs{a'}\le M\epsilon^{-1}$ for every $x\in\Omega_{j}$ and all $j$. We call $\left(h,L\right)$ an aligned-configuration if $L/h\in\bZ^{+}$ or a non-aligned configuration otherwise.
\end{assumption}
%
We introduce the variational problem and the numerical counterpart as follows. Then, the numerical error is related to the interpolation error through the Cea's lemma.
\begin{defn}
Eqn. \ref{eq:1d-proof-strong} is understood in the following variational sense: find $u\in H_{0}^{1}\left(\Omega\right)$s.t. $\forall v\in H_{0}^{1}\left(\Omega\right)$,
\begin{equation}
\left\langle a\,u',v'\right\rangle _{L^{2}\left(\Omega\right)}=\left(f,v\right)_{H^{-1}\left(\Omega\right),H^{1}\left(\Omega\right)}\label{eq:1d-proof-variational}
\end{equation}
where $\left\langle \cdot,\cdot\right\rangle _{L^{2}}$ is the $L^{2}$-inner product and $\left(\cdot,\cdot\right)_{H^{-1},H^{1}}$ is the duality pairing. Given the piece-wise linear interpolation operator $I_{h}$ and $V_{h}:=I_{h}H_{0}^{1}\left(\Omega\right)$, the numerical solution $u_{h}\in V_{h}$ solves Eqn. \ref{eq:1d-proof-variational} with any $v_{h}\in V_{h}$.
\end{defn}
%

Since $u'$ is piecewise $H^{1}$ within each $\Omega_{j}$, we can obtain an $H^{2}$-norm estimate in an aggregated manner by integrating $u''$ on each sub-interval.
\begin{prop}
\label{prop:H2-aggregated-norm}Given $u$ solving Eqn. \ref{eq:1d-proof-variational}, the aggregated $H^{2}$-norm is bounded by
\[
\left|u\right|_{H^{2}}^{\dagger}:=\sqrt{\sum_{j=1}^{L^{-1}}\norm{u''}_{L^{2}\left(\Omega_{j}\right)}^{2}}\le\left(M+M^{3}\epsilon^{-1}+M^{5}\epsilon^{-1}\right)\norm f_{L^{2}}.
\]
Besides, the $L^{\infty}$ bounds are given by $\norm u_{L^{\infty}},\norm{u'}_{L^{\infty}}\le M\norm f_{L^{1}}+M^{3}\norm f_{L^{2}}$.
\end{prop}
\begin{proof}
We write the solution $u$ in its closed form $u\left(x\right)=\int_{0}^{x}a^{-1}\left(y\right)\left[F\left(y\right)+C\right]\d y$ where $F\left(x\right):=\int_{0}^{x}f\left(y\right)\d y$ and $C:=-\int_{0}^{1}\frac{F}{a}\d y/\int_{0}^{1}\frac{1}{a}\d y$. The second order derivative can be written explicitly as $u''=\frac{f}{a}-\left(F+C\right)\frac{a'}{a^{2}}$ for $x\in\Omega_{j}$. Since $F\left(x\right)$ vanishes at $x=0$, by Poincare inequality, $\norm F_{L^{2}}\le\norm f_{L^{2}}$ and subsequently $\norm{F\frac{a'}{a^{2}}}_{L^{2}}\le M^{3}\epsilon^{-1}\norm f_{L^{2}}$. Similarly, $\abs C\le M^{2}\norm F_{L^{1}}\le M^{2}\norm f_{L^{2}}$. Thus, the $H^{2}$-semi-norm can be bounded by
\[
\sum_{j=1}^{L^{-1}}\norm{u''}_{L^{2}\left(\Omega_{j}\right)}^{2}\le\left(M+M^{3}\epsilon^{-1}+M^{5}\epsilon^{-1}\right)^{2}\norm f_{L^{2}}^{2}.
\]
The $L^{\infty}$ bounds are derived by $\abs{u'}\le\abs{Fa^{-1}}+\abs C\abs{a^{-1}}\le M\norm f_{L^{1}}+M^{3}\norm f_{L^{2}}$ and $\abs{u\left(x\right)}\le\max_{\xi\in\left[0,x\right]}\abs{u'\left(\xi\right)}$.
\end{proof}
%
\begin{prop}
\label{prop:approximation-error}The approximation error is $\norm{u-I_{h}u}_{H^{1}}\le\sqrt{h^{4}+h^{2}}\left|u\right|_{H^{2}}^{\dagger}$ for aligned configurations. 
\end{prop}
\begin{proof}
The interpolation difference $\delta u:=u-I_{h}u$ vanishes on the boundary of each interval $\Delta_{i}:=\left(x_{i-1},x_{i}\right)$, thus by Poincare inequality
\begin{equation}
\norm{\left(u-I_{h}u\right)'}_{L^{2}\left(\Delta_{i}\right)}\le h\left|\left(u-I_{h}u\right)'\right|_{H^{1}\left(\Delta_{i}\right)}=h\left|u\right|_{H^{2}\left(\Delta_{i}\right)}\label{eq:H1 interpolation error}
\end{equation}
and subsequently
\begin{equation}
\norm{u-I_{h}u}_{L^{2}\left(\Delta_{i}\right)}\le h\left|u-I_{h}u\right|_{H^{1}\left(\Delta_{i}\right)}=h^{2}\left|u\right|_{H^{2}\left(\Delta_{i}\right)}.\label{eq:L2 interpolation error}
\end{equation}
Since $\Delta_{i}$ is always included in some $\Omega_{j}$ for aligned configurations, we have
\[
\sum_{i=1}^{h^{-1}}\norm{u-I_{h}u}_{H^{1}\left(\Delta_{i}\right)}^{2}\le\left(h^{4}+h^{2}\right)\sum_{i=1}^{h^{-1}}\left|u\right|_{H^{2}\left(\Delta_{i}\right)}^{2}\le\left(h^{4}+h^{2}\right)\left(\left|u\right|_{H^{2}}^{\dagger}\right)^{2}.
\]
\end{proof}
%
\sepia{Cea's lemma \cite[Theorem 12.3]{quarteroniNumericalMathematics2007} states that $\norm{u-u_{h}}_{H^{1}\left(\Omega\right)}\le2M^{2}\norm{u-I_{h}u}_{H^{1}\left(\Omega\right)}$ which helps to bound the error in solution by the interpolation error. Consequently, we obtain the $H^{1}$ and $L^{2}$ estimates by combining this with Prop. \ref{prop:H2-aggregated-norm} and \ref{prop:approximation-error}.}

\begin{thm}
\label{thm:L2-estimate}Given $h<\epsilon<L<1<M$, the $H^{1}$-error is $\norm{u-u_{h}}_{H^{1}}\le6\sqrt{2}M^{7}\epsilon^{-1}h\norm f_{L^{2}}$ and the $L^{2}$-error reads $\norm{u-u_{h}}_{L^{2}}\le36M^{13}\epsilon^{-2}h^{2}\norm f_{L^{2}}$. 
\end{thm}
\begin{proof}
We apply the Aubin-Nitsche duality method. Let $e:=u-u_{h}$ and we seek for solution $\phi$ to $\left\langle a\,\phi',\psi'\right\rangle =\left(e,\psi\right)$, $\forall\psi\in H_{0}^{1}\left(\Omega\right)$. Since $e$ is the residual, it is orthogonal to $w_{h}\in V_{h}$ in terms of the $a$-inner product, leading to
\[
\norm e_{L^{2}}^{2}=\left\langle a\,\phi',e'\right\rangle =\left\langle a\,e',\left(\phi-I_{h}\phi\right)'\right\rangle \le M\norm e_{H^{1}}\norm{\phi-I_{h}\phi}_{H^{1}}.
\]
By \ref{prop:approximation-error}, the interpolation error is bounded by $\norm{\phi-I_{h}\phi}_{H^{1}}\le\sqrt{2}h\left|\phi\right|_{H^{2}}^{\dagger}$ where the regularity is established in Prop. \ref{prop:H2-aggregated-norm} as $\left|\phi\right|_{H^{2}}^{\dagger}\le3M^{5}\epsilon^{-1}\norm e_{L^{2}}$ and $\norm{\phi}_{L^{\infty}},\norm{\phi'}_{L^{\infty}}\le2M^{3}\norm e_{L^{2}}$. Thus, we have $\norm e_{L^{2}}\le3\sqrt{2}hM^{6}\epsilon^{-1}\norm e_{H^{1}}$.
\end{proof}
%
\begin{rem*}
For non-aligned configurations, the asymptotic $L^{2}$-bound is of order $\cO\left(h\right)$, which is slower than the aligned counterpart. In practice, the alignment is easy to satisfy since one can pick any $L$ and set $h$ as any fraction of $L$ as long as they meet the scale condition (see Sec. \ref{subsec:Finite-element-approach}).
\end{rem*}
%
\begin{rem*}
In general, for dimension $d>1$, it is much more difficult to build analogies to the approximation result \ref{prop:approximation-error} since $u$ may not be in $H^{2}\left(\Omega_{j}\right)$ on the sub-domains. Another technical issue is posed by irregularity near vertices that are shared by neighboring elements. In fact, it is pointed out in \cite{ciarletDomainDecompositionMethods2017} that there exists an exponent $r_{\max}\in\left(0,1\right]$ s.t. $u\in H^{1+r}\left(\Omega_{j}\right)$ for $0\le r<r_{\max}$ and $\norm u_{H^{1+r}}\apprle\norm f_{L^{2}}$. A domain-decomposition based method is proposed to handle the missing regularity for the mixed problem.
\end{rem*}
%
We can now put the pieces together (Eqn. \ref{eq:full-error-estimate-tri} and \ref{eq:dilated-system-homogenization-error}, Prop. \ref{prop:dilation error estimate}, Cor. \ref{thm:L2-estimate}) and derive an error bound for the FEM solution to the dilated system.
\begin{thm}
\label{cor:fem-solver-full-error}For aligned 1d domain setups and assumptions made in Assump. \ref{assu:conditions on A}, Cor. \ref{thm:L2-estimate}, and Prop. \ref{prop:dilation error estimate}, there exists constants $r_{0}\left(\Omega,r,M,d\right)$ and $C$ depending on $\Omega,r,Q,d,M$ s.t. the full error is bounded by
\[
\norm{u_{D,h}^{\epsilon}-u_{0}}_{L^{2}\left(\Omega\right)}\le C\left[\epsilon^{-2}h^{2}+m\epsilon\ln\left(\frac{r_{0}}{m\epsilon}\right)+L\right].
\]
\end{thm}

\subsection{Numerical experiments\label{subsec:experiments}}

We present the following two numerical examples and verify the asymptotic orders of each error component. We also include an integrated test to compare the performance of methods of partial dilation, with or without scale identification, and local dilation.

\subsubsection{Examples set-up}

According to Eqn. \ref{eq:homogenization-operator-def} and \ref{eq:intro-homogenized-pde}, the homogenized solution $u$ can be solved as long as the homogenized tensor $\overline{A}$ is obtained. However, it involves solving $\chi$ from Eqn. \ref{eq:intro-cell-problem} which in general is a family of elliptic PDEs, rendering this approach computationally intractable in higher dimensions $d>1$. Nevertheless, a closed form solution can be obtained if the coefficient only depends on one of the fast coordinates, which is often referred to as the case of layered materials. Without loss of generality, we work with underlying dimension $d=2$. 

\paragraph{Layered material \label{par:Layered-material}}

We start with a case where a closed form for $\overline{A}$ is available (\cite[Sec. 12.6.2]{Grigorios2008}). For a given diffusion coefficient in the form of $A\left(x,\lambda\right)=A\left(x_{1},x_{2},\lambda_{1}\right)$, the homogenized tensor reads $\overline{A}_{11}=1/\left\langle 1/A_{11}\right\rangle $, $\overline{A}_{12}=\left\langle A_{12}/A_{11}\right\rangle /\left\langle 1/A_{11}\right\rangle $, and $\overline{A}_{22}=\overline{A_{12}}\overline{A_{21}}/\overline{A_{11}}-\left\langle A_{22}-A_{12}A_{21}/A_{11}\right\rangle $ where $\left\langle g\right\rangle \left(x_{1},x_{2}\right):=\int_{0}^{1}g\left(x_{1},x_{2},\lambda_{1}\right)\d{\lambda_{1}}$ is the averaging operation. 

For given tilting angle $\theta$ and intensity factor $\eta\in\left[0,1\right]$, let $A_{\text{lay}}^{\epsilon}$ denote 
\begin{equation}
A_{\text{lay}}^{\epsilon}\left(x_{1},x_{2};\eta,\theta\right):=\left[y_{1}\left(x_{1},x_{2}\right)+y_{2}\sin\left(\frac{2\pi}{\epsilon}\left(x_{1}\cos\theta-x_{2}\sin\theta\right)\right)\right]I_{2\times2}\label{eq:setting-layered 2cylinder smooth}
\end{equation}
where the diagonal entry reads $y_{1}\left(x_{1},x_{2}\right):=1+0.1x_{1}+0.05x_{2}$ and $y_{2}:=0.9\eta$. The source term reads
\[
f_{\text{lay}}\left(x_{1},x_{2}\right)=e^{-60\left(\left(x_{1}-0.3\right)^{2}+\left(x_{2}-0.3\right)^{2}\right)}+e^{-60\left(\left(x_{1}-0.7\right)^{2}+\left(x_{2}-0.7\right)^{2}\right)}.
\]
We shall point out that Eqn. \ref{eq:homogenization-operator-def} does not apply to $A_{\text{lay}}^{\epsilon}$ directly since the oscillation depends on the linear combination $X_{1}:=x_{1}\cos\theta-x_{2}\sin\theta$. A rotation is needed to obtain the correct homogenized tensor 
\[
\overline{A}_{\text{lay}}=U_{\theta}\overline{U_{\theta}^{T}A_{\text{lay}}^{\epsilon}U_{\theta}}U_{\theta}^{T},U_{\theta}:=\left(\begin{array}{cc}
\cos\theta & \sin\theta\\
-\sin\theta & \cos\theta
\end{array}\right).
\]


\paragraph{Material with heterogeneous oscillation \label{par:Material-with-heterogeneous}}

The second case is composed of oscillations that involves $x_{1}/\epsilon$ and $x_{2}/\epsilon$ and changing amplitudes from site to site. We define 
\begin{equation}
A_{\text{het}}^{\epsilon}\left(x_{1},x_{2};\eta\right)=\begin{bmatrix}1+\frac{1}{10}x_{1}+\frac{4}{5}\eta\left(\frac{4+x_{1}}{5}\right)s_{1} & \frac{1}{10}\eta\left(1-\frac{3}{10}x_{2}\right)s_{1}\\
\frac{1}{10}\eta\left(1-\frac{3}{10}x_{2}\right)s_{1} & 1+\frac{4}{5}\eta\left(\frac{7+3\sin\left(2\pi x_{2}\right)}{10}\right)s_{2}
\end{bmatrix}.\label{eq:setting-het osci2}
\end{equation}
The source term reads $f_{\text{het}}\left(x_{1},x_{2}\right)=10\left(x_{1}-x_{2}\right)$. The challenge lies in that for each evaluation of $\overline{A}_{\text{het}}\left(\widehat{x}_{1},\widehat{x}_{2}\right)$, one has to solve the parametrized cell problem and the cost can soon explode since the number of queries $\left\{ \left(\widehat{x}_{1},\widehat{x}_{2}\right)\right\} $ scales with the mesh size $h$ by $\cO\left(h^{-d}\right)$. One way to circumvent this situation is to exploit the regularity of $\overline{A}_{\text{het}}$ according to Lem. \ref{lem:HA regularity}. The cell problems are solved on a much coarser mesh and the homogenized tensor is interpolated at the query points. A figure containing solutions for finite $\epsilon$ is attached in Fig. \ref{fig:oscillatory solution}. The oscillatory solution $u^{\epsilon}$ can be decomposed into a smooth part $u_{0}$ and the first-order oscillation where the spatial frequency increases as $\epsilon\to0$.

