Defining such a decomposition gives us a characterization of $\omega$-iipomsets in terms of their prefixes.
We say that $A \in \ipoms$ is a (finite) \emph{prefix} of $P \in \infipoms$ if there is $Q \in \infipoms$ such that $P = AQ$, and then write $A \prf P$. We call $\pref{P}$ the set of all prefixes of $P$.


\begin{remark}
    Unlike classical $\omega$-words theory, two prefixes of $P$ may be incomparable, for example $a\ibu \prf \loset{a\\b}$ and $b\ibu \prf \loset{a\\b}$ but $a\ibu \not\prf b\ibu$ and $b\ibu \not\prf a\ibu$. But we still have the property that for $A \in \pref{P}$ and $x \in A$, if $y <_P x$ then $y \in A$.
\end{remark}

The following lemma is trivial in classical $\omega$-word theory, but here relies crucially on the fact that we deal with valid $\omega$-ipomsets. 


\begin{lemma}
\label{lem:pref-exist}
    If $(A_i)_{i \in I}$ is an infinite set of prefixes of an $\omega$-ipomset $P$, and $R$ is a finite subset of $P$ (seen as a set), then there is $i\in I$ such that $R \subset A_i$.
\end{lemma}
\begin{proof}
	Let $(A_i)_{i \in I} \in \pref{P}^I$ (with $I$ infinite). We want, for any $x \in R$, the set $\set{A_i \midbar x \in A_i} $ to be infinite (so  we can iteratively add all elements of a finite subset $R$). Let $x \in P$, and $P^m$ be (the antichain of) the minimal elements of $\set{x} \cup \set{p \in P \midbar x \not< p \text{ and } p \not< x}$, and $Q := P^m \cup \set{p \in P \midbar p < x}$. As $P$ is valid, $Q$ is finite, and so there is a finite number of ipomsets included in $Q$. Thus there is an infinite number of $A_i \sth A_i \cap (P - Q) \neq \emptyset$. In such $A_i$, let $y_i \in A_i \cap (P - Q)$. There is an element $z_i \in P^m \sth z_i < y_i$ (either $x < y_i$ or $y_i \in \set{p \in P \midbar x \not< p \text{ and } p \not< x}$). As $A_i$ is a prefix of $P$, $y_i \in A_i$ implies that $z_i$ is necessarily in $A_i - T_{A_i}$, and so $x \in A_i$ (otherwise $x \in B_i - S_{B_i}$ with $P = A_i*B_i$ and so $z_i < x$, which is impossible because $P^m$ is an antichain). So there are infinitely many $A_i$ such that $x \in A_i$.
\end{proof}
\begin{remark}
\label{rem:pref-counter-example}
    Note that $P$ is not necessarily  interval in Lem.~\ref{lem:pref-exist}. 
    It only suffices to have an infinite number of prefixes. However being an interval $\omega$-ipomset ensures the existence of an infinite set of prefixes, see below.
    For example, $P = a^\omega \parallel b^\omega \not\in \wiipoms$ has a finite number of prefixes: $\pref{P} = \set{a \ibu,b\ibu,\loset{a\ibu \\ b\ibu}}$, while $Q = (aa \parallel bb).c^\omega \not\in \wiipoms$ has an infinite number of prefixes: $ \pref{Q}\supseteq \set{(aa \parallel bb).c^n \midbar n \in \Nat}$.
\end{remark}
From Lem.~\ref{lem:pref-exist} follows a sequential characterization of interval $\omega$-ipomsets:
\begin{proposition}
\label{prop:seq-wiipoms}
    Let $P$ be an $\omega$-ipomset, the following are equivalent:
    \begin{enumerate}
        \item 
            $P$ is an interval $\omega$-ipomset;
        \item
            $\pref{P}$ is infinite and for all $A \in \pref{P}$, $A$ is an interval ipomset;
        \item
            an infinite number of prefixes of $P$ are interval ipomsets.
    \end{enumerate}
\end{proposition}


In addition, from the last point of Prop.~\ref{prop:seq-wiipoms} along with the preservation of the interval property by gluing composition (see~\cite[Lem.~41]{DBLP:journals/mscs/FahrenbergJSZ21}) we have the following:

\begin{corollary}
\label{cor:inf-product-interval}
    If $P = P_0 * P_1 * \cdots$ is a valid $\omega$-ipomset and $\forall i \in \Nat,\, P_i \in \iipoms$, then $P \in \wiipoms$.
\end{corollary}



\section{Higher-dimensional automata}

In this section, we recall  \emph{higher-dimensional automata} (\emph{HDAs}) over iipomsets~\cite{amrane.23.ictac, DBLP:journals/mscs/FahrenbergJSZ21, DBLP:journals/corr/abs-2210-08298} and introduce $\omega$-HDAs.
Recall that $\conc$ denotes the set of conclists.

\subsection{HDAs over finite ipomsets}
\label{sec:finite-HDA}

	A \emph{precubical set} is a structure $(X,\ev,\Delta)$ with:
	\begin{itemize}
		\item
		a set of cells $X$;
		\item
		a function $\ev : X \maps \conc$ which assigns to a cell its list of active events (for $U \in \conc$ we write $X[U] = \set{q \in X \midbar \ev(x) = U}$); 
		\item
		face maps $\Delta = \set{\delta_{A,U}^0,\,  \delta_{A,U}^1\midbar U \in \conc,\, A \subset U}$ such that $\delta_{A,U}^0,\delta_{A,U}^1 : X[U] \maps X[U-A]$;
		\item 
		for $A,B \subset U \sth A \cap B = \emptyset$ and $\mu, \nu \in \set{0,1}$, we have the following \emph{precubical identities}: $\delta_{A,U-B}^\mu \circ \delta_{B,U}^\nu = \delta_{B,U-A}^\nu \circ \delta_{A,U}^\mu$.
	\end{itemize}
We usually refer to a precubical set by its set of cells $X$, and for face maps we often omit the second subscript $U$. The \emph{dimension} of a cell $q \in X$ is the size $|\ev(q)|$.
An \emph{upper} face map $\delta_A^1$ terminates the events in $A$, whereas a \emph{lower} face map $\delta_A^0$ ``unstart'' these events, that is, it maps to a cell where the events of $A$ are not yet started. 

A \emph{higher-dimensional automaton} is a tuple $(X, \bot_X, \top_X)$ where $X$ is a \emph{finite} precubical set, and $\bot_X, \top_X\subset X$ are the sets of \emph{starting} and \emph{accepting} cells. 
We may omit the subscripts $_X$ if the context is clear, and refer to an HDA only by its precubical set.

\begin{example}
	\label{ex:hda}
    Fig.~\ref{fig:hda-first-example} shows a two-dimensional HDA as a combinatorial object (left) and in a geometric realisation (right).
    The arrows between the cells on the left representation correspond to the face maps connecting them.   
    It consists of nine cells: the corner cells $X_0 = \{x,y,v,w\}$ in which no event is active (for all $z \in X_0$, $\ev(z) = \emptyset$), the transition cells $X_1 = \{g,h,f,e\}$ in which one event is active ($\ev(f) = \ev(e) = a$ and $\ev(g) = \ev(h) = b$), and the square cell $q$ where $\ev(q) = \loset{a\\b}$.
    By convention, for $a \evord b$, we represent the event $a$ horizontally and the event $b$ vertically.
\end{example}

