A \emph{track} $\alpha$ in $X$ is a sequence $(q_0,\phi_1,q_1, \dots,\phi_n,q_n)$ where $q_i \in X$ are cells and $\phi_i$ denote face map types. That is, for all $i \leq n$, $(q_i,\phi_i,q_{i\+1})$ is:
\begin{itemize}
    \item
    either an \emph{upstep}: $(\delta_A^0(q_{i\+1}),\arrO{A},q_{i\+1})$ with $A \subset \ev(q_{i\+1})$,
    \item
    or a \emph{downstep}: $(q_i,\arrI{B},\delta_B^1(q_i))$ with $B \subset \ev(q_i)$.
\end{itemize}
The \emph{source} of  $\alpha$ is  $\src(\alpha) = q_0$ and its \emph{target} is $\tgt(\alpha) = q_n$. A track is \emph{accepting} if $\src(\alpha) \in \bot_X$ and $\tgt(\alpha) \in \top_X$.
Note that tracks are concatenations (denoted using $*$) of upsteps and downsteps. 
The language of an HDA is defined in terms of the event ipomsets of its accepting tracks.
Formally, the \emph{event ipomset} of a track $\alpha$ (written $\ev(\alpha)$) is defined by:
\begin{itemize}
    \item
        $\ev((q)) = \id_{\ev(q)}$ (with $q \in X$ and $(q)$ a single-cell track)
    \item
        $\ev((q,\arrO{A},p)) = \starter{\ev(p)}{A}$ (the starter which starts events $A$)
    \item
        $\ev((q,\arrI{B},p)) = \terminator{\ev(q)}{B}$ (the terminator which terminates events $B$)
    \item 
        $\ev(\alpha_1 * \dots * \alpha_n) = \ev(\alpha_1) * \dots * \ev(\alpha_n)$
\end{itemize}
We say that two tracks $\alpha$ and $\beta$ are equivalent, denoted $\alpha \simeq \beta$, with $\simeq$ the relation generated by the three cases $(x \arrO{A} y \arrO{B} z)\simeq (x \arrO{A\cup B} z)$, $(x \arrI{A} y \arrI{B} z) \simeq (x \arrI{A\cup B} z)$, and $\gamma \alpha \delta\simeq \gamma \beta \delta$ whenever $\alpha\simeq \beta$. Basically, two tracks are equivalent if their ``contractions'' into sparse tracks (i.e.\ alternating upsteps and downsteps) and event ipomsets are equal.

\begin{example}
\label{ex:tracks}
    The HDA $X$ of Fig.~\ref{fig:hda-first-example} admits several accepting tracks with target $h$, for example $v\arrO{ab} q\arrI{a} h$.
    This is a sparse track and equivalent to the non-sparse tracks $v\arrO{a} e\arrO{b} q\arrI{a} h$ and $v\arrO{b} g\arrO{a} q\arrI{a} h$.
    Their event ipomset is $\loset{a\nibu\\b\ibu}$.
    The track $v\arrO{a} e \arrI{a} w \arrO{b} h$ is also accepting with event ipomset $ab\ibu \subsu \loset{a\nibu\\b\ibu}$.
    In addition, since $g$ is both a start and accept cell, we have also $g$ and $v\arrO{b} g$ as accepting tracks, with event ipomsets $\ibu b \ibu$ and $b \ibu$, respectively.
    Note that tracks move forward along upper face maps but backward along lower ones.
   $X$ accept tracks whose ipomsets are in $\set{b\ibu,\ibu b\ibu,ab\ibu,\loset{a\nibu\\b\ibu}, \loset{a\\\ibu b\ibu},\ibu b a,\loset{\nibu a\\\ibu b},ab,ba,\loset{a\\b}}$.
\end{example}

The \emph{language} of an HDA $X$ is $L(X) = \set{\ev(\alpha) \midbar \src(\alpha) \in \bot_X \text{ and } \tgt(\alpha) \in \top_X}$. The following result about languages of HDAs is a fundamental property:

\begin{proposition}[{\cite[Prop.~10]{DBLP:conf/concur/FahrenbergJSZ22}}]
	\label{prop:HDA-down-closed}
	Languages of HDAs over finite ipomsets are closed under subsumption (or down-closed).
\end{proposition}

For $L \subset \ipoms$, we write $L \down = \set{P \in \iipoms \midbar \exists Q \in L,\, P \subsu Q}$ for the subsumption closure of~$L$.
For example, the language of Ex.~\ref{ex:hda} is $L(X)=\{b\ibu,\ibu b\ibu,\loset{a\nibu\\b\ibu}, \loset{a\\\ibu b\ibu},\loset{a\\b},\loset{\nibu a\\\ibu b}\}\down$.
Let us extend the notation to $R \subset 2^\ipoms$ with $R\down = \set{L\down \midbar L \in R}$.

Previous work \cite{DBLP:conf/concur/FahrenbergJSZ22} defines \emph{down-closed rational operations} $\cup$, $*\sd$, $\|\sd$ and (Kleene plus) $^{+\sd}$ for languages of finite iipomsets, as follows:
\begin{itemize}
\item $L *\sd M = \{P*Q\mid P\in L,\; Q\in M,\; T_P=S_Q\}\down$,
\item $L\parallel\sd M = \{P\parallel Q\mid P\in L,\; Q\in M\}\down$,
\item $L^{+\sd} = \bigcup\nolimits_{n\ge 1} L^n$, with $L^1=L$ and $L^{n+1}= L*\sd L^n$.
\end{itemize}
The class $\Drat$ of \emph{down-closed rational languages} is then defined to be the smallest class that contains $\emptyset$, $\set{\eps}$, $\set{a}$, $\set{\ibu a}$,$\set{a\ibu}$, $\set{\ibu a \ibu}$ (for $a\in \Sigma$), and is closed under the operations above. 
Note that the explicit downclosure $\down$ of the operations above ensures that the built languages contain only interval ipomsets.\footnote{
For $L = \set{ac}$ and $M = \set{\ibu b d \ibu}$, $(ac \parallel\ibu bd \ibu) \not\in L \parallel\sd M$ but, for example, the ipomsets of Fig~\ref{fig:interval-ipomset} are in $L \parallel\sd M$.
}
We will below introduce rational operations which \emph{do not} apply down-closure;
to distinguish them from the ones above we have added a subscript $\sd$.

\begin{theorem}[\cite{DBLP:conf/concur/FahrenbergJSZ22}]
  \label{th:kleene}
  A language in $2^\iipoms$ can be recognized by an HDA iff it is in $\Drat$.
\end{theorem}


\subsection{$\omega$-higher-dimensional automata}
\label{sec:def-wHDA}

An \emph{$\omega$-HDA} is an HDA whose tracks are infinite. 
Formally, an \emph{$\omega$-track} is an infinite sequence $\alpha = (q_0,\phi_1,q_1, \dots)$ where $q_i \in X$ and each $(q_i,\phi_i,q_{i\+1})$ is an upstep or a downstep. 
The event ipomset of an $\omega$-track is defined similarly using the infinite gluing. 
From this we may directly introduce the classical acceptance conditions of $\omega$-automata theory:

Let $\Inf(\alpha) = \set{q \in X \mid |\{i \midbar q_i = q\}| = + \infty}$ be the set of cells seen infinitely often by $\alpha$.
\label{def:Büchi-w-HDA}
    A \emph{Büchi} $\omega$-HDA is an HDA $(X, \bot_X, \top_X)$ where $ \bot_X, \top_X\subset X$ are the sets of \emph{starting} and \emph{accepting} cells, and where an $\omega$-track $\alpha$ is accepting if $\src(\alpha) \in \bot_X$ and $\Inf(\alpha) \cap \top_X \neq \emptyset$.
    Similarly,  a \emph{Muller} $\omega$-HDA is an HDA $(X, \bot_X, F_X)$ where $ \bot_X \subset X$ is the set of \emph{starting} cells and $F_X \subset 2^X$ is the set of \emph{accepting sets} of cells, and where an $\omega$-track $\alpha$ is accepting if $\src(\alpha) \in \bot_X$ and $\Inf(\alpha) \in F_X$.

\begin{example}
\label{ex:buchi}
	Büchi $\omega$-HDAs $X_1,X_2$ and $X_3$ are defined in Fig.~\ref{fig:buchi-example}. 
	Cells of the same color are identified in each $\omega$-HDA, and so are their respective faces (as required by the definition of precubical sets).
    Observe that $X_1$ and $X_2$ form a torus and $X_3$ a cylinder.
   Their languages will be specified later in the paper (see Ex.~\ref{ex:wrat-languages} and Ex.~\ref{ex:buchi-wform}). 
\end{example}

\begin{example}
\label{ex:muller}
    Let $X_4$ be the torus HDA of Fig.~\ref{fig:buchi-example} and assume $\bot_{X_4} = \{q_0\}$ and $F_{X_4} = \{\{q_0,q_{ab}\}\}$.
    Then $(X_4,\bot_{X_4},F_{X_4})$ defines a Muller $\omega$-HDA.
