Since the labeling $\lambda$ is coherent with $E$, a word produced by an ST-automaton $A$ is \emph{coherent} in the sense that if $P_1\cdot P_2\cdot \ldots$ is the label of a path in $A$, then $T_{P_i} \cong S_{P_{i\+1}}$ for all $i \geq 0$ (and thus it can be seen as the gluing of starters and terminators). To be more precise, the set of coherent finite words over $\Xib$ is denoted $\coh(\Xib) = \set{U_1\cdot \ldots \cdot U_n \midbar U_i \in \Xib,\ T_{U_i} \cong S_{U_{i\+1}}}$.
For $\omega$-words we denote by $ \wcoh(\Xib)$ the set of coherent infinite words over $\Xib$, defined by 
$${\wcoh(\Xib) = \set{U_1\cdot U_2 \cdot \ldots \midbar U_i \in \Xib,\ \#\set{i : U_i \not\in \Id} = + \infty \text{ and } T_{U_i} = S_{U_{i\+1}}}}$$
and as usual we write $\infcoh(\Xib) = \coh(\Xib) \cup \wcoh(\Xib)$.

\begin{lemma}
\label{lem:ST-coh}
    Let $A$ be an ST-automaton.
    \begin{itemize}
        \item
            If $A$ accepts finite words then $L(A) \subset \coh(\Xib)$.
        \item
            If $A$ accepts infinite words then $L(A) \subset \wcoh(\Xib)$.
    \end{itemize}
\end{lemma}

Thus, one can ``glue'' words accepted by an ST-automaton to obtain an ($\omega$-)iipomset.
Let $\Psi \colon \infcoh(\Xib) \to \wiipoms$ be the \emph{gluing function} defined by $\Psi(P_1 \cdot P_2 \cdot \dots) = P_1 * P_2 * \dots$.
For a set $L \subset \infcoh(\Xib)$, we also define $\Psi(L) = \set{\Psi(P) \midbar P \in L}$.
In \cite{PIPI}, the authors show the following for ST-automata derived from HDAs over finite iipomsets:
\begin{proposition}[\cite{PIPI}]
\label{prop:eq-ST-HDA}
    For any HDA $X$, $L(X) = \Psi(L(ST(X)))$.
\end{proposition}

We show  that the proposition holds also for $\omega$-HDAs. 
First, since the labeling of states is coherent with the transitions, we have the following by applying definitions.
\begin{lemma}
\label{lem:equiv-evalutation}
    For all $\omega$-tracks $\alpha$ of $X$, we have $\ev(\alpha) = \Psi(l(ST(\alpha))$.
\end{lemma}

We can now show the $\omega$-equivalent of Prop.~\ref{prop:eq-ST-HDA}, by combining Lem.~\ref{lem:equiv-path} and Lem.~\ref{lem:equiv-evalutation}:

\begin{proposition}
\label{prop:eq-ST-wHDA}
    For any (Büchi or Muller) $\omega$-HDA $X$, $L(X) = \Psi(L(ST(X)))$.
\end{proposition}

\subsection{$\omega$-HDAs are $\omega$-rational}
\label{sec:eq-ST-wHDA}

The formalism of ST-automata provides a strong tool for HDAs. 
It allows  to use classical theorems of $\omega$-automata. 
This helps in particular to show that $\omega$-regular languages are $\omega$-rational 	as we will see in this section.


Indeed, any ST-automaton $A$ can be represented by a rational expression $e_A$, using the operations $+,.\,,^*$ and letters $U_i \in \Xib$. 
Similarly, given an ST-automaton $A'$ over infinite words, one can effectively build an equivalent $\omega$-rational expression $e_{A'}$ \cite{mcnaughton1966testing}. 


A ($\omega$-)rational expression is said \emph{positive} if it has no occurrences of $^*$ and $\varepsilon$.
Since ST-automata do not accept $\varepsilon$, ST-automata languages can be expressed by positive expressions:

\begin{lemma}
\label{lem:positive-expression}
    Any rational expression $e$ of an ST-automaton can be transformed into a positive rational expression $\overline{e}$ such that $\mc{L}(e)=\mc{L}(\overline{e})$.
\end{lemma}


We define inductively a function $\Psi'$ transforming a positive rational expression over  $\Xib$  into a set of ipomsets in the usual way by replacing $\cdot$ by $*$.
We directly have:

\begin{lemma}
\label{lem:psi'-in-wrat}
    Let $e(U_1,...,U_n)$ be a positive rational expression over $\Xib$.
    \begin{itemize}
        \item
            If $e$ is rational, then $\Psi'(e) \in  \rat$.
        \item
            If $e$ is $\omega$-rational, then $\Psi'(e) \in  \wrat$.
    \end{itemize}
\end{lemma}

In addition, $\Psi'$ preserves languages:
\begin{lemma}
\label{lem:psi'-psi}
    If $e$ is an ($\omega$-)rational expression over $\Xib$, then $\Psi'(e) = \Psi(\mc{L}(e))$
\end{lemma}

Thus, languages of ST-automata are rational:
\begin{lemma}
\label{lem:ST-rat}
    Let $A$ be an ST-automaton.
    \begin{itemize}
        \item
            If $A$ accepts finite words, then $\Psi(L(A)) \in \rat$.
        \item
            If $A$ accepts infinite words, then $\Psi(L(A)) \in \wrat$.
    \end{itemize}
\end{lemma}


\begin{theorem}
    \label{th:w-rationality}
    Büchi and Muller $\omega$-regular languages are $\omega$-rational.
\end{theorem}

\begin{proof}
    Let $(X,\bot_X,F_X)$ be a Büchi or Muller $\omega$-HDA. By definition of $\omega$-HDAs, $X$ is finite, hence so is its ST-automaton $ST(X)$. By Prop.~\ref{prop:eq-ST-wHDA}, $L(X) = \Psi(L(ST(X)))$, and by Lem.~\ref{lem:ST-rat}, $\Psi(L(ST(X))) \in \wrat$, thus all $\omega$-regular languages are $\omega$-rational.
\end{proof}

As a corollary of the above and Prop.~\ref{prop:infrat-in-infiipoms} we have:

\begin{corollary}
\label{cor:Buchi-Muller-finite-width}
    If $L$ is an $\omega$-regular language, then $\ms{wd}(L) < +\infty$ and $L \subset \wiipoms$.
\end{corollary}

\begin{example}
\label{ex:wrat-languages}
    In Fig.~\ref{fig:ST-example} are represented two $\omega$-HDAs with their corresponding ST-automata. From this we can directly compute their language in $\Xib^\omega$ (we omit the letters in $\Id$), and then use $\Psi$ to compute the languages of the original Büchi $\omega$-HDAs:
    \begin{align*}
            L(ST(X_2)) =& \Big(
            a \ibu \cdot \ibu a + b \ibu \cdot \ibu b
            + 
            (a\ibu \cdot \loset{\ibu a\ibu \\ \nibu b\ibu} + \loset{a \ibu \\ b \ibu} + b\ibu \cdot \loset{\nibu a\ibu \\ \ibu b\ibu})
            \cdot
            (\loset{\ibu a\ibu \\ \ibu b\nibu} \cdot\loset{\ibu a\ibu \\ \nibu b\ibu} + \loset{\ibu a\nibu \\ \ibu b\ibu} \cdot\loset{\nibu a\ibu \\ \ibu b\ibu})^*
            \\
            &\cdot(\loset{\ibu a \ibu \\ \ibu b \nibu} \cdot \ibu a + \loset{\ibu a \\ \ibu b} + \loset{\ibu a \nibu \\ \ibu b \ibu} \cdot \ibu b)
            \Big)^\omega\\
             L(ST(X_3)) =&
            (b \ibu \cdot \ibu b)^*
            \cdot
            (a \ibu \cdot \loset{\ibu a \ibu \\ \nibu b \ibu} + b \ibu \cdot \loset{\nibu a \ibu \\ \ibu b \ibu} + \loset{ a \ibu \\ b \ibu})
            \cdot
            (\loset{\ibu a \ibu \\ \ibu b \nibu} \cdot \loset{\ibu a \ibu \\ \nibu b \ibu})^\omega
    \end{align*}
    Languages in $\wcoh(\Xib)$ can be turned into the language of the original HDA using the function $\Psi$ and Prop.~\ref{prop:eq-ST-HDA}. We just replace the occurrences of $A^*$ by $A^+ + \varepsilon$ and develop the expression to avoid the word $\varepsilon$, then remove multiple occurrences of the same ipomset in unions:
    \begin{itemize}
        \item 
            $L(X_2) = \Psi(L(ST(X_2))) = (a + b + \loset{ a \\ b } +\loset{ a \ibu \\ b \ibu } *  (\loset{\ibu a \ibu \\\ibu bb \ibu } + \loset{\ibu aa \ibu \\\ibu b \ibu })^+ * \loset{ \ibu a \\ \ibu b})^\omega$
        \item
            $L(X_3) = \Psi(L(ST(X_3))) = b^+ * \loset{ a \ibu \\ b \ibu } * \loset{ \ibu a \ibu \\ \ibu bb \ibu }^\omega + \loset{ a \ibu \\ b \ibu } * \loset{ \ibu a \ibu \\ \ibu bb \ibu }^\omega$
    \end{itemize}
\end{example}

As we saw in the previous section, our definition of rational operations is different from the original one \cite{DBLP:conf/concur/FahrenbergJSZ22} since  we do not take subsumption closure into account.
Nevertheless:
\begin{proposition}
\label{prop:finite-rationality}
    $\rat\down = \Drat$.
\end{proposition}
\begin{proof}
	The inclusion $\rat\down \subseteq \Drat$ is done by induction.
	The other follows from Lem.~\ref{lem:ST-rat} and the fact that languages of $\Drat$ are closed under subsumption (see App.~\ref{app:proof-w-HDA} for details).
\end{proof}

\subsection{Muller vs Büchi vs $\omega$-rational}


In the classical $\omega$-theory, rational languages are as expressive as Muller and Büchi automata.
For $\omega$-HDA, these are no longer true. We describe and prove here some differences:



\begin{theorem}
    \label{prop:Muller-vs-Büchi}
    The Muller $\omega$-regular class is strictly bigger than the Büchi $\omega$-regular class.
\end{theorem}

\begin{proof}
    As for the classical $\omega$-theory, Büchi $\omega$-regular languages are Muller $\omega$-regular.

    However, the reciprocal is false. Take the Muller $\omega$-HDA $X_4$ of Ex.~\ref{ex:muller}. The only cycle (up to shift) using only states of $F_{X_4}$ is $(q_0, \arrO{ab},q_{ab}, \arrI{ab}, q_0, ...)$, so the language of $X_4$ is such that every accepted $\omega$-ipomset ends by $\loset{a \\ b}^\omega$. Assume that there is a Büchi $\omega$-HDA $Y$ that recognizes $L(X_4)$. Let $\alpha$ be an accepting $\omega$-track of $Y$, which exists because $L(X_4) \neq \emptyset$. We have $\ev(\alpha)= A*\loset{a \\ b}^\omega$ for some $A \in \iipoms$. So $\alpha$ goes through $Y[\loset{a \\ b}]$ an infinite number of times. However $Y$ is finite, so there is $p \in Y[\loset{a \\ b}]$ such that $\alpha$ goes through $p$ an infinite number of times. Thus there is a subtrack $\alpha_p = (\delta^0_{ab}(p), \arrO{ab}, p, \arrI{ab}, \delta^1_{ab}(p))$ which appears an infinite number of times in $\alpha$. (It may be a track equivalent to it, but as there is a finite number of them, it suffices to choose one of them who is used an infinite number of times.) As $Y$ is a precubical set, we can define the track $\alpha'_p = (\delta^0_{ab}(p) ,\arrO{a}, \delta^0_b(p), \arrI{a}, \delta^1_a(\delta^0_b(p)), \arrO{b}, \delta^1_a(p), \arrI{b}, \delta^1_{ab}(p))$ with label $ab$, and then replace one in two occurrences of $\alpha_p$ by $\alpha'_p$. The cells visited an infinite number of times by $\alpha$ are still visited an infinite number of times, hence the new $\omega$-track is also accepting. However, its label does not end by $\loset{a \\b}^\omega$ because $ab$ appears an infinite number of times. So $L(X_4)$ is not Büchi $\omega$-regular.
\end{proof}

\begin{theorem}
    \label{prop:wrational-not-muller}
    Some languages of $\wrat$ cannot be expressed by Muller $\omega$-HDA.
\end{theorem}

\begin{proof}
    Let $L_r = (\loset{a \ibu \\ b\ibu} * \loset{\ibu a \\ \ibu b})^\omega = \loset{a \\ b}^\omega\in \wrat$. Suppose that $(X,\bot_X,F_X)$ is a Muller $\omega$-HDA such that $L(X)= L_r$. An accepting $\omega$-track $\alpha$ (with label $\ev(\alpha) = \loset{a \\ b}^\omega$) in $X$ must start by a track (equivalent to) $\alpha_p = (\delta^0_{ab}(p), \arrO{ab}, p, \arrI{ab}, \delta^1_{ab}(p))$ with $p \in X[\loset{a\\b}]$. As $X$ is a precubical set, $\alpha'_p = (\delta^0_{ab}(p) ,\arrO{a}, \delta^0_b(p), \arrI{a}, \delta^1_a(\delta^0_b(p)), \arrO{b}, \delta^1_a(p), \arrI{b}, \delta^1_{ab}(p))$ is well-defined. If $\beta$ is such that $\alpha = \alpha_p * \beta$, then $\alpha' = \alpha'_p * \beta$ is a track in $X$ which is accepting (as Muller acceptance conditions only care about states seen an infinite number of times). Then $\ev(\alpha') = ab\loset{a\\b}^\omega \in L(X)$ but $ab\loset{a\\b}^\omega \not\in L_r$, and we conclude by contradiction.
\end{proof}

Note that defining $\omega$-rational operations with subsumption closure (following~\cite{DBLP:conf/concur/FahrenbergJSZ22}) would have made
$\omega$-rational languages \emph{less} expressive than $\omega$-HDAs.
For example, as $\{\loset{a \\ b}\}\down = \set{ab, ba, \loset{a \\ b}}$, the language $L(X_4)$ of Ex.~\ref{ex:muller} would then not be $\omega$-rational.

As $\wrat$ is more expressive than Büchi and Muller $\omega$-HDAs, it is natural to inquire about the form of languages of $\wrat$ with the same expressiveness. 
As a first step, define a \emph{locally down-closed lasso} (\emph{ldl}) $\omega$-language to be a language of the form $\bigcup\nolimits_{i \leq n} M_i\down * ((R_i^+)\down)^\omega$ for $n \in \Nat$ and  $M_i, R_i \in \rat$ for all $i \leq n$.

\begin{theorem}
    \label{prop:buchi-wform}
    Any Büchi regular $\omega$-language is a locally down-closed lasso $\omega$-language.
\end{theorem}

Thus, $\omega$-HDAs allow local subsumptions in some finite factors coming from $M_i$ and $R_i^+$. 
Using $R_i^+$ instead of $R_i$ more accurately reflects the behaviour of Büchi $\omega$-HDAs.
Indeed, for $R = \set{ \loset{\ibu a \\ \ibu b} * \loset{a \ibu \\ b \ibu}}$ and $M= \loset{a \ibu \\ b \ibu}$, $M$ and $R$ are down-closed, but $M * R^\omega = M\down * (R\down)^\omega = \set{ \loset{a \\ b}^\omega}$ which cannot be recognized by a Büchi $\omega$-HDA as seen in the proof of Th.~\ref{prop:Muller-vs-Büchi}.


\begin{example}
\label{ex:buchi-wform}
  We can use again Ex.~\ref{ex:wrat-languages}, and take $L(X_3)$ which is Büchi $\omega$-regular:
    \begin{align*}
            L(X_3)  = b^+ * \loset{ a \ibu \\ b \ibu } * \loset{ \ibu a \ibu \\ \ibu bb \ibu }^\omega + \loset{ a \ibu \\ b \ibu } * \loset{ \ibu a \ibu \\ \ibu bb \ibu }^\omega = (b^+ + \eps) * \loset{ a \ibu \\ b \ibu } * (\loset{ \ibu a \ibu \\ \ibu bb \ibu }^+)^\omega 
    \end{align*}
    For $M =  (b^+ + \eps) * \loset{ a \ibu \\ b \ibu }$ and $R =\loset{ \ibu a \ibu \\ \ibu bb \ibu }$, we have $L(X_3) = M\down * ((R^+)\down)^\omega$.
\end{example}

