\begin{proof}[Proof of Proposition~\ref{prop:unicity-iso} (Unicity of well-ordering isomorphisms)]

	Let $(P,\mc{R}_P)$ and $(Q,\mc{R}_Q)$ be two well-ordered sets, and $f,g : P \maps Q$ two isomorphisms and suppose that $f \neq g$. Let $x$ be the $\mc{R}_P$-least element of $\set{ p \in P \midbar f(p) \neq g(p)}$. Let $q_1 = f(x)$ and $q_2 = g(x)$ (so $q_1 \neq q_2$), as $f$ and $g$ are bijections there is $a,b \in P \sth g(a) = q_1$ and $f(b) = q_2$. $\mc{R}_Q$ is total so either $q_1 \mc{R}_Q q_2$ or $q_2 \mc{R}_Q q_1$. If $q_1 \mc{R}_Q q_2$ then $g(a) \mc{R}_Q g(x)$, and because $g$ is an isomorphism of $\omega$-ipomsets, it implies that $a \mc{R}_P x$. By minimality of $x$, $f(a)=g(a)$ so $f(a) = f(x)$, by injectivity $a=x$ and so $q_1=g(a)=g(x)=q_2$, contradiction. Symmetrically, if $q_2 \mc{R}_Q q_1$, we get that $b=x$ and so $q_2=f(b)=f(x)=q_1$, contradiction.
\end{proof}


\begin{proof}[Proof of Lemma~\ref{lem:infinite-product-well-defined}]

	Let $(P_i)_{i \in \Nat} \in \ipoms^\Nat$ such that $S_{P_i} \cong T_{P_{i\+1}}$, $I = \set{i \in \Nat \midbar P_i \not\in \Id}$ is infinite and there is $m \in \Nat$ such that $\ms{wd}(P_i) \leq m$. We want to show that it is a valid $\omega$-ipomset.
	It is routine to check that $P = P_0 * P_1 * \cdots$ is well-defined, however it can be a finite ipomset (for example for a constant sequence in $\Id$), or can define a not valid $\omega$-ipomset.  
	\begin{itemize}
		\item Infinity:
		By contradiction, suppose $P$ is finite. If so, there is an index $i_0$ such that, for $i > i_0$, $P_i$ does not start any event. Let $Q = P_0 * ... * P_{i_0} \in \ipoms$. For $i \in I$, $P_i \not\in \Id$ so it has to start or finish at least one event. Let $I' = I \cap \set{i \in \Nat \midbar i > i_0}$, as $I$ is infinite, $I'$ is infinite. For $ i \in I'$, $P_i$ has to end at least one event of $Q$. But $|Q|$ is finite and $I'$ is infinite, contradiction.
		\item Finite past:
		Let $z \in P$, there is $j \sth z \in P_j$. By definition of $<_P$, if $y <_P z$ then there is $i \leq j$ such that $y \in P_i$. So the $<_P$-predecessors of $z$ are in $(\bigcup_{i \leq j} (P_i,i) )_{/x \sim f(x)}$ which is finite.
		\item No infinite $<_P$-antichain:
		Let $A$ be an $<_P$-antichain, then there is $i$ such that $A \subset P_i$. So $|A| \leq \ms{wd}(P_i) \leq m$, so there is no infinite $<_P$-antichain.
	\end{itemize}
	Thus, $P$ is a valid $\omega$-ipomset.
\end{proof}

The following lemma is needed for the proof of Prop.~\ref{prop:eq-wiipoms}:
\begin{lemma}
	\label{lem:<<-linear}
	Let $P \in \wipoms$ and $E$ be its set of maximal $<_P$-antichains. If $\ll$ is a linear order on $E$, then $(E,\ll) \cong (\Nat,<)$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:<<-linear}]
	We first show that $\ll$ is effectively a strict order. It is irreflexive by definition. Now suppose $A \ll B$ and $B \ll C$. If $A = C$ then $A \cup B$ is an antichain, and $A \neq B$ so $A$ or $B$ is not a maximal antichain, contradiction, so $A \neq C$. If there is $(a,c) \in A \times C$ such that $c < a$: either for all $b \in B$, $b \not< c$, then $c \in B$ (by $B \ll C$ and maximality of $B$), or we have $ b \in B$ such that $b < c$, so $b < a$ by transitivity of $<$. In both case, it leads to $A \not\ll B$, contradiction, so $\ll$ is transitive.

	We now show that $E$ is infinite and for all $A \in E$, there is only a finite number of $\ll$-predecessors of $A$. Firstly, $P$ is infinite, and is a valid $\omega$-ipomset so antichains are finite, thus $E$ is infinite.
	Now, let $D \ll A$, for all $d \in D$, either there is $x \in A \sth d < x$, or $d \in A$ (by maximality of $A$). So $D \subset A \cup \set{y \in P \midbar \exists x \in A \sth y < x}$. As $P$ is a valid $\omega$-ipomset, this set is finite, so there is only a finite number of $D \sth D \ll A$. 

	We can now show that $(E,\ll) \cong (\Nat,<)$: $E$ is not empty, so we take an element $A \in E$, it has a finite number of predecessors, and as $\ll$ is linear, it has a unique $\ll$-minimal element $A_0$. It is the minimal element of $E$, and we remove it. We can repeat the construction, and create a sequence $A_0 \ll A_1 \ll A_2 \ll ...$. Suppose an element $B \in E$ such that for all $i,\, A_i \neq B$. By construction, for all $i,\, A_i \ll B$, so $B$ has an infinite number of predecessors, which is impossible, so $E = \set{A_0,A_1,A_2...}$.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:eq-wiipoms}]
	We want to prove the equivalence between (1) $P$ is an interval $\omega$-ipomset, (2) $P$ has an interval representation and (3) the order $\ll$ on maximal antichains is linear.

	\begin{itemize}
		\item (2) $\implies$ (1) :
		Let $w,x,y,z \in P$ with $w <_P y$ and $x <_P z$. By (2) we take an interval representation $b,e$, then $e(w) < b(y)$, $e(x) < b(z)$. Suppose that $w \nless_P z$, by (2) $e(w) \nless b(z)$, as $<$ is linear on $\Nat \cup \set{+\infty}$, $b(z) \leq e(w)$, and thus $e(x) < b(y)$ so by (2), $x <_P y$. Thus, $w <_P z$ or $x <_P y$.        
		\item (1) $\implies$ (3) :
		Let $A$ and $B$ be two different maximal antichains and suppose that $A \not\ll B$ and $B \not\ll A$. Then there is $(x,y) \in A \times B$ such that $x < y $ and  $(x',y') \in A \times B$ such that $y' < x'$. By (1)  we have $x < x'$ or $y' < y$, but $A$ and $B$ are antichains, contradiction.
		\item (3) $\implies$ (2) :
		By Lem.~\ref{lem:<<-linear}, we can order the set $E$ of maximal antichains of $P$ such that $E = \set{ A_0,\, A_1,\, A_2,\,  ...}$ and $A_0 \ll A_1 \ll A_2 \ll ...$. We define $b(x) = \inf{i \midbar x \in X_i}$ and $e(x) = \sup{i \midbar x \in A_i}$. By definition we have $b(x) \leq e(x)$. Let $x,y \in P \sth x <_P y$, then for all $i < j$ if $x \in A_j$, we have $A_i \ll A_j$ so $y \not\in A_i$, and $y \not\in A_j$ (otherwise $X_j$ is not an antichain), thus $e(x) < b(y)$.  Let $x,y \in P \sth x \not<_P y$. Either $y <_P x$, then by the previous point $e(y) < b(x)$ and so $b(y) < e(x)$, or we have $y \not<_P x$ thus $\set{x,y}$ is include in a maximal antichain of $P$, then there is $i$ such that $x,y \in A_i$ and so $b(y) \leq i \leq e(x)$. Thus $x <_P y \equivalent e(x) < b(y)$.
	\end{itemize}
	So we have (1) $\equivalent$ (2) $\equivalent$ (3).
\end{proof}


Before proving Th.~\ref{th:sparse-dec} we need lemma that characterise the nature (starter versus terminator) of the first element of the decomposition (Lem.~\ref{lem:starter-vs-terminator}), and one that characterise it solely from the $P$ considered (Lem.~\ref{lem:def-start}). We define $P^m$ the $<_P$-minimal elements of $P$ (which can be seen as a conclist with the induced event order of $P$) and $P^s := \set{p\in P \midbar \forall q \in P - P^m,\, p < q} \subset P^m$.

\begin{lemma}
	\label{lem:po=pm}
	Let $ P = P_0 * P_1 * \dots$ be a sparse decomposition, then $P_0 = P^m$ (seen as conclists).
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:po=pm}]
	By definition, we already have that $P_0 \subset P^m$. Let's show that $P - P_0 \subset P - P^m$ (which is equivalent to $P^m \subset P_0$). Let $x \in P - P_0$, there is $i \geq 1 \sth x \in  P_i - S_{P_i}$.
	\begin{itemize}
		\item If $P_0$ is a (proper) terminator:
		it exists $y \in P_0 - T_{P_0}$ and thus $y < x$
		\item  If $P_0$ is a starter:
		then $P_1$ is a (proper) terminator so it exists $y \in P_1 - T_{P_1}$, and $i \geq 2$ (because $P_1 = S_{P_1}$), thus $y < x$
	\end{itemize}
	In both cases there is an element before $x$ so $x \not\in P^m$, so $P - P_0 \subset P - P^m$.
\end{proof}

\begin{lemma}
	\label{lem:starter-vs-terminator}
	Let $P = P_0 * P_1 * \dots$ be a sparse decomposition, then $P_0$ is a starter iff $S_P \subsetneq P^m$ (equivalently, $P_0$ is a terminator iff $S_P = P^m$).
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:starter-vs-terminator}]
	Using Lem.~\ref{lem:po=pm}, $P_0 = P^m$, and by definition $S_{P_0} = S_P$. Then we have that $P_0$ is a starter iff $ S_P = S_{P_0} \subsetneq P_0 = P^m$.
\end{proof}

\begin{lemma}
	\label{lem:def-start}
	Let $P = P_0 * P_1 * \dots$ be a sparse decomposition:
	\begin{itemize}
		\item
		If $P_0$ is a starter, $P_0 =\ \starter{P^m}{P^m - S_P}$
		\item
		If $P_0$ is a terminator, $P_0 = \terminator{P^m}{P^s}$
	\end{itemize}
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:def-start}]
	Using Lem.~\ref{lem:po=pm}, $P_0 = P^m$:
	\begin{itemize}
		\item
		If $P_0$ is a starter, by Lem.~\ref{lem:starter-vs-terminator} $S_P = S_{P_0} \subsetneq P_0 = P^m$ and so $P_0 = \starter{P_0}{P_0 - S_{P_0}} = \starter{P^m}{P^m - S_P}$.
		\item 
		If $P_0$ is a terminator, we want to show that $P^s = P^m - T_{P_0}$, thus $P_0 = \terminator{P^m}{P^s}$. First let $ p \in T_{P_0}$, then $ p \in S_{P_1} \subset P_1$. $P_1$ is a (proper) starter so there is $q \in P_1 -  S_{P_1}$ so $q \not\in P_0 = P^m$ and $p \not< q$ so $p \not\in P^s$, thus $P^s \subset P^m - T_{P_0}$. Then let $ p \in P^m - T_{P_0} = P_0 - T_{P_0}$ and $q \in P - P^m = P - P_0$, thus there is $i \geq 1 \sth q \in P_i - S_{P_i}$, so $p < q$. Thus $p \in P^s$ and $P^m - T_{P_0} \subset P^s$.
	\end{itemize}
	Which concludes the proof.
\end{proof}

We can now prove the fundamental decomposition of $\omega$-iipomsets:



\begin{proof}[Proof of Theorem~\ref{th:sparse-dec}]

	Let $P \in \wiipoms$, by Lem.~\ref{lem:<<-linear}, as $\ll$ is linear by Prop.~\ref{prop:eq-wiipoms}, we have that $X_0 \ll X_1 \ll \dots$ . For all $i \in \Nat$, we can define $E_i = X_i - X_{i\+1}$ and $B_i = X_{i\+1} - X_i$. As $X_i$ are maximal antichains, the sets are not empty and $\forall (x,y) \in E_i \times B_i,\, x <_P y$. We then define $U_{2i} = \terminator{X_i}{E_i}$ and $U_{2i\+1} =\ \starter{X_{i\+1}}{B_i}$ which are proper (the event order on $U_{2i}$ and $U_{2i\+1}$ is the one induced by $\evord_P$). If $S_P \subsetneq X_0$, we shift all indices by 1 and redefine $U_0 = \starter{X_0}{X_0 - S_P}$. Thus $U_0*U_1*U_2* \dots$ is a sparse decomposition, and it is routine to check that $P = U_0 * U_1 * U_2 \dots$, concluding of the existence of a sparse decomposition.

	Let $P = P_0 * P_1 * \dots = Q_0 * Q_1 * \dots$ be two different sparse decompositions. Without loss of generality, we can delete the common prefix and consider that $P_0 \neq Q_0$. If $S_P \subsetneq P^m$, by Lem.~\ref{lem:starter-vs-terminator} $P_0$ and $Q_0$ are (proper) starters, and by Lem.~\ref{lem:def-start}, $P_0 = \starter{P^m}{P^m - S_P} = Q_0$. If $S_P = P^m$, by Lem.~\ref{lem:starter-vs-terminator} $P_0$ and $Q_0$ are (proper) terminators, and by Lem.~\ref{lem:def-start}, $P_0 = \terminator{P^m}{P^s} = Q_0$, so contradiction.
\end{proof}

\begin{proof}[Proof of Propoposition~\ref{prop:seq-wiipoms}]
	We show the equivalence between (1) $P$ is an interval $\omega$-ipomset, (4) all prefixes of $P$ are interval ipomsets and $\pref{P}$ is infinite, and (5) an infinite number of prefixes of $P$ are interval ipomsets.

	\begin{itemize}
		\item (1)  $\implies$ (4) :
		Suppose for all $w,x,y,z \in P$ where $w < y$ and $x < z$, then $w < z$ or $x < y$. Then for all $A \in \pref{P}$, we have the same property for all  $w,x,y,z \in A \subset P$. Moreover, $\pref{P}$ is infinite as a direct consequence of the existence part of Th.~\ref{th:sparse-dec}.
		\item (4) $\implies$ (5) :
		Trivial.
		\item (5) $\implies$ (1) :
		Let $(A_i)_{i \in  I}$ be the infinite set of interval ipomsets in $\pref{P}$. Let $w,x,y,z \in P$ where $w < y$, $x < z$. By Lem.~\ref{lem:pref-exist}, there is a prefix $A_i$ with $\set{w,x,y,z} \subset A_i$, which is an interval ipomset, then $w < y$ or $x < z$.    
	\end{itemize}
	Which concludes the proof.
\end{proof}

\section{Complementary proofs of Section~\ref{sec:w-rat}}
\label{app:proof-w-HDA}

\begin{lemma}
	\label{lem:width-in-factor}
	Let $P$ be a (possibly not valid) $\omega$-ipomset, with a decomposition $P = P_1 * P_2 * ...$ and let $X$ be an antichain of $P$, then there is $i \in \Nat$ such that $X \subset P_i$
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:width-in-factor}]
	Let $P = P_1 * P_2 * ...$ be an $\omega$-ipomset. By definition of the gluing, this decomposition gives, for all $x \in X$, a non-empty subset $I_x = \set{i \in \Nat \midbar x \in P_i}$, which is an interval set (i.e. if $i,k \in I_x$ and $i \leq j \leq k$ then $j \in I_x$). Suppose there is no $i \in \Nat$ such that $X \subset P_i$, then there is $x,y \in X$ such that $m_x = \max(I_x) < \min(I_y) = m_y$. So $x \not\in T_{P_{m_x}}$ and $y \not\in S_{P_{m_y}}$. So by definition of the gluing, $x <_P y$. Thus by contraposition, if $X$ is an antichain, there is $i \in \Nat$ such that $X \subset P_i$.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{prop:wrat-finite-width}]
	The finite part of the theorem is straight forward, but for the operation $.^\omega$ we need to use the previous lemma. We recall that we cannot suppose $\omega$-ipomsets to be valid in this proof:

	\begin{itemize}
		\item
		$\ms{wd}(\emptyset) = \ms{sup}(\emptyset) = - \infty < + \infty$
		\item
		Let $U \in \Xi$, as $<_U$ is empty, $\ms{wd}(\set{U}) = |U| \in \Nat$
		\item
		Let $L,M \in \infrat$ such that $\ms{wd}(L) < + \infty$ and $\ms{wd}(M) < + \infty$, then we have that $\ms{wd}(L+M) = \max(\ms{wd}(L),\ms{wd}(M)) < + \infty$
		\item 
		Let $L \in \rat$ and $M \in \infrat$ such that $\ms{wd}(L) < + \infty$ and $\ms{wd}(M) < + \infty$, then $\ms{wd}(L*M) \leq \max(\ms{wd}(L),\ms{wd}(M)) < + \infty$
		\item
		Let $L \in \rat$ such that $\ms{wd}(L) < + \infty$, by previous point and recurrence, for all $n \geq 1$, $\ms{wd}(L^n) \leq \ms{wd}(L)$, so we have that $\ms{wd}(L^+) = \underset{n \in \Nat^*}{\max}(\ms{wd}(L^n)) \leq \ms{wd}(L)$ so $ \ms{wd}(L^+) < + \infty$
		\item
		Let $L \in \rat$ such that $\ms{wd}(L) < + \infty$. Let $P \in L^\omega$, then $P = P_1 * P_2 * ...$ with $P_i \in L$. Let $X$ be an antichain of $P$, then by Lem.~\ref{lem:width-in-factor} there is $i \in \Nat$ such that $X \subset P_i$. But $P_i \in L$ and $\ms{wd}(L) < + \infty$ so $|X| < + \infty$. So $\ms{wd}(P) < + \infty$ and thus $\ms{wd}(L^\omega) < + \infty$.
	\end{itemize}
	Thus, by induction, all languages in $\infrat$ have a finite width.
\end{proof}

\section{Complementary proofs of Section~\ref{sec:relation-of-w-languages}}
