\begin{proof}[Proof of Lemma~\ref{lem:ST-coh}]
	For an expression $e_A$ of finite words, we replace any occurrence of the Kleene star with the formula $L^* = \varepsilon + L^+$, and ``developp'' the expression. For ST-automaton $A$, $ \varepsilon \not\in L(A)$, the resulting expression after developing is such that there is no $\varepsilon$ anymore.

	For an $\omega$-rational expression $e_{A'}$, we know that $e_{A'}$ can be a finite union of the form $\bigcup X.Y^\omega$ with $X$ and $Y$ rational sets of finite words (see Th.~3.2 of~\cite{PePin04}). It suffices to show that we can remove the occurrences of $^*$ and $\varepsilon$ for an expression $X.Y^\omega$. We replace any occurrences of the Kleene star by $L^* = \varepsilon + L^+$. Then we develop the expression such that:
	\begin{itemize}
		\item
		If $\varepsilon \in X$, $X = \varepsilon + X'$ (with $\varepsilon \not\in X'$) and $X.Y^\omega = Y^\omega + X'.Y^\omega = Y.Y^\omega + X'.Y^\omega$
		\item
		If $\varepsilon \in Y$, $Y = \varepsilon + Y'$ (with $\varepsilon \not\in Y'$) and because of the definition of $^\omega$, we have $X.Y^\omega = X.Y'\ ^\omega$
	\end{itemize}
	Thus we can transform $e_A$ into a positive expression $\overline{e}_A$ (resp. $e_{A'}$ into $\overline{e}_{A'}$). For a formula over infinite words, it is moreover still of the form $\bigcup X.Y^\omega$.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:equiv-evalutation}]
	Let $\alpha = (q_0,\phi_0,q_1,...)$ be an $\omega$-track in $X$ and $ST(\alpha) = (q_0,e_0,q_1,...)$ with $e_i = (q_i,P_i,q_{i\+1})$. By definition:
	\begin{itemize}
		\item
		If $(q_i,\phi_i,q_{i\+1}) = (\delta_{A_i}^0(q_{i\+1}),\arrO{A_i},q_{i\+1})$, then $P_i = \ev(q_i,\phi_i,q_{i\+1})$
		\item
		If $(q_i,\phi_i,q_{i\+1}) = (q_i,\arrI{A_i},\delta_{A_i}^1(q_i))$, then $P_i = \ev(q_i,\phi_i,q_{i\+1})$
	\end{itemize}
	We recall that $\lambda$ is coherent, so for $(q_i,e_i,q_{i\+1}) \in E$ we have $\lambda(q_i) = T_{P_i}$, $\lambda(q_{i\+1}) = S_{P_{i\+1}}$, hence:
	\begin{align*}
		\ev(\alpha)
		&=\ \ev(q_0,\phi_0,q_1) * \ev(q_1,\phi_1,q_2) * \cdots
		=\ P_0 * P_1 * \cdots 
		=\ \id_{\lambda(q_0)} * P_0 * \id_{\lambda(q_1)} * P_1 * \cdots \\
		&=\ \Psi( \id_{\lambda(q_0)} \cdot P_0 \cdot \id_{\lambda(q_1)} \cdot P_1 \cdot \ldots) 
		=\ \Psi( l(ST(\alpha)) ) \qedhere
	\end{align*}
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:positive-expression}]
	Let $A = (Q,E,I,F,\lambda)$ be an ST-automaton. 
	As $\lambda$ is coherent with $E$, all interfaces coincide in a word produced by $A$. Then it remains to show that the languages does not contain not allowed words.

	If $A$ accepts finite words, then even for a path of one states $q$, the label contains at least the letter $\id_{\lambda(q)}$. Thus $\varepsilon \not\in L(A)$, and $L(A) \subset \coh(\Xib)$.


	If $A$ accepts infinite words, then for every infinite path, one letter out of two is in $\Xib \setminus \Id$, so there is an infinite number of non-identity letters, thus $L(A) \subset \wcoh(\Xib)$.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:psi'-psi}]
	This proof is done by induction.
	\begin{itemize}
		\item
		By definition of $\Psi'$, if $e = \emptyset$ then $\Psi'(\emptyset) = \emptyset = \Psi(\mc{L}(\emptyset))$ and if $e = U$ (for $U \in \Xib$) then $\Psi'(U) = \set{U} = \Psi(\mc{L}(U))$
		\item 
		If $e = e_1 + e_2$ with $\Psi'(e_1) = \Psi(\mc{L}(e_1))$ and $\Psi'(e_2) = \Psi(\mc{L}(e_1))$, then: 
		\begin{align*}
			\Psi'(e_1 + e_2) =&\ \Psi'(e_1) + \Psi'(e_2) \tag{definition of $\Psi'$}\\
			=&\ \Psi(\mc{L}(e_1)) + \Psi(\mc{L}(e_1)) \tag{induction hypothesis}\\
			=&\ \Psi(\mc{L}(e_1)+\mc{L}(e_1))\\
			=&\ \Psi(\mc{L}(e_1+e_2)) \tag{definition of $\mc{L}$}
		\end{align*}
		\item 
		If $e = e_1 . e_2$ with $\Psi'(e_1) = \Psi(\mc{L}(e_1)) \subset \coh(\Xib)$ and $\Psi'(e_2) = \Psi(\mc{L}(e_2)) \subset \infcoh(\Xib)$, then:
		\begin{align*}
			\Psi'(e_1.e_2) =&\ \Psi'(e_1) * \Psi'(e_2) \tag{definition of $\Psi'$}\\
			=&\ \Psi(\mc{L}(e_1)) * \Psi(\mc{L}(e_2)) \tag{induction hypothesis}\\
			=&\ \set{ P_1*...*P_n \midbar P_1...P_n \in  \mc{L}(e_1) \cap \coh(\Xib)}\\
			&\ *\set{Q_1*... \midbar Q_1... \in  \mc{L}(e_2) \cap \infcoh(\Xib)} \tag{definition of $\Psi$}\\
			=&\ \Psi(\set{ P_1...P_n.Q_1... \midbar P_1...P_n \in  \mc{L}(e_1),\, Q_1... \in  \mc{L}(e_2)}) \tag{definition of $\Psi$}\\
			=&\ \Psi(\mc{L}(e_1).\mc{L}(e_2))\\
			=&\ \Psi(\mc{L}(e_1.e_2)) \tag{definition of $\mc{L}$}
		\end{align*}
		\item 
		If $e = e_1^+$ with $\Psi'(e_1) = \Psi(\mc{L}(e_1)) \subset \coh(\Xib)$, then: 
		\begin{align*}
			\Psi'(e_1^+) =&\ \Psi'(e_1)^+ \tag{definition of $\Psi'$}\\
			=&\ \Psi(\mc{L}(e_1))^+ \tag{induction hypothesis}\\
			=&\ \bigcup_{n \geq 1} \Psi(\mc{L}(e_1))^n\\
			=&\ \bigcup_{n \geq 1} \Psi(\mc{L}(e_1^n)) \tag{previous point}\\
			=&\ \Psi(\mc{L}(\bigcup_{n \geq 1} e_1^n)) \tag{definition of $\Psi$ and $\mc{L}$}\\
			=&\ \Psi(\mc{L}(e_1^+)) 
		\end{align*}
		\item 
		If $e = e_1^\omega$ with $\Psi'(e_1) = \Psi(\mc{L}(e_1))$, then: 
		\begin{align*}
			\Psi'(e_1^\omega) =&\ \Psi'(e_1)^\omega \tag{definition of $\Psi'$}\\
			=&\ \Psi(\mc{L}(e_1))^\omega \tag{induction hypothesis}\\
			=&\ \set{ P_1* ... * P_n \midbar P_1...P_n \in \mc{L}(e_1) \cap \coh(\Xib)}^\omega \tag{definition of $\Psi$}\\
			=&\ \set{ U_1*U_2*... \midbar U_i \in \mc{L}(e_1) \cap \coh(\Xib),\, \#\set{i : U_i \not\in\Id} = + \infty ,\, T_{U_i} = S_{U_{i\+1}}} \tag{definition of $.^\omega$}\\
			=&\ \Psi( \set{U_1.U_2... \midbar U_i \in \mc{L}(e_1)\setminus\set{\varepsilon}})  \tag{definition of $\Psi$}\\
			=&\ \Psi(\mc{L}(e_1)^\omega) \\
			=&\ \Psi(\mc{L}(e_1^\omega)) \tag{definition of $\mc{L}$}
		\end{align*}
	\end{itemize}
	Which concludes the proof.
\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:ST-rat}]

	Let $A$ be an ST-automaton of finite words. The ST-automaton is finite, so by the classical Kleene theorem, $L(A)$ can be represented by a rational expression $e_A(U_1,...,U_n)$, written $e_A$ for simplification. We have $\mc{L}(e_A) = L(A)$. By Lem~\ref{lem:positive-expression} , we can suppose $e_A$ to be positive, and by Lem~\ref{lem:psi'-psi}, $\Psi(L(A)) =\Psi(\mc{L}(e_A)) = \Psi'(e_A)$. By Lem~\ref{lem:psi'-in-wrat}, $\Psi'(e_A) \in \rat$, so $\Psi(L(A)) \in \rat$.

	The same can be done for an ST-automaton of infinite words $A'$. By the $\omega$-Kleene theorem (for example shown in~\cite{PePin04}), $L(A')$ can be represented by a $\omega$-rational positive expression $e_{A'}$, with $\mc{L}(e_{A'}) = L(A')$, and we have $\Psi(L(A')) = \Psi(\mc{L}(e_{A'}) = \Psi'(e_{A'})$, and by Lem~\ref{lem:psi'-in-wrat}, $\Psi(L(A')) \in \wrat$.
\end{proof}

The following results are needed for the induction part of the proof of Prop.~\ref{prop:finite-rationality}:
\begin{lemma}
	\label{lem:rat-eq-*}
	For $L,M \subset \iipoms$, $(L * M)\down = L\down *\sd M\down$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lem:rat-eq-*}]
	Let $P \in (L * M)\down$, there is $A \in L$ and $B \in M$ such that $P \subsu A * B$. As $L \subset L\down$ and $ M \subset M\down$, $A*B \in L\down * M\down$ so $P \in (L\down * M\down)\down = L\down *\sd M\down$ and $(L * M)\down \subset L\down *\sd M\down$. 

	Let $Q \in  L\down *\sd M\down$, there is $A \in L\down$ and $B \in M\down$ such that $Q \subsu A*B$. There is $A' \in L$ such that $A \subsu A'$ and $B' \in M$ such that $ B \subsu B'$. By Lem.~48 of~\cite{DBLP:journals/mscs/FahrenbergJSZ21}, $A*B \subsu A'*B'$ and by transitivity, $Q \subsu A'*B'$. But we have $A'*B' \in L*M$, so $Q \in (L * M)\down$ and $L\down *\sd M\down \subset (L * M)\down$.
\end{proof}

\begin{corollary}
	\label{cor:rat-eq-+}
	For $L,M \subset \iipoms$, $(L^+)\down = (L\down)^{+\sd}$.
\end{corollary}

\begin{proof}[Proof of Proposition~\ref{prop:finite-rationality}]
	We start by showing that $\rat\down \subset \Drat$ by induction:
	\begin{itemize}
		\item
		$\emptyset\down = \emptyset \in \Drat$
		\item
		For $U \in \Xi$, $\set{U}\down = \set{U}$ (as $<_U$ is empty) and $\set{U} \in \Drat$ (by a finite use of $\parallel\sd$ and $\set{a \ibu}$ and $\set{\ibu a \ibu}$,  or $\set{\ibu a}$ and $\set{\ibu a \ibu}$, for $a \in \Sigma$)
		\item
		For $L,M \in \rat$, if $L\down,M\down \in \Drat$, then $(L+M)\down = L\down + M\down \in \Drat$
		\item
		For $L,M \in \rat$, if $L\down,M\down \in \Drat$, then $(L*M)\down = L\down *\sd M\down \in \Drat$ (by Lem.~\ref{lem:rat-eq-*})
		\item
		For $L \in \rat$, if $L\down \in \Drat$, then $(L^+)\down = (L\down)^{+\sd} \in \Drat$ (by Cor.~\ref{cor:rat-eq-+})
	\end{itemize}
	Then by induction $\rat\down \subset \Drat$.

	Next we show that $\Drat \subset \rat$, which is just a more detailed version of the Remark 7.3 of~\cite{DBLP:conf/concur/FahrenbergJSZ22}. Let $L \in \Drat$, by Th.~\ref{th:kleene} there is a HDA $X$ such that $L = L(X)$. Let $ST(X)$ be its ST-automata, by Prop.~\ref{prop:eq-ST-HDA} $L(X) = \Psi(L(ST(X)))$, and by Lem.~\ref{lem:ST-rat}, $\Psi(L(ST(X))) \in \rat$. Thus $\Drat \subset \rat$.

	But $L \in \Drat$, $L$ is down-closed (by Prop.~\ref{prop:HDA-down-closed} and Th.~\ref{th:kleene}) so as $L \in \rat$, $L = L\down \in \rat\down$. Then $\Drat \subset \rat\down$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{prop:buchi-wform}]
	We use the key property that language of a classical Büchi automaton $A = (Q,E,I,F)$ is of the form $\bigcup_{q_i \in I,\, q_f \in F} W(q_i,q_f).W(q_f,q_f)^\omega$, where $W(p,q)$ is the language of the Büchi automaton $(Q,E,\set{p},\set{q})$ (see~\cite{Farwer01} for more details).

	Let $(X,\bot_X,\top_X)$ be a Büchi $\omega$-HDA, and $ST(X) = (Q,E,I,F,\lambda)$ be its ST-automaton. Thus $L(ST(X)) = \mc{L}(\bigcup_{q_i \in I,\, q_f \in F} W(q_i,q_f).W(q_f,q_f)^\omega)$. To simplify, we write $W_1 = W(q_i,q_f)$ and $W_2 = W(q_f,q_f)$. As, $ W_2 = (W_2)^+ + \varepsilon$ so we have $L(ST(X)) = \mc{L} (\bigcup W_1.((W_2)^+)^\omega)$.

	But $\mc{L}(W_1)$ and $\mc{L}(W_2)$ are languages of ST-automata from HDAs (over finite tracks), so by Prop.~\ref{prop:finite-rationality} it exists $X,Y \subset \iipoms$ such that $\Psi(\mc{L}(W_1)) = X\down$ and $\Psi(\mc{L}(W_2)) = Y\down$. Then:
	\begin{align*}
		L(X) =&\ \Psi(L(ST(X))) \tag{Prop.~\ref{prop:eq-ST-wHDA}}\\
		=&\ \Psi( \mc{L} (\bigcup W_1.((W_2)^+)^\omega) )\\
		=&\ \Psi'( \bigcup W_1.((W_2)^+)^\omega )  \tag{Lem.~\ref{lem:psi'-psi}}\\
		=&\ \bigcup \Psi'(W_1) * (\Psi'(W_2)^+)^\omega \tag{definition of $\Psi'$}\\
		=&\ \bigcup \Psi(\mc{L}(W_1)) * (\Psi(\mc{L}(W_2))^+)^\omega \tag{Lem.~\ref{lem:psi'-psi}}\\
		=&\ \bigcup X\down * ((Y\down)^+)^\omega
	\end{align*}
	Which concludes the proof.
\end{proof}


