      \rtsem{\rctx,\form} & \defsym \{\rho \in \rtsem{\rctx} \mid \rtsem[\rho]{\form}\}
    \end{align*}
  \end{spec}

\caption{Interpretation of Formulae and Refinement Types.}
  \label{fig:semforms}
\end{figure}

\subsection{Soundness}
The following theorem presents the main technical result of this section, \emph{soundness of the
refinement type system}, informally, stating that typable terms adhere to their type specification.
Formally, the semantic interpretation of a typable term lies within the interpretation of its corresponding refinement type, as stated below. 
\begin{theorem}[Type soundness]\label{thm:rts}
  If $\rctx \INFr \te : \rty$ then
  $\ksem{\env}{\kost}{\te} \in \rtsem[\env]{\rty}$
  for every $\env \in \rtsem{\rctx}$.
  \qed
\end{theorem}
The notion of expected cost and expected values can be extended to open terms $\st \in \Terms$ as follows:
\[
  \ecost[\disto]{\st}(\sigma)\triangleq\ecost[\disto]{\st \sigma}\hspace{1mm}
\evalue[\disto]{\st}{\sigma} \triangleq \mathsf{evalue}_{\disto,\keg} (\st\sigma)
\]
where $\sigma$ is a substitution in $\mathsf{fv}(\st) \to \cValues$.
Given a substitution $\sigma =[\vec{\sv} / \vec{\sx} ]$, we use $\env_{\sigma}$ as a shorthand for the valuation $\emptyset\{\qetv{ \vec{\sx}}:=\qetv{\vec{\sv}} \}$.

From Theorems~\ref{thm:ecost} and~\ref{thm:rts} we have that the expected cost of a 
term belongs to the interpretation of the refinement type of its transformation applied to the continuation $\lambda \tx.0$.


\begin{theorem}\label{cor:ub:ecost}
Let $\Rext$ be the cost-structure $(\Rext,+)$.
Given $\st \in \Terms$, if $\vec{\tx} : \vec{\rty} \INFrr \qet{\st}{\lambda \tx.0} : \rty$, then for each $ \sigma$ s.t.
  $\env_\sigma \in \rtsem[][\Rext]{\vec{\tx} : \vec{\rty} }$, 
$ \ecost[\disto]{\st}(\sigma) \in \rtsem[{\env_\sigma}][\Rext]{\rty}.$
\qed
\end{theorem}
An upper bound is obtained as $ \ecost[\disto]{\st}(\sigma) \leq \lub \rtsem[\env_\sigma][\Rext]{\rty}$.

Similarly, for expected values, Theorems~\ref{thm:evalue} and~\ref{thm:rts} imply that the expected value of a 
term belongs to the interpretation of the refinement type of its transformation.

\begin{theorem}\label{cor:ub:value}
Let $\kost$ be the cost-structure $(\keg,\fplus)$.
Given $\st \in \Terms$, if $\vec{\tx} : \vec{\rty}, \cont : \rty'  \INFrk \qet{\st}{\cont} : \rty$, then for each $\sigma$ s.t.
  $\env_\sigma \in \rtsem[][\kost]{\vec{\tx} : \vec{\rty}}$ and for each $\te \in \Costfuns$ s.t. $\ksem{\env_\sigma}{\kost}{\te} \in \rtsem[\env_\sigma][\kost]{\rty'}$, 
$\evalue[\disto]{\st}{\sigma}(\lambda \tx.\ksem{\env_\sigma}{\kost}{\te \app \tx} )  \in  \rtsem[{\env_\sigma}\{\cont := \lambda \tx.\ksem{\env_\sigma}{\kost}{\te \app \tx} \}][\kost]{\rty}.$
\qed
\end{theorem}


\section{Examples}

In this section we demonstrate our methodology on three examples.
To ease their description, we will reason modulo semantical equivalence on cost terms. To this end, let
$\te \equiv \te'$ if $\te$ and $\te'$ are semantically equivalent, i.e., $\ksem{\env}{\kost}{\te} =\ksem{\env}{\kost}{\te'}$, for all valuation $\env$.


\vspace*{-0.1cm}
\subsection{Quantum cointossing cost analysis}\label{ss:cointoss}
\renewcommand{\cointoss}{\fun{ct}}
\newcommand{\COINTOSS}{\fun{CT}}
We start by re-visiting the simple cointossing example from the introduction and show
how our methodology can be used to reason about its expected cost.
To this end, re-consider the program $\cointoss : \qbty \multimap \qbty$ of the illustrating example, formally defined as
\begin{flalign*}
  & \cointoss \defsym
  \letrec{ct}{\sx}{
    \caseof**{\tick{(\meas \sx)}}
    [\inj_0(;\sx_0)]{\sx_0}
    [\inj_1(;\sx_1)]{ct \app \unary[H]{\sx_1}}
    }
\end{flalign*}
Towards the application of \Cref{cor:ub:ecost}, observe that
\begin{align*}
  \mparbox{5mm}{\qet{\cointoss \app y}{\lambda Z.\ \bzero}} \\
  & = \qet{y}{\lam{X_1}{\qet{\cointoss}{\lam{X_0}{X_0 \app X_1 \app (\lambda Z.\ \bzero)}}}} \\
  & \equiv \qetv{\cointoss} \app Y \app (\lambda Z.\ \bzero) \\
  & =
    \begin{lalign}
      \bigl(\letrec*{CT}{X, \cont}{
        \bun \cadd (\cont' \app \inj_0(\Meas{0}{X}) \cbary{X} \cont' \app \inj_1(\Meas{1}{X}))\bigr)
      } \\
      \eindent \app Y \app (\lambda Z.\ \bzero) \\
      \textit{where }
      \cont' = \lam{X}{
        \caseof*{\tx}
        [\inj_0(X_0)]{\cont \app X_0}
        [\inj_1(X_1)]{CT \app \unary[H]{X_1} \app \cont}
      }
    \end{lalign}
    \\
  & \equiv
    \begin{lalign}
      \bigl(\letrec*{CT}{X, \cont}{
        \bun \cadd (\cont \app \Meas{0}{X} \cbary{X} CT \app \unary[H]{(\Meas{1}{X})} \app \cont)\bigr)
      }\\
      \eindent \app Y \app (\lambda \tz.\ \bzero)
    \end{lalign}
    \\
  & \equiv \underbrace{\bigl(\letrec{CT}{X}{
    \bun \cadd (\bzero \cbary{X} CT \app \unary[H]{(\Meas{1}{X})})
    }\bigr)}_{\defsym\ \COINTOSS} \app Y
\end{align*}
Notice how, up-to the use of the operations of the cost structure, $\COINTOSS$ corresponds
exactly with the cost function defined in \Cref{ss:bev}.

To derive a tight refinement type for the above expression,
let us attribute to $\COINTOSS$ the refinement type
\[
  \rty \defsym (X:\qty) \Rightarrow \refine{\realty}{\tz \leq c(X)},
\]
where the function the function $c$ is yet to be determined.
Let $\rctx \defsym CT:\rty,X:\qty$.
Proceeding inside-out, using
Rules~\ref{rty:ax}, \ref{rty:meas}, \ref{rty:un}, respectively,
and a subtyping one can derive
$
  \rctx
  \INFrr \unary[H]{(\Meas{1}{X})}
  : \qty
,
$
\noindent thus $
  \rctx \INFrr \COINTOSS \app \unary[H]{(\Meas{1}{X})} :
  \refine{\realty}{\tz \leq c(\unary[H]{(\Meas{1}{X})})}
  \,,$  
with Rules~\ref{rty:ax} and \ref{rty:expe}. Using Rules~\ref{rty:bary}, and \ref{rty:real}
it follows that
\begin{align*}
  \rctx \INFrr \bzero \cbary{X} CT \app \unary[H]{(\Meas{1}{X})} :\{\tz : \realty \mid \exists \tz_0, \tz_1.
  \tz = \tz_0 \cbary{X} \tz_1 \land \tz_0 = \bzero \land \tz_1 \leq c(\unary[H]{(\Meas{1}{X})}) \},
\end{align*}
thus, by Rule~\ref{rty:RTsub},
\[
  \rctx
  \INFrr\!\!\!
  \bzero \cbary{X} CT \app \unary[H]{(\Meas{1}{X})} :
  \refine{\realty}{\tz \leq p_1(X) \times c(\unary[H]{(\Meas{1}{X})})}
  .
\]
Reasoning similarly using Rules~\ref{rty:opplus}
and \ref{rty:RTsub}, we derive
\begin{align*}
  \rctx
  \INFrr
  \bun \cadd  (\bzero \cbary{X} CT \app \unary[H]{(\Meas{1}{X})}) :
  \{ \tz : \realty \mid \tz \leq
  1 + p_1(X)
  \times c(\unary[H]{(\Meas{1}{X})})\},
\end{align*}
and thus via another application of Rule~\ref{rty:RTsub},
\[
  \rctx
  \INFrr
  \bun \cadd  (\bzero \cbary{X} CT \app \unary[H]{(\Meas{1}{X})}) :
  \refine{\realty}{\tz \leq c(X)}
  \,,
\]
\begin{equation}
 \label{eq:ct:constr}
 \text{provided }  \tag{\dag}
  \rctx \vDash \forall Z. \tz \leq 1 + p_1(X) \times c(\unary[H]{(\Meas{1}{X})}) \Rightarrow \tz \leq c(X) \,.
\end{equation}
Using that $\rty$ is admissible, this will permit us to derive
$\INFrr \COINTOSS : \rty$ by Rules~\ref{rty:rec} and \ref{rty:expi}. Observe that the
constraint \eqref{eq:ct:constr} can be shown to hold taking
$c(X) \defsym 1 + 2 \times p_1(X)$, since then
\begin{align*}
  1 + p_1(X) \times c(\unary[H]{(\Meas{1}{X})})
   = 1 + p_1(X) \times (1 + 2 \times p_1(\unary[H]{(\Meas{1}{X})}) 
   = 1 + p_1(X) \times (1 + 2 \times \tfrac{1}{2}) = c(X) \,.
\end{align*}
In conclusion $ \cdot \INFrr \COINTOSS : (X:\qty) \Rightarrow \refine{\realty}{\tz \leq 1 + 2 \times p_1(X)},$ 
and hence also $  Y : \qty \INFrr \COINTOSS \app Y : \{\tz \leq 1 + 2 \times p_1(Y)\}.$

Putting things together, by \Cref{cor:ub:ecost} certifies that
the expected cost of $\COINTOSS \app \ket{\psi}$ is bounded from above by $1 + 2 \times p_1(\ket{\psi})$.


\vspace*{-0.1cm}
\subsection{Higher-order quantum cointossing}\label{ss:qwalk}
\newcommand{\qwalk}{\ensuremath{\mathsf{qwalk}}}
\newcommand{\QWALK}{\ensuremath{\mathsf{QWALK}}}
To demonstrate that our methodology also encompasses a modular analysis of higher-order functions,
we consider a higher-order variation of $\cointoss$, $\qwalk :  \qbty \multimap  (\qbty \multimap \qbty)  \Rightarrow \qbty $, generalizing the Hadamard
gate applied at each iteration to an arbitrary quantum state transformation $f : \qbty \multimap \qbty$.
\begin{flalign*}
  & \qwalk \defsym
    \letrec{qw}{\sx\, f}{
    \caseof**{\tick{(\meas \sx)}}
    [\inj_0(;\sx_0)]{\sx_0}
    [\inj_1(;\sx_1)]{qw \app (f \app \sx_1) \app f}
    }
\end{flalign*}
Notice that $\cointoss \app \sy \equiv \qwalk \app \sy \app (\lambda X. \unary[H]{X})$.


Proceeding similar to the previous example, we obtain
\[
  \qet{\qwalk \app \sy \app g}{\lambda Z.\ \bzero}
  \equiv \QWALK \app Y \app G ,
\]
for
$
  \QWALK \defsym
  \letrec*{QW}{X\,F}{
    \bun \cadd (\bzero \cbary{X} F \app (\Meas{1}{X}) \app (\lambda X'. QW \app X' \app F)).
  }
$

Notice how the recursive call defines the continuation of
$F : \qbty \Rightarrow (\qbty \Rightarrow \realty) \Rightarrow \realty$.
As in the previous example, the central step lies now in attributing
a suitable refinement type to the recursive function. Specifically,
one can prove
\[
 \cdot \INFrr \QWALK :
  \begin{lalign}
    \forall c : (\qbty \Rightarrow \realty). ( X : \qbty)\\
    \Rightarrow
    \begin{lalign}
      (\refine{\qbty}{\tz = \Meas{1}{X}} \\
      \Rightarrow (X' : \qbty \Rightarrow \refine{\realty}{\tz \leq c(X')}) \\
      \Rightarrow \refine{\realty}{1 + (0 \bary{p_0(X)} \tz) \leq c(X)})
    \end{lalign} \\
    \Rightarrow \refine{\realty}{\tz \leq c(X)}\,.
  \end{lalign}
\]
The above type makes use of bounded quantification, with $c: \qbty \Rightarrow \realty$
referring to the expected cost of an invocation of $\QWALK$. This generality is essential,
the overall cost of $\qwalk$ essentially depends on the state transformation $f$, represented
by $F$ in $\QWALK$. The refinement type associated to this argument reflects the minimal
constraint necessary to derive an overall cost of $c(X)$.

To recover the bound inferred for $\cointoss \app y \equiv \qwalk \app y \app (\lambda X. \unary[H]{X})$, one instantiates the type of $\QWALK$
taking $c(X) = 1 + 2 \times p_1(X)$, observing that,
$\qetv{(\lambda X.\ \unary[H]{X})} = \lambda X.\lambda K.\ K \app (\unary[H]{X})$ can be typed as:
\[
  \cdot \INFrr \qetv{(\lambda X.\ \unary[H]{X})} :
  \begin{lalign}
      \refine{\qbty}{\tz = \Meas{1}{X}} \\
      \hspace{-4mm}\Rightarrow (X' : \qbty \Rightarrow \refine{\realty}{\tz \leq 1 + 2 \times p_1(X')}) \\
      \hspace{-4mm}\Rightarrow \refine{\realty}{1 + (0 \bary{p_0(X)} \tz) \leq 1 + 2 \times p_1(X)}
    \end{lalign}
\]



\vspace*{-0.1cm}
\subsection{Grover search}\label{ss:grover}
\newcommand{\grover}{\ensuremath{\mathsf{grover}_{f}}}
\newcommand{\GROVER}{\ensuremath{\mathsf{GROVER}_{f}}}
Grover's quantum search algorithm finds a marked item in an
unsorted database of $2^n$ items with a quadratic speedup over classical search.
It relies on two key operators: $U_f$ and $G$. The function $f : \mathbb{N} \to
\mathbb{B}$ determines whether an item is marked or not. The oracle operator $U_f$ flips the sign of the amplitude of the
marked state (encoding the solution to the search problem), while the
Grover operator $G$ amplifies the probability of the marked state.
Repeated application of $U_f$ to
flip the sign and $G$ to amplify the amplitude of the marked state continues
until a measurement is performed, revealing the solution with high probability
in $O(\sqrt{2^n})$ iterations.
The oracle $U_f$ for the function $f$ is defined by
$
  U_f\ket{x}\ket{y} = \ket{x}\ket{y \oplus f(x)}\textrm{, for }x\in\{0,1\}^n
$.
Thus, $U_f\ket{x}\ket{-} = (-1)^{f(x)}\ket{x}\ket{-}$.



Grovers algorithm, for fixed $f$ on a data-set of $n$ entries, is given by the term $\grover : \Nat \Rightarrow \qbty$ defined as:
\begin{flalign*}
  & \grover \defsym \letrec{grov}{m}{
    \caseof**{m}
     [\zero]{\ket{\psi_0} \ } 
     [\suc(m';\!)]{\unary[G]{(\unary[U_f]{(grov \app m'))}}}
  }
\end{flalign*}
where $
  G \triangleq 2\ket{\phi}\bra{\phi} - I
$ and $\ket{\psi_0}  \triangleq (H \ket{0})^{\otimes n} \otimes \ket{-}$.

We are interested in binding the error probability,
described by $\qet{\grover \app \ite}{\mathsf{err}}$ with the
term $\emptyset \INF err : \qbty \Rightarrow [0,1]$
measuring the error probability $1 - |\alpha_b|^2$, given 
a quantum state $\sum_{b_i \in \{0,1\}^n} \alpha_i \ket{b_i}$,
Specifically, we seek an upper-bound
depending on the number of iterations $\ite$.
Observe that $\qet{\grover \app \ite}{err}$ $\equiv \GROVER \app \ITE \app err$, where
\begin{flalign*}
& \GROVER \defsym
  \letrec*{GROV}{M\,K}{
     \caseof**{M}
        [\zero]{K \app \ket{\psi_0}}
        [\suc(M';\!)]{GROV \app M' \app (\lambda X.\ K \app \unary[G]{(\unary[U_f]{X})})}
  }
\end{flalign*}
We can ascribe $\GROVER$ the following type:
\[
  \cdot \INFr[(\Rext,\fplus)] \GROVER :
  \begin{lalign}
    \forall k: \qbty \Rightarrow [0,1].\\
    \ITE : \Nat \\
    \Rightarrow (X : \qbty \Rightarrow \refine{[0,1]}{Z \leq k(X)}) \\
    \Rightarrow \refine{[0,1]}{Z \leq k((\mathsf{G}\,\mathsf{U_f})^{\ITE} \,\ket{\psi_0})}
  \end{lalign}
\]
Thus, in particular,
\[
  \ITE : \Nat \INFr[(\Rext,\fplus)] \GROVER \app \ITE \app err :
  \{
  \begin{lalign}
    Z : [0,1] \mid \\
    Z \leq err((\mathsf{G}\,\mathsf{U_f})^{\ITE} \,\ket{\psi_0}) \} \,.
  \end{lalign}
\]
As one can show
$$\ksem{\{\ITE := i\}}{(\Rext,\fplus)}{err((\mathsf{G}\,\mathsf{U_f})^{\ITE} \,\ket{\psi_0})}=
\cos^2((2i+1)\sin^{-1}(\frac{1}{\sqrt{2^n}})),$$
the above typing thus binds the error probability of $\GROVER$ in terms
of the iteration count $i$.

\section{Conclusion}
We have developed an expectation-transformer analysis for a universal higher-order quantum programming language and shown that it can be instantiated as a refinement type system.
Future research will focus on sound implementations of these techniques as well as extending them to languages with quantum control.

