\section{Proof of Theorem~\ref{thm:rts} (Soundness of the Refinement Type System)}
In this section, we proof the Soundness of the refinement type system, that is, Theorem~\ref{thm:rts}.
We start by some technical lemmas.

\begin{lemma}[Term substitution]
  \label{lem:substCS}
  $\ksem{\env}{\kost}{\te[\tv/\tx]}=\ksem{\env\{\tx:=\ksem{\env}{\kost}{\tv}\}}{\kost}{\te}$.
\end{lemma}
\begin{proof}
  Straightforward induction on the structure of $\te$.
\end{proof}

\begin{lemma}[Formulae Substitution]
  \label{lem:fsubst}
    $\rtsem[\env]{\form[\tv/\tx]}=\rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\form}$.
\end{lemma}
\begin{proof}
  By induction on the structure of $\form$.
  \begin{itemize}
    \item Case $\rtsem[\env]{\prpred(\te_1,\ldots,\te_n)[\tv/\tx]}$: Using Lemma~\ref{lem:substCS}, we have
      \begin{align*}
	\rtsem[\env]{\prpred(\te_1,\ldots,\te_n)[\tv/\tx]}
	&=\rtsem[\env]{\prpred(\te_1[\tv/\tx],\ldots,\te_n[\tv/\tx])}
	\Leftrightarrow (\ksem{\env}{\kost}{\te_1[\tv/\tx]},\ldots,\ksem{\env}{\kost}{\te_n[\tv/\tx]})\in\rtsem{\prpred}\\
	&\Leftrightarrow (\ksem{\env\{\tx:=\ksem{\env}{\kost}{\tv}\}}{\kost}{\te_1},\ldots,\ksem{\env\{\tx:=\ksem{\env}{\kost}{\tv}\}}{\kost}{\te_n})\in\rtsem{\prpred}
	\Leftrightarrow \rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\prpred(\te_1,\ldots,\te_n)}
      \end{align*}
    \item All the other cases are straightforward.
      \qedhere
  \end{itemize}
\end{proof}

\begin{lemma}[Refinement Types Substitution]
  \label{lem:subst}
    $\rtsem[\env]{\rty[\tv/\tx]}=\rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\rty}$.
\end{lemma}
\begin{proof}
  By induction on the structure of $\rty$.
  \begin{itemize}
    \item Case $\rtsem[\env]{\refine{\rtb}{\form}[\tv/\tx]}$:
      Using Lemma~\ref{lem:fsubst}, we have
      \[
	\rtsem[\env]{\refine{\rtb}{\form}[\tv/\tx]}
	= \{ v \in \typesem{\rtb} \mid \rtsem[\env\{\tz := v\}]{\form[\tv/\tx]} \} 
	= \{ v \in \typesem{\rtb} \mid \rtsem[\env\{\tz := v,\tx:=\ksem{\env}{\kost}{\tv}\}]{\form} \} 
	= \rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\refine{\rtb}{\form}}
      \]
    \item Case $\rtsem[\env]{((\tx' \ofty \rty) \Rightarrow \rty')[\tv/\tx]}$:
      \begin{align*}
	&\rtsem[\env]{((\tx' \ofty \rty) \Rightarrow \rty')[\tv/\tx]} 
	= \{ f \in \typesem{\skel{\rty} \Rightarrow \skel{\rty'}} \mid \forall v \in \rtsem[\env]{\rty[\tv/\tx]},\ \apply(f,v) \in \rtsem[\env\{\tx := v\}]{\rty'[\tv/\tx]} \} \\
	&= \{ f \in \typesem{\skel{\rty} \Rightarrow \skel{\rty'}} \mid \forall v \in \rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}\}]{\rty},\ \apply(f,v) \in \rtsem[\env\{\tx := v,\tx:=\ksem{\env}{\kost}{\tv}\}]{\rty'} 
	= \rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{(\tx \ofty \rty) \Rightarrow \rty'}
      \end{align*}
    \item Case $\rtsem[\env]{(\forall \tx' \ofty \rty.\ \rty')[\tv/\tx]}$:
      \begin{align*}
	&\rtsem[\env]{(\forall \tx' \ofty \rty.\ \rty')[\tv/\tx]} 
	= \{ f \in \typesem{\skel{\rty'}} \mid \forall v \in \rtsem[\env]{\rty[\tv/\tx]},\ f \in \rtsem[\env\{\tx' := v\}]{\rty'[\tv/\tx]} \} \\
	&= \{ f \in \typesem{\skel{\rty'}} \mid \forall v \in \rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\rty},\ f \in \rtsem[\env\{\tx' := v\}]{\rty'} \} 
	= \rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\forall \tx' \ofty \rty.\ \rty'}
	\tag*{\qedhere}
      \end{align*}
  \end{itemize}
\end{proof}

\begin{lemma}[Subtyping soundness]\label{lem:subtypingSoundness}
  If $\rctx\INFs \rty \rsubtype \rty'$ then 
  $\rtsem[\env]{\rty} \subseteq \rtsem[\env]{\rty'}$ for every $\env \in \rtsem{\rctx}$.
\end{lemma}
\begin{proof}
  We proceed by induction on the size of the derivation.
  \begin{itemize}
      \item Rule \ref{rsubtype:refl}. This case is trivial by the reflexivity
	of the subset relation.

      \item Rule \ref{rsubtype:trans}. This case is trivial by the transitivity
	of the subset relation.

      \item Rule \ref{rsubtype:basic}, we have $\rctx\INFs
	\refine{\rtb}{\form} \rsubtype \refine{\rtb}{\formtwo}$ as a
	consequence of $\rctx\vDash \forall \tz^\rtb,\ \form
	\Rightarrow \formtwo$. Direct from the definition of $\vDash_\kost$.

      \item Rule \ref{rsubtype:arr}, we have $\rctx\INFs
	\tx:\rty_0\Rightarrow\rty_0' \rsubtype \rty_1\Rightarrow\rty_1'$ as a
	consequence of $\rctx\INFs \rty_1 \rsubtype \rty_0$ and
	$\rctx\INFs \rty_0' \rsubtype \rty_1'$.  We need to prove that
	$\forall\env\in\rtsem{\rctx}$,
	$\rtsem[\env]{\tx:\rty_0\Rightarrow\rty_0'}\subseteq\rtsem[\env]{\tx:\rty_1\Rightarrow\rty_1'}$.
	That is, $\forall f\in\typesem{\skel{\rty_0}\Rightarrow\skel{\rty_0'}}$
	such that $\forall v_0\in\rtsem[\env]{\rty_0}$,
	$\apply(f,v_0)\in\rtsem[\env\{\tx:=v_0\}]{\rty_0'}$, implies that
	$\forall v_1\in\rtsem[\env]{\rty_1}$,
	$\apply(f,v_1)\in\rtsem[\env\{\tx:=v_1\}]{\rty_1'}$.

	By the induction hypothesis,
	$\rtsem[\env]{\rty_1}\subseteq\rtsem[\env]{\rty_0}$, thus
	$\apply(f,v_1)\in\rtsem[\env\{\tx:=v_1\}]{\rty_0'}$, and since also by
	the induction hypothesis,
	$\rtsem[\env]{\rty_0'}\subseteq\rtsem[\env]{\rty_1'}$, we are done.
	\qedhere
  \end{itemize}
\end{proof}
\begin{proof}[Proof of Theorem~\ref{thm:rts} (Type soundness)]
  Theorem statement:
  \emph{If $\rctx \INFr \te : \rty$ then $\ksem{\env}{\kost}{\te} \in \rtsem[\env]{\rty}$ for every $\env \in \rtsem{\rctx}$.}

  Proof:
  We proceed by induction on the size of the derivation.
    \begin{itemize}
      \item Rule \ref{rty:ax}, we have $\rctx\INFr  \tx : \rty$ with
	$\tx:\rty\in\rctx$.  We need to prove that $\forall \env \in
	\rtsem[\env]{\rctx},\ \ksem{\env}{\kost}{\tx} \in \rtsem[\env]{\rty}$.
	That is, $\forall \env \in \{\env'\{\tx:=v\}\mid
	\env'\in\rtsem{\rctx\setminus\{\tx:\rty\}}, v\in\rtsem[\env']{\rty}\}$,
	we have $\env(\tx) \in \rtsem[\env]{\rty}$, which is trivial.

      \item Rule \ref{rty:expi}, we have $\rctx,\rctx'\INFr \lambda \tx.\ \te :
	(\tx \ofty \rty) \Rightarrow \rty'$ as a consequence of $\rctx, \tx :
	\rty,\rctx'\INFr \te : \rty'$, with $X\notin\mathsf{fv}(\rctx')$. 
	We need to prove that $\forall \env \in
	\rtsem{\rctx,\rctx'},\ \ksem{\env}{\kost}{\lambda \tx.\ \te} \in
	\rtsem[\env]{(\tx \ofty \rty) \Rightarrow \rty'}$.  That is, $\forall
	\env \in \rtsem{\rctx,\rctx'},\ \ksem{\env}{\kost}{\lambda \tx.\ \te}
	\in [\typesem{\skel{\rty}} \tocont \typesem{\skel{\rty'}}]$,
	equivalently, $\forall v \in \rtsem[\env]{\rty},\
	\ksem{\env\{X:=v\}}{\kost}{\te} \in \rtsem[\env\{\tx := v\}]{\rty'}$,
	which is true by the induction hypothesis.

      \item Rule \ref{rty:expe}, we have $\rctx\INFr \te \app \tv :
	\rty'[\tv/\tx]$ as a consequence of $\rctx\INFr \te : (\tx \ofty
	\rty) \Rightarrow \rty'$ and $\rctx\INFr \tv : \rty$.  We need
	to prove that $\forall \env \in \rtsem{\rctx},\
	\ksem{\env}{\kost}{\te \app \tv} \in \rtsem[\env]{\rty'[\tv/\tx]}$, or
	equivalently, $\apply(\ksem{\env}{\kost}{\te},\ksem{\env}{\kost}{\tv})
	\in \rtsem[\env]{\rty'[\tv/\tx]}$.

	By the induction hypothesis $\ksem{\env}{\kost}{\te} \in
	\rtsem[\env]{(\tx \ofty \rty) \Rightarrow \rty'}$ and
	$\ksem{\env}{\kost}{\tv} \in \rtsem[\env]{\rty}$.  Since, by
	Lemma~\ref{lem:subst},
	$\rtsem[\env]{\rty'[\tv/\tx]}=\rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\rty'}$,
	we are done.

      \item Rule \ref{rty:st}, we have
	$\rctx\INFr\ket{\psi}:\refine{\qbty}{\tz = \ket\psi}$.  We need
	to prove that $\forall \env \in \rtsem{\rctx},\
	\ksem{\env}{\kost}{\ket{\psi}} \in \rtsem[\env]{\refine{\qbty}{\tz =
	\ket\psi}}$, or equivalently, $\ket{\psi} \in \{
	v\in\typesem{\qbty}\mid\rtsem[\env\{\tz:=v\}]{\tz = \ket\psi} \}
	=\{\ket\psi \}$, which is trivial.

      \item Rule \ref{rty:un}, we have $\rctx\INFr
	\unary{\tv}:\refine{\qbty}{\tz = \unary{\tv} \land \form[\tv]}$ as a
	consequence of $\rctx\INFr \tv:\refine{\qbty}{\form}$.  We
	need to prove that $\forall \env \in \rtsem{\rctx},\
	\ksem{\env}{\kost}{\unary{\tv}} \in \rtsem[\env]{\refine{\qbty}{\tz =
	\unary{\tv} \land \form[\tv]}}$.  Since, by the induction
	hypothesis, $\form[{\ksem{\env}{\kost}{\tv}}]$ holds, we are done.

      \item Rule \ref{rty:prod}, we have $\rctx\INFr \tv_0\qtimes
	\tv_1:\refine{\qbty}{\tz = \tv_0 \qtimes \tv_1 \land \form_0[ \tv_0]
	\land \form_1[\tv_1]}$ as a consequence of $\rctx\INFr
	\tv_0:\refine{\qbty}{\form_0}$ and $\rctx\INFr
	\tv_1:\refine{\qbty}{\form_1}$.

	We need to prove that $\forall \env \in \rtsem{\rctx}$ we have
	$\ksem{\env}{\kost}{\tv_0\qtimes \tv_1} \in
	\rtsem[\env]{\refine{\qbty}{\tz = \tv_0 \qtimes \tv_1 \land \form_0[
	\tv_0]  \land \form_1[\tv_1]}}$.  Since, by the induction
	hypothesis, we have that $\form_0[\ksem{\env}{\kost}{\tv_0}]$ and
	$\form_1[\ksem{\env}{\kost}{\tv_1}]$ hold, we are done.

      \item Rule \ref{rty:cons}, we have $\rctx  \INFr
	\cons(\vec{\tv}):\refine[\tz]{\typ}{ \tz = \cons(\vec{\tz}) \land
	\overrightarrow{\land \form}}[\vec{\tv}/\vec{\tz}]$ as a consequence of
	$\rctx \INFr \overrightarrow{\tv} :
	\overrightarrow{\refine{\typ}{\form}}$ with $\cons :: \vec{\typ} \to
	\typ$.  We need to show that $\forall \env \in \rtsem{\rctx},\
	\ksem{\env}{\kost}{\cons(\vec{\tv})} \in
	\rtsem[\env]{\refine[\tz]{\typ}{ \tz = \cons(\vec{\tz}) \land
	\overrightarrow{\land \form}}[\vec{\tv}/\vec{\tz}]}$.  That is,
	$\ksem{\env}{\kost}{\cons(\vec{\tv})} \in
	\rtsem[{\env\{\vec{\tz}:=\ksem{\env}{\kost}{\vec{N}}\}}]{\refine[\tz]{\typ}{
	\tz = \cons(\vec{\tz}) \land \overrightarrow{\land \form}}}$.  Since,
	by the induction hypothesis, we have that
	$\overrightarrow{\form[\ksem{\env}{\kost}{\tv}]}$ holds, we are done.

      \item Rule \ref{rty:case}, we have
	$\rctx \INFr\caseof{\tv}[\cons(\vec{\tx})]{\te_0}[\txtwo]{\te_1}: \rty$ as a
	consequence of
	$\rctx\INFr \tv : \refine{\typ}{\form}$,
	$\rctx, \overrightarrow{\tx : \typ}; \form,\tv = \cons(\vec{\tx})
	\INFr \te_0 : \rty$, and
	$\rctx, \txtwo : \refine{\typ}{\form}; \txtwo = \tv,
	\forall \vec{X}^{\vec{\typ}}.\ \txtwo \neq \cons(\vec{\tx}) \INFr \te_1
	: \rty$, where $\cons :: \vec \typ  \to \typ$.

	We need to prove that $\forall \env \in \rtsem{\rctx},\
	\ksem{\env}{\kost}{\caseof{\tv}[\cons(\vec{\tx})]{\te_0}[\txtwo]{\te_1}}
	\in \rtsem[\env]{\rty}$. 
	That is, 
	$\ksem{\env\{\vec X:=\ksem{\env}{\kost}{\vec{\tv}}\}}{\kost}{\te_0} \in \rtsem[\env]{\rty}$ when $\ksem{\env}{\kost}{\tv} =
	\cons(\ksem{\env}{\kost}{\vec{\tv}})$ and
	$\ksem{\env\{\txtwo:=\ksem{\env}{\kost}{\vec{\tv}}\}}{\kost}{\te_1} \in
	\rtsem[\env]{\rty}$ otherwise; which are direct consequences from the
	induction hypothesis.

      \item Rule \ref{rty:rec}, we have $\rctx,\rctx'\INFr
	\letrec{\tf}{\tx}{\te} : \rrfty$ as a consequence of $\rctx,\tf:
	\rrfty,\rctx'\INFr  \lambda \tx .\te : \rrfty$, where
	$\text{Admis}(\rctx\INFwf  \rrfty)$ and $\tf\notin\mathsf{fv}(\rctx')$.
	We need to prove that
	$\forall \env \in \rtsem{\rctx,\rctx'}$,
	$\ksem{\env}{\kost}{\letrec{\tf}{\tx}{\te}} \in \rtsem[\env]{\rrfty}$.
	By the induction hypothesis, $\forall v\in\rtsem[\env]{\rrfty}$,
	$\ksem{\env\{\tf:=v\}}{\kost}{\lambda \tx .\te} \in
	\rtsem[\env\{\tf:=v\}]{\rrfty}$, and since $\text{Admis}(\rctx\INFwf  \rrfty)$, we are done.

      \item Rule \ref{rty:real}, we have $\rctx\INFr \breal{r} :
	\refine{\realty}{\tz = \breal{r}}$.  We need to prove that $\forall
	\env \in \rtsem{\rctx}$, $\ksem{\env}{\kost}{\breal{r}} \in
	\rtsem[\env]{\refine{\realty}{\tz = \breal{r}}}$, or equivalently,
	$\breal{r} \in \{v \in \Rext \mid \rtsem[\env\{\tz = v\}]{\tz =
	\breal{r}}\}$, which is trivial.

      \item Rule \ref{rty:opplus}, we have $\rctx\INFr \te_0 \cadd
	\te_1 : \refine{\kty}{\exists \tz_0^{\realty}, \tz_1^{\kty}.\ \tz =
	\tz_0 \cadd \tz_1 \land \form_0[\tz_0] \land \form_1[\tz_1]}$ as a
	consequence of $\rctx\INFr \te_0 : \refine{\realty}{\form_0}$
	and $\rctx\INFr \te_1 : \refine{\kty}{\form_1}$.

	We need to prove that $\forall \env \in \rtsem{\rctx}$,
	$\ksem{\env}{\kost}{\te_0 \cadd \te_1} \in
	\rtsem[\env]{\refine{\kty}{\exists \tz_0^{\realty}, \tz_1^{\kty}.\ \tz
	= \tz_0 \cadd \tz_1 \land \form_0[\tz_0] \land \form_1[\tz_1]}}$.
	Since, by the induction hypothesis,
	$\form_0[\ksem{\env}{\kost}{\te_0}]$ and
	$\form_1[\ksem{\env}{\kost}{\te_1}]$ hold, we are done.

      \item Rule \ref{rty:bary}, we have
	$\rctx\INFr \te_0\cbary{\tv} \te_1  : \{ \tz : \kty \mid
	{\exists \tz_0^{\kty}, \tz_1^{\kty}.\ \tz = \tz_0 \cbary{\tv} \tz_1
        \land \form_0[\tz_0 ] \land\form_1[\tz_1 ]\land \form_2[\tv ]}\}$
	as a consequence of
	$\rctx\INFr \te_0 : \refine{\kty}{\form_0}$,
	$\rctx\INFr \te_1 : \refine{\kty}{\form_1}$,
	and $\rctx\INFr \tv : \refine{\qbty}{\form_2}$.

	We need to prove that $\forall \env \in \rtsem{\rctx}$,
	we have
	\[\ksem{\env}{\kost}{\te_0\cbary{\tv} \te_1} \in \rtsem[\env]{\{ \tz :
	\kty \mid {\exists \tz_0^{\kty}, \tz_1^{\kty}.\ \tz = \tz_0 \cbary{\tv}
  \tz_1 \land \form_0[\tz_0 ] \land\form_1[\tz_1 ]\land \form_2[\tv ]}\}}\]
	Since, by the induction hypothesis, we have that
	$\form_0[\ksem{\env}{\kost}{\te_0}]$,
	$\form_1[\ksem{\env}{\kost}{\te_1}]$, and
	$\form_2[\ksem{\env}{\kost}{\tv}]$ hold, we are done.

      \item Rule \ref{rty:RTsub}, we have $\rctx\INFr \te : \rty$ as a
	consequence of $\rctx\INFr \te : \rty'$ and $\rctx\INFs \rty' \rsubtype
	\rty$.  We need to prove that $\forall \env \in \rtsem{\rctx}$,
	$\ksem{\env}{\kost}{\te} \in \rtsem[\env]{\rty}$.  By the induction
	hypothesis, $\ksem{\env}{\kost}{\te} \in \rtsem[\env]{\rty'}$ and by
	Lemma~\ref{lem:subtypingSoundness},
	$\rtsem[\env]{\rty'} \subseteq \rtsem[\env]{\rty}$, thus, we are done.

      \item Rule \ref{rty:Gen}, we have $\rctx,\rctx' \INFr \te : \forall \tx :
	\rty'.\ \rty$ as a consequence of $\rctx, \tx : \rty',\rctx'\INFr \te :
	\rty$, with $\tx \notin \mathsf{fv}(\rctx')\cup\mathsf{fv}(\te)$.  We
	need to prove that $\forall \env \in \rtsem{\rctx}$,
	$\ksem{\env}{\kost}{\te} \in \rtsem[\env]{\forall \tx : \rty'.\ \rty}$.
	That is, $\ksem{\env}{\kost}{\te} \in\typesem{\skel{\rty}}$ and
	$\forall v'\in\rtsem[\env]{\rty'}$,
	$\ksem{\env}{\kost}{\te}\in\rtsem[\env\{\tx:=v'\}]{\rty}$.  By the
	induction hypothesis, $\ksem{\env\{\tx:=v'\}}{\kost}{\te} \in
	\rtsem[\env\{\tx:=v'\}]{\rty}$, and since $\tx \notin
	\mathsf{fv}(\te)$, we are done.

      \item Rule \ref{rty:Inst}, we have $\rctx \INFr \te : \rty[\tv/\tx]$ as a consequence of
	  $\rctx \INFr \te : \forall \tx : \rty'.\ \rty$ and $\rctx \INFr \tv : \rty'$.
	  We need to prove that $\forall \env \in \rtsem{\rctx}$, $\ksem{\env}{\kost}{\te} \in \rtsem[\env]{\rty[\tv/\tx]}$, which, using Lemma~\ref{lem:subst}, is the same to prove that $\ksem{\env}{\kost}{\te} \in \rtsem[\env\{\tx:=\ksem{\env}{\kost}{\tv}\}]{\rty}$.
	  By the induction hypothesis, $\ksem{\env}{\kost}{\te} \in \rtsem[\env]{\forall \tx : \rty'.\ \rty}$ and $\ksem{\env}{\kost}{\tv} \in \rtsem[\env]{\rty'}$, thus, we are done.
	  \qedhere
    \end{itemize}
\end{proof}

