\end{proof}

Combining Lemma~\ref{lem:complexity_of_feasible_region_vertices} with the polygon clipping algorithm, we get a running time of $\Oh{n \log n}$ to compute the intersection between the previous feasible region and a visibility polygon.


% --------------------------------------------------------------------
\subsection{The last visible point}
\label{sec:greedy_segment_ext_last_edge}
% --------------------------------------------------------------------

When computing $\lastVisPoint{P}{F_{i - 1}}{e_{i - 1}}$, the input is a simple polygon $P$ with $n$ vertices, an edge $e_{i - 1} = \lrParents{v_{i - 1}, v_i}$, and a feasible region $F_{i - 1}$ with $f$ vertices where $v_{i - 1}$ is visible from all points of $F_{i - 1}$ and $v_i$ is not visible from any point of $F_{i - 1}$. 
The output is the point $y$ on $e_{i - 1}$ closest to $v_i$ visible from $F_{i - 1}$ and the guard $g \in F_{i - 1}$ that can see $y$. 
We first show that it suffices to consider only the vertices of $F_{i - 1}$.

\begin{lemma}
\label{lem:extending_on_last_edge_vertices_of_F_enough}
    Let ${P}$, ${F_{i - 1}}$, and ${e_{i - 1}}$ be defined as above. Then the vertices of ${F_{i - 1}}$ can see at least as far along ${e_{i - 1}}$ as all of ${F_{i - 1}}$.
\end{lemma}

\begin{proof}
    We prove the lemma by showing that points in the interior of ${F_{i - 1}}$ can see no further than points on the boundary $\partial {F_{i - 1}}$ which again can see no further than the vertices of ${F_{i - 1}}$.

    First, let $y_I$ be a point on ${e_{i - 1}}$ visible from a point $p_I$ in the interior.
    Clearly, the point of $\linesegment{p_I}{y_I} \cap {F_{i - 1}}$ with minimal distance to $y_I$ is a point on the boundary of ${F_{i - 1}}$ that can see $y_I$.

    Second, let $y_B$ be a point along $e_{i - 1}$ visible from a point $p_B$ on edge $(a, b)$ of the boundary of $F_{i-1}$ that can see $y_B$. 
    Note $F_{i - 1}$ cannot intersect the line $H := \lineextension{v_{i-1}}{v_i}$ defined by $e_{i - 1}$, since that would imply a point in $F_{i - 1}$ that can see $v_i$ contradicting the input assumption that $e_{i-1}$ cannot be seen from $F_{i-1}$. 
    Recall that $F_{i - 1}$ is connected by Lemma~\ref{lem:feasible_region_is_connected} which further implies that it must lie exclusively on one side of $H$. 
    If ${F_{i - 1}}$ is below $H$ then all points of $F_{i - 1}$ can see no further than $v_{i - 1}$.
    Otherwise, ${F_{i - 1}}$ is above $H$, and in particular edge $(a, b)$ of $F_{i-1}$ is above $H$. 
    Let $a$ (symmetrically $b$) be the vertex on the same side of the half-plane defined by $\lineextension{p_B}{y_B}$ as $v_{i - 1}$.
    By the contrapositive of Lemma~\ref{lem:convex_viewing_lemma} the triangle $\tri{p_B y_B v_{i - 1}}$ is inside $P$.
    Thus, if $a$ is in $\tri{y_B p_B v_{i - 1}}$ it can also see $y_B$.
    Otherwise, $a$ and $v_i$ lie on opposite sides of the half-plane defined by $(p_B, v_{i - 1})$. 
    See Figure~\ref{fig:extending_on_last_edge_vertices_of_F_enough} for an example of this case.
    Since $a$ can see $v_{i - 1}$, the triangle $\tri{a p_B v_{i - 1}}$ is also inside $P$ by the contrapositive of Lemma~\ref{lem:convex_viewing_lemma}.
    Thus, the segment from $a$ to $y_B$ is fully contained in triangles $\tri{a p_B v_{i - 1}}$ and $\tri{y_B p_B v_{i - 1}}$, which implies that $a$ can see $y_B$.
\end{proof}

