\begin{remark}
\label{rem:one_guard_is_not_enough}
    We will from now on always assume that $P$ is not star-shaped, as otherwise when we run the \Greedy algorithm it will find that the entire boundary can be covered by a single guard, which is clearly optimal.
    Thus, $\Gsc(x) \neq x$ for all $x \in \partial P$.
    Furthermore, the greedy interval $[x,\Gsc(x)]$ from any point $x \in \partial P$ always contains at least one edge, since a guard can be placed at the first vertex encountered from $x$.
\end{remark}

\begin{lemma}[Properties of visible intervals]
\label{lem:properties_of_Fc}
    \text{}
    \begin{enumerate}
        \item If $[a,b] \subseteq [c,d]$ and $[c,d] \in \Fc$ then $[a, b]\in \Fc$.
        \item $[x, \Gsc(x)] \in \Fc$.
        \item $[x,y] \subseteq [x, \Gsc(x)]$ if and only if $[x, y] \in \Fc$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    1. and 2. follow by definition.
    3. The only if implication follows directly from 1. and~2. For the if implication let $[x, y] \in \Fc$ and assume for contradiction that $[x,y] \not\subseteq [x, \Gsc(x)]$. Then $\Gsc(x)$ must be strictly before $y$, contradicting the maximality of \Greedy.
\end{proof}

Lemma~\ref{lem:properties_of_Fc} together with Remark~\ref{rem:one_guard_is_not_enough} acts as combinatorial axioms for our problem. Thus, for the rest of the section, we will use these to obtain properties of \Greedy.

\begin{lemma}
\label{lem:properties_of_greedy}
    Let $[a, b] \in \Fc$ and $x, y\in \partial P$, then
    \begin{enumerate}
        \item $[x, \Gsc(x)] \subseteq [a, b]$ implies $\Gsc(x) = b$.
        \item $x \in [a, b]$ implies $b \in [x, \Gsc(x)]$.
        \item If $[x,y] \subseteq [a,b]$, then $\Gsc(x) \in [b, \Gsc(y)]$.
    \end{enumerate}
\end{lemma}

