% --------------------------------------------------------------------
\section{\RepeatedGreedy, a geometric viewpoint}
\label{sec:the_greedy_algorithm_geometry}
% --------------------------------------------------------------------

In this section, we explore the behavior of Algorithm~\ref{alg:greedy} in the geometric setting.
We observe the behavior of the (local) greedy sequences by adapting the combinatorial optimality conditions Corollaries~\ref{cor:positive_fingerprint_is_optimal}, \ref{cor:escaping_an_interval_implies_optimal} and \ref{cor:periodicity_implies_optimal} to include geometric observations and finally show that the sequence contains an optimal solution within a polynomial number of revolutions.

First, Corollary~\ref{cor:positive_fingerprint_is_optimal}~and~\ref{cor:escaping_an_interval_implies_optimal} can be related in the geometric to when local greedy sequences move onto new edges:

\begin{definition}[Edge jumps]
    Let $(x_i^m)_{i = 0}^\infty$ be a local greedy sequence. We say that $(x_i^m)_{i = 0}^\infty$ is an \emph{edge jump} at $i$ if $x_i^m$ is a vertex of $P$ or $x_i^m$ and $x_{i+1}^m$ are in different edges of $P$ and neither is a vertex of $P$.
\end{definition}

\begin{lemma}[Maximal edge jumping]
\label{lem:maximal_edge_jumping}
    Let $(x_i^1)_{i =0}^\infty, \dots, (x_i^k)_{i=0}^\infty$ be the local greedy sequences. 
    If there are at least $n + 1$ edge jumps across all the local greedy sequences then some local greedy sequence $(x_i^m)_{i=0}^\infty$ will lie outside $[x_{m-1}, x_m]$ after these edge jumps.
\end{lemma}

\begin{proof}
    Let $n_m$ be the number of vertices of $P$ in $(x_{m-1},x_m)$ and $n_{k+1}$ the number of vertices in $(x_k,x_0)$. Then $\sum_{m = 1}^k n_m \leq \sum_{m=1}^{k+1} n_m \leq n$. 
    If the local greedy sequence $(x_i^m)_{i = 0}^\infty$ jumps $n_m + 1$ times it will at some point have passed $x_{m-1}$ and thus one of the points must lie in $[x_{m-2}, x_{m-1})$. 
    The lemma follows by the pigeonhole principle.
\end{proof}

This leads to a new progress condition based on edge jumps:

\begin{corollary}[Many edge jumps implies optimal] \label{cor:too_many_edge_jumps_will_force_greedy_sequence_to_be_optimal}
     Let $(x_i)_{i=0}^N$ be a greedy sequence whose local greedy subsequences $n + 1$ edge jumps. 
     Then the revolution after $x_N$ will be optimal.
\end{corollary}

\begin{proof}
    The proof is immediate from Lemma~\ref{lem:maximal_edge_jumping} and Corollary~\ref{cor:escaping_an_interval_implies_optimal}.
\end{proof}

\begin{remark}[Geometric progress conditions]
\label{rem:geometric_progresss}
    We establish three progress conditions on the basis of our combinatoric optimality conditions and extend them with geometric results. If one of these are satisfied, we discover an optimal solution or make progress towards one.
    \begin{enumerate}
    \item If we see a positive finger print, the greedy sequence is optimal (Corollary~\ref{cor:positive_fingerprint_is_optimal}).
    \item If we see a repetition in the greedy sequence, the sequence is optimal (Corollary~\ref{cor:periodicity_implies_optimal}).
    \item If we see $n+1$ edge jumps, the greedy sequence is optimal (Corollary~\ref{cor:too_many_edge_jumps_will_force_greedy_sequence_to_be_optimal}).
    \end{enumerate}
\end{remark}

The goal of the remainder of this section is to prove that we eventually make progress:

\begin{restatable}[\RepeatedGreedy will reach a progress condition]{theorem}{thmJumpEdgesOrRepeat}
\label{thm:repeatedgreedy_will_jump_edges_or_repeat}
    Running \Greedy for $\Oh{kn^2}$ revolutions guarantees the occurrence of a progress condition.
\end{restatable}

We will prove Theorem~\ref{thm:repeatedgreedy_will_jump_edges_or_repeat} by considering the local behavior of $\Greedy$ when applied to one local greedy sequence. We will need terminology to describe this; see Figure~\ref{fig:geometry_notation_overview}.

