\end{figure}

So we have at least one blockage between $z_i$ and $g_i$, the closest to $z_i$ we denote $C_{z,i}$.
If $y_{i+1}$ could see $g_i$, then $g_i$ could see $[y_{i+1},z_i]$, thus we would repeat in the greedy sequence (as $z_i = z_{i+1}$). Assuming this does not happen, there must be something blocking $g_i$ from $y_{i+1}$. We let $y_i'$ be the point on $\ell_y$ farthest up, which is still visible from $g_i$. As it is farther up, there must be some blockage between $y_i'$ and $g_i$, the closest to $y_i'$ we denote $C_{z,i}$.

We will refer to the points $C_{y,i}$ and $C_{z,i}$ as \emph{pivot points} and $\ell_i :=\lineextension{C_{y,i}}{C_{z,i}}$ the \emph{pivot line} for a given $i$. It is clear that $C_{y,i} \neq C_{z,i}$ so the pivot line is well defined.
The pivot points are all vertices of the polygon, thus there are at most $\Oh{n^2}$ possible pivot lines. In the following, we will look only at one pivot line at a time, and then run enough revolutions to see the same pivot line multiple times by the pigeonhole principle.

Finally, we track where we can place guards. For this, we define feasible regions:

\begin{definition}[Feasible region]\label{def:feasible_region}
    Let $y, z \in \partial P$and $\I{y}{z}$ the interval of $P$ from $y$ to $z$. 
    Then the \emph{feasible region} $\FeasibleRegion{\I{y}{z}}$ is the subset of $P$ of all possible guard placements that see $\I{y}{z}$.
    Specifically, $\FeasibleRegion{\I{y}{z}} \neq \emptyset$ if and only if$\I{y}{z} \in \Fc$.
\end{definition}

In the following, for a greedy step $\GscNEW{y_i} = z_i$ where $y_i$ and $z_i$ are on edges $\ell_y$ and $\ell_z$, we define $F := \FeasibleRegion{\I{y}{z}}$, where $y$ and $z$ are the endpoints of edges $\ell_y$ and $\ell_z$ contained in $[y_i, z_i]$. 


% --------------------------------------------------------------------
\subsubsection*{Strategy}
% --------------------------------------------------------------------

We briefly outline our approach, which is based on the relationship between the feasible region and the pivot line in a greedy step, $\GscNEW{y_i} = z_i$. 
In Section~\ref{sec:F_above_pivot_line}, we show that the case where $F$ is entirely above $\ell_i$ will lead to a progress condition. 
In Section~\ref{sec:F_under_pivot_line}, we show that if the feasible region $F$ contains points below $\ell_i$, then within the next revolution a different pivot line $\widehat{\ell_i}$ is visited, with corresponding feasible region $\widehat{F}$ entirely above $\widehat{\ell_i}$.


% --------------------------------------------------------------------
\subsection{Supporting lemmas}
% --------------------------------------------------------------------

Throughout this section, we will need the following two properties:

\begin{restatable}{lemma}{lemFeasibleRegionIsConnected}
\label{lem:feasible_region_is_connected}
    For any $a, b \in \partial P$, the feasible region $\FeasibleRegion{[a, b]}$ is connected. Furthermore, for any convex subset $C \subset P$, $C \cap \FeasibleRegion{[a,b]}$ is convex.
\end{restatable}

\begin{proofsketch}
    The proof follows by induction in the number of vertices in $[a,b]$. In the base case, the feasible region is a single visibility polygon, hence it is connected. In the induction step, we intersect the previous feasible region with a visibility polygon from a vertex $v_{i+1}$. If this new feasible region $F$ were to be disconnected, we find two points $S, T$ in different components of $F$, where $\linesegment{S}{T}$ is contained in a triangle completely visible to $v_{i+1}$, i.e. completely contained inside $P$. This will contradict Lemma~\ref{lem:convex_viewing_lemma} in Appendix~\ref{apx:feasible_region_connected} and thus $F$ will be connected. A similar argument shows in convexity claim.

    For the detailed proof, see Appendix~\ref{apx:feasible_region_connected}.
\end{proofsketch}

\begin{restatable}[Blockings happen outside visible area]{lemma}{lemBlockingCornerNotInView}
\label{lem:Blocking_corner_not_in_view}
    Let $y \in \partial P$ and $z = \Gsc(y)$ and assume that neither $y$ nor $z$ is a vertex of $P$. Let $g$ be a guard seeing $[y,z]$ and let $c$ be a vertex blocking the view from $g$ to $z$. Then $c \not \in [y, z]$. 
\end{restatable}

\begin{proofsketch}
    One considers what $g$ can see around $C$. It can be shown, that $g$ cannot see everything in the vicinity of $C$ (Lemma~\ref{lem:what_G_sees_around_C} in Appendix~\ref{apx:yz_cannot_block_z}). Assume for contradiction that $C \in [y,z]$, then either some part of $[y, z]$ is not visible from $g$ or $z$ can be moved to a visible vertex, yielding a contradiction.

    For the detailed proof, see Appendix~\ref{apx:yz_cannot_block_z}.
\end{proofsketch}


