\begin{lemma}[Successor and predecessor edges to $a \in F$ lie in $S(a)$]
\label{lem:successor_and_predecessor_edges_to_a_will_lie_in_Ta}
    Assume $F$ lies strictly above $\ell_i$ and let $a$ be a vertex of $F$ closest to $\ell_i$. Let $e$ and $f$ denote the edges of $F$ connected to $a$. Then $e, f \subseteq S(a)$.
\end{lemma}

\begin{proof}
    We will start by determining what characterizes edges in $F$. 
    Since $F$ is the intersection of the visibility polygons of vertices of $\partial P$, an edge of $F$ has to be an part of an edge of the visibility polygon to a vertex $v$.

    The edges of the visibility polygon from $v$ come in two ways: Either they come from shooting rays from $v$ through other vertices of $P$ or as edges of $P$.

    Assume for contradiction that $e$ or $f$ is not contained in $S(a)$. As the proof is symmetric, we assume $e \not \subseteq S(a)$, $e$'s other endpoint is $b$ and $b$ is closer to $C_{y,i}$ than $C_{z,i}$ (again by symmetry). Furthermore let $z$ be the last vertex of $[y_i, z_i]$, thus $z$ can see $F$ and hence also points $a$ and $b$. Now $e$ must either be a segment contained in a ray from a vertex $v \in [y_i, z_i]$ or $e$ is a part of $\partial P$.

    \begin{case}
        If $e \subseteq \ray{v}{a}$ we must have $v \in \lineextension{b}{a}$. For $z$ to see $a$, $z$ must lie above $\lineextension{b}{a}$ as $[v,z]$ would block it otherwise. However now we would need $z$ above $\lineextension{a}{C_{z,i}}$, which we disallow by Remark~\ref{rem:z_over_li}. Thus we arrive at a contradiction.
    \end{case}

    \begin{case}
        If $e$ is a part of $\partial P$, we can assume $F$ lies above $\lineextension{b}{a}$, since $a$ is a lowest point of $F$; see Figure~\ref{fig:z_cannot_see_a_and_b} (right). However, now $z$ cannot see $b$ as the space directly below $\linesegment{a}{b}$ is not inside $P$ and Remark~\ref{rem:z_over_li} forcing $z$ below $\lineextension{b}{a}$, leading to a contradiction.
        \popQED
    \end{case}
\end{proof}

