        \draw[black, decorate, decoration={brace, amplitude=1ex, raise=0.5ex}] 
        ($(A0)$) -- node[right, xshift = 0.15cm] {$\gamma$} ($(b)$);

        \draw[black, decorate, decoration={brace, amplitude=1ex, raise=0.5ex}] 
        ($(A2)$) -- node[above, yshift = 0.15cm] {$\delta$} ($(a)$);

    \end{tikzpicture}
    \caption{$P$ embedded into a coordinate system with coordinates marked. A guard placed in $(\delta, 0)$ can see no longer than $(-\sqrt{1/2}, 1 + \sqrt{1/2} - \gamma)$. Here $\gamma$ is the distance between the new point and the next vertex of $P$.}\label{fig:octagon_with_coordinates}
\end{figure}

Calculating, we get that the equation of the dashed line is:

\begin{align*}
 y = \left(\frac{\sqrt{2}+2\delta}{\sqrt{2}-1 +2\varepsilon + 2\delta}-1\right)(\delta - x) 
\end{align*}

Inserting $x = -\sqrt{1/2}$ in this equation will yield the y-coordinate, $y'$, of the intersection with the dashed line and the left vertical edge:

\begin{align*}
    y' &= \left(\frac{\sqrt{2}+2\delta}{\sqrt{2}-1 +2\varepsilon + 2\delta}-1\right)\left(\delta + \sqrt{\frac12}\right)\\
    &= \frac{1 + 2\sqrt{2}\delta + 2\delta^2}{\sqrt{2}-1 +2\varepsilon + 2\delta} - \sqrt{\frac{1}{2}} - \delta
\end{align*}

And now $\gamma$ is calculated as $\gamma = 1 + \sqrt{\frac{1}{2}} - y'$:
\begin{align*}
    \gamma &= \delta + \frac{2\delta - 2\delta^2 + (2 + 2\sqrt{2})\varepsilon}{\sqrt{2}-1 +2\varepsilon + 2\delta}\\
    &\in (\delta, 7\delta + 12\varepsilon)
\end{align*}

We now chooce $\varepsilon = \frac1{2 \cdot 12 \cdot 8 ^ {2N}}$ where $N$ is some large number. Consider the sequence $(\gamma_i)_{i=0}^{2N}$ of distances from the furthest visible point and the next vertex when taking such steps. Note that in Figure~\ref{fig:octagon_with_coordinates} we have, say, $\delta=\gamma_i$ and $\gamma = \gamma_{i+1}$, i.e. the $\delta$ is the member of the of the $\gamma_i$ sequence that precedes $\gamma$. The above bound then becomes $\gamma_{i+1} \in (\gamma_{i},7\gamma_{i}+12\varepsilon)$ and especially $\gamma_i < \gamma_{i+1}$ hence the associated local greedy sequences will have negative fingerprints and no repetitions.

Furthermore we show by induction that $\gamma_i < \frac1{2 \cdot 8^{2N - i}}$ as $\gamma_0 = 0$ and if $\gamma_i < \frac1{2 \cdot 8^{2N - i}}$, we get:
\begin{align*}
    \gamma_{i+1} &< 7 \gamma_i + 12 \varepsilon\\
    &= \frac7{2\cdot 8^{2N-i}} + \frac1{2\cdot 8^{2N}}\\
    &\leq \frac1{2\cdot 8^{2N-(i+1)}}
\end{align*}
And we thus have $\gamma_i \in [0, 1)$ for all $\gamma = 0,1,\dots, 2N$, thus for all the guards will be on the same two edges, i.e. we get no edge jumps. Thus in the first $N$ greedy steps we do not reach a geometric progress condition. 

Since $N$ is independent of $n$ the runtime of \RepeatedGreedy is unbounded in the real RAM model.

\end{example}




