\infer{ts\to t's}{t\to t'} &\qquad& 
\infer{\lambda x.\,t\Dar \lambda x.\,t}{} && 
\infer{ts\Dar v}{t\Dar\lambda x.\,t'\quad t'[s/x]\Dar v} 
