\begin{example}\label{exa:non-sep}
Consider a language over the signature $\{f/1,g/1,\Omega/0\}$ where $/n$ indicates 
that the arity of the corresponding operation is $n$. Consider the following 
small-step specification:
%
\begin{gather*}		
		\frac{}{g(x) \stackrel{y}{\to} f(y)} \qquad\qquad
		\frac{}{\Omega \to \Omega}  \qquad\qquad
		\frac{x \to y}{f(x) \to g(y)} \qquad\qquad
		\frac{x \stackrel{x}{\to} y}{f(x) \to x} 
\end{gather*}		
which identifies $g$ as a value former and $f$ and $\Omega$ as computation formers.
This specification yields a separated abstract HO-GSOS law, in which the only 
argument of $f$ is necessarily strict, because the behaviour of $f(t)$ generally depends 
on the behaviour of $t$. The only way to define big-step rules would be as follows:
%
\begin{gather*}
\infer{g(x) \Dar g(x)}{} \qquad\qquad
\infer{f(x) \Dar v}{x \Dar g(y)&\qquad g(y)\Dar v}
\end{gather*}
%
The equivalence~\eqref{eq:sem-eq} now fails, because $f(f(g(\Omega))) \to g(g(\Omega))$, 
but $f(f(g(\Omega))) \Dar g(\Omega)$. 
%
%
%
%
%
%
%
%
%
%
%
%
\exend\end{example} 
%
%

\subsection{Categorical Modeling} \label{sec:cat}
%
The reasoning of the previous section is not sufficiently precise in various respects. 
Haskell provides a very concrete type-theoretic ambient with general recursion
and other features we might want or not want to include, but in any case we need 
to be conscious about them. This is particularly important for constructing proofs,
an aspect, we completely omitted so far, but which we consider as the main contribution.
The above treatment of \xCL can be naturally formalized in the category of sets,
using a suitable \emph{partiality monad}~\cite{ChapmanUustaluEtAl15,AltenkirchDanielssonEtAl17,Goncharov21} for modeling iteration and recursion. 
More generally, one would need other categories: multisorted sets for typed languages,
categories of presheaves or nominal sets for the $\lambda$-calculus, the corresponding 
combinations and extensions thereof. It is also not necessary to restrict to partiality
as the only effect -- one can treat nondeterministic or even probabilistic semantics 
in a similar manner. We thus generally work with \emph{strong $\omega$-continuous monads},
which are arguably the largest semantically relevant class of monads that support iteration 
via least fixed points~\cite{GoncharovSchroderEtAl18}.

We then recall and/or fix relevant categorical notations and conventions in order. 
For the basics of category theory we refer to~\cite{Mac-Lane78,Awodey10}. 
%
In a category~$\BC$,~$|\BC|$ will denote the 
class of objects and~$\BC(X,Y)$ will denote the set of morphisms from~$X$ to~$Y$. The judgement 
$f\c X\to Y$ will be regarded as an equivalent to $f\in\BC(X,Y)$ if $\BC$ is clear
from the context.
%
%
%
We will denote by $\id_X$, or simply $\id$ the identity morphism on~$X$. 
In what follows, we generally work in an ambient distributive category~$\BC$ (as defined below). 
By $|\BC|$ we refer to the objects of $\BC$. We tend to
omit indexes at natural transformations for better readability. 
%
%
\emph{Dinatural transformations} generalize natural transformations to 
the case of mixed variance functors. More precisely, given two functors $F,G\c\BC^\op\times\BC\to\BD$,
a family of morphisms $\alpha = (\alpha_{X,Y}\c F(X,Y)\to G(X,Y))_{X,Y\in |\BC|}$ is a dinatural transformation
if the diagram
%
%
\begin{equation*}
\begin{tikzcd}[column sep=3em, row sep=1em]
&
F(X,X)
	\rar["{\alpha_{X,X}}"]
&
G(X,X)
	\ar[dr,"{G(\id,f)}"]
\\
F(Y,X) 
	\ar[ur,"{F(f,\id)}"]
    \ar[dr,"{F(\id,f)}"'] 
	& & & 
G(X,Y)
\\
&
F(Y,Y)
	\rar["{\alpha_{Y,Y}}"]
&
G(Y,Y)
	\ar[ur,"{G(f,\id)}"']
\end{tikzcd}
\end{equation*} 
%
commutes for any $f\c X\to Y$. A prototypical example of a dinatural transformation is the evaluation transformation $Y^X\times X\to Y$.


Some further notions we will need are as follows.

%
\myparagraph{Distributive categories} %
A \emph{distributive category} is a category with finite products and coproducts, 
and such that every morphism $[\id\times\inl,\id\times\inr]\c X\times Y + X\times Z\to X\times (Y+Z)$ is an isomorphism.
%
%
%
Let $\nabla=[\id,\id]\c X+X\to X$ and let $\dl$ be the functor $\BC\to\BC\times\BC$,
sending~$X$ to $(X,X)$. Moreover, let $\Fst,\Snd\c\BC\times\BC\to\BC$ be the 
obvious projections.

\myparagraph{Functors and algebras} We involve three types of (endo-)functors: the usual 
unary covariant functors $F\c\BC\to\BC$, bifunctors $F\c\BC\times\BC\to\BC$ and
mixed variance functors $F\c\BC^\op\times\BC\to\BC$. Given a functor $F\c\BC\to\BC$
in a distributive category~$\BC$, the \emph{(pointwise) free monad} $F^\star\c\BC\to\BC$ 
over $F$ is characterized by a universal property: for any object $X$ there are 
morphisms $\iota_X\c F(F^\star X)\to F^\star X$, and $\eta_X\c X\to F^\star X$, such 
that for any $f\c FY\to Y$ and $g\c X\to Y$ the diagram 
%
\begin{equation*}
\begin{tikzcd}[column sep=3em, row sep=normal]
F(F^\star X)
	\rar["\iota_X"] 
	\dar["{F(\init[f,g])}"']
&
F^\star X
	\dar["{\init[f,g]}"]
&[4em]
X
\lar["\eta_X"']
\ar[dl,"g"]
\\
FY
	\rar["f"] 
&
Y
&
\end{tikzcd}
\end{equation*}
%
commutes for precisely one morphism $\init[f,g]$. It follows that $\iota_X$ and $\eta_X$
are natural in~$X$. By generalities (Lambek's theorem), $[\eta,\iota]$ is an isomorphism. 
For every $X$, $F^\star X$ is also called a \emph{free (F-)algebra}
on $X$. We can often think of~$F^\star X$ as an object of terms with variables from $X$
and with operations from~$F$, and of $\mu F=F^\star\iobj$ as an object of closed terms thereof. 
This is specifically true for \emph{polynomial functors},
i.e.\ functors of the form $FX=\coprod_{f\in Ops} X^{\ar(f)}$ where $Ops$ is a 
set of operations~$f$ of corresponding arities $\ar(f)$. One example is the functor 
\begin{align*}
  F X
  = \underbrace{1+1+1}_{I,K,S} \,+\, \underbrace{X + X}_{K',S'}
  \,+\, 
  \underbrace{X\times X}_{S''}%
\end{align*}
%
induced by the grammar of \xCL~\eqref{eq:xcl-grammar}. 
By definition, an element of the dependent sum $\coprod_{f\in Ops} X^{\ar(f)}$ 
has the form $(f\in Ops,(x_i\in X)_{i\in\ar(f)})$, which we will also write 
as $f(x_i)_{i\in\ar(f)}$, or even $f(x_1,\ldots,x_{\ar(f)})$ when $\ar(f)\in\nats$,
if no confusion arises. In what follows we assume that all the involved free objects 
$F^\star X$ exist, without further mention.

\myparagraph{Strong monads and distributive laws} A monad~$\BBT$ on~$\BC$ is determined by a \emph{Kleisli triple}~$(T,\eta, (-)^\klstar)$,
consisting of a map $T\c{|\BC|\to|\BC|}$, a family of morphisms 
$(\eta_X\c X \to TX)_{X\in|\BC|}$ and \emph{Kleisli lifting} sending each~$f\c X \to T Y$ to~$f^\klstar\c TX \to TY$ and
%
%
%
obeying \emph{monad laws}: 
\begin{align*}
	\eta^{\klstar}=\id,\qquad f^{\klstar}\comp\eta=f,\qquad (f^{\klstar}\comp g)^{\klstar}=f^{\klstar}\comp g^{\klstar}.
\end{align*}
%
It follows that~$T$ extends to a functor, $\eta$ extends to a natural transformation -- \emph{unit},
${\mu = \mmul\c TTX\to TX}$ extends 
to a natural transformation -- \emph{multiplication}, and that $(T,\eta,\mu)$ 
is a monad in the standard sense~\cite{Mac-Lane78}. Any free monad $F^\star$ is
an example of a monad. 

We will emphasize that a functor $T$ is also a monad by writing 
it boldfaced (such as~$\BBT$).
%
%
%
%
Given $f\c X\to TZ$ and $g\c Y\to TW$, we abbreviate $f\klplus g = [T\inl\comp f,T\inr\comp g]\c X+Y\to T(Z+W)$.

A monad $\BBT$ is \emph{strong} if it comes with 
a natural transformation $\tau_{X,Y}\c X\times TY\to T(X\times Y)$ called \emph{strength} 
and satisfying a number of coherence conditions~\cite{Moggi91}. 
A well-known fact due to Kock~\citep{Kock72} is that in self-enriched categories (such 
as $\Set$) strength is equivalent to enrichment. In particular, in $\Set$, 
every functor $T$ and every monad $\BBT$ are strong with the canonical strength 
$\tau_{X,Y} = \lambda (x,z).\,T(\lambda y.\,(x,y))(z)$.

%
By a \emph{(Kleisli) distributive law} between
a monad $\BBT$ and a functor $F$ we mean a natural transformation $FT\to TF$ suitably interacting 
with unit and multiplication of the monad~\cite{HasuoJacobsEtAl07}.

\myparagraph{Order enrichment and fixpoints} 
Recall that \emph{Kleene's fixpoint theorem} states that every continuous endomap 
$f$ on a pointed $\omega$-cpo has the least pre-fixpoint~$\mu f$ (which is also the least fixpoint),
which is a least upper bound of the chain
%
\begin{align*}
\bot\appr f(\bot)\appr f(f(\bot))\appr\ldots
\end{align*}
%
An \emph{$\omega$-continuous} monad~\cite{GoncharovSchroderEtAl18} is a monad~$\BBT$ together with
an enrichment of the Kleisli category~$\BC_{\BBT}$ of~$\BBT$ over pointed $\omega$-cpos and
(nonstrict) $\omega$-continuous maps, satisfying the following principles:
\begin{itemize}
\item strength is $\omega$-continuous: $\tau(\id\times\bigjoin_i f_i)=\bigjoin_i\tau(\id\times f_i)$;
\item copairing in $\BC_{\BBT}$ is $\omega$-continuous: $\bigl[\bigjoin_i f_i,\bigjoin_i g_i\bigr]= \bigjoin_i [f_i,g_i]$;
\item bottom elements are preserved by strength and by postcomposition in $\BC_{\BBT}$: $\tau(\id\times\bot)=\bot$, $f^\klstar\comp\bot=\bot$.
\end{itemize}
%
Every $\omega$-continuous monad $\BBT$ is a (complete) Elgot monad, i.e.\ it supports
an (Elgot) iteration operator that sends every $f\c X\to T(Y+X)$ to $f^\istar\c X\to TY$,
subject to several standard laws of iteration. Specifically, $f^\istar=\mu g.\, [\eta,g]^\klstar\comp f$. 
%
Standard classical examples of (strong) $\omega$-continuous monads are the \emph{maybe-monad} $TX=X+1$
and the \emph{powerset monad} $TX=\PSet X$. 
Note that the identity monad $T=\Id$ is generally not $\omega$-continuous, for
the Kleisli hom-sets need not posses least elements.
%
We call a distributive law $\dl\c F\BBT\to\BBT F$ $\omega$-continuous if all the correspondences $f\in\BC(X,TY)\mapsto\dl_Y\comp Ff\in\BC(FX, TFY)$
are $\omega$-continuous.

\subsection{Abstract HO-GSOS}
%
We proceed to recall and modify slightly the notion of abstract 
HO-GSOS law from previous work~\cite{GoncharovMiliusEtAl23}. This is indeed the notion
we already implemented in~\autoref{sec:hask}. Let us fix a 
bifunctor $\Sigma'\c\BC\times\BC\to\BC$ (signature) and a mixed variance 
functor $B\c\BC^\op\times\BC\to\BC$ (behaviour) on a distributive category~$\BC$. 
Let $\Sigma=\Sigma'\dl$ and let
%
\begin{align}\label{eq:ho-gsos-law}
\rho_{X,Y} \c \Sigma' (X \times B(X,Y),X)\to B(X, \Sigma^\star (X+Y)),
\end{align}
%
be a family of morphisms natural in $Y$ and dinatural in $X$. 
%
This is a slight generalization of the original notion, which is obtained
making~$\Sigma'$ independent of the second argument. In that case $\Sigma'(X,Y)=\Sigma X$.
We need the additional parameter for $\Sigma'$ to identify those arguments of signature 
operations, whose behaviour is not inspected. The key notion 
that~\eqref{eq:ho-gsos-law} generates is that of \emph{operational model}, which is a morphism 
$\gamma$, defined by parametrized structural recursion as follows:
%
\begin{equation}\label{eq:op-mod}
\kern-2ex\begin{tikzcd}[column sep=3ex, row sep=4ex]
\Sigma'(\mS,\mS)
  \dar["{\Sigma'(\brks{\id,\gamma},\id)}"']
  \ar[rr,"\iota"] & &[5ex]
\mS
  \dar["\gamma"]\\
%
\Sigma'(\mS\times {B(\mS,\mS)},\mS)
  \rar["\rho"] &
B(\mS,\Sigma^\star (\mS+\mS))
  \rar["{B(\id,\nabla^\klstar)}"] &
B(\mS,\mS)
\end{tikzcd}
\end{equation}
%
That is: there is precisely one $\gamma\c\mS\to B(\mS,\mS)$, such that~\eqref{eq:op-mod} commutes.

In fact, given a law~\eqref{eq:ho-gsos-law}, we can introduce an abstract higher-order 
GSOS for $\Sigma$ and $B$ in the original sense as follows:
%
\begin{equation}\label{eq:ho-var-conv}
\begin{tikzcd}[column sep=20ex,row sep=4ex]
\Sigma' (X \times B(X,Y),X \times B(X,Y)) 
	\rar["{\Sigma' (\id\times B(\id,\inr),\inl\comp\fst)}"]
&
\Sigma' (X \times B(X,X+Y),X + Y)
	\ar[dl,"\rho"',bend right=4,pos=.7]\\
B(X, \Sigma^\star (X+(X+Y)))
	\rar["{B(\id,\Sigma^\star[\inl,\id])}"]
&
B(X, \Sigma^\star (X+Y))
\end{tikzcd}
\end{equation}
%
and it is shown below that the operational model for it coincides with the one specified 
by~\eqref{eq:op-mod}. In that sense our present generalization is indeed mild -- it does 
not add more strength to the original notion, but it provides more flexibility for 
the analysis of the transformations~\eqref{eq:ho-gsos-law}.

\begin{proposition}\label{pro:theta-om}
Let $\rho'_{X,Y}\c \Sigma(X \times B(X,Y)) \to B(X, \Sigma^\star (X+Y))$ be defined 
by~\eqref{eq:ho-var-conv}. Then the operational model for $\rho'$ is the unique such 
morphism that the diagram~\eqref{eq:op-mod} commutes.
%
\end{proposition}

\section{Separable Abstract Higher-Order GSOS}\label{sec:gsos-separated}
%
%
%
%
%
%
%
%
%
%

Let us reintroduce the notion of 
separable abstract HO-GSOS from~\autoref{sec:hask} in categorical terms.
\begin{definition}[Separable Abstract Higher-Order GSOS]\label{def:separated}
We say that the law~\eqref{eq:ho-gsos-law} is \emph{separable} if $B(X,Y)=D(X,Y) + TY$, $\Sigma'=\Sigma_\val\Snd+\Sigma_\com$
and 
\begin{align}\label{eq:separated-rho}
\rho = D(\id,\Sigmas\inl)\comp \rho^\val+\rho^\com %
\end{align}
%
for some $D\c\BC^\op\times\BC\to\BC$, $\Sigma_\val\c\BC\to\BC$, $\Sigma_\com\c\BC\times\BC\to\BC$,
a strong monad $\BBT$, families of morphisms
%
\begin{align}
\label{eq:separated1}  
\rho_{X}^\val\c&\Sigma_\val X \to D(X,\Sigma^\star X),
\\*
\label{eq:separated2}
\rho_{X,Y}^\com\c&\Sigma_\com(X\times B(X,Y),X)\to T\Sigma^\star (X+Y),
\intertext{dinatural in $X$ and natural in $Y$, and a distributive law}
\label{eq:separated3}
\dl_{X,Y}\c&\Sigma_\com(TX,Y)\to T\Sigma_\com(X,Y).
\end{align}
%
between the monad $\BBT$ and the functors $\Sigma_\com(\argument,Y)$ naturally in $Y$.
%
%
%
%
%
%
The triple $(\rho^\val,\rho^\com,\dl)$ is then a \emph{separated abstract higher-order GSOS law}.

%
We call $\Sigma_\val$ \emph{value formers}
and $\Sigma_\com$ \emph{computation formers}. Moreover, we call  
$\mSv=\Sigma_\val(\mS)$ the \emph{object of values} and $\mSc=\Sigma_\com(\mS,\mS)$
the \emph{object of computations}. Let $\iota^\val = \iota\comp\inl\c\Sigma_\val\Sigma^\star\to\Sigma^\star$
and $\iota^\com = \iota\comp\inr\c\Sigma_\com\Delta\Sigma^\star\to\Sigma^\star$.
\end{definition}
%
For the time being we are not making any assumptions about the monad $\BBT$. 
In the simplest (total, deterministic) case, $\BBT$ in \autoref{def:separated} is the identity 
monad and $\dl=\id$. %
%
%
%


Since $\mS\iso\mSv+\mSc$, the object of 
all closed $\Sigma$-terms $\mS$ crisply decomposes into values and computations.
That $\Sigma_\com$ is a binary functor is meant to capture a partitioning of the 
arguments of the computation formers into those that depend on the associated 
behaviour, and those that do not. We call the former type of arguments \emph{strict}
and the latter \emph{lazy}.

For a separated abstract higher-order GSOS law $(\rho^\val,\rho^\com,\dl)$,
we define a refinement $(\gamma^\val,\gamma^\com)$ of the operational model~\eqref{eq:op-mod}.
The morphism $\gamma^\val$ is the composition
%
\begin{align}\label{eq:op-mod-v}
\mSv
	\xto{\rho^\val}
D(\mS,\Sigma^\star\mS)
	\xto{D(\id,\mmul)} 
D(\mS,\mS)
\end{align}
%
and the morphism $\gamma^\com$ is characterized by the diagram
%
\begin{equation}\label{eq:op-mod-c}
\begin{tikzcd}[column sep=5ex, row sep=4ex]
\Sigma_\com(\mSv+\mSc,\mS)
	\dar["{\Sigma_\com(\brks{\iota,\gamma^\val+\gamma^\com},\id)}"']
	\ar[rr,"{\Sigma_\com(\iota,\id)}"] 
& 
&[2ex]
\mSc
	\dar["\gamma^\com"]	
\\
%
\Sigma_\com(\mS\times {B(\mS,\mS)},\mS)
  \rar["{\rho^\com }"] 
&
T\Sigmas(\mS+\mS)
	\rar["T\nabla^\klstar"]
&
T\mS
\end{tikzcd}
\end{equation}
%
in the following sense.
\begin{proposition}\label{pro:gamma_c}
There is unique $\gamma^\com\c\mSc\to T(\mS)$, for which \eqref{eq:op-mod-c}
commutes. Moreover:
%
\begin{align}\label{eq:gammas}
\gamma^\val+\gamma^\com = \gamma\comp\iota.
\end{align}
\end{proposition}
%
Let $\hat\gamma^\com$ be the morphism $[\eta\comp\iota^\val,\gamma^\com]\comp\iota^\mone\c\mS\to T(\mS)$.
Intuitively, $\hat\gamma^\com$ acts on computations as $\gamma^\com$ and as $\eta$ on values.

%
