\begin{example}[Extended Combinatory Logic]\label{exa:xcl}
Recall the grammar~\eqref{eq:xcl-grammar} of the extended combinatory logic \xCL. 
The corresponding signature functor consists of two parts: 
%
\begin{displaymath}
  \Sigma_\val X = \coprod\nolimits_{f\in\{S,K,I,K',S',S''\}} X^{\ar(f)} \qquad\qquad \Sigma_\com (X,Y) = \{\tcomp\}\times (X\times Y).
\end{displaymath}
%
Here $\ar(f)$ denotes the arity of $f$. Binary application operator $\tcomp$
is the only computation former. The expression for $\Sigma_\com$ indicates that 
the one-step behaviour of it only depends on the behaviour of the first argument, but not on
the second. 
%
%

Let $D(X,Y) = Y^X$ and $T=\Id$. The small-step operational semantics rules in~\autoref{fig:rules} define $\rho^\val$
and $\rho^\com$, and hence the law~\eqref{eq:ho-gsos-law}. Concretely (eliding the obvious isomorphisms and parentheses):
%
\begin{align*}
\rho^\val(I)(r) 		=&\; r\qquad	&\rho^\val(K'(t))(r)  =&\; t	& \rho^\com(\tcomp((t,t'), s))	=&\; \tcomp(t', s)\\ 
\rho^\val(K)(r) 		=&\; K'(r)		&\rho^\val(S'(t))(r)	=&\; S''(t, r)	& \rho^\com(\tcomp((t,f), s)) =&\; f(s) \\
\rho^\val(S)(r) 		=&\; S'(r)		&\rho^\val(S''(t,s))(r)	=&\; \makebox[4em][l]{$\tcomp(\tcomp(t, r),\tcomp(s,r))$}\\[-8ex]
\end{align*}
%
\exend
\end{example}
%
From~\eqref{eq:separated2} we derive
%
%
\begin{align}
\label{eq:separated21}
\rho_{X,Y}^{\com\val}\c&\Sigma_\com(X\times D(X,Y),X)\xto{\rho^\com\comp\Sigma_\com(\id\times\inl,\id)}  T\Sigma^\star (X+Y). %
%
%
\end{align}
%
%
%
%
%
%
%
%
%
%
%
%
In what follows, we globally make the following mild technical assumption.
\begin{assumption}\label{ass:compl}
We assume that for all $X,Y,Z$, and for $\Sigma_\com$ figuring in~\autoref{def:separated} 
the morphisms $\Sigma_\com(\inl,\id)\c\Sigma_\com(X,Z)\to\Sigma_\com(X+Y,Z)$ are \emph{complemented},
and the complementation is natural in $X,Y$ and $Z$.
In other words, for some functor~$\Theta\c\BC\times\BC\times\BC\to\BC$ and some natural transformation 
$\theta_{X,Y,Z}\c\Theta(X,Y,Z)\to\Sigma_\com(X+Y,Z)$, the cospan 
%
\begin{align*}
\Sigma_\com(X,Z) \xto{\Sigma_\com(\inl,\id)}\Sigma_\com(X+Y,Z)\xfrom{\theta}\Theta(X,Y,Z)
\end{align*}
is a coproduct naturally in $X$, $Y$ and $Z$.
%
\end{assumption}
%
\begin{remark}\label{rem:poly-theta}
Note that if $\Sigma_\com$ is polynomial $\Sigma_\com(X,Y)=\coprod_{f\in Ops} X^{\sar(f)}\times Y^{\lar(f)}$ (where $\sar(f)$
is the number of strict arguments of $f$ and $\lar(f)$ is the number of lazy ones) 
\autoref{ass:compl} is satisfied whenever it is satisfied for every summand $X^{\sar(f)}\times Y^{\lar(f)}$.
Let us fix~$f$, and let $n=\sar(f)$, $m=\lar(f)$. \autoref{ass:compl} is then satisfied, since (by using the binomial formula)
%
\begin{align*}
(X+Y)^n\times Z^m\cong X^n\times Z^m + \coprod_{k=1}^n C_n^k\times Y^k\times X^{n-k}\times Z^m,
\end{align*}
and we can take $\Theta(X,Y,Z) = \coprod_{k=1}^n C_n^k\times Y^k\times X^{n-k}\times Z^m$.
%
\end{remark}
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
