%
%

%
%


We now introduce a well-behavedness condition on separated abstract HO-GSOS 
guaranteeing that a notion of big-step operational semantics can be sensibly 
derived.

Recall that we defined $f\klplus g = [T\inl\comp f, T\inr\comp g]$.
%
\begin{definition}[Strong Separation]\label{def:strong-sep}
A separated abstract HO-GSOS law $(\rho^\val,\rho^\com,\dl)$ is \emph{strongly separated}
if the following diagram commutes:
%
\begin{equation}\label{eq:str_sep}
\begin{tikzcd}[column sep=-4em, row sep=normal]
&\Theta(X\times D(X,Y),X\times TY,X)
	\ar[dl,"\theta"']
	\ar[dr,"\theta"]&
\\
\Sigma_\com(X\times D(X,Y) + X\times TY,X)
	%
	\ar[dd,"\iso"']
& &
\Sigma_\com(X\times D(X,Y) + X\times TY,X)
	\dar["{\Sigma_\com(\eta\comp\fst\klplus\snd,\inl)}"]
%
\\
& &
\Sigma_\com(T(X+Y),X+Y)
	\dar["\dl"]
\\
%
\Sigma_\com(X\times (D(X,Y)+TY),X)
	\ar[dr,"\rho^\com"']
& &
T\Sigma_\com(X+Y,X+Y)
	\ar[dl,"{T(\iota^\com\comp\Sigma_\com(\eta,\eta))}"]
\\
& T\Sigma^\star (X+Y) &
\end{tikzcd}
\end{equation}
\end{definition}
%
If $\Sigma_\com$ is a coproduct $\coprod_{i\in I}\Sigma_\com^i$, it suffices
to verify~\eqref{eq:str_sep} with $\Sigma_\com\ass\Sigma_\com^i$ for every $i$.
Intuitively, the left path of the diagram (from top to bottom) corresponds to
the general form of a rule, as represented by~$\rho^\com$, while the right path
specifies the required format. The commutativity of the diagram thus imposes a
constraint on~$\rho^\com$. Precomposition with~$\theta$ ensures that this constraint 
becomes effective only for rules with at least one premise from the computation 
part of the behaviour.
%

One could directly verify that strong separation holds for \xCL. It is instructive 
though to spell out~\eqref{eq:str_sep} for a larger class of examples, of which \xCL
is a member. 
%
\begin{remark}\label{rem:total-sep}
Let us spell out the strong separation condition in the total deterministic case, i.e.\
when $T=\Id$ and $\dl = \id$. The diagram \eqref{eq:str_sep} then simplifies as 
follows:
%
\begin{equation*}
\begin{tikzcd}[column sep=-4em, row sep=normal]
&\Theta(X\times D(X,Y),X\times Y,X)
	\ar[dl,"\theta"']
	\ar[dr,"\theta"]&
\\
\Sigma_\com(X\times D(X,Y) + X\times Y,X)
	%
	\ar[d,"\iso"']
& &
\Sigma_\com(X\times D(X,Y) + X\times Y,X)
	\dar["{\Sigma_\com(\fst+\snd,\inl)}"]
\\[1ex]
\Sigma_\com(X\times (D(X,Y) + Y),X)
	\ar[dr,"\rho^\com"']
& &
\Sigma_\com(X+Y,X+Y)
	\ar[dl,"{\iota^\com\comp\Sigma_\com(\eta,\eta)}"]
\\
& \Sigma^\star (X+Y) &
\end{tikzcd}
\end{equation*}
%
Furthermore, let us interpret this diagram in the category of sets. Suppose 
that~$\Sigma_\com(X,Y)$ contains $F(X,Y)={X^n\times Y^m}$ as a summand for some natural 
numbers~$n$ and $m$. That is, $\Sigma_\com$ contains a computation former, say $f$,
whose~$n$ first arguments are strict and whose remaining~$m$ arguments are lazy.
As in the case of \xCL (\autoref{exa:xcl}), let $D(X,Y) = Y^X$. The restriction 
of $\rho^\com$ to~$F$ corresponds to the rules that describe the 
behaviour of terms of the form $f(x_1,\ldots,x_n,y_1,\ldots,y_m)$. The strong separation
condition requires the following: if the rule has at least one premise of the form 
$x_k\to x_k'$ then the conclusion of the rule must be of the form
%
\begin{align*}
f(x_1,\ldots,x_n,y_1,\ldots,y_m)\to f(x_1',\ldots,x_n',y_1,\ldots,y_m)
\end{align*}
%
where either $x_i\to x_i'$ occurs in the premise, or else, the premise contains a labeled 
transition for $x_i$, in which case $x_i'=x_i$.
\exend
\end{remark}
\begin{remark}
Our strong separation condition~\eqref{eq:str_sep} is a reminiscent of cool GSOS 
formats by~\mbox{\citet{Bloom95}} and~\citet{Glabbeek11} in the context 
of process algebra. These formats require that certain operations come with enough 
\emph{patience rules}, which are rules for the form
%
\begin{align*}
\frac{x_k\to x_k'}{f(x_1,\ldots,x_n)\to f(x_1,\ldots,x_{k-1},x_k',x_{k+1},\ldots,x_n)}
\end{align*}
This is needed to ensure that the semantics is sufficiently transparent to unlabeled 
transitions (or $\tau$-transitions in op.cit.). Originally, this enabled congruence properties of weak notions of process 
equivalence (such as weak bisimilarity). In our context, similar condition is needed to ensure 
that a small-step semantics can have a sensible a big-step semantics counterpart.
\end{remark}
\begin{example}
It is easy to see that \xCL satisfies strong separation: in view of \autoref{rem:total-sep},
the only relevant operation is application and the only relevant rule is
%
\begin{align*}
\infer{ts\to t's}{t\to t'}
\end{align*} 
%
Clearly, it has the requisite form.\exend
\end{example}
%
\begin{example}
Revisiting \autoref{exa:non-sep}, note that the strong separation condition is 
violated by the third rule.
%
%
%
%
%
As we argued, for the present small-step semantics we cannot define big-step semantics satisfying~\eqref{eq:sem-eq}. Thus,
in this case, strong separation effectively rules out an undesired example. \exend
\end{example}
%
As we see latter, the equivalence between the small-step and the big-step semantics
requires an $\omega$-continuous monad $\BBT$, while the identity monad is not $\omega$-continuous (Kleisli hom-sets do not have least elements).
We thus may need to adjoin a (separated) abstract higher-order GSOS law over a 
monad $\BBT$ to a given (separated) abstract higher-order GSOS law over the identity monad.
\begin{proposition}\label{pro:transfer}
Given families of morphisms
%
\begin{align*}
\rho_{X}^\val\c&\Sigma_\val X \to D(X,\Sigma^\star X),
\\*
\rho_{X,Y}^\com\c&\Sigma_\com(X\times (D(X,Y)+Y),X)\to \Sigma^\star (X+Y),
\end{align*}
natural in $Y$ and dinatural in $X$, a strong monad $\BBT$ and a distributive law $\dl_{X,Y}\c\Sigma_\com(TX,Y)\to T\Sigma_\com(X,Y)$, 
let $\hat\rho^\com$ be the family of morphisms, whose components are the compositions 
%
%
\begin{equation*}
\begin{tikzcd}[column sep=4ex,row sep=4ex]
\Sigma_\com(X\times B(X,Y),X)
	\ar[rr,"{\Sigma_\com(\id\times(\eta\klplus\id),\id)}"]
& &[-6ex]
\Sigma_\com(X\times T(D(X,Y)+Y),X)
	\ar[dll,"{\Sigma_\com(\tau,\id)}"',bend right=4,pos=.8]\\
\Sigma_\com(T(X\times (D(X,Y)+Y)),X)
	\rar[r,"\dl"]
& T\Sigma_\com(X\times (D(X,Y)+Y),X)
	\rar["T\rho^\com"] &
T\Sigma^\star (X+Y)
\end{tikzcd}
\end{equation*}
%
%
Suppose that the morphisms
%
\begin{align*}
\Theta(TX,TY,Z)\xto{\theta} \Sigma_\com(TX+TY,Z)\xto{\Sigma_\com(\id\klplus\id,\id)} \Sigma_\com(T(X+Y),Z)\xto{\dl} T\Sigma_\com(X+Y,Z)
\end{align*}
%
factor through $T\theta\c T\Theta(X,Y,Z)\to T\Sigma_\com(X+Y,Z)$.
%
Then if $(\rho^\val,\rho^\com,\id)$ is a strongly separated abstract higher-order GSOS law, then 
so is $(\rho^\val,\hat\rho^\com,\dl)$ .
\end{proposition}
%
A typical case for using \autoref{pro:transfer} is extending a deterministic law 
to a nondeterministic one, using the powerset monad. 
%
\begin{remark}\label{ref:transfer}
As in \autoref{rem:poly-theta}, consider $\Sigma_\com(X,Y) = X^n \times Y^m$, 
now on the category of sets. Let us choose $\Theta(X,Y,Z)\subseteq\Sigma_\com(X+Y,Z)$ to be $\{(\bar v,\bar z)\in (X+Y)^n\times Z^m\mid \exists i.\,\exists y\in Y.\,v_i = \inr y \}$
(so, $\theta$ is a set inclusion). Let $\BBT$ be the powerset functor $\PSet$, and assume 
the standard distributive law~\cite{HasuoJacobsEtAl07} $\dl_{X,Y}((A_i)_{i\in\{1,\ldots,n\}},\bar{y})=\{(\bar{x},\bar{y})\mid x_i\in A_i\}$.
Then, to show that $\dl \comp \Sigma_\com(\id \klplus \id , \id) \comp \theta$
factors through~$\PSet\theta$ is to show that for any $\bar V\in (\PSet X+\PSet Y)^n$ and $\bar z\in Z^m$
such that at least one $V_i$ is of the form $\inr A$, if $(\bar v,\bar z')\in (\dl \comp \Sigma_\com(\id \klplus \id , \id))(\bar V,\bar z)$
then also $v_i$ is of the form $\inr y$. Let us show it by contradiction: suppose that 
$(\bar v,\bar z')\in (\dl \comp \Sigma_\com(\id \klplus \id , \id))(\bar V,\bar z)$ but $v_i=\inl x$ for some $x\in X$.
Then for some %
$(\bar W,\bar z')\in (\Sigma_\com(\id \klplus \id , \id))(\bar V,\bar z)$, $W_i$ contains $\inl x$,
contradicting to the assumption that~$V_i=\inr A$.
\end{remark}
