\section{Equivalence of Small-Step and Big-Step, Abstractly}%
%

In this section we assume that the monad $\BBT$ is $\omega$-continuous. 
We then abstractly define multi-step transitions $t\to^\star v$ from computations to values as the least fixpoint
%
\begin{align}\label{eq:multi}
\beta = (T\iota^\mone\comp\gamma^\com)^\istar =\mu f.\, [\eta,f]^\klstar\comp T\iota^\mone\comp\gamma^\com \c\mSc\to T(\mSv).
\end{align}
%
In other words, $\beta$ is the least solution of the equation $\beta = [\eta,\beta]^\klstar\comp T\iota^\mone\comp\gamma^\com$. 
Let moreover $\hat\beta = [\eta,\beta]\comp\iota^\mone\c\mS\to T(\mSv)$.
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%

Suppose that $D(X,Y) = Y^X$ and that $\Sigma$ is some algebraic signature on~$\Set$. 
Let $f$ be some $(n+m)$-ary computation former with precisely~$n$ strict first arguments.
Suppose that $t_1\to^\star v_1,\ldots,t_n\to^\star v_n$ and that ${f(v_1,\ldots,v_n,t_{n+1},\ldots,t_m)\to t\to^\star v}$ 
for some values $v_1,\ldots,v_n,v$. We then expect that $f(t_1,\ldots,t_{n+m})\to^\star v$.
The following lemma captures this fact abstractly.
%
\begin{lemma}\label{lem:beta-delta}
Let $(\rho^\val,\rho^\com,\dl)$ be a strongly separated abstract higher-order GSOS law,
such that the law $\dl$ is $\omega$-continuous. 
%
Then 
%
\begin{align}\label{eq:beta-ineq}
\hat\beta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp\hat\beta,\id)\appr\beta.
\end{align}
%
%
%
%
%
%
%
%
%
%
%
\end{lemma}
\begin{proof}[Proof Sketch]
The key step is proving that the following diagram commutes:
%
\begin{equation}
\begin{tikzcd}[column sep=normal, row sep=normal]
\mSc
	\rar["\beta"]
	\dar["{\Sigma_\com(\hat\gamma^\com,\id)}"'] 
&
T(\mSv)
\\               
\Sigma_\com(T\mS,\mS)
	\rar["\dl"] 
%
&
T(\mSc)
	\uar["\beta^\klstar"']
\end{tikzcd}
\end{equation}
%
To that end we use the fact that, by \autoref{ass:compl}, $\mSc$ is a coproduct of $\Sigma_\com(\mSv,\mS)$ and $\Theta(\mSv,\mSc,\mS)$.
The diagram then falls into two equations:
%
\begin{align*}
\beta^\klstar\comp\dl\comp\Sigma_\com(\hat\gamma^\com,\id)\comp\Sigma_\com(\iota^\val,\id) =&\; \beta\comp\Sigma_\com(\iota^\val,\id),\\
\beta^\klstar\comp\dl\comp\Sigma_\com(\hat\gamma^\com,\id)\comp\Sigma_\com(\iota,\id)\comp\theta =&\; \beta\comp\Sigma_\com(\iota,\id)\comp\theta.
\end{align*}
%
The first is obtained by unfolding definitions and using the fact that $\dl$ is a distributive law.
%
The second one relies on~\eqref{eq:str_sep}. Using the 
diagram, the goal is obtained by induction, using the fact that
(by Kleene's fixpoint theorem) $\hat\beta = \bigjoin_n\hat\beta_n$ where 
$\hat\beta_0 = [\eta,\bot]\comp\iota^\mone$, $\hat\beta_{n+1} = \hat\beta_{n}^\klstar\comp\hat\gamma^\com$.
\end{proof}


%
%
%
%
%
%

%
%
%

Another property that we need to abstract is that $t\to s$ together with $s\Dar v$
entails $t\Dar v$.
%
\begin{lemma}\label{lem:big-and-small}
Let $(\rho^\val,\rho^\com,\dl)$ be an strongly separated abstract HO-GSOS with 
$\omega$-continuous~$\dl$ and let~$\xi$
be defined by~\eqref{eq:xi-constr}. 
%
Then $\hat\zeta^\klstar\comp\gamma^\com\appr\zeta$.
\end{lemma}
\begin{proof}[Proof Sketch]
%
%
The diagram~\eqref{eq:op-mod-c} identifies
$\gamma^\com$ as the unique fixpoint of the map $f\mto T\nabla^\klstar\comp\rho^\com\comp\Sigma_\com(\brks{\id,(\gamma^\val+ f)\comp\iota^\mone},\id)$,
hence, also as the least fixpoint. Thus $\gamma^\com = \bigjoin_n \gamma^\com_n$ where $\gamma^\com_0 = \bot$ and $\gamma^\com_{n+1} = T\nabla^\klstar\comp\rho^\com\comp\Sigma_\com(\brks{\id,(\gamma^\val+\gamma_n^\com)\comp\iota^\mone},\id)$, and it suffices to show $\hat\zeta^\klstar\comp\gamma^\com_n\appr\zeta$
%
for all $n$. The induction base is obvious. The induction step, by \autoref{ass:compl}, we reduce to two subgoals:
%
\begin{align*}
\hat\zeta^\klstar\comp\gamma^\com_{n+1}\comp\Sigma_\com(\iota^\val,\id) 		\appr&\; \zeta\comp\Sigma_\com(\iota^\val,\id),\\*
\hat\zeta^\klstar\comp\gamma^\com_{n+1}\comp\Sigma_\com(\iota,\id)\comp\theta   \appr&\; \zeta\comp\Sigma_\com(\iota,\id)\comp\theta.
\end{align*}
%
The first one is easy to obtain by unfolding definitions. The second one is a result of a somewhat tedious 
calculation, using the induction hypothesis and the strong separation assumption.
\end{proof}

We proceed with formalizing and proving an abstract version of the 
equivalence~\eqref{eq:sem-eq} between the small-step and the big-step semantics
for strongly separated abstract HO-GSOS laws. To that end, we first rewrite the formula~\eqref{eq:bs-xi} in the setting 
when $\xi$ comes from~\eqref{eq:xi-constr}.

%
\begin{proposition}\label{lem:bs-fix}
Let $(\rho^\val,\rho^\com,\dl)$ be an abstract higher-order separated GSOS with $\omega$-continuous 
$\dl$ and let~$\xi$ be defined by~\eqref{eq:xi-constr}. Then 
%
\begin{align}\label{eq:bs-xi-fix}
	\hat\zeta = \mu f.\,[\eta, f^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp f,\id)]\comp\iota^\mone.
\end{align}
\end{proposition}
%
%
Finally, we prove our main result.
\begin{theorem}\label{the:main}
Let $(\rho^\val,\rho^\com,\dl)$ be a strongly separated abstract higher-order  GSOS with 
$\omega$-continuous~$\dl$ and let~$\xi$
be defined by~\eqref{eq:xi-constr}. 
%
Then $\hat\zeta = \hat\beta$.
\end{theorem}
\begin{proof}
%
We proceed by proving mutual inequality. 

$\hat\zeta\appr\hat\beta$. By \autoref{lem:bs-fix}, $\hat\zeta$ is the least pre-fixpoint of 
\eqref{eq:bs-xi-fix}. By \autoref{lem:beta-delta}, $\hat\beta$ is a pre-fixpoint of the 
same function. Hence, indeed, $\hat\zeta\appr\hat\beta$.

$\hat\beta\appr\hat\zeta$. The goal is equivalent to $[\eta,\beta]\comp\iota^\mone\appr[\eta,\zeta]\comp\iota^\mone$.
Proving this is equivalent to proving that $\beta\appr\zeta$, which will then be our new goal. By definition,~$\beta$ is the least pre-fixpoint of the map
$f\mto [\eta,f]^\klstar\comp T\iota^\mone\comp\gamma^\com$. Hence, it suffices to
prove that $\zeta$ is a pre-fixpoint of the same map, i.e.\ the inequality
$[\eta,\zeta]^\klstar\comp T\iota^\mone\comp\gamma^\com\appr\zeta$,~i.e.\ $\hat\zeta^\klstar\comp\gamma^\com\appr\zeta$,
which we have by \autoref{lem:big-and-small}.
\end{proof}
