\section{Case Studies}\label{sec:exa}
%
We proceed to consider various aspects of programming languages from the perspective
of our framework, and demonstrate in detail, how it can cope with them.  
%
\subsection{Types}
In this section, we stick to a typed version of $\xCL$, previously dubbed $\xTCL$~\cite{GoncharovSantamariaEtAl24}. 
The transition from $\xCL$ to $\xTCL$ demonstrates the strength of our categorical modeling: from
$\Set$ as the ambient category $\BC$ we simply switch to the category of sorted sets $\Set^\Ty$,
where the sorts $\Ty$ are indeed the conventional types of typed combinatory logic~\cite{HindleySeldin08}. The remaining 
ingredients of the framework are then upgraded as expected, which we detail further below. 

Assuming a postulated set of basic sorts $\CS$, the set of types $\Ty$ is defined by the grammar:
%
\begin{flalign*}
&&\Ty \Coloneqq (\tau\in\CS)  \mid  \arty{\Ty}{\Ty}. && 
\end{flalign*}
%
More concretely, an object $A$ 
of~$\BC$ is a family of sets $(A_\tau)_{\tau \in \Ty}$ and a morphism $f \c A \to B$ in $\BC$ is a family of functions
$(f_\tau \c A_\tau \to B_\tau)_{\tau\in\Ty}$. Morphism composition $g \comp f$ is defined
as $(g_\tau \comp f_\tau)_{\tau \in \Ty}$. Note that $\BC$ is a presheaf topos over~$\Ty$ as a discrete category, 
in particular, limits and colimits in $\BC$ are computed pointwise.  
%
We introduce $\Sigma_\val$ and $\Sigma_\com$ for $\xTCL$ as follows:
\begin{align*}
	\Sigma_\val (X)_\tau =&\; \coprod\nolimits_{f\c\tau_1,\ldots, \tau_n \to \tau\in Ops} \prod\nolimits_{i=1}^n X_{\tau_i}
	&&\Sigma_\com (X,Y)_\tau= \{\tcomp_{\tau',\tau}\}\times (X_{\arty{\tau'}{\tau}} \times Y_{\tau'}),
\end{align*}
where $Ops=\{I_{\tau_1}, K_{\tau_1,\tau_2}, K'_{\tau_1,\tau_2}, S_{\tau_1,\tau_2,\tau_3}, S'_{\tau_1,\tau_2,\tau_3}, S''_{\tau_1,\tau_2,\tau_3}\}$
is the set of operations, constituting $\Sigma_\val$, and typed in the expected way. For example, the type of~$K'_{\tau_1,\tau_2}$ is $\tau_1 \to (\arty{\tau_2}{\tau_1})$. 
Analogously, we view~$\Sigma_\com$ as a signature of one binary operation $\tcomp_{\tau_1,\tau_2}$ of type $(\arty{\tau_1}{\tau_2}), \tau_1 \to \tau_2$.

To define the behaviour functor $B$, let $\BBT$ be the identity monad, and let $D$ be as follows: 
%
\begin{align*}
D(X,Y)_{\tau}=\{\}\text{\quad for $\tau\in\CS$}, \qquad D(X,Y)_{\arty{\tau_1}{\tau_2}}=Y_{\tau_2}^{X_{\tau_1}}
\end{align*}
%
and then $B(X,Y)_\tau =\fpc_\tau$ if $\tau\in\CS$ and $B(X,Y)_{\arty{\tau_1}{\tau_2}} = Y_{\arty{\tau_1}{\tau_2}}+ Y_{\tau_2}^{X_{\tau_1}}$. %
%
Next, we define $\rho^\val$ and $\rho^\com$ essentially like in \autoref{exa:xcl}, modulo 
adding the typing information. For example, the clause for~$S''$ in the definition of 
$\rho^\val_{\tau}\c\Sigma_\val (X)_{\tau} \to D(X,\Sigmas X)_{\tau}$ becomes
%
\begin{align*}
	\rho^\val_{\tau}(S''_{\tau_1,\tau_2,\tau}(t,s))(r)=&\; 
	\tcomp_{\tau_2,\tau} (\tcomp_{\tau_1,\arty{\tau_2}{\tau}} (t,r) ,\tcomp_{\tau_1,\tau_2}(s,r)).
\end{align*}
%
The definition of $\rho^\com_{\tau}\c\Sigma_\com (X \times B(X,Y), X)_{\tau} \to \Sigma^\star(X+Y)_{\tau}$ is as follows:
\begin{align*}
	\rho^\com_\tau (\tcomp_{\tau_1,\tau_2} ((s, s'),t)) =&\; \tcomp_{\tau_1,\tau_2} (s',t) 	&&\text{if}\; s' \in Y_{\arty{\tau_1}{\tau_2}}\\*
	\rho^\com_\tau (\tcomp_{\tau_1,\tau_2} ((s, f),t)) =&\; f(t) 														&&\text{if}\; f \in Y_{\tau_2}^{X_{\tau_1}}
\end{align*}
%
Finally, we obtain $\xi_\tau \c \Sigma_\com (\Sigma_\val X , X)_\tau \to \Sigma^\star (X)_\tau$ by instantiating
the general definition~\eqref{eq:xi-constr}. For example, we have
%
%
	$\xi_\tau(\tcomp_{\tau_1,\tau} (S''_{\tau_1,\tau_2,\tau}(t,s),r\c\tau_1))=
	\tcomp_{\tau_2,\tau}(\tcomp_{\tau_1,\arty{\tau_2}{\tau}}(t,r),\tcomp_{\tau_1,\tau_2}(s,r))$.
%
%
\subsection{Recursion and Conditionals}

In this section, we complement $\xTCL$ with recursion and control
in the style of PCF~\cite{Mitchell96}.
We assume the sort $\bool \in \mathcal{S}$ of Booleans. Then we add the following operators to the signature:
\begin{align*}
	\fpc_\tau \c& \arty{(\arty{\tau}{\tau})}{\tau}&
	 \casec_\tau \c& \bool , \tau , \tau \to \tau&
	\true,
	\false \c& \bool
\end{align*}
%
More concretely, this amounts to defining $\Sigma_\val$ with the same formula 
from $Ops$, which is now the set $\{I_{\tau_1}, K_{\tau_1,\tau_2}, K'_{\tau_1,\tau_2}, S_{\tau_1,\tau_2,\tau_3}, S'_{\tau_1,\tau_2,\tau_3}, S''_{\tau_1,\tau_2,\tau_3}, \fpc_{\tau_1}\}$,
and to defining $\Sigma_\com$ as follows:
\begin{gather*}
%
%
\Sigma_\com (X,Y)_\tau= \{\tcomp_{\tau',\tau}\}\times (X_{\arty{\tau'}{\tau}} \times Y_{\tau'}) \;+\; \{\casec_{\tau}\}\times (X_{\bool} \times Y_\tau \times Y_\tau).
\end{gather*}
%
The left summand corresponds to the application operator $\tcomp_{\tau_1,\tau_2}$, as before, while the 
right summand corresponds to the conditional statement $\casec_\tau$.
This indicates that the first argument of~$\casec_\tau$ is strict and the others 
are lazy.
The new operators are subject to the following small-step specification:
%
\begin{gather*}
\frac*{\fpc_\tau \xto{t}t (\fpc_\tau t)}{}\qquad\quad
\frac*{ \true \dar_\true}{} \qquad\quad
\frac*{ \false \dar_\false}{} \\[1ex]
\frac*{ \casec_\tau (b,s,t) \to  \casec_\tau (b',s,t)}{b \to b'}\qquad\quad
\frac*{ \casec_\tau (b,s,t) \to s }{b \dar_\true}\qquad\quad
\frac*{ \casec_\tau (b,s,t) \to t }{b \dar_\false}
\end{gather*}

\medskip\noindent
where we use a new type of judgements $b\dar_\true$ and $b\dar_\false$, indicating 
that $b=\true$ and $b=\false$ correspondingly.
%
Note that the if-then-else statement suffices to program the standard logical 
connectives: $\neg b = \casec_{\bool}(b,\false,\true)$, $b\land b' = \casec_{\bool}(b,b',\false)$, 
$b\lor b' = \casec_{\bool}(b,\true,b')$.
%
To address the above rules we modify~$D$ as follows:
\begin{align*}
	D(X,Y)_{\arty{\tau_1}{\tau_2}}=Y_{\tau_2}^{X_{\tau_1}} && D(X,Y)_\tau = \begin{cases}\{\true,\false\} & \text{~~if~~}\tau=\bool\\ \{\}&\text{~~if~~}\tau\in\CS\setminus\{\bool\}\end{cases}
\end{align*}
Finally, we complement the definitions of $\rho^\val$ and $\rho^\com$ with the clauses
\begin{align*}
	\rho^\val_\tau(\fpc_\tau) (t) =&\; \tcomp_{\tau,\tau} (t , \tcomp_{\arty{\tau}{\tau}, \tau}(\fpc_\tau,t))\!\!&
	\rho^\com_\tau(\casec_\tau((b,b') , s , t))=&\;  \casec_\tau(b' , s , t)
	\\*
	\rho^\val_\bool(\true) =&\; \true&
	\rho^\com_\tau(\casec_\tau((b,\true) , s , t))=&\; s
	\\*
	\rho^\val_\bool(\false) =&\; \false&
	\rho^\com_\tau(\casec_\tau((b,\false) , s , t))=&\; t
\end{align*}
%
It is easy to see by~\autoref{rem:total-sep} that $(\rho^\val,\rho^\com)$ 
constitute a strongly separated abstract HO-GSOS law.
%
By applying~\eqref{eq:xi-constr} we obtain the following new clauses for $\xi$:
\begin{align*}
	\xi_\tau (\tcomp_{\arty{\tau}{\tau},\tau} (\fpc_\tau , t \c \arty{\tau}{\tau})) =&\; \tcomp_{\tau,\tau} (t , \tcomp_{\arty{\tau}{\tau}, \tau}(\fpc_\tau,t))\\
	\xi_\tau (\casec_\tau (\true,s,t))  =&\; s\\
	\xi_\tau (\casec_\tau (\false,s,t)) =&\; t
\end{align*}
Equivalently: the following big-step rules:
\begin{gather*}
	\infer{s t \Dar v}{s \Dar \fpc_\tau & t  (\fpc_\tau t) \Dar v}\qquad\quad
	\infer{\casec_\tau(b,s,t) \Dar v}{b \Dar \true & s \Dar v} \qquad\quad
	\infer{ \casec_\tau(b,s,t) \Dar v}{b \Dar \false & t \Dar v}
\end{gather*}

\subsection{Nondeterminism and Parallelism} \label{sec:non-d}
%
We proceed to illustrate how our modeling can cope with nondeterminism and parallelism
in higher-order setting by extending $\xCL$ suitably. The standard binary \textit{erratic choice} 
operator $\ndet$ \cite{DeliguoroPiperno95} can easily be specified with the small-step 
rules:
%
\begin{align}\label{eq:err-choice}
	\infer{t \ndet s \to t}{} \qquad\qquad
	\infer{t \ndet s \to s}{}
\end{align}
%
This amounts to updating the separable abstract HO-GSOS law in \autoref{exa:xcl}
as follows: $\Sigma_\com(X,Y) = \{\tcomp\}\times (X\times Y)+\{\oplus\}\times(Y\times Y)$, 
$\BBT$ is the powerset monad $\PSet$, and the clauses for $\rho^\com$ are as follows:
%
\begin{align*}
	\rho^\com(\tcomp((t,S),s))	=&\; \{\tcomp(t', s) \mid t' \in S\cap Y\} \cup \{f(s) \mid f\c X\to Y \in S\}\\
		\rho^\com(t \ndet s)=&\; \{t,s\}
\end{align*}
%
The rules in~\eqref{eq:err-choice} thus jointly correspond to a single clause 
for $\rho^\com$, stating that $\{t,s\}$ is the set of direct successors of $t\ndet s$.
%
The construction~\eqref{eq:xi-constr} produces an abstract big-step SOS, which can be 
represented with the rules:
\begin{align*}
	\infer{t \ndet s \Dar v}{t \Dar v}\qquad\qquad
	\infer{t \ndet s \Dar v}{s \Dar v}
\end{align*}
%
In order to specify the behaviour of a parallel composition operator we orient to
\emph{concurrent $\lambda$-calculus}~\cite{Dezani-CiancagliniEtAl98}. This is an extension of 
the (call-by-name) $\lambda$-calculus with the erratic choice operator, as above, with a (fair)
parallel composition operator $\paral$ and with a certain version of call-by-value evaluation.
The latter feature is independent of the others, and was added to express the well-known
\emph{parallel-or} operator. We will presently not include call-by-value evaluation, 
but consider it in dedicated~\autoref{sec:cbv} instead. Intuitively, in $s\paral t$,
$s$ and $t$ are reduced simultaneously if possible, and otherwise the one 
that can be reduced is reduced, while keeping the other one intact; eventually,
neither~$s$ nor~$t$ can be reduced, meaning that $s\paral t$ is morally a value. 
We capture the latter situation by arranging a reduction from $s\paral t$ to $s\paralv t$
where $\paralv$ is a new value former.

\begin{gather*}
	\frac{t \to t' \quad s \to s'}{t \paral s \to t' \paral s'}	\qquad
	\frac{t \xto{r} t' \quad s \to s'}{t \paral s \to t \paral s'}\qquad
	\frac{t \to t' \quad s \xto{r} s'}{t \paral s \to t' \paral s}\\[1ex]
	\frac{t \xto{r} t' \quad s \xto{r} s'}{t \paral s \to t \paralv s}\qquad
	\frac{}{t\paralv s \xto{r} tr\paral sr}
\end{gather*}
%
These rules yield the following new clauses for $\rho^\com$:
%
\begin{align*}
\rho^\com((t,T)\paral (s,S))	=&\; \{t'\paral s'\mid t'\in T,s'\in S\}&
\rho^\com((t,f)\paral (s,S))	=&\; \{t\paral s'\mid s'\in S\}\\
\rho^\com((t,T)\paral (s,g))	=&\; \{t'\paral s\mid t'\in T\}&
\rho^\com((t,f)\paral (s,g))	=&\; \{t\paralv s\}
\end{align*}
%
and the following new clause for $\rho^\val$:
%
\begin{align*}
\rho^\val(t\paralv s)(r) = (t\cdot r)\paral (s\cdot r).
\end{align*}
%
The new big-step rules are as follows:
%
\begin{gather*}
	%
	\infer{s t\; \Dar   w}{s\; \Dar \; v \paralv u\qquad v t\paral ut\;\Dar w}\qquad\qquad 
	\infer{s \paral t \;\Dar v \paralv u}{s \Dar v \qquad t \Dar u & } 
\end{gather*}

%
%
%
%
%



\subsection{Call-by-Value}\label{sec:cbv}
%
Rules in \autoref{fig:rules} can be easily modified to capture the familiar call-by-value 
evaluation strategy:\sgnote{Maybe use letter codes to refer to values.}
%
\begin{gather*}
%
\frac{}{S\xto{t}S'(t)}
\qquad
\frac{}{S'(t)\xto{s}S''(t,s)}
\qquad
\frac{}{S''(t,s)\xto{r}(tr)(sr)}
%
\\[2ex]
\frac{}{K\xto{t}K'(t)}
\qquad
\frac{}{K'(t)\xto{s}t}
\qquad
\frac{}{I\xto{t}t}
\\[2ex]
%
\frac{t\to t'}{t s\to t's}~~ (a)
\qquad
\frac{t\xto{r} t'\quad s\to s'}{t s\to ts'}~~ (b)
\qquad
\frac{t\xto{s} t'\quad s\xto{r} s'}{t s\to t'}~~ (c) %
%
\end{gather*}
%
In this specification, we reduce $ts$ by first reducing $t$ (a), unless it expects an
input, i.e.\ $t$ is a value, in which case we reduce $s$ (b), unless also $s$ is a value; in the remaining 
case we evaluate $t$ on $s$ (c).
%
To turn this specification into a separated abstract HO-GSOS, 
we need to decide which arguments of the application operator are lazy 
and which are strict. In general, the behaviour of~$ts$ depends both on the 
behaviour of $t$ and of~$s$, hence both arguments must be strict. However, as explained
in \autoref{rem:total-sep}, for the above specification to be strongly separated, it must contain 
the rule 
\begin{align*}
\frac{t \to t' \quad s \to s'}{t \app s \to t' \app s'}~~(a1)
\end{align*}
%
which is not the case. We can amend the original specification by replacing 
(a) by (a1) together with
%
\begin{align*}
\frac{t \to t' \quad s \xto{r} s'}{t \app s \to t' \app s}~~(a2)
\end{align*}
%
This results in a specification to which we can apply \autoref{the:main} and 
obtain the equivalence of the small-step semantics with the following big-step semantics:
%
\begin{equation}\label{eq:bs-cbv}
\begin{gathered}
	\infer{v \Dar v}{} \qquad\qquad
	\infer{st\Dar v}{s \Dar I & t \Dar v} \qquad\qquad
	\infer{st\Dar v}{s \Dar K \quad t\Dar w\quad  K'(w)\Dar v}\\[2ex]
	\infer{st\Dar v}{s \Dar S \quad t\Dar w\quad S'(w)\Dar v}  \qquad\qquad
	\infer{st\Dar v}{s \Dar K'(r) \quad t\Dar w\quad r \Dar v} \\[2ex]
	\infer{st\Dar v}{s \Dar S'(r) \quad t\Dar w \quad S''(r,w)\Dar v}\qquad\quad
	\infer{st\Dar v}{s \Dar S''(r,q) \quad t\Dar w\quad (rw)(qw)\Dar v}
	%
\end{gathered}
\end{equation}
%
Although, the variant of the small-step specification with (a) replaced by (a1) 
and (a2) makes perfect sense, the resulting multi-step relation $\to^\star$ is not the 
standard one: e.g.\ originally $(I\app I) \app (I \app I) \to^\star I \app (II)$, but 
in the modified system $(I\app I) \app (I \app I) \to I \app I$, and hence $(I\app I) \app (I \app I) \not\to^\star I \app (II)$.  
To model the standard multi-step relation, we replace the rules (a)--(c) with the 
following ones:
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
%
\begin{gather*}
	%
	\frac{s \to s'}{s \app t\to s' \app t}\qquad
	\frac{s\xto{r} s'}{s\app t\to s \lcomp t}\qquad
	\frac{t \to t'}{s \lcomp t \to s \lcomp t'}\\[2ex]
	\frac{t\xto{r} t'}{s \lcomp t \to s \fcomp t}\qquad
	\frac{s \to s'}{s \fcomp t \to s' \fcomp t}\qquad
	\frac{s \xto{t} s'}{s\fcomp t \to s'}
	%
\end{gather*}
where $\lcomp$ and $\fcomp$ are new auxiliary composition operators. The idea is to treat 
the original application operator (juxtaposition) and $\fcomp$ as strict in the first argument 
and lazy in the second, and $\lcomp$ as lazy in the first argument and strict in the second.
The original multi-step behaviour is thus recovered,
strong separation holds and the equivalent big-step specification takes the form:
%
%
\begin{gather*}
\infer{v \Dar v}{} \quad\qquad
\infer{st \Dar v}{s \Dar w & w\lcomp t \Dar v} \quad\qquad
\infer{s\lcomp t \Dar v}{t \Dar w & s\fcomp w \Dar v} \quad\qquad
\infer{s\fcomp t\Dar v}{s\Dar I & t \Dar v} \quad\qquad
\infer{s\fcomp t\Dar v}{s\Dar K \quad K'(t)\Dar v}
\\[2ex]
\infer{s\fcomp t\Dar v}{s\Dar S \quad S'(t)\Dar v}\quad\quad ~~ 
\infer{s\fcomp t\Dar v}{s\Dar K'(r) \quad r \Dar v}\quad\quad ~~
\infer{s\fcomp t\Dar v}{s\Dar S'(r) \quad S''(r,t)\Dar v}\quad\quad ~~
\infer{s\fcomp t\Dar v}{s\Dar S''(r,q) \quad (rt)(qt)\Dar v}
%
\end{gather*}
%
Observe that the only way to obtain $st\Dar v$ is by using the following derivation
%
\begin{align*}
\infer{st\Dar v}{\infer{s \Dar w}{\vdots} \quad &\quad  \infer{w\lcomp t \Dar v}{\infer{t \Dar u}{} \quad &\quad \infer{w\fcomp u \Dar v}{\vdots}}}
\end{align*}
%
where $\vdots$ refers to undischarged premises. By inspecting the six 
rules whose conclusions match $w\fcomp u \Dar v$, it is easy to see that for terms 
in the original signature (without~$\lcomp$ and $\fcomp$) we obtain the same big-step 
semantics as in~\eqref{eq:bs-cbv}. In summary,~\eqref{eq:bs-cbv} is equivalent to
the two variants of the small-step semantics: the one with the rules (a), (b), (c) and 
the one with the rules (a1), (a2), (b), (c). Hence, they are equivalent to each other
in the sense that $t\to^\star v$ in one system iff $t\to^\star v$ in the other system
(for any value $v$). 
%
%
%
%

Our use of the auxiliary operators $\lcomp$ and $\fcomp$ tactically helped us to 
satisfy our strong separation condition. However, such operations emerge independently
in the context of \emph{pretty-big-step semantics}~\cite{Chargueraud13}. In fact, 
one can say that what we 
generally call abstract big-step SOS, specialized to the pretty-big-step semantics in this case.

\section[Variable Binders and the λ-calculus]{Variable Binders and the $\lambda$-calculus}\label{sec:lam}
%
So far, we stuck to the extended combinatory logic as the core higher-order vehicle  
for language features of interest. Modeling languages with binders adds a
certain technical overhead to the problem of modeling the small-step and 
the big-step semantics categorically. In fact, the type profile in \eqref{eq:separated1} 
turns out to be too restrictive. In this section we show how to remedy this and 
to cover the $\lambda$-calculus. Similar issue arose recently in categorical 
treatment of logical predicates for languages with binders~\cite{GoncharovSantamariaEtAl24},
and required a refinement of abstract HO-GSOS, called $\lambda$-laws.

\subsection{Separable HO-GSOS for Languages with Binders}\label{sec:bind-gsos}

We begin by equipping our ambient category $\BC$ with a closed monoidal structure 
$(\BC, \Pt, \mon,\monto)$, meant to abstract from the internal mechanisms of variable
management~\cite{Fiore08}. Monoidal closedness yields a natural isomorphism 
$(\argument)^{\flat}\c\BC(X \mon Y, Z)\to \BC(X, Y\monto Z)$, which we will need below.
%
%
%
%
%
%
%
%
%

In this setting, we need the following technical
\begin{definition}[Pointed Strength~\cite{Fiore08,HirschowitzHirschowitzEtAl22}]\label{def:pointed-str}
Let us denote by $j$ the forgetful functor from $V/\BC$ to $\BC$, sending a 
morphism $V\to X$ to $X$. Objects of $V/\BC$ are called \emph{(V-)pointed objects} of $\BC$. 

A \emph{($\Pt$-)pointed strength} on an endofunctor $F\c\BC\to\BC$ is a family of morphisms
$\mathrm{st}_{X,Y}\c FX\mon jY\to F(X\mon jY)$, natural in $X\in \BC$ and
$Y\in \Pt /\BC$, such that the following diagrams commute:
%
\begin{equation*}
\!\!\!\begin{tikzcd}[column sep=0em, row sep=normal]
 & FX\\
 FX\mon\Pt  & & F(X\mon\Pt) 
%
