&& \gamma^\val+\gamma^\com &\;= [\inl\comp D(\id,\mu) \comp \rho^\val, \inr\comp T\nabla^\klstar\comp \rho^\com\comp \Sigma_\com(\brks{\id,\gamma},\id)]&\\*
&&  &\;= [\inl\comp D(\id,\mu)\comp \rho^\val, B(\id,\nabla^\klstar)\comp\inr\comp \rho^\com\comp \Sigma_\com(\brks{\id,\gamma},\id)]\\
&&  &\;= B(\id,\nabla^\klstar)\comp [\inl\comp D(\id,\Sigmas\inl)\comp \rho^\val, \inr\comp \rho^\com\comp \Sigma_\com(\brks{\id,\gamma},\id)]\\
%
&&  &\;= B(\id,\nabla^\klstar)\comp (D(\id,\Sigmas\inl)\comp  \rho^\val+ \rho^\com)\comp \Sigma'(\brks{\id,\gamma},\id)\\
&&  &\;= B(\id,\nabla^\klstar)\comp \rho\comp \Sigma'(\brks{\id,\gamma},\id)\\
&&  &\;= \gamma\comp\iota.
\end{flalign*}
%
By applying \eqref{eq:gammas} to~\eqref{eq:op-mod-c}, we obtain a diagram 
that commutes by the definition of~$\gamma^\com$. We are left to show that $\gamma^\com$
is the only morphism, for which~\eqref{eq:op-mod-c} commutes. Let $g$ be a
morphism replacing $\gamma^\com$ for which~\eqref{eq:op-mod-c} commutes. It then 
follows that the diagram
%
%
\begin{equation*}
\begin{tikzcd}[column sep=6ex, row sep=4ex]
\Sigma'(\mS,\mS)
	\dar["{\Sigma'(\iota^\mone,\id)}"']
	\ar[rr,"\iota"] 
& 
&[1ex]
\mS
	\dar["\iota^\mone"]	
\\
%
\Sigma'(\mSv+\mSc,\mS)
	\dar["{\Sigma'(\brks{\iota,\gamma^\val+ g},\id)}"']
	\ar[rr,"{\Sigma'(\iota,\id)}"] 
& 
&[1ex]
\Sigma'(\mS,\mS)
	\dar["\gamma^\val+ g"]	
\\
%
\Sigma'(\mS\times {B(\mS,\mS)},\mS)
  \rar["{\rho}"] 
&
B(\mS,\Sigma^\star (\mS+\mS))
	\rar["{B(\id,\nabla^\klstar)}"]
&
B(\mS,\mS)
\end{tikzcd}
\end{equation*}
%
commutes as well. Since $\Sigma'(\brks{\iota,\gamma^\val+ g},\id)\comp\Sigma'(\iota^\mone,\id) = \Sigma'(\brks{\id,(\gamma^\val+ g)\comp\iota^\mone},\id)$,
we conclude that $(\gamma^\val+ g)\comp\iota^\mone$ satisfies the characteristic property~\eqref{eq:op-mod}
of $\gamma$. Therefore, $\gamma = (\gamma^\val+ g)\comp\iota^\mone$. By combining it 
with~\eqref{eq:gammas}, we obtain $\gamma^\val+ g = \gamma^\val+\gamma^\com$,
and therefore $g = T\nabla^\klstar\comp\rho^\com\comp\Sigma_\com(\brks{\iota,\gamma^\val+\gamma^\com},\id)\comp\Sigma_\com(\iota^\mone,\id)$,
using the assumption about~$g$. We obtain that any $g$, for which \eqref{eq:op-mod-c} commutes 
equals to an expression that does not depend on $g$. Hence, there is at most one such $g$.
%
\qed
%

