%
%
\begin{align*}
\hat\beta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp\hat\beta_n,\id)\appr\beta
\end{align*}
%
for every $n\in\nats$. We proceed by induction on $n$.

\medskip\noindent Induction base: $n = 0$. The goal is obtained as follows:
%
%
\begin{flalign*}
&&\hat\beta^\klstar\comp T\nabla^\klstar&\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp[\eta,\bot]\comp\iota^\mone,\id)\\
&&\;=&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com([\eta\comp\brks{\iota^\val,\gamma^\val},\bot]\comp\iota^\mone,\id)\\
&&\;=&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp\rho^{\com\val}\comp\Sigma_\com([\brks{\iota^\val,\gamma^\val},\bot]\comp\iota^\mone,\id)\\
&&\;=&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp\rho^{\com}\comp\Sigma_\com([\brks{\iota^\val,\inl\comp\gamma^\val},\bot]\comp\iota^\mone,\id)\\
&&\;\appr&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp \rho^\com\comp\Sigma_\com([\brks{\iota^\val,\inl\comp\gamma^\val},\brks{\iota^\com,\inr\comp\gamma^\com}]\comp\makebox[0pt][l]{$\iota^\mone,\id)$}\\
&&\;=&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp \rho^\com\comp\Sigma_\com(\brks{\id,[\inl\comp\gamma^\val,\inr\comp\gamma^\com]\comp\iota^\mone},\id)\\
&&\;=&\;[\eta,\beta]^\klstar\comp T\iota^\mone\comp\gamma^\com\\
&&\;=&\;\beta.
\intertext{Induction step: $n > 0$. We have}
%
&&\hat\beta^\klstar\comp T\nabla^\klstar&\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp\hat\beta_n,\id)\\
&&\;=&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp\Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp \hat\beta_{n-1}^\klstar\comp\hat\gamma^\com,\id)&\\
&&\;=&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl^\klstar\comp\dl\comp\Sigma_\com(TT\brks{\iota^\val,\gamma^\val}\comp T\hat\beta_{n-1}\comp\hat\gamma^\com,\id)&\\
&&\;=&\;\hat\beta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl^\klstar\comp T\Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp\hat\beta_{n-1},\id)\comp\dl\comp\Sigma_\com(\hat\gamma^\com,\id).&
\end{flalign*}
By induction hypothesis, the latter is smaller or equal $\beta^\klstar\comp\dl\comp\Sigma_\com(\hat\gamma^\com,\id)$,
