\subsection{Proof of \autoref{lem:big-and-small}}
%
%
The diagram~\eqref{eq:op-mod-c} identifies
$\gamma^\com$ as the unique fixpoint of $f\mto T\nabla^\klstar\comp\rho^\com\comp\Sigma_\com(\brks{\id,(\gamma^\val+ f)\comp\iota^\mone},\id)$,
hence, also as the least one. Thus, $\gamma^\com = \bigjoin_n \gamma^\com_n$ where $\gamma^\com_0 = \bot$ and $\gamma^\com_{n+1} = T\nabla^\klstar\comp\rho^\com\comp\Sigma_\com(\brks{\id,(\gamma^\val+\gamma_n^\com)\comp\iota^\mone},\id)$, and it suffices to show 
%
\begin{align}\label{eq:main-ind}
	\hat\zeta^\klstar\comp\gamma^\com_n\appr\zeta
\end{align}
%
for all $n$. The induction base is obvious. For the induction step, assume~\eqref{eq:main-ind}
and show $\hat\zeta^\klstar\comp\gamma^\com_{n+1}\appr\zeta$. By \autoref{ass:compl}, $\mSc$ is a coproduct of $\Sigma_\com(\mSv,\mS)$ and $\Theta(\mSv,\mSc,\mS)$.
We thus reduce to two inequations:
%
\begin{align*}
\hat\zeta^\klstar\comp\gamma^\com_{n+1}\comp\Sigma_\com(\iota^\val,\id) 		\appr&\; \zeta\comp\Sigma_\com(\iota^\val,\id),\\*
\hat\zeta^\klstar\comp\gamma^\com_{n+1}\comp\Sigma_\com(\iota,\id)\comp\theta   \appr&\; \zeta\comp\Sigma_\com(\iota,\id)\comp\theta.
\end{align*}
%
The first inequation is easy to obtain by unfolding definitions:
%
\begin{flalign*}
&& \hat\zeta^\klstar\comp\gamma^\com_{n+1}&\,\comp\Sigma_\com(\iota^\val,\id)\\*
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp\rho^\com\comp{\Sigma_\com(\brks{\iota,\gamma^\val+\gamma^\com_n},\id)}\comp\Sigma_\com(\inl,\id)&\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp\rho^\com\comp\Sigma_\com(\brks{\iota^\val,\inl\comp\gamma^\val},\id)\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp\rho^{\com\val}\comp\Sigma_\com(\brks{\iota^\val,\gamma^\val},\id)  \\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp\eta,\id)  \\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp \hat\zeta,\id)\comp\Sigma_\com(\iota^\val,\id)  \\
&&  &\;= \zeta\comp\Sigma_\com(\iota^\val,\id). &\by{\autoref{lem:bs-fix}}
%
\end{flalign*}
%
For the second inequation, we need the following auxiliary property:
%
\begin{align}\label{eq:main-help}
\Sigma_\com(\eta\comp\fst\klplus\snd,\inl)\comp\theta\comp\Theta(\brks{\iota^\val,\gamma^\val},\brks{\iota^\com,\gamma^\com_n},\id)
= \Sigma_\com(\eta\comp\iota^\val\klplus\gamma^\com_n,\inl)\comp\theta,
\end{align}
which entails the goal as follows:
\begin{flalign*}
%
&& \hat\zeta^\klstar\comp\gamma&\,^\com_{n+1}\comp\Sigma_\com(\iota,\id)\comp\theta\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp\rho^\com\comp{\Sigma_\com(\brks{\iota,\gamma^\val+\gamma^\com_n},\id)}\comp\theta&\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp\rho^\com\comp{\Sigma_\com([\id\times\inl,\id\times \inr],\id)}\comp\theta\comp\Theta(\brks{\iota^\val,\gamma^\val},\brks{\iota^\com,\gamma^\com_n},\id)\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp{T(\iota^\com\comp\Sigma_\com(\eta,\eta))}\comp\dl\comp\\
	&&&\qquad\qquad\Sigma_\com(\eta\comp\fst\klplus\snd,\inl)\comp\theta\comp\Theta(\brks{\iota^\val,\gamma^\val},\brks{\iota^\com,\gamma^\com_n},\id)&\by{\eqref{eq:str_sep}}\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp T\iota^\com\comp T\Sigma_\com(\eta,\eta)\comp\dl\comp\Sigma_\com(\eta\comp\iota^\val\klplus\gamma^\com_n,\inl)\comp\theta&\by{\eqref{eq:main-help}}\\
&&  &\;= \zeta^\klstar\comp T\Sigma_\com(\nabla^\klstar,\nabla^\klstar)\comp T\Sigma_\com(\eta,\eta)\comp\dl\comp\Sigma_\com(\eta\comp\iota^\val\klplus\gamma^\com_n,\inl)\comp\theta\\
&&  &\;= \zeta^\klstar\comp T\Sigma_\com(\nabla,\nabla)\comp\dl\comp\Sigma_\com(\eta\comp\iota^\val\klplus\gamma^\com_n,\inl)\comp\theta\\
&&  &\;= \zeta^\klstar\comp\dl\comp \Sigma_\com(T\nabla,\nabla)\comp\Sigma_\com(\eta\comp\iota^\val\klplus\gamma^\com_n,\inl)\comp\theta\\
%
&&  &\;= \zeta^\klstar\comp\dl\comp\Sigma_\com([\eta\comp\iota^\val,\gamma^\com_n],\id)\comp\theta\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl^\klstar\comp T\Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp \hat\zeta,\id)\comp\dl\comp\Sigma_\com([\eta\comp\iota^\val,\gamma^\com_n],\id)\comp\theta\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl^\klstar\comp\dl\comp \Sigma_\com(TT\brks{\iota^\val,\gamma^\val}\comp T\hat\zeta,\id)\comp\Sigma_\com([\eta\comp\iota^\val,\gamma^\com_n],\id)\comp\theta\\
&&  &\;= \hat\zeta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp\Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp \hat\zeta^\klstar\comp[\eta\comp\iota^\val,\gamma^\com_n],\id)\comp\theta\\
&&  &\;\appr \hat\zeta^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp\Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp \hat\zeta^\klstar\comp[\eta\comp\iota^\val,\eta\comp\iota^\com],\id)\comp\theta&\by{\eqref{eq:main-ind}}\\
&&  &\;= \zeta^\klstar\comp\dl\comp\Sigma_\com([\eta\comp\iota^\val,\eta\comp\iota^\com],\id)\comp\theta\\
&&  &\;= \zeta\comp\Sigma_\com(\iota,\id)\comp\theta.
\intertext{The equation~\eqref{eq:main-help} is shown as follows:}
%
&& \!\!\!\Sigma_\com(\eta\comp\fst&\;\klplus\snd,\inl)\comp\theta\comp\Theta(\brks{\iota^\val,\gamma^\val},\brks{\iota^\com,\gamma^\com_n},\id)\\*
&&  &\;= \Sigma_\com(\id\klplus\id,\inl)\comp\Sigma_\com(\eta\comp\fst+\snd,\id)\comp\theta\comp\Theta(\brks{\iota^\val,\gamma^\val},\brks{\iota^\com,\gamma^\com_n},\id)\\
&&  &\;= \Sigma_\com(\id\klplus\id,\inl)\comp\theta\comp\Theta(\eta\comp\fst,\snd,\id)\comp\Theta(\brks{\iota^\val,\gamma^\val},\brks{\iota^\com,\gamma^\com_n},\id)\\
&&  &\;= \Sigma_\com(\id\klplus\id,\inl)\comp\theta\comp\Theta(\eta,\id,\id)\comp\Theta(\iota^\val,\gamma^\com_n,\id)\\
&&  &\;= \Sigma_\com(\id\klplus\id,\inl)\comp\Sigma_\com(\eta+\id,\id)\comp\theta\comp\Theta(\iota^\val,\gamma^\com_n,\id)\\
&&  &\;= \Sigma_\com(\eta\klplus\id,\inl)\comp\theta\comp\Theta(\iota^\val,\gamma^\com_n,\id)\\
&&  &\;= \Sigma_\com(\eta\comp\iota^\val\klplus\gamma^\com_n,\inl)\comp\theta&\tag*{$\qed$}
\end{flalign*}

\subsection{Proof of \autoref{lem:bs-fix}}
%
By rewriting the relevant subexpression of~\eqref{eq:bs-xi}:
\begin{flalign*}
&& [\eta,&\,f^\klstar\comp T\mu\comp\xi^\klstar\comp\dl\comp\Sigma_\com(f,\id)]\comp\iota^\mone&\\
&&  &\;= [\eta, f^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp T\Sigma_\com(\brks{\iota^\val,\gamma^\val},\id)\comp\dl\comp\Sigma_\com(f,\id)]\comp\iota^\mone&\by{\autoref{lem:xi-mS}}\\
&&  &\;= [\eta, f^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val},\id)\comp\Sigma_\com(f,\id)]\comp\iota^\mone\\
&&  &\;= [\eta, f^\klstar\comp T\nabla^\klstar\comp(\rho^{\com\val})^\klstar\comp\dl\comp \Sigma_\com(T\brks{\iota^\val,\gamma^\val}\comp f,\id)]\comp\iota^\mone. &\tag*{$\qed$}
\end{flalign*}
%

\subsection{Proof of \autoref{lem:bs-fix-lam}}
%
Observe first, that the following diagram commutes:
\begin{equation*}
%
\begin{tikzcd}[column sep=-7em, row sep=0ex]
