	\dar["{\Sigma_\com(\Sigma_\val (\id\times(\mmul\monto\id)),\id)}"']
	\ar[ddr,"{\Sigma_\com(\brks{\iota^\val\comp\Sigma_\val\fst,\Sigma_\val(\mmul\times\id)},\id)}", bend left=20, pos=.3]
& &
\\[4ex]
