\Sigma_\com(\mu^2\Sigma\times\Sigma_\val(\mS\times (\mS\monto\mS)),\mu^2\Sigma)\qquad\quad
	\ar[d, "{\Sigma_\com(\id\times \rho^\val,\id)}"']
&
\\[5ex]
&
\Sigma_\com(\mu^2\Sigma\times D(\mS,\Sigmas(\mS+\mS)),\mu^2\Sigma)\quad
	\ar[dd,"{\Sigma_\com(\id\times D(\mmul,\id),\id)}",pos=.3]
	\ar[ruuuu, "{\Sigma_\com(\mmul\times\id,\mmul)}", bend right=35, pos=.6, end anchor=-120]
&
\\[2ex]
\Sigma_\com(\mu^2\Sigma\times D(\mu^2\Sigma,\Sigmas(\mu^2\Sigma+\mS)),\mu^2\Sigma)
	\ar[dd,"\rho^{\com\val}"']
	\ar[dddr, "{\Sigma_\com(\id\times D(\id,[\mu,\id]^\klstar),\id)}", bend right=25,pos=.475]
