T\Sigmas(\mu^2\Sigma+\Sigmas(\mu^2\Sigma+\mS))\qquad
	\ar[dddd,"{T[\Sigmas\inl,[\Sigmas\inl,\eta\comp\inr]^\klstar]^\klstar}"']
	\ar[dddr, "{T\Sigmas(\id+[\mu,\id]^\klstar)}", bend right=30,pos=.2]
