We then prove the claim by modifying the argument from \autoref{lem:bs-fix}.
%
It suffices to show that
%
\begin{align*}
T\nabla^\klstar\comp\xi\comp\Sigma_\com(\Sigma_\val\brks{\id,(\oname{subst}\comp(\id\times\mu))^{\flat}},\id) 
= T\nabla^\klstar\comp\rho^{\com\val}\comp\Sigma_\com(\brks{\iota^\val,\gamma^\val},\id).
\end{align*}
%
Using the definition 
%
\begin{align*}
\xi=T[\Sigmas\inl,[\Sigmas\inl,\eta\comp\inr]^\klstar]^\klstar\comp\rho^{\com\val}\comp\Sigma_\com(\brks{\iota^\val\comp\Sigma_\val\fst,\,   \rho^\val},\id)\comp\Sigma_\com(\Sigma_\val(\eta\times\id),\eta)
\end{align*}
and the above diagram,
%
\begin{align*}
T\nabla^\klstar\comp\xi\comp&\,\Sigma_\com(\Sigma_\val\brks{\id,(\oname{subst}\comp(\id\times\mu))^{\flat}},\id) \\*
=\;& T\nabla^\klstar\comp T[\Sigmas\inl,[\Sigmas\inl,\eta\comp\inr]^\klstar]^\klstar\comp\rho^{\com\val}\comp\Sigma_\com(\brks{\iota^\val\comp\Sigma_\val\fst,\, \rho^\val},\id)\comp\\
&\qquad\Sigma_\com(\Sigma_\val(\eta\times\id),\eta) \comp\Sigma_\com(\Sigma_\val\brks{\id,(\oname{subst}\comp(\id\times\mu))^{\flat}},\id)\\
=\;& T\nabla^\klstar\comp T[\Sigmas\inl,[\Sigmas\inl,\eta\comp\inr]^\klstar]^\klstar\comp\rho^{\com\val}\comp\Sigma_\com(\brks{\iota^\val\comp\Sigma_\val\fst,\, \rho^\val},\id)\comp\\
&\qquad\Sigma_\com(\Sigma_\val(\eta\times\id),\eta) \comp\Sigma_\com(\Sigma_\val (\id\times(\mmul\monto\id)),\id)\comp\Sigma_\com(\Sigma_\val\brks{\id,\oname{subst}^{\flat}},\id) \\
=\;& T\nabla^\klstar\comp T[\Sigmas\inl,[\Sigmas\inl,\eta\comp\inr]^\klstar]^\klstar\comp\rho^{\com\val}\comp\Sigma_\com(\brks{\iota^\val\comp\Sigma_\val\fst,\, \rho^\val},\id)\comp\\
&\qquad\Sigma_\com(\Sigma_\val (\id\times(\mmul\monto\id)),\id)\comp\Sigma_\com(\Sigma_\val(\eta\times\id),\eta) \comp\Sigma_\com(\Sigma_\val\brks{\id,\oname{subst}^{\flat}},\id) \\
=\;& T\nabla^\klstar\comp\rho^{\com\val}\comp \Sigma_\com(\id\times D(\id,\nabla^\klstar),\id)\comp\\
&\qquad\Sigma_\com(\brks{\iota^\val\comp\Sigma_\val\fst,\, \rho^\val},\id) \comp\Sigma_\com(\Sigma_\val\brks{\id,\oname{subst}^{\flat}},\id)\\
