Given an $n$-dimensional map $\mathbf{P}(\mathbf{a})$ over $\Zp{k}^n$, 
the ring of $n$-dimensional column vectors over $\Zp{k}$, let $S_{\mathbf{a}}=
\{\mathbf{P}^i(\mathbf{a})\}_{i=0}^\infty$
denote the sequence generated by iterating $\mathbf{P}$ from the initial state $\mathbf{a}$, where $\mathbf{P}^i$ represents 
the $i$-fold application of $\mathbf{P}$, and $\mathbf{a}=(a_1, a_2, \cdots, a_n)^\intercal\in\Zp{k}^n$.
If the sequence $S_{\mathbf{a}}$ satisfies the recurrence relation
\begin{equation}\label{eq:2:cP}
\mathbf{P}^i(\mathbf{a})+c_1 \mathbf{P}^{i-1}(\mathbf{a})+\cdots+c_L \mathbf{P}^{i-L}(\mathbf{a})=0
\end{equation}
for all $i\ge L$, it is called an $L$-order linear recurrence over $\Zp{k}^n$.
The characteristic polynomial of the sequence is given by
$f_{\rm c}(t)=1+c_1 t+\cdots+c_{L-1} t^{L-1}+ c_L t^L$.
Note that the operators in \eqref{eq:2:cP} can be compactly represented as $f_c(\mathbf{P})$.

Let the generating function of the vector-valued sequence be defined as $G_{\mathbf{a}}(t)=\sum_{i=0}^{\infty} d(\mathbf{P}^i(\mathbf{a}))t^i$, where
$d(\bx)=\sum_{i=1}^n x_i p^{i-1}$ is a function applied element-wise to each coordinate of the vector $\bx=(x_1, x_2, \cdots, x_n)^\intercal\in\Zp{k}^n$. 
Then, one has 
\begin{multline*}
  G_{\mathbf{a}}(t) \cdot f_{\rm c}(t) = \sum_{i=0}^{L-1} \left( \sum_{j=0}^{i} c_j d(\mathbf{P}^{i-j}(\mathbf{a})) \right) t^i \\
    \quad + \sum_{i=L}^{\infty} \left( \sum_{j=0}^{L} c_j d(\mathbf{P}^{i-j}(\mathbf{a})) \right) t^i. 
\end{multline*}
Since 
$\sum_{j=0}^{L} c_j d(\mathbf{P}^{i-j}(\mathbf{a}))=d(\sum_{j=0}^{L} c_j \mathbf{P}^{i-j}(\mathbf{a}))$ for any $i\ge L$, one has
\begin{equation}\label{eq:PRE:gt}
G_{\mathbf{a}}(t) \cdot f_{\rm c}(t)=g(t)
\end{equation}
from \eqref{eq:2:cP}, where $g(t)= \sum_{i=0}^{L-1} \left( \sum_{j=0}^{i} c_j d(\mathbf{P}^{i-j}(\mathbf{a})) \right) t^i$. Moreover, 
it follows from \eqref{eq:2:cP} that
\begin{equation}\label{eq:PRE:Ht}
H(t)=(1-t^{T_s})\cdot G_{\mathbf{a}}(t)=\sum_{i=0}^{T_s-1}d(\mathbf{P}^i(\mathbf{a}))t^i, 
\end{equation}
where $T_s$ denotes the least period of the sequence $S_{\mathbf{a}}$. 
There is $f(t)=b_0+b_1 t+\cdots+b_{m-1}t^{m-1}+b_mt^m$ such that
\begin{equation}\label{eq:ft}
f(t)=\frac{f_{\rm c}(t)}{\gcd(g(t), f_{\rm c}(t))}.
\end{equation}
Since $f(t)$ is the polynomial of the smallest degree among all characteristic polynomials of the sequence $S_{\mathbf{a}}$, it is referred to as the \textit{minimal polynomial} of the sequence.

The minimal polynomial can also be expressed using the generating function.
From~\eqref{eq:PRE:gt} and~\eqref{eq:PRE:Ht}, it follows that
\[
\frac{f_{\rm c}(t)}{g(t)}=\frac{1-t^{T_s}}{H(t)}, 
\]
which, together with \eqref{eq:ft}, implies that the minimal polynomial is given by
$f(t)=\frac{1-t^{T_s}}{\gcd(H(t), 1-t^{T_s})}$, removing the redundant factors to capture only the essential periodicity.
Thus, as stated in Lemma~\ref{le:2:T=P_e}, the least period of a sequence is determined by the order of the corresponding minimal polynomial. When $k=1$, $\mathbb{Z}_p$ is a finite field, the order of the 
polynomial is quantified as Lemma~\ref{le:2:P_1} shown.

\begin{lemma}\label{le:2:T=P_e}
%Let $f(t)$ be a minimal polynomial of a periodic sequence $s$ over $\Zp{k}^n$, then
%the least period $T_s$ of $s$ satisfies $T_s=P_k(f)$.
For a periodic sequence $S_{\mathbf{a}}$ over $\Zp{k}^n$, the order of its minimal polynomial $f(t)$ over $\mathbb{Z}_{p^k}$, denoted as $P'_k(f)$, is equal to the least period of $S_{\mathbf{a}}$.
\end{lemma}
\begin{proof}
See proof in \cite{Linear:Zierler:1959}.
\end{proof}

\begin{lemma}\label{le:2:P_1}
Let \( f(x) \) be a polynomial over \( \mathbb{F}_q \) with a nonzero constant term and assume that  
\[ f(x) = f_1(x)^{e_1} f_2(x)^{e_2} \cdots f_r(x)^{e_r}, \]  
where \( f_1(x), f_2(x), \ldots, f_r(x) \) are \( r \) distinct irreducible polynomials in \( \mathbb{F}_q[x] \) and \( e_1, e_2, \ldots, e_r \) are \( r \) positive integers, then  
\[ 
p(f) = \lcm(p(f_1), p(f_2), \ldots, p(f_r)) \cdot p^t,
\]
where $t=\min\{t\vvert p^t \geq \max(e_1, e_2, \ldots, e_r)\}$.
\end{lemma}
\begin{proof}
See proof in \cite{Wan:Lecture:2003}.
\end{proof}

It follows from \eqref{eq:2:cP} and the definition of $f(t)$ that
\begin{equation}\label{eq:2:An2x}
\mathbf{P}^{i}(\mathbf{a})=-\sum_{j=1}^{m}b_i\mathbf{P}^{i-j}(\mathbf{a}).
\end{equation}
To disclose the relation between $f(t)$ and $\mathbf{P}(\mathbf{a})$, construct a map
\begin{equation}\label{eq:3:ma=}
\mathbf{A}(\bx)=
\bM\cdot \bx
\end{equation}
over $\mathbb{Z}^{mn}_{p^k}$, 
\begin{equation*}
\bM=
\begin{bmatrix}
    \bo      & \mathbf{I}    &\cdots & \bo\\
    \vdots          & \vdots        &\vdots & \vdots    \\
    \bo      & \bo    &\cdots & \mathbf{I}\\
  -b_1\mathbf{I}    & -b_2\mathbf{I}  &\cdots & -b_{m}\mathbf{I}
\end{bmatrix}_{mn\times mn}, 
\end{equation*}
and $\mathbf{I}$ denotes the $n\times n$ identity matrix.
The minimal polynomial of sequence $\{\bM^i\cdot \bx\}_{i\geq 0}$ is also $f(t)$, and its least period over $\mathbb{Z}^{mn}_{p^k}$
is denoted by $T_k$.
For an initial state $\bx_0$, let $T_k(\bx_0)$ be the least period of $\{\mathbf{A}^i(\bx)\}_{i\geq 0}$ over $\Zp{k}$. Note that
$T_k{(\bx_0)}$ is a divisor of $T_k$.

For any state $\mathbf{a}$ in $\mathbb{Z}^n_{p^k}$, one can form the state
\[
\bx =(\mathbf{a}^\intercal, (\mathbf{P}(\mathbf{a}))^\intercal, (\mathbf{P}^2(\mathbf{a}))^\intercal, \cdots, (\mathbf{P}^{m-1}(\mathbf{a}))
^\intercal)^\intercal\in \mathbb{Z}^{mn}_{p^k}.
\]
However, given an arbitrary state $\bx$ in $\mathbb{Z}^{mn}_{p^k}$, there may not exist a corresponding state $\mathbf{a}$ in $\mathbb{Z}^n_{p^k}$ that satisfies the above relationship. Consequently, one may first analyze the structure of the functional graph generated by $\mathbf{A}(\bx)$ and then derive that of $\mathbf{P}(\mathbf{a})$ by truncation.

