\section{The period distribution of a permutation map over $\Zp{k}$}
\label{sec:main}

\subsection{The Period Dstribution of $\mathbf{A}(\bx)$ over $\Zp{k}^{mn}$}
\label{subsec:3A}

Given the minimal polynomial $f(t)$, the companion matrix $\bM$ in (\ref{eq:3:ma=}) is uniquely determined.
The analysis of the period distribution of map $\mathbf{A}(\bx)$ relies on the
order of $f(t)$ and its factorization in $\Zp{k}[t]$.
When $f(t)$ is irreducible, one passes to the minimal ring extension $\mathbb{R}_k$ of $\mathbb{Z}_{p^k}$, over which $f(t)$ splits into linear factors. 
Lemma~\ref{le:3:orderZ=R} then shows that the order of $f(t)$ in $\mathbb{Z}_{p^k}[t]$ coincides with its order in $\mathbb{R}_k[t]$. Moreover, Lemma~\ref{le:3A:P_kfp} establishes that, beyond a threshold $k_{\rm s}$, the order in $\mathbb{R}_k[t]$ increases by a factor of $p^{k-k_{\rm s}}$ relative to $P_1(f)$.

\begin{lemma}\label{le:3:orderZ=R}
The order of $f(t)$ in $\mathbb{Z}_{p^k}[t]$, denoted by $P'_k(f)$, is equal to its order in $\mathbb{R}_{k}[t]$, denoted by $P_k(f)$.
\end{lemma}
\begin{proof}
First, by definition of $P'_k(f)$, there exists a polynomial $g(t)\in\mathbb{Z}_{p^k}[t]$ such that 
\begin{equation}\label{eq:3A:gftP}
    g(t)f(t)= t^{P'_k(f)}-1
\end{equation}
in $\mathbb{Z}_{p^k}[t]$. Since $\mathbb{R}_k$
is an extension ring of $\mathbb{Z}_{p^k}$, there is a map $\varphi:\mathbb{Z}_{p^k}[t]\rightarrow\mathbb{R}_k[t]$ that maps each polynomial to itself with coefficients reinterpreted in $\mathbb{R}_k[t]$. Since $\varphi$ is a ring homomorphism, it preserves polynomial identities. Thus, Eq.~\eqref{eq:3A:gftP} holds in $\mathbb{R}_k[t]$. By definition of $P_k(f)$, one has
\begin{equation}\label{eq:3A:P'=P}
    P_k(f)\mid P'_k(f).
\end{equation}
Next, by definition of $P_k(f)$, there is $g'(t)\in\mathbb{R}_{k}[t]$ such that \begin{equation}\label{eq:3A:g'f}
    g'(t)f(t) = t^{P_k(f)} - 1.
\end{equation}
in $\mathbb{R}_{k}[t]$. By the construction of $\mathbb{R}_k$, there exists a minimal generating set $\{1, \beta_1, \beta_2, \cdots, \beta_s\}$, where the set $\{\beta_i\}_{i=1}^s$ is algebraically independent over $\mathbb{Z}_{p^k}$. %meaning $\beta_i \neq \sum_{j\neq i} c_j\beta_j$ for any $c_j \in \mathbb{Z}_{p^k}$.
Then, write
\begin{equation*}
%\label{eq:3A:g'=g0+}
    g'(t) = g'_0(t)+\sum_{i=1}^s \beta_i g'_i(t),
\end{equation*}
where $g'_i(t)\in\Zp{k}[t]$. 
Substituting this expression into \eqref{eq:3A:g'f} yields
\begin{equation*}
    g'_0(t)f(t) + \sum_{i=1}^s \beta_i g'_i(t)f(t) = t^{P_k(f)} - 1.
\end{equation*}
Let the left-hand side of the above equation 
can be expressed as 
$\sum_{i=0}b_it^i$,
where $b_i=c_{i,0} +\sum_{j=1}^s c_{i,j}\beta_j$ and $c_{i,0}\in \mathbb{Z}_{p^k}$.
Then $b_0=c_{0,0}=1, b_{P_k(f)}=c_{P_k(f),0}=1$ and $b_i=c_{i,0}=0$ for any $i\not\in\{0, P_k(f)\}$.
Assume $\beta_{j_1}g'_{j_1}(t)f(t)\neq 0$. There is $c_{i_1,j_1}\neq 0$.
Since $\beta_i$ cannot be expressed as a linear combination of other generators, 
there is $b_{i_1}-c_{i_1,0}\neq 0$, which leads to a contradiction.
So $g'_0(t)f(t)=t^{P_k(f)}-1$ in $\mathbb{Z}_{p^k}[t]$, namely $P'_k(f)\mid P_k(f)$. Combining this with relation~\eqref{eq:3A:P'=P}, this lemma holds.
\end{proof}

\begin{lemma}\label{le:3A:P_kfp}
If the monic polynomial $f(t)$ has no root of value zero in $\mathbb{R}_1$, then one has
  \begin{equation}\label{eq:f:pef-nomul}
      P_k(f)=
      \begin{cases}
            P_1(f)                & \mbox{if } k<k_{\rm s}; \\
            p^{k-k_{\rm s}}P_1(f) & \mbox{if } k\ge k_{\rm s}, 
      \end{cases}
  \end{equation}
where
\begin{equation}\label{eq:3A:f_hatkf_define}
    k_{\rm s}=\max\{k\mid P_k(f)=P_1(f)\}.
\end{equation}
\end{lemma}
\begin{proof}
If $k\leq k_{\rm s}$, \eqref{eq:f:pef-nomul} holds by~\eqref{eq:3A:f_hatkf_define}. 
If $k\geq k_{\rm s}$, one can prove 
\begin{equation}\label{eq:3A:ftmnom}
\left\{
\begin{split}
    P_{k_{\rm s}+i}(f)   & = p^iP_1(f);\\
    P_{k_{\rm s}+i+1}(f) &\neq p^iP_1(f)    
\end{split}
\right.
\end{equation}
by mathematical induction on $i$. 
When $i=0$, it follows from the definition of $k_{\rm s}$ that \eqref{eq:3A:ftmnom} holds. Assume that \eqref{eq:3A:ftmnom} holds for $i\leq s$. When $i=s+1$, in the ring $\mathbb{R}_{{k_{\rm s}+s+1}}[t]$, there is $v(t)\not\in(p)$ such that $f(t)\nmid v(t)$ but
\begin{equation*}%\label{eq:3A:vkt}
    f(t) \mid (t^{p^{s}P_{1}(f)}-1+p^{k_{\rm s}+s} \cdot v(t)).
\end{equation*}
Note that $(t^{p^{s}P_{1}(f)}-1)(\sum_{i=0}^{p-1} t^{i \cdot p^{s}P_{1}(f)}) = t^{ p^{s+1}P_{1}(f)}-1$, one can construct a polynomial
\begin{equation}\label{eq:3A:qt}
    q(t) = p^{k_{\rm s}+s} \cdot v(t) r(t)
\end{equation}
where $r(t)=\sum_{i=0}^{p-2}(p-1-i)t^{i\cdot p^{s}P_{1}(f)}$.
It follows that 
\begin{multline}\label{eq:3A:t-1rt}
\left(\sum_{i=0}^{p-1} t^{i \cdot p^{s}P_{1}(f)} - q(t)\right)  \left(t^{p^{s}P_{1}(f)} - 1 + p^{k_{\rm s}+s} \cdot v(t)\right) \\ 
= t^{p^{s+1}P_{1}(f)} - 1+ p^{k_{\rm s}+s+1} \cdot v(t).
\end{multline}
%where 
%\begin{equation*}
%\begin{split}
%   R(t) &= r(t)(t^{p^{s}P_{1}(f)}-1) -\sum_{i=0}^{p-1} t^{i \cdot p^{s}P_{1}(f)}\\
%   &=-p.
%\end{split}
%\end{equation*}
Hence $f(t)\mid t^{p^{s+1}P_{1}(f)} - 1$ in $\mathbb{R}_{{k_{\rm s}+s+1}}[t]$, namely 
$P_{k_{\rm s}+s+1}=p^{s+1}P_{1}(f)$.
In $\mathbb{R}_{{k_{\rm s}+s+2}}[t]$, it follows that $v'(t)\not\in(p)$ such that $f(t)\nmid v(t)$ and
\begin{equation*}
    f(t) \mid t^{p^{s}P_{1}(f)}-1+p^{k_{\rm s}+s} \cdot v'(t).
\end{equation*}
Similarly to~\eqref{eq:3A:t-1rt}, there is $f(t)\mid t^{p^{s+1}P_{1}(f)} - 1+ p^{k_{\rm s}+s+1} \cdot v'(t)$. Since $f(t)\nmid v(t)$, one obtain $f(t)\nmid t^{p^{s+1}P_{1}(f)}-1$.
So \eqref{eq:3A:ftmnom} holds for $i=s+1$.
This completes the proof of \eqref{eq:3A:ftmnom}, which means that 
\begin{equation*}
\left\{
    \begin{split}
        P_{k}(f) & \nmid p^{k-k_{\rm s}-1} P_{1}(f); \\
        P_{k}(f) & \mid  p^{k-k_{\rm s}}P_{1}(f).
    \end{split}
    \right.
\end{equation*}
Thus, this lemma holds.
\end{proof}

A monic polynomial $f(t)$ can be represented as
\[
f(t)=(t-\alpha_{1, k})(t-\alpha_{2, k})\cdots(t-\alpha_{m, k})
\]
in $\mathbb{R}_{{k}}[t]$.
Then these roots should reduce modulo $p$ to the roots $\{\alpha_i\}_{i=1}^m$ in $\mathbb{R}_{{1}}[t]$, namely 
\begin{equation}\label{eq:3A:alpha-}
    \alpha_{i, k}-\alpha_i\in(p). 
\end{equation}
Based on the analysis of root lifting between the rings $\mathbb{R}_k$, the specific value $k_{\rm s}$ can be explicitly determined. When the polynomial $f(t)$ has no non-zero multiple roots in $\mathbb{R}_1$, Lemma~\ref{le:3:hensem3} provides the exact formulation for $k_{\rm s}$.

\begin{lemma}\label{le:3:hensem3}  
If the monic polynomial $f(t)$ has exactly $m$ distinct non-zero roots 
in $\mathbb{R}_1$, (\ref{eq:f:pef-nomul}) holds
with $k_{\rm s}=\min\limits_{1\leq i\leq m}f_{\rm k}(\alpha_i)$, 
%\begin{equation}\label{eq:3:ef=minealpha}
%k_{\rm s}=\min\{k(\alpha_1), k(\alpha_2), \cdots, k(\alpha_m)\}, 
%\end{equation}  
where $\alpha_i$ is the $i$-th root, 
\begin{equation}\label{eq:3:ealphaj}
f_{\rm k}(\alpha_i)=\max\left\{ k \vvert \ord_{k}\left(g^{(k-1)}(\alpha_i)\right)=\ord_1(\alpha_i) \right\}, 
\end{equation}
%$g^{(k+1)}(\alpha_i)=g^{(k)}(\alpha_i)$ 
and
$g^{(n)}(x)$ indicates iterating 
\begin{equation}\label{eq:2:alphai+1}
g(x)=x-f'(x)^{-1}\cdot f(x)
\end{equation}
$n$ times.
\end{lemma}
\begin{proof}
Since $f(t)$ has no non-zero multiple root in $\mathbb{R}_1$ and~\eqref{eq:3A:alpha-}, the same holds in $\mathbb{R}_k$ for any $k$. 
Then, $f(t)=\prod\limits_{i=1}^m f_i$, where 
each linear factor $f_i=t-\alpha_{i,k}$ is pairwise coprime.
Let 
\begin{equation}\label{eq:3A:l}
l=\lcm(P_k(f_1), P_k(f_2), \cdots, P_k(f_m)), 
\end{equation}
then $f_i\mid t^{P_k(f_i)}-1 \mid t^l-1$. From $f_i$ being pairwise coprime, one has $f\mid t^l-1$ by the Chinese Remainder Theorem, namely $P_k(f)\mid l$. Otherwise, since $P_k(f_i) \mid P_k(f)$ for any $i$, one has $l\mid P_k(f)$. It follows from \eqref{eq:3A:l} that 
\begin{equation}\label{eq:3:P_efnomul}
P_k(f)=\lcm(P_k(f_1), P_k(f_2), \cdots, P_k(f_m)).
\end{equation}

In $\mathbb{R}_k$, since $\mathbb{R}_k/(p)\cong\mathbb{R}_1$, one has $\alpha_i\in\mathbb{R}_k$ and $f(\alpha_i)\in(p)$. As $f(t)$ has no multiple root in $\mathbb{R}_1$, one has 
\begin{equation}\label{eq:3A:f'}
    f'(\alpha_i)\not\in(p). 
\end{equation}
Let $\alpha^{(n)}_i=g^{(n)}(\alpha_i)$. It follows from \eqref{eq:2:alphai+1} that $\alpha^{(n)}_i-\alpha_i\in(p)$.  
Then $f'(\alpha^{(n)}_i)-f'(\alpha_i)\in(p)$ by Taylor's formula. Referring to \eqref{eq:3A:f'}, one has $f'(\alpha^{(n)}_i)\not\in(p)$.
Then, from \eqref{eq:2:alphai+1}, one has 
\begin{multline*}
%\label{eq:3:f'i}   
f(\alpha^{(n+1)}_i)=f(\alpha^{(n)}_i)+f'(\alpha^{(n)}_i)(-f'(\alpha^{(n)}_i)^{-1}f(\alpha^{(n)}_i)+ \\ \sum^m_{j=2}f^{(j)}(\alpha^{(n)}_i)(-f'(\alpha^{(n)}_i)^{-1}f(\alpha^{(n)}_i))^j
\end{multline*}
by Taylor's formula.
It follows that $f_i=t-\alpha^{(n+1)}_i$ is a factor of $f(t)$ in $\mathbb{R}_n$, then 
\begin{equation}\label{eq:ord=pe}
\ord_k(g^{(k)}(\alpha_i))=P_k(f_i).
\end{equation}
Combining this equation with \eqref{eq:3:ealphaj}, one has 
\begin{equation*}
\left\{
    \begin{split}
        P_{f_{\rm k}(\alpha_i)}(f_i)   &=P_1(f_i);\\
        P_{f_{\rm k}(\alpha_i)+1}(f_i) &\neq P_1(f_i).
    \end{split}
    \right.
\end{equation*}
Referring to \eqref{eq:3A:l}, there is $f_{\rm k}(\alpha_{i_1})=\min\limits_{1\leq i\leq m} f_{\rm k}(\alpha_{i_1})$ such that 
\begin{equation*}
\left\{
    \begin{split}
        P_{f_{\rm k}(\alpha_{i_1})}(f)   &=P_1(f);\\
        P_{f_{\rm k}(\alpha_{i_1})+1}(f) &\neq P_1(f).
    \end{split}
    \right.
\end{equation*}
According to \eqref{eq:3A:f_hatkf_define}, this lemma holds.
\end{proof}

For $f(t)$ with a multiple root $\alpha$ over $\mathbb{R}_1$, one has $\hat{f}_k\equiv g^a \pmod{p}$ in $\mathbb{R}_k[t]$, 
where $\hat{f}_k=(t-\alpha_{1, k})(t-\alpha_{2, k})\cdots(t-\alpha_{a, k})$.
Lemma~\ref{le:3A:R1pf'} determines the least period of $f(t)$ in $\mathbb{R}_{1}$.
Lemma~\ref{le:3A:gmpkfm<p} describes the regulation of the change of least period of $f(t)$ in $\mathbb{R}_{k}$ as $k$ increases when $m\leq p$. Lemma~\ref{le:3A:gmpkfm>p} addresses the scenario for $m>p$. The combined insights from Lemmas~\ref{le:3:hensem3},~\ref{le:3A:gmpkfm<p} and~\ref{le:3A:gmpkfm>p} are further distilled in Theorem~\ref{coro:2:e>1b=1}, which governs the regulation of the change of least period of $f(t)$ in $\mathbb{R}_{k}$ as $k$ increases.

\begin{lemma}\label{le:3A:R1pf'}
If the monic polynomial $f(t)$ has a nonzero root $\alpha$ of multiplicity $a$ in $\mathbb{R}_1$, then one has
    \begin{equation}\label{eq:peh:g^s}
       P_1((t-\alpha)^a)=p^c \cdot P_1(t-\alpha), 
    \end{equation}
where $c=\min\{k\ \vert \ a \leq p^k\}$.
\end{lemma}
\begin{proof}
In $\mathbb{R}_1[t]$, $(t-\alpha) \mid t^{P_1(t-\alpha)}-1$. 
Since $t^{P_1(t-\alpha)}-1$ is coprime with its derivative, it has only simple roots. Consequently, $(t-\alpha)^a\mid (t^{P_1(t-\alpha)}-1)^{p^c}$ but $(t-\alpha)^a\nmid (t^{P_1(t-\alpha)}-1)^{p^{c-1}}$. It follows that $P_1((t-\alpha)^a)\mid p^c\cdot P_1(t-\alpha)$ but $P_1((t-\alpha)^a)\nmid p^{c-1}\cdot P_1(t-\alpha)$. 
Thus, this lemma holds.
\end{proof}

\begin{lemma}\label{le:3A:gmpkfm<p}
If the monic polynomial $f(t)$ has a nonzero root $\alpha$ of multiplicity $a\leq p$ in $\mathbb{R}_k$, then one has
    \begin{equation}\label{eq:peh:g^s}
       P_k((t-\alpha)^a)=p^{k}\cdot P_1(t-\alpha).
    \end{equation}
\end{lemma}
\begin{proof}
In $\mathbb{R}_1$, it follows from $a\leq p$ and Lemma~\ref{le:3A:R1pf'} that
$P_1(\hat{f})=p\cdot P_1(t-\alpha)$, where $\hat{f}=(t-\alpha)^a$. Then, referring to Lemma~\ref{le:3A:P_kfp}, one has
\begin{equation}\label{eq:3:P_efmidpe}
    P_k(\hat{f}) \mid p^{k}\cdot P_1(g).
\end{equation}
Next, since $\hat{f}$ is a factor of $f(t)$, there exist distinct indices
$i_1, i_2\in \{1, 2, \cdots, m\}$ such that $\alpha_{i_1, 2}-\alpha\in(p)$ and $\alpha_{i_1, 2}-\alpha\in(p)$.
Consequently, one has 
\begin{equation}\label{eq:3A:alpha_{i_1k}}
    \alpha_{i_1, 2}\not\in(p).
\end{equation}
and
\begin{equation}\label{eq:3A:alphai12}
(t-\alpha_{i_1, 2})(t-\alpha_{i_2, 2})\mid t^{P_2(\hat{f})}-1.
\end{equation}
Since $\alpha_{i_1, 2}^{P_2(\hat{f})}=1$,
\begin{equation}\label{eq:3A:t=alphai1}
t^{P_2(\hat{f})}-1=(t-\alpha_{i_1, 2})\sum^{P_2(\hat{f})}_{i=1}\alpha_{i_1, 2}^{i-1}t^{P_2(\hat{f})-i}.
\end{equation}
Then, it follows from the Division algorithm that 
    \begin{multline}\label{eq:3A:remainer}
        \sum^{P_2(\hat{f})}_{i=1}\alpha_{i_1, 2}^{i-1}t^{P_2(\hat{f})-i}=\\
        (t-\alpha_{i_2, 2})\left(\sum^{P_2(\hat{f})-2}_{i=0}d_i\cdot t^{P_2(\hat{f})-2-i}\right)+d_{P_2(\hat{f})-1}, 
    \end{multline}
where
\begin{equation}\label{eq:3A:ds}
d_s=\alpha_{i_2, 2}^s+\alpha_{i_2, 2}^{s-1}\alpha_{i_1, 2}+\cdots+\alpha_{i_1, 2}^s.
\end{equation}
Since $d_s$ is the constant term, one has $d_{P_2(\hat{f})-1}\nmid t-\alpha_{i_2, 2}$.
Combining \eqref{eq:3A:alphai12}, \eqref{eq:3A:t=alphai1}, and~\eqref{eq:3A:remainer}, one can obtain 
\begin{equation}\label{eq:3:dpef-1}
d_{P_2(\hat{f})-1}\in (p^2).
\end{equation}
Thus, from
\begin{equation*}
d_{P_2(\hat{f})-1}(\alpha_{i_2, 2}-\alpha_{i_1, 2})=\alpha_{i_2, 2}^{P_2(\hat{f})}-\alpha_{i_1, 2}^{P_2(\hat{f})}, 
\end{equation*}
 the analysis of $f_{i_1}$, $f_{i_2}$ can be divided into two cases by the relation between $\alpha_{i_2, 2}$ and $\alpha_{i_1, 2}$:
\begin{itemize}
    \item $\alpha_{i_2, 2}=\alpha_{i_1, 2}$: it follows from \eqref{eq:3A:ds} that $d_{P_2(\hat{f})-1}=P_2(\hat{f})\alpha_{i_2, 2}^{P_2(\hat{f})-1}$. Since $t\nmid g$, one has $\alpha\not\in(p)$, then $\alpha_{i_2, 2}^{P_2(\hat{f})-1}\not\in(p)$. Referring to \eqref{eq:3:dpef-1}, one can obtain $P_k(f_{i_1}f_{i_2})\in (p^2)$.

    \item $\alpha_{i_2, 2}\neq \alpha_{i_1, 2}$: one can derive
    \begin{equation*}
    \begin{split}
        d_{P_2(\hat{f})-1}&=\frac{\alpha_{i_2, 2}^{P_2(\hat{f})}-\alpha_{i_1, 2}^{P_2(\hat{f})}}{\alpha_{i_2, 2}-\alpha_{i_1, 2}}\\
                    &=\frac{(\alpha_{i_2, 2}-\alpha_{i_1, 2}+\alpha_{i_1, 2})^{P_2(\hat{f})}-\alpha_{i_1, 2}^{P_2(\hat{f})}}{\alpha_{i_2, 2}-\alpha_{i_1, 2}}\\
                    &=\sum_{i=1}^{P_2(\hat{f})} \binom{i}{P_2(\hat{f})}\alpha_{i_1, 2}^{P_2(\hat{f})-i}(\alpha_{i_2, 2}-\alpha_{i_1, 2})^{i-1}, 
    \end{split}
    \end{equation*}
    Combining the conditions $\alpha_{i_2, 2}-\alpha_{i_1, 2}\in (p)$ and $\alpha_{i_1, 2}\not\in(p)$ with \eqref{eq:3:dpef-1}, one obtains $P_2(\hat{f})\in (p)$ and
    \begin{equation*}
        \sum_{i=1}^{2} \binom{i}{P_2(\hat{f})}\alpha_{i_1, 2}^{P_2(\hat{f})-i}(\alpha_{i_2, 2}-\alpha_{i_1, 2})^{i-1}\in(p^2).
    \end{equation*}
    This expression can be simplified to $P_k(f)(\alpha_{i_1, 2}-(P_k(f)-1)(\alpha_{i_2, 2}-\alpha_{i_1, 2}))\in(p^2)$. Since $\alpha_{i_1, 2}-\alpha\in(p)$, one has $\alpha_{i_2, 2}-\alpha_{i_1, 2}\in(p)$. Combining this with \eqref{eq:3A:alpha_{i_1k}} and $P_k(f)\in(p)$, one obtains $P_2(\hat{f})\in (p^2)$.
\end{itemize}
Now, one can conclude that $P_2(\hat{f})\nmid p\cdot P_1(g)$ over $\mathbb{R}_2$.
Referring to Lemma~\ref{le:3A:P_kfp} and \eqref{eq:3:P_efmidpe}, this lemma holds.
\end{proof}

\begin{lemma}\label{le:3A:gmpkfm>p}
If the monic polynomial $f(t)$ has a nonzero root $\alpha$ of multiplicity $a>p$ in $\mathbb{R}_k$, then one has
    \begin{equation}\label{eq:peh:g^s}
       P_k((t-\alpha)^a)=p^{k+c-1}\cdot P_1(t-\alpha), 
    \end{equation}
    where $c=\min\{k\ \vert \ a \leq p^k\}$.
\end{lemma}
\begin{proof}
This lemma can be proved by mathematical induction on $c$. When $c=0$, there is $a=1$. Referring to Lemma~\ref{le:3A:gmpkfm<p}, \eqref{eq:peh:g^s} holds. 
Assume that \eqref{eq:peh:g^s} holds for $c\leq s$.
When $c=s+1$, in $\mathbb{R}_1$, referring to Lemma~\ref{le:3A:R1pf'} and $a>p$, one has \begin{equation}\label{eq:3A:ftppk-1} 
    P_1(\hat{f})=p^{s+1}\cdot P_1(g)
\end{equation}
 and 
\begin{equation}\label{eq:3A:p1hatf}
P_1(\hat{f}_1)=p^{s}P_1(g), 
\end{equation}
where $\hat{f}_1=(t-\alpha_{k, 1})(t-\alpha_{k, 2})\cdots (t-\alpha_{k, p^{s}})$. 
In $\mathbb{R}_2$, since \eqref{eq:3A:p1hatf} holds when $c=s$, there is $\hat{v}(t)\not\in(p)$ such that $\hat{f}_1\mid t^{p^{s}\cdot P_1(g)}-1+p\hat{v}(t)$. 

Similar to \eqref{eq:3A:t-1rt}, there is 
\begin{equation}\label{eq:3A:hatr2t}
    \hat{r}(t)=\sum_{i=0}^{p-2}(p-1-i)t^{i\cdot p^{s}P_1(g)}
\end{equation}
such that
\begin{multline}\label{eq:3A:cfp-m}
\left(\sum_{i=0}^{p-1} t^{i \cdot p^{s}P'_{1}(g)} + p\hat{v}(t)\hat{r}(t)\right)\left(t^{p^{s}P_1(g)}-1-p\hat{v}(t)\right)=\\
t^{p^{s+1}P_1(g)} - 1.
\end{multline}
Referring to Lemma~\ref{le:3A:R1pf'}, there is $\alpha_{i, 2}$ for any $i\in\{p^s+1, p^s+2, \cdots, a\}$ such that $(t-\alpha_{i, 2})\hat{f}_1\nmid t^{p^s\cdot P_1(g)}-1$ 
in $\mathbb{R}_1$.
Then, in $\mathbb{R}_2$, one obtains $(t-\alpha_{i, 2})\hat{f}_1\nmid t^{p^s\cdot P_1(g)}-1+\hat{v}(t)$.
Assume $P_2(\hat{f})=p^{s+1}P_1(g)$. In $\mathbb{R}_2$, combining with \eqref{eq:3A:cfp-m}, one can obtain
\[
(t-\alpha_{i, 2})\mid\left(\sum_{i=0}^{p-1} t^{i \cdot p^{s}P'_{1}(g)} -p\hat{v}(t)\hat{r}(t)\right).
\]
This implies
\[
\left(\sum_{i=0}^{p-1} \alpha_{i, 2}^{i \cdot p^{s}P'_{1}(g)} - p\hat{v}(\alpha_{i, 2})\hat{r}(t\alpha_{i, 2})\right)=0
\]
It follows from the definition of $P_1(g)$ and $\alpha_{i, 2}-\alpha\in(p)$ that $\alpha_{i, 2}^{p\cdot P_1(g)}=1$.
Substituting into the right-hand side of the above equation yields a simplified result that equals $p$, which leads to a contradiction.
Hence, $\hat{f}\nmid t^{p^{s+1}P_1(g)}-1$ in $\mathbb{R}_2$. It follows from \eqref{eq:3A:ftppk-1} that $f\mid t^{p^{s+2}P_1(g)}-1$, then $P_2(\hat{f})=p^{s+2}P_1(g)$.
Applying Lemma~\ref{le:3A:P_kfp}, one concludes that \eqref{eq:peh:g^s} holds for $c=s+1$. This completes the proof of \eqref{eq:peh:g^s}.
\end{proof}

%When $p=2$, it follows from \eqref{eq:3A:hatr2t} that $\hat{r}_2(\alpha_{j, 2})=1$.

\begin{theorem}\label{coro:2:e>1b=1}
If the monic polynomial $f(t)$ has exactly $m$ non-zero roots in $\mathbb{R}_1$, (\ref{eq:f:pef-nomul}) holds with
\begin{equation*}
 k_{\rm s}=
 \begin{cases}
     1    & \mbox{if } \prod_{i=1}^l a_i>1;\\
 \min\limits_{1\leq i\leq m} f_{\rm k}(\alpha_i) & \mbox{if } \prod_{i=1}^l a_i=1,    
 \end{cases}
\end{equation*}
where $a_i$ is the multiplicity of the $i$-th root $\alpha_i$ of $f(t)$, $l$ is the number of different roots of $f(t)$, 
\begin{equation*}
f_{\rm k}(\alpha_i)=\max\left\{ k \vvert\ord_{k}\left(g^{(k-1)}(\alpha_i)\right)=\ord_1(\alpha_i) \right\}, 
\end{equation*} 
and $m\leq p$.
\end{theorem}
\begin{proof}
The monic polynomial $f(t)$ can be factorized as $f(t)=g_1^{a_1}(t)g_2^{a_2}(t)\cdots g_l^{a_l}(t)$ in $\mathbb{R}_1$, where the factors $\{g_i(t)\}_{i=1}^l$ are pairwise coprime.
Therefore, by the multiplicity of the period function, $P_k(f)=\lcm\{ P_k(g_i^{a_i}) \mid 1\leq i\leq l \}$.
Finally, Lemmas \ref{le:3:orderZ=R}, \ref{le:3:hensem3} and \ref{le:3A:gmpkfm<p} together yield the claimed value of $k_{\rm s}$. This completes the proof of the theorem.
\end{proof}

In $\mathbb{Z}_{p^k}^{mn}$, let $\bx\in (p)$ denote that $\bx\equiv\bo\pmod{p}$. In such cases, it follows from \eqref{eq:3:ma=} that $\mathbf{A}^{i}(\bx)\in (p)$ when $\bx\in (p)$. Since map~\eqref{eq:3:ma=} is a permutation, the elements in $\{\mathbf{A}^i({\bx})\}_{i=0}^{T_k}$ form a cycle in the functional graph $G_{p^k}$. 
This establishes a distinct separation between states belonging to 
$\{\bx\ \vert\ \bx\in(p)\}$ and those outside it. Consequently, the analysis of the period distribution of map~\eqref{eq:3:ma=} bifurcated based on whether $\bx\in (p)$.
Lemma~\ref{le:3:x(p)iso} discloses that for map~\eqref{eq:3:ma=}, the subgraph of $G_{p^{k}}$ composed of all elements satisfying $\bx\in (p)$ in $\Zp{k}$ is isomorphic to $G_{p^{k-1}}$.

\begin{lemma}\label{le:3:x(p)iso}
The cycle $\{\mathbf{A}^i({\bx})\}_{i=0}^{T_k}$ in $\Zp{k-1}$ 
is isomorphic to the cycle $\{\mathbf{A}^i(p\cdot{\bx})\}_{i=0}^{T_k}$ in $\Zp{k}$ with respect to their corresponding operators.
\end{lemma}
\begin{proof}
Given any $\bx\in\Zp{k-1}^n$, define a multiplication operation $\circ$ for any two elements
$g_1$ and $g_2$ of the set 
$\{\mathbf{A}^i({\bx})\}_{i=0}^{T_k}$:
$g_1\circ g_2=\mathbf{A}^{i_1+i_2}({\bx})\bmod p^{k-1}$,
where $g_1=\mathbf{A}^{i_1}({\bx})$ and $g_2=\mathbf{A}^{i_2}({\bx})$.
Under the operation, the cycle in $\Zp{k-1}^n$ composes a cyclic group of order $T_k$, with the group law
$\mathbf{A}^{i_1}(\bx) \circ \mathbf{A}^{i_2}(\bx)=\mathbf{A}^{i_1+i_2}(\bx)$,
identity $\bx$, and inverses $(\mathbf{A}^i(\bx))^{-1}=\mathbf{A}^{T_k-i}(\bx)\bmod p^{k-1}$.
Similarly, the cycle $\{\mathbf{A}^i(p\cdot{\bx})\}_{i=0}^{T_k}$ in $\Zp{k}$ composes a cyclic group of the same
order under the analogous operation (mod $p^k$).
Define a map
$$
h: \Zp{k-1}^n \;\longrightarrow\; \Zp{k}^n \quad h(\bx)=p\bx.
$$
Since multiplication by $p$ on $\Zp{k}^n$ is injective on residues modulo $p^{k-1}$, $h$ is a bijection from $\Zp{k-1}^n$ onto the subgroup $p\Zp{k}^n$.
Moreover, $\mathbf{A}$ commutes with $h$:
$\mathbf{A}(h(\bx)=\mathbf{A}(p\bx)=\bM(p\bx)=p(\bM \bx)
=h(\mathbf{A}(\bx))$. 
By induction, $h(\mathbf{A}^i(\bx))=\mathbf{A}^i(h(\bx))$ for all $i$.
Thus $h$ restricts to a bijection between the two cycles that intertwines their group operations, establishing a group isomorphism. This completes the proof.
\end{proof}

When $\bx\not\in(p)$, the minimal polynomial of the sequence 
$\{\mathbf{A}^i(\bx)\}_{i\geq0}$ differs from the case where $\bx\in(p)$ previously analyzed.
The evolution of the period of $\{\mathbf{A}^i(\bx)\}_{i\geq0}$ over $\Zp{k}^{mn}$ 
changes as $k$ increases. The analysis of the period is different from the period of the mapping $\mathbf{A}$, because the minimal polynomial of the sequence also changes as $k$ increases. 
Lemma~\ref{le:3A:P_kfp} establishes that, beyond a threshold $k_{\rm s}(\bx_0)$, the period of the sequence in $\mathbb{R}_{k+1}[t]$ increases by a factor of $p$ relative to $T_k(\bx_)$.

\begin{lemma}\label{le:3:xe+1}
For any $\bx_0\in\Zp{k}^{mn}$, one has
 \begin{equation}\label{eq:3:Te+1y}
     T_{k+1}(\bx_0)=
     \begin{cases}
         T_k(\bx_0)         & \text{if } k\leq k_{\rm s}(\bx_0); \\
          p\cdot T_k(\bx_0) & \text{if } k> k_{\rm s}(\bx_0), 
     \end{cases}
 \end{equation}
where
\begin{equation}\label{eq:3a:ksx0}
     k_{\rm s}(\bx)=\max\{k\mid T_k(\bx)=T_1(\bx)\}.
\end{equation}
\end{lemma}
\begin{proof}
Given an initial state $\bx_0$, there is $\bM^{T_1(\bx_0)}(\mathbf{x_0})-\mathbf{x_0}=\bo$ in $\mathbb{Z}_p$.
When $k\leq k_{\rm s}(\bx_0)$, one obtains $T_k(\bx_0)=T_1(\bx_0)$. One can prove 
$t^{p^{k-k_{\rm s}(\bx_0)}T_1(\bx_0)}-1$ is a null polynomial of the sequence in $\mathbb{Z}_{p^k}$ and not a null polynomial in $\mathbb{Z}_{p^{k+1}}$ by mathematical induction on $k$. When $k = k_{\rm s}(\bx_0)$, the statement holds. Assume that the statement holds for $k\leq k_{\rm s}(\bx_0)+s$, there is $v(t)\not\in(p)$ such that $t^{p^sT_1(\bx_0)}-1= p^{k}v(t)$ in $\mathbb{Z}_{p^{k+1}}$. 
Similar to \eqref{eq:3A:qt} and \eqref{eq:3A:t-1rt}, one has $t^{p^sT_1(\bx_0)}-1- p^{k}v(t)\mid t^{p^{s+1}T_1(\bx_0)}-1+p^{k+1}v(t)$, which means that the statement holds for $k=k_{\rm s}(\bx_0)+s+1$. This completes the proof of the statement. When $k> k_{\rm s}(\bx_0)$,
\begin{equation}
    \begin{cases}
        (\bM^{p^{k-k_{\rm s}(\bx_0)}T_1(\bx_0)}-\mathbf{I})(\bx_0)  & \neq \bo;\\
        (\bM^{p^{k-k_{\rm s}(\bx_0)+1}T_1(\bx_0)}-\mathbf{I})(\bx_0) &= \bo
    \end{cases}
\end{equation}
in $\mathbb{Z}_{p^{k+1}}$, namely $T_{k+1}(\bx_0)=pT_{k}(\bx_0)$. This lemma holds.
\end{proof}

Since $\bM$ is a companion matrix, its eigenvalues correspond precisely to the roots $\{\alpha_i\}_{i=1}^m$ of the minimal polynomial $f(t)$. Suppose $t\nmid f(t)$, in $\mathbb{R}_1$, since $\mathbb{R}_1$ is a field and $f(t)$ can be factored, one has the Jordan canonical form $\bJ_1$ of $\bM$ and there is an invertible matrix $\bQ_1$ such that 
\begin{equation}\label{eq:3A:M-PDP}
\bM=\bQ_1\bJ_1\bQ_1^{-1}.
\end{equation}
Then $\bQ_1$ is constructed by the eigenvectors $\{\bv_i\}_{i=1}^m$, where
$\bv_i$ satisfying 
\begin{equation}\label{eq:3A:eignvec}
    (\bM-\alpha_i\mathbf{I})\bv_i=\bo.
\end{equation}
Since $\bQ$ is an invertible matrix, one has 
\begin{equation}\label{eq:3A:detP1}
    \det(\bQ_1)\not\in(p)
\end{equation}
In $\mathbb{R}_k$, similar to \eqref{eq:3A:eignvec}, one has $\bv_{i,k}$ such that 
\begin{equation*}\label{eq:3A:eignveck}
    (\bM-\alpha_{i,k}\mathbf{I})\bv_{i,k}=\bo.
\end{equation*}
Since $\alpha_{i,k}-\alpha_i\in(p)$, one has 
