\begin{lemma}\label{le:3A:ksx0}
Equation~\eqref{eq:3:Te+1y} holds with
\[
k_{\rm s}(\bx_0) = \min_{1\leq j \leq m_h} k(\alpha_j),
\]
where
\[
k(\alpha_j) = \max\{k \mid \ord_k(\alpha_{j,k}) = \ord_1(\alpha_j)\},
\]
$\{\alpha_j\}_{1\leq j\leq m_h}$ are the roots of the minimal polynomial $h(t)$ of the sequence $\{\bA^i(\bx_0)\}_{i\geq 0}$ in $\mathbb{R}_1$, and $m_h = \deg h(t)$.
\end{lemma}
\begin{proof}
In $\mathbb{R}_{1}$, since $\mathbb{Z}_p$ is a finite field, for the sequence generated by $\bx_0$, $h(t)$ as a unique minimal polynomial can divide all null polynomials, that is, $h(t)\mid f(t)$. Hence, there are all roots $\{\alpha_{j}\}_{1\leq j\leq m_h}$ of $h(t)$ such that $\alpha_{j}^{T_{1}(\bx_0)}-1=0$. 
Referring to
\begin{equation}\label{eq:3A:MTMPT}
        \bM^{T_{1}(\bx_0)}\bx_0\equiv \bx_0 \pmod{p}, 
\end{equation}    
and 
\[
\bM^{s\cdot T_{k}(\bx_0)}-\mathbf{I}=\bQ_{k}(\bJ_{k}^{s\cdot T_{k}(\bx_0)}-\mathbf{I})\bQ_{k}^{-1},
\]
one obtains
\begin{equation}\label{eq:3A:J1T}
        (\bJ_{1}^{T_{1}(\bx_0)}-\mathbf{I})\by_0= \bo 
\end{equation}
where $\by_0=\bQ_{1}^{-1}\bx_0$. 

One can prove the statement that there exists a vector $\mathbf{y}_{0,s}$ with no zero elements such that 
\begin{equation}\label{eq:J1s}
    (\bJ_{1,s}^{T_1(\bx_0)}-\mathbf{I})\by_{0,s}=\bo,
\end{equation}
where $\mathbf{J}_{1,s}$ is a submatrix of $\mathbf{J}_1$ corresponding to $f_s(t)$ and $f_s(t)$ is the null polynomial of both $\{\mathbf{J}_{1,s}^i \mathbf{y}_{0,s}\}_{i\geq 0}$ and the $\{\bA^i(\bx_0)\}_{i\geq 0}$ by mathematical induction on $s$. When $s = 1$, let $\mathbf{y}_{0,1}=\mathbf{y}_{0}$ and $\mathbf{J}_{1,s}=\mathbf{J}_{1,1}$, it follows from ~\eqref{eq:3A:J1T} that the statement holds. Assume that the statement holds for $s=l$.
If the $i$-th element of $\by_{0,l}$ is $0$, one has the $i$-th element of $(\bJ_{1,l}^{T_1(\bx_0)}-\mathbf{I})\by_{0,l}$ is $0$. Note that the null polynomial of the sequence $\{\bA^i(\bx_0)\}_{i\geq 0}$ is also the null polynomial of the sequence of $\{\bJ_{1,l}^i(\by_{0,l})\}_{i\geq 0}$ with deleting the $i$-th element. By matrix transformation, there is a Jordan canonical form $\bJ_{1,l+1}$ of $\frac{f_s(t)}{t-\alpha_{i}}$ which is the matrix deleting the $i$-th row and column of $\bJ_{1,l}$. Then 
\[
(\bJ_{1,l+1}^{T_1(\bx_0)}-\mathbf{I})\by_{0, l+1}=\bo,
\]
where $\by_{0, l+1}$ is $\by_{0,l}$ with deleting the $i$-th element. 
Hence, $\frac{f_s(t)}{t-\alpha_{i}}$ is the null polynomial of 
$\{\bJ_{1,l+1}^i\by_{0,l+1}\}_{i\geq 0}$ and
$\{\bA^i(\bx_0)\}_{i\geq 0}$. This statement holds.

Since $h(t)$ is the minimal polynomial of $\{\bA^i(\bx_0)\}_{i\geq 0}$, there is $s$ such that $h(t)\mid f_s(t)$ and any element of $\by_{0,s}$ is not $0$.
Let $\alpha_j$ is a root of $f(t)$ in $\mathbb{R}_1$, 
there is the $i_j$-th row of $\mathbf{J}_{1,s}$ where only the diagonal element is $\alpha_j$.
Since ~\eqref{eq:J1s}, in $\mathbb{R}_{k(\alpha_{i_j})+1}$, there is $\alpha_{i_j, k}^{T_1(\bx)}-1= c p^{k(\alpha_{i_j})}$.
It follows from ~\eqref{eq:J1s} that $(\bJ_{k,s}^{T_1(\bx)}-\mathbf{I})\by_{0,s}\neq \bo$. Then $(\bJ_{k}^{T_1(\bx)}-\mathbf{I})\by_{0}\neq \bo$, namely $(\bM^{T_1(\bx)}-\mathbf{I})\bx_{0}\neq \bo$.
 Since ~\eqref{eq:3a:ksx0}, one has $k_{\rm s}(\bx_0)=\min k(\alpha_{i_j})$.
\end{proof}

\begin{lemma}\label{le:3:xe+1c}
For any $\bx_0\in\mathbb{Z}_{p^{k'}}^{\times}$, one has
    \begin{equation}\label{eq:3A:Tx0+c}
        T_{k}(\bx_0+ p^{k'}\cdot{\bf c})=\lcm( T_{k}(\bx_0), T_{k-k'}({\bf c})), 
    \end{equation}
where ${\bf c}\in\mathbb{Z}_{p^{k-k'}}^{mn}$.
\end{lemma}
\begin{proof}
Let $l=\lcm(T_{k}(\bx_0), T_{k-k'}({\bf c}))$. 
In $\mathbb{Z}_{p^{k}}$, since $\bM^{ T_{k}(\bx_0)}\bx_0=\bx_0$, one obtains 
$\bM^{l}(\bx_0+ p^{k'}\cdot{\bf c})=\bx_0+ p^{k'}\cdot{\bf c}$.
Hence,
\[
T_{k}(\bx_0+ p^{k'}\cdot{\bf c})\mid l.
\]
Since the sequence generated with initial state $\bx_0+ p^{k'}\cdot{\bf c}$ in $\mathbb{Z}_{p^{k}}$ corresponds to the sequence generated with initial state $\bx_0$ in $\mathbb{Z}_{p^{k-1}}$, one has 
\begin{equation}\label{eq:3A:Tk|Tk+1}
    T_{k-1}(\bx_0)\mid T_{k}(\bx_0+ p^{k'}\cdot{\bf c}).
\end{equation}
There are two cases of this proof whether $T_{k}(\bx_0)=T_{k+1}(\bx_0)$ or not.
\begin{itemize}
    \item $T_{k-1}(\bx_0)=T_{k}(\bx_0)$: one has $T_{k}(\bx_0+ p^{k'}\cdot{\bf c})=s\cdot T_{k-1}(\bx_0)$, where $s$ is an integer. Then 
\begin{equation*}
    \bM^{s\cdot T_{k}(\bx_0)}(\bx_0+ p^{k'}\cdot{\bf c})=\bx_0+p^{k'}\cdot\bM^{s\cdot T_{k}(\bx_0)}{\bf c}=\bx_0+p^{k'}\cdot {\bf c}.
\end{equation*}
namely $p^{k'}\cdot\bM^{s\cdot T_{k}(\bx_0)}{\bf c}={\bf c}$. Hence $T_{k-k'}(\mathbf{c})\mid s\cdot T_{k+1}(\bx_0)$, that is, $T_{k+1}(\bx_0+ p^{k'}\cdot{\bf c})=l$.
\item $T_{k-1}(\bx_0)\neq T_{k}(\bx_0)$, it follows from \eqref{eq:3:Te+1y} that $T_{k}(\bx_0)=p \cdot T_{k-1}(\bx_0)$. 
In $\mathbb{R}_{k}$, referring to
\begin{equation}\label{eq:3A:MTMPT}
    \left\{\begin{split}
        \bM^{T_{k-1}(\bx_0)}\bx_0&\equiv \bx_0 \pmod{p^{k-1}}; \\
        \bM^{T_{k-1}(\bx_0)}\bx_0&\not\equiv \bx_0 \pmod{p^{k}}
    \end{split}
    \right.
\end{equation}
and 
\[
    \bM^{s\cdot T_{k-1}(\bx_0)}-\mathbf{I}=\bQ_{k}(\bJ_{k}^{s\cdot T_{k-1}(\bx_0)}-\mathbf{I})\bQ_{k}^{-1},
\]
one obtains
\begin{equation}\label{eq:3A:Dy}
\left\{
\begin{split}
        (\bJ_{k-1}^{T_{k-1}(\bx_0)}-\mathbf{I})\by_0&\in (p^{k-1}),\\
         (\bJ_{k-1}^{T_{k-1}(\bx_0)}-\mathbf{I})\by_0&\not\equiv \bo 
\end{split}
 \right.
\end{equation}
where $\by_0=\bQ_{k}^{-1}\bx_0$. Note that $\{\alpha_{i,k}\}_{i=1}^m$ are the diagonal elements of the $\bJ_k$. Assume $\alpha_{i,k}^{T_{k-1}(\bx_0)}-1\neq 0\pmod{p^{k-1}}$ for any $i$. 
In $\mathbb{R}_k$, $\det(\bJ_k^{T_{k-1}(\bx_0))}-\mathbf{I})\neq 0$. It follows from the above equation that $\by_0=\bo$. Since $\bQ_{k}$ is an invertible matrix, one has $\bx_0\equiv \bo$, which is contradicted by $\bx_0\in\mathbb{Z}_{p^{k'}}^{\times}$. Hence, there is $\alpha_{i_i+l,k}$ such that  
\begin{equation}\label{eq:3A:alphatk-1}
 \left\{\begin{split}
     \alpha_{i_1,k}^{T_k(\bx_0)}-1 & \in(p^{k-1});\\
 \alpha_{i_1,k}^{T_k(\bx_0)}-1     & \not\equiv 0\pmod{p^{k}},
 \end{split}
 \right.
 \end{equation}
 Let $s$ is algebraic multiplicity of the value $\{\alpha_{i_i,k}\}$.
 For the $s\times s$ Jordan block in $\bJ_k$ corresponding $\alpha_{i_1,k}$, there is $j$-th row of $\bJ$ corresponding to its bottom row has only value $\alpha_{i_1,k}$ on the diagonal and zeros elsewhere. 
Referring to \eqref{eq:3A:Dy}, one has $y_{j}\neq 0\pmod{p}$.
Assume 
\[
T_{k}(\bx_0)\nmid T_{k}(\bx_0+ p^{k'}\cdot{\bf c}).
\]
Since relation~\eqref{eq:3A:Tk|Tk+1}, one has 
\begin{equation*}
        \bM^{s\cdot T_{k-1}(\bx_0)}(\bx_0+p^{k'}\cdot \mathbf{c})=\bx_0+p^{k'}\cdot \mathbf{c}
\end{equation*}
namely
\[
 (\bM^{s\cdot T_{k-1}(\bx_0)}-\mathbf{I})\bx_0=-(\bM^{s\cdot T_{k-1}(\bx_0)}-\mathbf{I})(p^{k'}\cdot \mathbf{c}).
\]
According to \eqref{eq:3A:Dy}, one has 
\[
(\bJ_{k}^{s\cdot T_{k-1}(\bx_0)}-\mathbf{I})\by_0= p^{k'}\cdot (\bJ_{k}^{s\cdot T_{k-1}(\bx_0)}-\mathbf{I})\mathbf{b},
\]
where $\mathbf{b}=\bQ_{k}^{-1}\mathbf{c}$. Then 
\[
    (\alpha_{i_1,k}^{s\cdot T_{k-1}(\bx_0)}-1)y_{i_1}=0,
\]
which is a contradiction.
Hence, 
\[
T_{k}(\bx_0)\mid T_{k}(\bx_0+ p^{k'}\cdot{\bf c}).
\]
It follows from
\[
\begin{split}
    &\bM^{ T_{k}(\bx_0+ p^{k'}\cdot{\bf c})}(\bx_0+ p^{k'}\cdot{\bf c})\\
    &=\bx_0+p^{k-1}\bM^{T_{k}(\bx_0+ p^{k'}\cdot{\bf c})}{\bf c}\\
&=\bx_0+{\bf c}
\end{split}
\]
that
\[
\bM^{T_{k}(\bx_0+ p^{k'}\cdot{\bf c})}{\bf c}={\bf c},
\]
then $T_{k-k'}(\mathbf{c})\mid T_{k}(\bx_0+ p^{k'}\cdot{\bf c})$.
So, $T_{k}(\bx_0+ p^{k'}\cdot{\bf c})=\lcm(T_{k}(\bx_0), T_{k-k'}({\bf c}))$. 
\end{itemize}
Combining the above analysis, this lemma holds.
\end{proof}

Given a state $\bx\in\mathbb{Z}_{p^{k^*}}^{mn}$, there exists a cycle containing $\bx$ in $G_{p^{k^*}}$, and all elements of this cycle form a set denoted by $C_{k}({\bx})=\{ \hat{\bx} \vvert \hat{\bx}=\mathbf{A}^i(\bx), \bx\in{\Zp{k}}, i\in \mathbf{Z}\}$. 
As $k$ increases, for any element $\bx'$ corresponds to an element ${\bx}$ that composes a set $N_{k, \bx}=\{\bx'\vert \bx'\equiv\bx\pmod{p^{k^*}}\}$. 
Hence, $C_{k}(\bx')$ corresponds to a cycle $C_{k^*}(\bx)$ in $G_{p^{k^*}}$. 
Let
\[
S_{k, \bx} = \bigcap_{\bx'\in N_{k, \bx}} C_{k}(\bx')
\]
for $\bx\in\mathbb{Z}^{mn}_p$ indicates that all elements in this set form several cycles corresponding to the cycle $C_{k^*, \bx}$. 
Furthermore, let 
\begin{equation}\label{eq:3A:NTS}
    N(T, S_{k, {\bx}})=|\{C_{k}(\bx')\vvert C_{k}(\bx')\subseteq S_{k, {\bx}}, |C_{k}(\bx')|=T\}|
\end{equation}
be the number of cycles of length $T$ in the set $S_{k, {\bx}}$. 


\begin{lemma}\label{le:3A:N=a}
   Given $T^*>P_1(f)$, for any $\bx_0$ such that $T_k(\bx_0)=T^*$, 
   there is $S_{k+1}(\bx_0)=\{\bx \vert (\bx \bmod p^k)\in C_k(\bx_0), \bx\in\mathbb{Z}_{p^{k+1}}^{mn}\}$
   and 
   \[
   N(T, S_{k+1}(\bx_0))=\frac{a(T^*, T)T^*}{T},
   \]
   where
       \begin{equation}\label{eq:3a:aTT}
        a(T^*, T_1)=|\{\mathbf{c}\vvert \mathbf{c}\in\mathbb{Z}^{mn}_p,\lcm(pT^*, T_1(\mathbf{c}))=T\}|
    \end{equation}
    is a constant depending on $T^*$ and $T$.
\end{lemma}
\begin{proof}
    From Lemma~\ref{le:3:xe+1c}, one obtains $|C_{k+1}(\bx_0+p^k \mathbf{c})|=T$ if and only if $\lcm(pT^*, T_1(\mathbf{c}))=T$. 
    Hence 
    \begin{multline*}
    |\{\bx\vvert \bx\in S_{k+1}(\bx_0), |C_{k+1}(\bx)|=T\}|=a(T^*, T)\cdot T^*.
    \end{multline*}
    It follows that 
    \begin{equation*}
            N(T, S_{k+1}(\bx_0))=\frac{a(T^*, T)T^*}{T}.
    \end{equation*}
    Then this lemma holds.
\end{proof}

