        &=\left|\left\{\mathbf{c} \Bigg \vert  \mathbf{c}\in\mathbb{Z}^{mn}_p,\lcm\left(T_{1,i}, \frac{T_1(\mathbf{c})}{p^{\bnu(T_1(\mathbf{c}))}}\right)=T_{1,j}\right\}\right|.
    \end{split}
\end{equation}
Since $S_{k+1}(\bx_0)\in S'(p^vT_{1,i})$ for any $\bx_0$ satisfying $T_k(\bx_0)=p^vT_{1,i}$,
one has
    \[
    N\left(p^{v+1}T_{1,j}, S'(p^vT_{1,i})\right)=p\cdot a_{ij} N(p^vT_{1,i}, \mathbb{Z}_p^k).
    \]
Referring to ~\eqref{eq:3A:Sk+1capcap}, one obtains 
    \begin{equation*}
    \begin{split}
        N\left(p^{v+1}T_{1,j}, \mathbb{Z}_{p^{k+1}}^{mn}\right)&=N\left(p^{v+1}T_{1,j}, \bigcup_{i=1}^r S'(p^vT_{1,i})\right)\\
        &=\frac{1}{p}\sum_{i=1}^r a_{ij} N(p^vT_{1,i}, \mathbb{Z}_p^k).
    \end{split}
\end{equation*}
Hence
${\bf N}_{k+1}(v+1)=\mathbf{D}{\bf N}_{k}(v)$.
When $i<j$, it follows from $T_{1,i}<T_{1,j}$ that $T_{1,j}\nmid T_{1,i}$, then $a_j=0$ and $b_{i,j}=0$.
Hence
\[
\mathbf{D}=
\begin{bmatrix}
    b_{1,1} & 0& \cdots,&0\\
    b_{1,2} & b_{2,2}& \cdots,&0\\
    \vdots  & \vdots & \ddots &\vdots\\
    b_{1,r} & b_{2,r}& \cdots,&b_{r,r}
\end{bmatrix}
\].
It follows from ~\eqref{eq:3a:aij} that $b_{i,j}$ is constant depending on $i$ and $j$.
So ~\eqref{eq:the:Nkv} holds.
\end{proof}




