\begin{theorem}\label{th:3A:fe*}
If $f(1)\neq 0$ and $f(-1)\neq 0$, then there exists a threshold $\hat{k}_{\rm s}=\max\{k_{\rm s}(\bx) \vvert \bx\in\Zp{}^{mn}, \bx\neq \bo\}$ such that
for $k\ge \hat{k}_{\rm s}$, 
    \begin{equation}\label{prop:Ntce2}
	  N_{T, \hat{k}_{\rm s}+\bnu(T)+l}=N_{T, \hat{k}_{\rm s}+\bnu(T)},
	\end{equation}
where $l\in \mathbb{N}^+$.
\end{theorem}
\begin{proof}
If $f(1)\neq 0$ and $f(-1)\neq 0$, there is a finite integer $\hat{k}_{\rm s}$.
When $k>\hat{k}_{\rm s}$, for any $\bx\in\{\bx \vvert \bx\in\Zp{k}^{mn},\bx\not\equiv\bo\pmod{p}\}$,
there is $\bnu(T_k(\bx))\geq {k-\hat{k}_{\rm s}}$. It follows from Lemma~\ref{le:3:x(p)iso} that $N_{T, k}=N_{T, k-1}$ for any $T$ satisfying $\bnu(T)<{k-\hat{k}_{\rm s}}$. Further, it can be obtained that 
\[
N_{T, k+l}=N_{T, k-1}
\]
for any $T$ satisfying $\bnu(T)<{k-\hat{k}_{\rm s}}$.
Since Lemma~\ref{le:3:xe+1} and the definition of $\hat{k}_{\rm s}$, when $k=\hat{k}_{\rm s}+\bnu(T)+1$, there is $\bnu(T)<k-\hat{k}_{\rm s}$. Hence 
~\eqref{prop:Ntce2} holds.
\end{proof}

