\begin{theorem}\label{le:3:cat1}
When $a,b$ are not both zero, the least period of the Cat map in $\Zp{k}$ is ${T}_k$ and there exists a threshold of $k$, 
\begin{equation}\label{eq:Cat:kf}
 k_{\rm s}=
 \begin{cases}
     1             & \mbox{if } \alpha=\alpha^{-1};\\
 f_{\rm k}(\alpha) & \mbox{if } \alpha\neq\alpha^{-1},  
 \end{cases}
\end{equation}
satisfying
\begin{equation}\label{eq:3B:Tcxe=pe*}
    T_{k+1}=p^{k-k_{\rm s}}\cdot T_{k_{\rm s}}
\end{equation}
when $k\geq k_{\rm s}$, 
where $f(t)=t^2-(ab+2)t+1$, $\alpha$ is a root of $f(t)$ in $\mathbb{R}_1$, 
\begin{equation*}
f_{\rm k}(\alpha)=\max\left\{ k \vvert \ord_{k}\left(g^{(k-1)}(\alpha)\right)=\ord_1(\alpha) \right\}, 
\end{equation*}
%$g^{(k+1)}(\alpha_i)=g^{(k)}(\alpha_i)$ 
and
$g^{(n)}(x)$ indicate applying 
\begin{equation*}
g(x)=x-f'(x)^{-1}f(x)
\end{equation*}
over $\mathbb{R}_k$ $n$ times.
\end{theorem}
\begin{proof}
When $a\neq0$ or $b\neq0$, the minimal polynomial is $f(t)=t^2-(ab+2)t+1$.
According to Theorem~\ref{coro:2:e>1b=1}, this theorem holds.
\end{proof}

The Cat map as a kind of $\mathbf{P}(\mathbf{a})$ satisfies some properties:
\begin{itemize}
    \item For $\mathbf{P}(\mathbf{a})$ in $\mathbb{Z}_{p^k}^n$, there is a subset $\mathbb{S}_{p^k}^n$ of $\mathbb{Z}_{p^k}^n$ composed of all states of $\mathbf{P}(\mathbf{a})$. 
    \item As $k$ increases, for any $\mathbf{a}\in\mathbb{S}_{p^{k+1}}^n$, there is $\mathbf{c}$ such that $\mathbf{a}=\mathbf{a}_k+p^k\mathbf{c}$, where $\mathbf{a}_k\in\mathbb{S}_{p^{k}}^{mn}$. 
\end{itemize}
Let $\mathbb{C}^{mn}_p$ be the set composed of all states of $\mathbf{c}$. 
Similar to Lemma~\ref{le:3A:N=a} and Theorem~\ref{th:3A:Nkv}, the period distribution of a given state as $k$ to $k+1$ is disclosed in Corollary~\ref{coro:3b:PaNTSx0} and a property of the period distribution as $k$ increases is disclosed in Corollary~\ref{coro:3b:PaNTS}.
\begin{Corollary}\label{coro:3b:PaNTSx0}
    Given $T^*>P_1(f)$, for any $\mathbf{a}_0$ such that $T_k(\mathbf{a}_0)=T^*$, 
   there is $S_{k+1}(\mathbf{a}_0)=\{\mathbf{a}\vert (\mathbf{a} \bmod p^k)\in C_k(\mathbf{a}_0), \mathbf{a} \in\mathbb{S}_{p^{k+1}}^{mn}\}$
   and 
   \[
   N(T, S_{k+1}(\mathbf{a}_0))=\frac{a(T^*, T)T^*}{T},
   \]
   where
       \begin{equation}\label{eq:3a:aTT}
        a(T^*, T_1)=|\{\mathbf{c}\vvert \mathbf{c}\in\mathbb{C}^{n}_p,\lcm(pT^*, T_1(\mathbf{c}))=T\}|
    \end{equation}
    is a constant depending on $T^*$ and $T$.
\end{Corollary}
\begin{proof}
    This proof is similar to Lemma~\ref{le:3A:N=a}.
\end{proof}

\begin{Corollary}\label{coro:3b:PaNTS}
There exists 
\begin{equation}\label{eq:the:Nkv2}
    \mathbf{N}_{k+l}(v+l)= \bD^l\cdot \mathbf{N}_{k}(v)
\end{equation}
for any $v>\bnu(P_1(f))$, where ${\bf N}_k(v)$ is a column vector of size $r\times 1$ with the $i$-th component $N_k(T_{k, i}(v), \mathbb{S}^{mn}_{p^k})$, 
$\{T_{k, i}(v)\}_{i=1}^r= \{T\vvert \bnu(T)=v, T\mid P_k(f)\}$ and $T_{k, i}(v)<T_{k, i+1}(v)$, 
$\bD$ is a $r\times r$ lower triangular matrix, and $l\in \mathbb{N}^+$.
\end{Corollary}
\begin{proof}
    This proof is similar to Theorem~\ref{th:3A:Nkv}.
\end{proof}

Any state $\mathbf{a}_0$ of the Cat map in $\mathbb{Z}^2_{p^k}$ corresponds to the state 
\[
\bx_0=
\begin{bmatrix}
    \mathbf{a}_0, \\
    \mathbf{C}\cdot\mathbf{a}_0
\end{bmatrix}.
\]
of the $\mathbf{A}(\mathbf{x})$. Referring to the definition of $\mathbb{S}^{4}_{p^k}$ and $\mathbb{C}_p^{mn}$ there is 
\[
\mathbb{S}^{4}_{p^k}=\left\{\bx \Bigg\vert \bx=
\begin{bmatrix}
    \mathbf{a}, \\
    \mathbf{C}\cdot\mathbf{a}
\end{bmatrix}, \mathbf{a}\in\mathbb{Z}^2_{p^k}\right\}
\]
and 
$\mathbb{C}=\mathbb{S}^{4}_{p}$. Based on Corollary~\ref{coro:3b:PaNTS},
Theorem~\ref{the:numbercycle} characterizes how the number of cycles evolves as the exponent $k$ increases by one.

\begin{theorem}
The number of cycles of period $T_{\rm c}$ of Cat map~\eqref{eq:ArnoldInteger} over $(\mathbb{Z}_{p^e}, +, \cdot)$, denoted by $N_{T_{\rm c}, e}$, 
expands in both count and period as
    \begin{equation}\label{eq:3B:Ncxe>e*} 
    p\cdot N_{T_{\rm c}, k}=N_{p\cdot T_{\rm c}, k+1}
    \end{equation}
    if $\bnu(T_c)> p$.
    \label{the:numbercycle}
\end{theorem}
\begin{proof}
Since $f(t)=t^2-(ab+2)t+1=(t-\alpha_k)(t-\alpha_k^{-1})$ in $\mathbb{R}_{k}$, it follows from the definition of $\{T_{k, i}(v)\}$ in Corollary~\ref{coro:3b:PaNTS} that there are three cases of $\{T_{k, i}(v)\}$ which are divided by the property of the root $\alpha_1$.
\begin{itemize}
    \item $\alpha_1\not\in\mathbb{Z}_{p}$: the minimal polynomic of all sequence with the initial state $\mathbf{a}\neq \bo$ is $f(t)$ and corresping period is $P_1(f)$. From the definition of $\{T_{k, i}(v)\}$, one has $\{T_{k, i}(v)\}=p^vP_1(f)$.
\item $\alpha_1\in\mathbb{Z}_{p}$ and $\alpha_1\neq \alpha^{-1}_1$: the minimal polynomic of all sequence with the initial state $\mathbf{a}\neq \bo$ maybe $f(t)$, $f_1(t)=t-\alpha_1$ and $f_2(t)=t-\alpha^{-1}_1$. Combining with $\ord_1(\alpha_1)=\ord_1(\alpha_1^{-1})$ and Lemma~\ref{le:2:P_1}, oen has $P_1(f)=P_1(f_1)=P_1(f_2)=\ord(\alpha_1)$. 
\item $\alpha_1\in\mathbb{Z}_{p}$ and $\alpha_1=\alpha^{-1}_1$: it follows from Lemma~\ref{le:2:P_1} that $P_1(f)=p\cdot \ord(\alpha_1)$. This implys that $\{T_{k, i}(v)\}=p^v\ord(\alpha_1)$. 
\end{itemize}

According to above cases, $\{T_{k, i}(v)\}$ only has one element. Hence $\mathbf{N}_k(v)$ is $1$-dimension in \eqref{eq:the:Nkv2} and $\mathbf{N}_k(v)=N(T_{k, 1}(v), \mathbb{S}_{p^k}^4)$. Since ~\eqref{eq:3a:N=bij} and ~\eqref{eq:3a:aij}, one has 
        \begin{equation*}
    \begin{split}
        a_{ij}&=\left|\left\{\mathbf{c} \Bigg \vert  \mathbf{c}\in\mathbb{C}^{4}_p,\lcm\left(T_{1,i}, \frac{T_1(\mathbf{c})}{p^{\bnu(T_1(\mathbf{c}))}}\right)=T_{1,j}\right\}\right|.\\
        &=|\mathbb{C}^{4}_p|\\
        &=p^2
    \end{split}
\end{equation*}
and $b_{ij}=p$. For any $\bnu(T_c)> p$, ~\eqref{eq:3B:Ncxe>e*} holds.
\end{proof}

\begin{theorem}\label{th:3B:TT}
When
\begin{equation}\label{eq:Cat:kf}
k\ge
\begin{cases}
     1     & \mbox{if } \alpha=\alpha^{-1};\\
 k(\alpha) & \mbox{if } \alpha\neq\alpha^{-1},    
 \end{cases}
\end{equation}
the number of cycles of period $T_{\rm c}$ of Cat map~\eqref{eq:ArnoldInteger} over $(\mathbb{Z}_{p^e}, +, \cdot)$, 
denoted by $N_{T_{\rm c}, e}$,
satisfies
\begin{equation}
    N_{T_{\rm c}, k}=N_{T_{\rm c}, k+1}, 
\end{equation}
where $\alpha$ is a root of $f(t)$ in $\mathbb{R}_1$.
\end{theorem}
\begin{proof}
Referring to Theorem~\ref{th:3A:fe*}, this theorem holds.
\end{proof}

\begin{theorem}\label{th:3B:TT}
The number of cycles of period $T_{\rm c}$ of Cat map~\eqref{eq:ArnoldInteger} over $(\mathbb{Z}_{p^e}, +, \cdot)$, 
denoted by $N_{T_{\rm c}, e}$, 
satisfies the invariance property
\begin{equation}
N_{T_{\rm c}, k}=N_{T_{\rm c}, k+1}
\end{equation}
if $k>p(p^2-1)\log_p(a\cdot b+2)$.
\end{theorem}
\begin{proof}
The proof follows the same reasoning as that of Theorem~\ref{th:3A:fe*} and is therefore omitted.
\end{proof}

