\includegraphics[width=\textwidth]{FVgrid_magnus.pdf}
\caption{Depiction of a grid. The solid lines mark the primary grid and the dashed lines the dual grid.}\label{fig:grid}
\end{figure}

$N_i$ is the set of indices of nodes that are connected to $(x_i,y_i)$ by an edge. If $i$ is a boundary node, then the index $i$ is also included in $N_i$ and represents the contribution from the physical boundary. Furthermore,  the set of all points is denoted $\N$, and the set of boundary points is denoted as $\B$. 



For  a boundary point $i\in\B$, we characterise the flow as
\begin{align*}
  (v_n)_{i}<0, \quad & |(v_n)_{i}|\geq c_b(x_i,y_i,t) &\Rightarrow&\quad \textrm{supersonic inflow},\\
  (v_n)_{i}<0, \quad &|(v_n)_{i}|< c_b(x_i,y_i,t) &\Rightarrow& \quad\textrm{subsonic inflow},\\
  (v_n)_{i}>0, \quad &|(v_n)_{i}|< c_{i} &\Rightarrow&\quad \textrm{subsonic outflow,}\\
  (v_n)_{i}>0, \quad & |(v_n)_{i}|\geq c_{i} &\Rightarrow& \quad\textrm{supersonic outflow}.\\
\end{align*}
At time $t$, we define $\B^{out}$ to be the set of all outflow points and   $\B^{in}$ the set of all inflow points. These sets are further split in $\B^{sup.in}$, $\B^{sub.in}$, $\B^{sub.out}$ and $\B^{sub.out}$ according to the above rules.


\begin{remark}
  Since the sides of the Cartesian grid may be subject to different boundary data, one may keep track of each side of the corner cell and impose the correct data. (See also discussion in Sec. \ref{sec:comp}.) However, seeing the corner cell as entirely belonging to one or the other boundary will not formally degrade the accuracy of the  scheme. This is inevitable in some cases, e.g. if the left boundary is a wall where the no-slip is imposed strongly, and the bottom is an outlet. Then the point with index $i=0$ (low-left corner) is either considered to be a wall point, in which case the boundary fluxes are unnecessary when updating the velocity since it is set strongly. If it is not considered to be the wall, then the entire corner cell is treated like an inflow. Finally, note that these remarks are, by and large, independent of the order of accuracy of the scheme. To achieve high-order accuracy, the solution must be highly regular, which requires data to be compatible to a high degree of approximation, which is unlikely to be the case at corners between inflows and walls. 
\end{remark}

We will use the viscous approximation scheme proposed in \cite{SvardCarpenter18}, and also used in \cite{GjestelandSvard22}. To define this scheme, we need some further notation. We also remark that we only need flux approximations at the interior points. At the boundary the total flux is given by the data flux vector. Thus, using the Cartesian indexing, we have
\begin{align*}
  D^xa_k&=D^xa_{i,j}=\frac{a_{i+1,j}-a_{i-1,j}}{2h_x},\quad 1\leq i\leq N-1,\, 0\leq j\leq M,
%    D^xa_k&=D^xa_{0,j}=\frac{a_{1,j}-a_{0,j}}{2h},\quad\quad 0\leq j\leq   M,\\
%        D^xa_k&=D^xa_{N,j}=\frac{a_{N,j}-a_{N-1,j}}{2h},\quad  0\leq j\leq M,\\   
%  D^ya_k=D^ya_{i,j}=\frac{a_{i,j+1}-a_{i,j-1}}{2h},\quad 0\leq i\leq N,\, 1\leq j\leq M-1,\\
\end{align*}
and similarly in the $y$-direction.% Further, 
%\begin{align*}
%D^x_- a_{k+1/2}&=D^x_-a_{i+1/2,j}=\frac{a_{i+1/2,j}-a_{i-1/2,j}}{h_x},\\
%%D^x_- a_{k+1/2}&=D^x a_{1/2,j}=\frac{a_{1/2,j}-a_{0,j}}{h_x/2},\\
%%D^x_- a_{k+1/2}&=D^x a_{N+1/2,j}=\frac{a_{N,j}-a_{N-1/2,j}}{h_x/2}.
%\end{align*}
%The corresponding operators in the $y$-direction are defined similarly.

Furthermore, we define the mean values,
\begin{align*}
  \overset{x}{a}_k=\overset{x}{a}_{i,j}=\frac{a_{i+1,j}+a_{i-1,j}}{2},\quad 1\leq i\leq N-1,\, 0\leq j\leq M,\\
  \overset{y}{a}_k=\overset{y}{a}_{i,j}=\frac{a_{i,j+1}+a_{i,j-1}}{2},\quad 0\leq i\leq N,\, 1\leq j\leq M-1.\\
\end{align*}
The following approximations of "1" will also be used,
\begin{align*}
(1_x)_k=(1_x)_{i,j}=\frac{T^{-1}_{i,j}}{\overset{x}T^{-1}_{i,j}}, \quad\quad
(1_y)_k=(1_y)_{i,j}=\frac{T^{-1}_{i,j}}{\overset{y}T^{-1}_{i,j}}.
\end{align*}
 These are necessary to use in the numerical viscous fluxes given below, to allow for the viscous terms to form a positive definite term in the numerical entropy estimate. (See \cite{SvardCarpenter18} for further details.)



