%\begin{align*}
%  \overset{x}{a}_i&=  \overset{x}{a}_{0,j}=a_{1,j}\\
%    \overset{x}{a}_i&=  \overset{x}{a}_{N,j}=a_{N-1,j} 
%\end{align*}



\subsection{ The finite-volume scheme}



Turning to the numerical approximation of \eqref{eq:NS}, we use a standard node-centred scheme (see \cite{NordstromForsberg03}),
\begin{align}
V_{i}(\u_{i})_t + \left[ \sum_{j \in N_i} (\f_{ij}^I-\f_{ij}^V) \Delta y_{ij} \right]- \left[ \sum_{j \in N_i} (\g^I_{ij}-\g_{ij}^V) \Delta x_{ij}  \right], & \quad i \in\N, \label{scheme}
\end{align}
where $\u$ is the full solution vector, and $\u_{i}$ a 4-component subvector holding the approximate solution at  $(x_i,y_i,t)$. Furthermore, $\bsff^{I,V}_{ij}$ and $\bsfg^{I,V}_{ij}$ are consistent approximations of the inviscid and viscous fluxes. We require that the inviscid fluxes between two nodes ($i\neq j$) are entropy-stable approximations satisfying
\begin{equation}\label{shuffle}
	\begin{aligned}
 \tfrac{\bw^\top_j - \bw^\top_i}{2} \f^I_{ij} \Delta y_{ij} - \tfrac{\psi^x_{j} - \psi^x_{i}}{2} \Delta y_{ij}  \leq 0,  \\
		 - \tfrac{\bw^\top_j - \bw^\top_i}{2} \g^I_{ij} \Delta x_{ij} + \tfrac{\psi^y_{j} - \psi^y_{i}}{2} \Delta x_{ij}  \leq 0.
	\end{aligned}
\end{equation}
where $\bw_i=\bw(\u_i)$ are the entropy variables.  (See  \cite{Tadmor03,IsmailRoe09,Chandrashekar13,Svard22} for examples of such fluxes.)


The approximations of the viscous fluxes were developed in \cite{SvardCarpenter18} for a Cartesian finite-difference scheme,
\begin{align*}
  \f^V_{i}=(0,1_x\tau_{xx},1_x\tau_{xy},1_x(\overset{x}{u} \tau_{xx}+\overset{x}{v}\tau_{xy}) + \kappa D_xT)^T_{i},\\
  \g^V_{i}=(0,1_y\tau_{xy},1_y\tau_{yy},1_y(\overset{y}{u} \tau_{xy}+\overset{y}{v}\tau_{yy}) +\kappa D_y T)^T_{i},
\end{align*}
where, at the point $i$,
\begin{align*}
  \tau_{xx}&=\mu (\frac{4}{3}D^xu-\frac{2}{3}D^yv), \\
  \tau_{xy}&=\mu(D^yu+D^xv), \\
  \tau_{yy}&=\mu (\frac{4}{3}D^yv-\frac{2}{3}D^xu). \\
\end{align*}
As in the continuous equations, we have invoked Stokes' hypothesis in the formulae above. The viscous fluxes along an edge are subsequently computed as the mean values,
\begin{align*}
  \f_{ij}^V=\frac{\f^V_{i}+\f^V_{j}}{2},\\
  \g_{ij}^V=\frac{\g^V_{i}+\g^V_{j}}{2}.\\
\end{align*}
Analogous to the continuous case, we define at subsonic inflow boundary points a velocity where the tangential component is given by data,
\begin{align*}
  (u^*)_i=(v_n)_in^1_{ii}-v_{b\tau}(x_i,y_i,t)  n^2_{ii},\\
  (v^*)_i=(v_n)_in^2_{ii}+v_{b\tau}(x_i,y_i,t)n^1_{ii}.
\end{align*}
%and $v_n^2+\sfv_{b\tau}^2 = (u^*)^2 + (v^*)^2$ holds at these points.

At the boundaries, we set,
\begin{align}
(n^1(\f^I-\f^V)+n^2(\g^I-\g^V))_{ii}=(n^1\f_b+n^2\g_b)_{ii}.\label{num_bc}
\end{align}
The discrete boundary data fluxes $(n^1\f_{b}+n^2\g_{b})_{ii}$  are constructed in the same way as the continuous ones. 
\begin{remark}
Note that there is no need to define an approximation of the normal boundary 
flux (left-hand side of \eqref{num_bc}), since we simply insert the right-hand side of \eqref{num_bc} in the scheme at the boundary points. 
\end{remark}


For the time and space dependent boundary data, we use the notation $(\rho_b)_i=\rho_b(x_i,y_i,t)$, $i\in \B^{in}$, and analogously for the other boundary-data functions. We also use the superscripts $\rho$ and $E$ to denote the first and last component of the flux-approximation vector.



$\textbf{Supersonic inflow:}$
\begin{equation}\label{b_flux_supin_disc}
  \begin{aligned} 
(n^1\f_b+n^2\g_b)_{ii}=&\phantom{+}n^1_{ii}\left(\rho_bu_b,\rho_bu_b^2+p_b,\rho u_bv_b,u_b(E_b+p_b) \right)^\top\Big|_{(x_i,y_i,t)}\\
&+n^2_{ii}\left(\rho_bv_b,\rho_bu_bv_b,\rho v_b^2+p_b,v_b(E_b+p_b) \right)^\top\Big|_{(x_i,y_i,t)},\\
E_b(x_i,y_i,t)=&\,\frac{1}{2}\rho_b(u_b^2+v_b^2)+\frac{p_b}{\gamma-1}\Big|_{(x_i,y_i,t)}.
\end{aligned}
\end{equation}

$   \textbf{Subsonic inflow:}$
\begin{equation}\label{b_flux_subin_disc}
  \begin{aligned}
 (n^1\f_b+n^2\g_b)_{ii}   &=
    \left(\rho_bv_n,v_n\rho_bu^*+n^1p_b,v_n\rho_b v^*+n^2p_b,v_n(E^*+p_b) \right)^\top\Big|_{(x_i,y_i,t)},\\
    E^*_{ii}&=\frac{1}{2}\rho_b(v_n^2+v_{b\tau}^2)+\frac{p_b}{\gamma-1}\Big|_{(x_i,y_i,t)}.
\end{aligned}
\end{equation}



 $   \textbf{Subsonic outflow:}$
\begin{equation}\label{b_flux_subout_disc}
  \begin{aligned}
(\f_{b})_{ii}&=\left(\rho u,\rho u^2+p_b,\rho uv,u(E+p) \right)^\top\Big|_{(x_i,y_i,t)},\\
(\g_{b})_{ii}&=\left(\rho v,\rho uv,\rho v^2+p_b,v(E+p) \right)^\top\Big|_{(x_i,y_i,t)}.
\end{aligned}
\end{equation}


$    \textbf{Supersonic outflow:}$
\begin{equation}\label{b_flux_supout_disc}
  \begin{aligned}
(\f_{b})_{ii}&=\left(\rho u_,\rho u^2+p,\rho uv,u(E+p) \right)^\top\Big|_{(x_i,y_i,t)},\\
(\g_{b})_{ii}&=\left(\rho v,\rho uv,\rho v^2+p,v(E+p) \right)^\top\Big|_{(x_i,y_i,t)}.
\end{aligned}
\end{equation}
Note that the variables at the boundary points are updated by the scheme; providing data for the boundary fluxes constitutes a weak imposition of the boundary conditions. 
\begin{remark}
These boundary conditions reduce to the Euler conditions in \cite{Svard25}, if $\mu=\kappa=0$. 
\end{remark}

\subsection{A priori estimates}



%Below, we will demonstrate that the proposed scheme leads to the same numerical boundary terms as in \cite{Svard25}. The remaining the details in the proof of entropy stability are exactly the same as in the a priori estimates for the equations and therefore omitted.


\subsubsection{Mass balance}


The mass balance is obtained by summing the continuity equation over all grid points. 
\begin{align}
\sum_{i= 1}^\N V_i(\rho_i)_t +\sum_{i\in\B^{out}} \left(\f^\rho_{b,ii}\Delta y_{ii}-\g^\rho_{b,ii}\Delta x_{ii}\right)=\sum_{i\in\B^{in}} \left(-\f^\rho_{b,ii}\Delta y_{ii}+\g^\rho_{b,ii}\Delta x_{ii}\right).\label{rho_balance}
\end{align}
The right-hand side is a sum over the inflow points where $(v_n)_{ii}\leq 0$.
We split the right-hand side into two sums, one for $\B^{sup.in}$ and one for $\B^{sub.in}$. Beginning with the subsonic inflow points, we have $\f^\rho_{b,ii}=(\rho_b)_iu_i$ and  $\g^\rho_{b,ii}=(\rho_b)_i(v_n)_{ii}$ leading to
\begin{align*}
 -\f^\rho_{b,ii}\Delta y_{ii}+\g^\rho_{b,ii}\Delta x_{ii} = -(\rho_b)_i(v_n)_{ii}dl_{ii},\quad i\in \B^{sub.in}.
\end{align*}
At these points, the right-hand side is positive, but $|(v_n)|_{ii}\leq c_{b,i}$, $(i\in\B^{sub.in})$, leading to the desired bound. In the supersonic case $(i\in\B^{sup.in})$, $(v_n)_{ii}$ is also specified  by data, immediately leading to a bound.

At outflow points ($i\in \B^{out}$), $(v_n)_{ii}\geq 0$ (and $\rho_i>0$) implying that the outflow boundary sum is non-negative. Hence, we obtain the following a priori bound,
\begin{align}
\int_0^T\sum_{i\in\B^{out}} \left(\f_{b,ii}^\rho\Delta y_{ii}-\g_{b,ii}^\rho\Delta x_{ii}\right)\,dt\leq \C,\label{m_boundary}
\end{align}
along with an $L^1$ bound on density for all $t$.
%which is the numerical counterpart to \eqref{boundary_est}.

\subsubsection{Energy balance}
Turning to the energy balance, we have
\begin{align*}
\sum_{i=1}^\N V_i(E_i)_t+\sum_{i\in\B^{out}} \left(\f^E_{b,ii}\Delta y_{ii}-\g^E_{b,ii}\Delta x_{ii}\right) &=\\
\sum_{i\in\B^{in}} \left(-\f^E_{b,ii}\Delta y_{ii}+\g^E_{b,ii}\Delta x_{ii}\right).%\label{E_balance}
\end{align*}
At supersonic inflow points, the fluxes are completely defined by the data vector, such that the left-hand side is bounded for all $i\in \B^{sup.in}$. At the subsonic inflow ($i\in \B^{sub.in}$), the normal velocity is not given by data but satisfy $|(v_n)|_{ii}\leq c_{b,i}$, and we deduce from (\ref{b_flux_subin_disc}) that
\begin{align*}
 -\f^E_{b,ii}\Delta y_{ii}+\g^E_{b,ii}\Delta x_{ii} = -(v_n)_{ii}dl_{ii}\left(\frac{1}{2}\rho_{i}((v_n)_{ii}^2+(v_{b\tau})_{ii}^2)+ \frac{\gamma p_b}{\gamma-1}\right)\leq \C dl_{ii}.
\end{align*}
%Using that $|(u_n)|_{iB}\leq c_{iB}$, the left hand side is bounded.
At both types of outflow, no boundary data is used to construct the flux. However, the terms are all positive implying that,
\begin{align}
\int_0^T\sum_{i\in\B^{out}} \left(\f_{b,ii}^E\Delta y_{ii}-\g_{b,ii}^E\Delta x_{ii}\right)\,dt\leq \C,\label{E_boundary}
\end{align}
and we also collect an $L^1$ bound on $E$ for all $t$. 

\subsubsection{Entropy balance}


The numerical approximations of entropy potentials are $\psi^{x,y}_i=\psi^{x,y}(\u_i)$  at all grid points, $i\in \N$, and the entropy flux approximations associated with the edges are
\begin{equation}\label{ent_flux}
  \begin{aligned}
    F_{ij} &= \tfrac{\bw^\top_j + \bw^\top_i}{2}\f^I_{ij}-\frac{\psi^x_i+\psi^x_j}{2},\\
    G_{ij}&= \tfrac{\bw^\top_j + \bw^\top_i}{2}\g^I_{ij}-\frac{\psi^y_i+\psi^y_j}{2}.
  \end{aligned}
\end{equation}
The entropy balance is obtained by  multiplying \eqref{scheme} by $\bw_i^\top$ and summing over all points. Using \eqref{ent_flux} at all interior edges, the shuffle condition \eqref{shuffle}, and the numerical boundary flux (\ref{num_bc}) , we arrive at
\begin{align}
\sum_{i= N}^NV_iU(\u_i)_t  +\sum_{i\in \B}\left(\left(\bw^\top_i\f_{b,ii}-\psi^x_{i}\right)\Delta y_{ii}-\left(\bw^\top_i\g_{b,ii}-\psi^y_{i}\right)\Delta x_{ii}\right) \leq DIFF\label{ent_balance}.
\end{align}
where
\begin{align*}
DIFF = \sum_{i\in \N}\sum_{j\in \N_i\cap i} \Delta \bw^\top_{ij}(\f^V_{ij}\Delta y_{ij}-\g^V_{ij}\Delta x_{ij}).
\end{align*}
and $\Delta \bw_{ij}=\bw_j-\bw_i$.
Since the grid is Cartesian and the viscous approximations are exactly the same as in \cite{SvardCarpenter18}, it follows (from that paper) that $DIFF\leq 0$. 

Hence, stability follows if the boundary terms,
\begin{align}
  (n^1)_{ii}(\bw_i^\top\f_{b,ii}-\psi^x_i)+  (n^2)_{ii}(\bw_i^\top\g_{b,ii}-\psi^y_i)\geq \C,\label{disc_bt}
\end{align}
are bounded from below, which was shown in \cite{Svard25}. We conclude that $\sum_{i= 1}^\N V_iU(\u_i)_t\leq \C$.

From positivity and the bounds on entropy, energy and  density,  we obtain the following semi-discrete a priori bounds
\begin{align*}
\{ \rho, \rho \log \rho\, \rho |\v|^2, \rho \log T, p\}\in L^{\infty}(0,\T,L^1(\Omega)).
\end{align*}




\subsection{Other entropy-stable schemes}\label{sec:other_schemes}

Here, we have chosen to present the boundary conditions, and numerical boundary conditions using a conservative entropy-stable finite-volume scheme with the standard (conservative-variable) form of the viscous terms.

However, the boundary procedures are largely decoupled from the interior discretisations as long as the latter satisfy a few properties. 
\begin{itemize}
\item The scheme must preserve positivity of $\rho$ and $p$.
\item The scheme must be on divergence (conservation form). This ensures the $L^1$ estimates on $\rho$ and $E$. 
\item The inviscid flux approximations must be entropy stable and produce the same boundary terms in the entropy balance as the current finite volume scheme. The viscous approximations must be entropy dissipative in the interior (i.e., $DIFF\leq 0$) and produce the same boundary terms as the current scheme.  
\end{itemize}
As noted in \cite{Svard25}, the requirement that the scheme is on divergence form  can be omitted as long as the other two are met and one is only concerned with the approximation of \emph{smooth solutions}. However, note that for smooth solutions, linear stability is sufficient for convergence (see \cite{Strang64}).

%In the literature, many different entropy-stable summation-by-parts schemes have been proposed. See e.g. \cite{ChanBencomo21,Parsani_etal21,Fernandez_etal20}. Naturally, the question arises whether or not the proposed boundary fluxes may be used in such schemes. 


\subsection{Consistency with no-slip wall}\label{sec:no-slip}

It is also important that inflow and outflow boundary conditions are compatible with other boundary procedures. This is indeed the case, since for schemes satisfying the above list of properties, each boundary point (actually boundary face) contributes with a term to the estimates that is independent of the terms from all other boundary points/faces. Hence, boundary points can be assigned as walls or in/outflows independently.

In particular, the provably entropy-stable strong imposition of the no-slip boundary condition along with a weak imposition of the adiabatic wall condition proposed in \cite{GjestelandSvard22} is seamlessly compatible with the boundary conditions proposed in this paper. 



