\begin{definition}\label{def:closure}
    The \textbf{closure} of a set $S$ is the union of $S$ and its boundary $\delta S$: $\mathbf{cl}S = S \bigcup \delta S$ or equivalently, the intersection of all closed sets containing $S$.
\end{definition}

\begin{definition} \label{def:int}
    The \textbf{interior} of a set $S$, $\mathbf{int}S$, is the set of all interior points in $S$.
\end{definition}

\begin{definition} \label{def:compl}
    For a set $S$ in topological space $X$, the \textbf{complement} $S^c$ is the set of points in $X$ but not in $S$, i.e., $S^c = X \setminus S$.
\end{definition}

\section{Problem Setting}
Consider a discrete-time \textbf{dynamical system} that is described by a system state $x_t \in R^n$ and a dynamics function $f$ that produces the state at the next step as a function of the current state and  the current control input $x_{t+1} = f(x_t, u_t)$; $u_t \in R^m$.
If the control policy providing the control signal $u_t$ is provided and fixed, $u_t = c()$, we refer to this as an \textbf{autonomous system}.
If the control signal $u_t$ at each time step is generated by a neural network policy $u_t = NN(x_t)$, we call this dynamical system a \textbf{neural feedback loop}.
%-- a discrete-time dynamical system  where the control signal $u_t$  at each time step is generated by a neural network policy $u_t = NN(x_t)$. 
The \textbf{closed-loop} dynamics function, also known as the plant, is defined $f_{cl}(x_t) = f(x_t, NN(x_t))$.

We are interested in computing backward reachable sets under the closed-loop plant $f_{cl}$.
\begin{definition} \label{def:breach}
The exact $\mathbf{k}$\textbf{-step backward reachable set} of $\mathcal G$ for autonomous system $f_{cl}$ is defined 
\begin{align}  \label{eq:breach_def}
\Rback{k}{G} \triangleq \{ \vec{x}_{-k} \mid \vec{x}_{-k+1} &= f_{cl}(\vec{x}_{-k}), \\ \nonumber
\vec{x}_{-k+2} &= f_{cl}(\vec{x}_{-k+1}),\\ \nonumber
& \ldots, \\ \nonumber
\vec{x}_{0} &= f_{cl}(\vec{x}_{-1}), \\ \nonumber
\vec{x}_0 &\in \mathcal G\} \nonumber
\end{align} 
\end{definition}
Once we have computed backward reachable sets, we are interested in checking goal-reaching properties. 
\begin{definition}\label{def:goalreach}
    We say that a neural feedback loop $f_{cl}$ satisfies a \textbf{goal-reaching specification} with goal $\mathcal G$ and horizon $k$ if $\forall x \in \mathcal X_s. \exists t \in[0\ldots k]. f\circ^t(x) \in \mathcal G$. 
    %Where $\mathcal X_t$ is the set of states that the neural feedback loop may be in at time $t$. 
    %If the system begins within $\mathcal R_{-n}(\mathcal G)$ at time $t=-n$, $\mathcal X_{-n} \subseteq \Rback{k}{G}$, it is guaranteed that at time $t=0$ the system lies within $\mathcal G$, $\mathcal X_0 \subseteq \mathcal G$.
\end{definition}
\begin{definition}\label{def:brgr}
A goal-reaching specification holds for goal set $\mathcal G$ if the starting set of the system is a subset of the finite horizon transitive closure of backward reachable sets: 
\begin{equation} \label{eq:brgr}
\mathcal X_{s} \subseteq \bigcup_{t=1}^k\Rback{t}{G}
\end{equation}
\end{definition}
However, if we assume $f$ is an arbitrary nonlinear function, it is not possible to compute exact backward reachable sets.
We must therefore approximate, and our choice of approximation is guided by our intention to check goal-reaching properties.
% In order to check goal-reaching properties, we must compute underapproximate backward reachable sets.
\begin{lemma}
Computing underapproximate backward reachable sets $\Runderf{t}{G} \subseteq \Rback{t}{G}$ allows for the sound verification of goal-reaching properties.
\end{lemma}
\begin{proof}
If $\mathcal X_{s} \subseteq \bigcup_{t=1}^k\Runderf{t}{G}$ and $\Runderf{t}{G} \subseteq \Rback{t}{G}$ this implies $\mathcal X_{s} \subseteq \bigcup_{t=1}^k\Rback{t}{G}$.
\end{proof}
To summarize, we state the problem as follows. 
\subsection{Problem Statement} \label{sec:prob_state}
Given a nonlinear neural feedback loop (NFL) $x_{t+1} = f(x_t, NN(x_t))$ where $x_t \in R^n$, $u_t \in R^m$ and a goal set $\mathcal G \subseteq R^n$, compute a sequence of $k$ underapproximate backward reachable sets $\Runderf{t}{G}$ such that $\forall t\in1\ldots k.\Runderf{t}{G} \subseteq \Rback{t}{G}$. 

