We claim that $Ball_p(x_d, \epsilon^*)$ is the largest possible $p$-norm ball underapproximation of the backwards reachable set centered at $x_d$.
We argue that this is true because $Ball_p(x_d, \epsilon^*)$ is what we call a boundary coincident subset centered at $x_d$.
If $Ball_p(x_d, \epsilon^*)$ were any larger in radius, it would exceed the backward reachable set and no longer serve as a sound underapproximation. 

\begin{definition}
    \textbf{Boundary Coincident Subset} We call a set $A$ a boundary coincident subset of set $B$, $A \bndc B$, if $A\subseteq B$ and $\delta A \cap \delta B \neq \emptyset$.
\end{definition}
\begin{lemma}\label{lem:closure}
    If $A$ is an open set and $\mathbf{cl}B$ is a closed set, $A \subseteq \mathbf{cl}B \implies \mathbf{cl} A \subseteq \mathbf{cl}B$.   
\end{lemma}
\begin{proof}
    % https://math.stackexchange.com/questions/121236/if-a-is-a-subset-of-b-then-the-closure-of-a-is-contained-in-the-closure-o
    By \cref{def:closure}, $\mathbf{cl}A$ is a subset of any closed set containing A. $\mathbf{cl}B$ is a closed set containing $A$, therefore $\mathbf{cl} A \subseteq \mathbf{cl}B$.
\end{proof}
