\begin{algorithm}
\caption{Rejection Sampling}\label{alg:samp}
\KwData{$\mathcal O$, $\mathcal D$, $f$, $t$}
% dynamics, neural network control, number of steps, dataset, goal region, domain
\KwResult{$x_d$}
