\subsection{RDM for solving quasilinear parabolic PDEs}

By approximating $\mathcal{D}$ with $\mathcal{D}_h$ defined in \eqref{eq_rdo}, the PDE in \eqref{eq_pde} can be reformulated as
\begin{equation}\label{eq_ER0}
    \E{R(t, x, \xi; v)} = 0, \quad (t, x) \in [0, T-h] \times \R^d,
\end{equation}
where $R(t, x, \xi; v)$ is the residual function defined by
\begin{align}
    R(t, x, \xi; v) &:= \frac{v(t + h, x + \xi_h) - v(t, x)}{h} - f(t, x, v(t, x)), \label{eq_defR}\\
    \xi_h &:= \mu(t, x, v(t, x)) h + \sqrt{h} \sigma(t, x, v(t, x)) \xi. \label{eq_def_xih}
\end{align}
The formulation \eqref{eq_ER0} avoids explicit computation of spatial partial derivatives including the Hessian, however an  expectation in \eqref{eq_ER0} is needed for each $(t, x)$.  This is the trade off between the PINN and the RDM approach, the former needs the computation of partial derivatives of the solution at each sampled point $(t,x)$, which is avoided by the RDM in lieu of an expectation over the random jumps $\xi_h$ from $(t,x)$.
Approximating this expectation directly using Monte Carlo methods can be computationally intensive.
In the next section, we address this issue by reformulating \eqref{eq_ER0} using a weak form.

We close this section with two remarks that clarify the connections between the formulation~\eqref{eq_ER0} and existing works.

\begin{remark}[Connection to martingale methods]
    The formulation \eqref{eq_ER0} is equivalent to the martingale formulation proposed in \cite{cai2024socmartnet,cai2023deepmartnet,cai2024martnet}. 
    To see this connection, we recall the martingale condition for the function $v(t,x)$ being a solution of the PDE \eqref{eq_rdo} \cite[subsection 2.1]{cai2024martnet}:
    \begin{equation}\label{eq_mart_cond}
        \E{\M_{t+h} - \M_{t} \big\vert X_t = x} = 0, \quad (t, x) \in [0, T-h] \times \R^d,
    \end{equation}
    where 
    \begin{equation}
        \M_t := v(t, X_t) + \int_0^t f(s, X_s, v(s, X_s)) \di s,
    \end{equation}
    and $X_s$ is given by the forward SDE in \eqref{eq_bsde}.
    When $X_t$ is approximated by the Euler-Maruyama scheme \cite[section 14.1]{Kloeden1992Numerical} applied to the forward SDE in \eqref{eq_bsde}, 
    the martingale condition~\eqref{eq_mart_cond} reduces to the expectation condition~\eqref{eq_ER0} with $\xi \sim \mathrm{N}(0, I_q)$.
\end{remark}

\begin{remark}[Connection to FBSDE methods]
    The formulation~\eqref{eq_ER0} can also be derived from a time discretization of the FBSDEs~\eqref{eq_bsde}. 
    Specifically, taking the conditional expectation $\Etx{\,\cdot\,} := \E{\,\cdot\,\vert X_t = x}$ on both sides of the backward SDE in \eqref{eq_bsde} gives
    \begin{equation}\label{eq_bsde_cond}
        \Etx{Y_t} = \Etx{Y_{t+h}} + \int_t^{t+h} \Etx{f(s , X_s, Y_s)} \di s.  
    \end{equation}
    The condition \eqref{eq_ER0} then follows by: (i) substituting $Y$ using the Feynman-Kac formula \eqref{eq_feynman} in \eqref{eq_bsde_cond}; 
    (ii) approximating the integral in \eqref{eq_bsde_cond} with the left-rectangle rule;
    (iii) approximating the conditional expectations $\Etx{\,\cdot\,}$ by the Euler-Maruyama scheme \cite[section 14.1]{Kloeden1992Numerical} applied to the forward SDE in \eqref{eq_bsde}. 
    For more details on time discretization methods for FBSDEs \eqref{eq_bsde} and their generalizations, see \cite{zhao2006new,zhao2014new,Yang2020unified,Wang2022Sinc,Fang2023Strong}, etc.
\end{remark}

\section{Deep neural network with RDM (DRDM)}\label{sec_rdo_pde}

In this section, we introduce deep learning implementation to learn the solution $v$ from the condition \eqref{eq_ER0}, and subsequently extend the method to HJB equations.

\subsection{RDM with a Galerkin method}\label{sec_galerkin}

Similar to PINN methods~\cite{Raissi2019Physics,hu2024sdgd,Hu2024Hutchinson,He2023Learning,wang2022is,Gao2023Failure}, we enforce the condition~\eqref{eq_ER0} on a set of randonly sampled time-space points in $[0, T] \times \R^d$. 
Without loss of generality, we assume that for each $t \in [0, T]$, the spatial sampling points are independent and identically distributed (i.i.d.) samples of a random variable $X_t$ taking values in $\R^d$.
The construction of $X_t$ is specified in \eqref{eq_pathX} in later subsections.
We then reformulate~\eqref{eq_ER0} into a weak formulation:
\begin{equation}\label{eq_weakform}
    \int_0^{T-h} \int_{\R^d} \rho(t, x) \E{R(t, x, \xi; v)} P_{X_t}(x) \di x \di t = 0, \quad \forall \rho \in \mathcal{T},
\end{equation}
where $\mathcal{T}$ denotes the set of test functions, typically defined as:
\begin{equation}\label{eq_defrho}
    \mathcal{T} := \bbr{\rho: [0, T] \times \R^d \to \R^r \;\Big\vert\; \rho \text{ is smooth and bounded}},
\end{equation}
Here, $P_{X_t}(\cdot)$ is the probability density function (PDF) of $X_t$, serving as a weight function on $\R^d$. 
It is worth noting that the test function $\rho$ is chosen to be vector-valued, which enhances the stability of the adversarial training process described in the next subsection.

For the convenience of sample generation, let $X_t$ be independent of $\xi$, leading to
\begin{equation}\label{eq_jointpdf}
    P_{(X_t, \xi)}(x, z) = P_{X_t}(x) P_{\xi}(z), \quad (t, x, z) \in [0, T] \times \R^d \times \R^q,
\end{equation}
where $P_{(X_t, \xi)}$ is the joint PDF of $(X_t, \xi)$, and $P_{\xi}$ is the marginal PDF of $\xi$.
Using \eqref{eq_jointpdf}, the left side of \eqref{eq_weakform} can be rewritten as
\begin{align}
    &\int_0^{T-h} \int_{\R^d} \rho(t, x) \E{R(t, x, \xi; v)} P_{X_t}(x) \di x \di t \notag\\
    =\;& \int_0^{T-h} \int_{\R^d} \int_{\R^q} \rho(t, x) R(t, x, z; v) P_{\xi}(z)  P_{X_t}(x) \di z \di x \di t \notag\\
    =\;& \int_0^{T-h} \int_{\R^d} \int_{\R^q} \rho(t, x) R(t, x, z; v) P_{(X_t, \xi)}(x, z) \di z \di x \di t \notag\\
    =\;& \int_0^{T-h} \E{\rho(t, X_t) R(t, X_t, \xi; v)} \di t. \label{eq_intERdt} 
\end{align}
Substituting \eqref{eq_intERdt} into \eqref{eq_weakform}, we obtain the following minimax problem for solving $v$:
\begin{equation}\label{eq_minmax}
    \min_{v \in \mathcal{V}} \max_{\rho \in \mathcal{T}} \abs{L(v, \rho)}^2, \quad L(v, \rho) := \int_0^{T-h} \E{\rho(t, X_t) R(t, X_t, \xi; v)} \di t,
\end{equation}
where $\mathcal{V}$ represents the set of candidate functions $v$ satisfying the terminal condition, i.e., 
\begin{equation}\label{eq1_defV}
    \mathcal{V} := \bbr{v: [0, T] \times \R^d \to \R \;\;\big\vert\; v \in C_b^{2, 4}, \; v(T, x) = g(x), \;\; x \in \R^d}
\end{equation}
with the regularity condition ensuring the validity of the RDM method in \eqref{eq_rdo}.

Compared to the original problem \eqref{eq_weakform}, the minimax formulation is computationally more efficient, 
as it involves only a single expectation in the loss function, which can be effectively approximated through joint Monte Carlo sampling of $(t, X_t, \xi)$.

\subsection{Spatial sampling rule based on error propagation}\label{sec_pathsamp}

In this subsection, we analyze how the residual of the PDE \eqref{eq_pde} propagates and affects the error of the numerical solution. 
This analysis provides guidance for designing the PDF $P_{X_t}(\cdot)$ in \eqref{eq_weakform}.


\subsubsection{Error equation}

To obtain an explicit relationship between the residual and the error, 
we focus on the case where the PDE \eqref{eq_pde} is linear, i.e.,
\begin{equation}\label{eq_linear_pde}
    \mu(t, x, v) = \mu(t, x), \quad \sigma(t, x, v) = \sigma(t, x), \quad f(t, x, v) = f(t, x)
\end{equation}
for $(t, x, v) \in [0, T] \times \R^d \times \R$.
Although the following analysis is derived for the linear case, the sampling method obtained in \cref{sec_pathsamp2} is also applicable to the nonlinear case.

We decompose the operator $\mathcal{D}$ in \eqref{eq_defD} as follows:
\begin{equation}\label{eq_decompD}
    \mathcal{D} = \partial_t + \mathcal{L}, \quad \mathcal{L} := \mu^{\top} \partial_x + \frac{1}{2} \mathrm{Tr}[\sigma \sigma^{\top} \partial_{xx}^2].
\end{equation} 
Let $\hat{v}$ be an approximation to the solution $v$ of \eqref{eq_pde}.
Under the condition~\eqref{eq_linear_pde},
the error $\epsilon(t, x) := \hat{v}(t, x) - v(t, x)$ satisfies the following equation:
\begin{equation}\label{eq_error_eq}
    (\partial_t + \mathcal{L}) \epsilon(t, x) = \hat{r}(t, x), \quad (t, x) \in [0, T) \times \R^d,
\end{equation}
where $\hat{r}(t, x)$ denotes the residual at $(t, x)$, defined by
\begin{equation}\label{eq_def_rtx}
    \hat{r}(t, x) := \fbr{\partial_t + \mathcal{L}} \hat{v}(t, x) - f(t, x), \quad (t, x) \in [0, T) \times \R^d. 
\end{equation}

Let $p(t, x)$ be a weight function defined on $[0, T] \times \R^d$.
Taking the inner product of $\epsilon$ with $p(t, x)$ over $x \in \R^d$, we obtain the integral form of the error equation:
\begin{equation}\label{eq_dt_vp}
\begin{aligned}
    \partial_t \int_{\R^d} \epsilon p \di x &= \int_{\R^d} (\partial_t \epsilon) p \di x + \int_{\R^d} \epsilon (\partial_t p) \di x \\
    &= \int_{\R^d} \hat{r} p \di x - \int_{\R^d} (\mathcal{L} \epsilon) p \di x + \int_{\R^d} \epsilon \partial_t p \di x, 
\end{aligned}
\end{equation}
where the second line follows from \eqref{eq_error_eq}. 

\subsubsection{Error propagation from residuals}

Now, we shall simplify the right-hand side of \eqref{eq_dt_vp} to obtain an ODE with an explicit solution of $\int \epsilon p \di x$. 
Let $\mathcal{L}^*$ denote the $L^2$-adjoint of $\mathcal{L}$ on $\R^d$, so that
\begin{equation}\label{eq_Ladj}
    \int_{\R^d} (\mathcal{L} \epsilon) p \di x = \int_{\R^d} \epsilon (\mathcal{L}^* p) \di x. 
\end{equation}
Inserting \eqref{eq_Ladj} into \eqref{eq_dt_vp} yields
\begin{equation}\label{eq_error_eq_lin}
    \partial_t \int_{\R^d} \epsilon p \di x = \int_{\R^d} \hat{r} p \di x + \int_{\R^d} \epsilon (\partial_t p - \mathcal{L}^* p) \di x. 
\end{equation}
In particular, let $p$ satisfies the adjoint equation:
\begin{equation}\label{eq_adjpde}
\left\{\begin{aligned}
    &\fbr{\partial_t - \mathcal{L}^*} p = 0, \quad (t, x) \in (0, T] \times \R^d,\\
    &p(0, x) = \delta_{x_0}(x), \quad x \in \R^d,
\end{aligned}\right.
\end{equation}
where $\delta_{x_0}$ denotes the Dirac delta function centered at $x_0 \in \R^d$.
By substituting \eqref{eq_adjpde} into the right-hand side of \eqref{eq_dt_vp}, the second integral term is eliminated. 
Integrating both sides with respect to $t$ over $[0, T]$, we obtain the error representation at $(0, x_0)$:
\begin{equation}\label{eq_v0x0}
\begin{aligned}
    \epsilon(0, x_0) &= \int_{\R^d} (\epsilon p)(0, x) \di x \\
    &= \int_{\R^d} \epsilon(T, x) p(T, x) \di x - \int_0^T \int_{\R^d} \hat{r}(s, x) p(s, x) \di x \di s. 
\end{aligned}
\end{equation}

The representation \eqref{eq_v0x0} shows that the error at $(0, x_0)$ is determined by the terminal error, weighted by $p(T, x)$, and the accumulation of the residual $\hat{r}$ over time and space, weighted by $p(s, x)$. 
The function $p(t, x)$ therefore quantifies the influence of the time-space point $(t, x)$ on the error at $(0, x_0)$, motivating the use of $p$ as a sampling weight during training.

\subsubsection{Sampling method}\label{sec_pathsamp2}

The key issue is how to efficiently sample according to $p$ without incurring the high computational cost of directly solving the adjoint problem~\eqref{eq_adjpde}.
In fact, the adjoint equation \eqref{eq_adjpde} coincides with the Fokker-Planck equation, whose solution $x \mapsto p(t, x)$ represents the PDF of $X_t$ governed by the forward SDE in \eqref{eq_bsde} \cite[Proposition 3.3]{pavliotis2014stochastic}.
Therefore, spatial samples can be generated by simulating the forward SDE in \eqref{eq_bsde} using the weak Euler-Maruyama scheme.

Specifically, we introduce a time partition on $[0, T]$
\begin{equation}\label{eq_timepart}
    t_n = n h, \quad h = T/N, \quad n = 0, 1, \cdots, N.
\end{equation}
The spatial samples $\bbr{X_n^m}_{m=1}^M$ at time $t_n$ are generated by
\begin{equation}\label{eq_pathX}
    X_{n+1}^m = X_n^m + \mu\br{t_n, X_n^m, \hat{v}(t_n, X_n^m)}\,h + \sigma\br{t_n, X_n^m, \hat{v}(t_n, X_n^m)} \,\sqrt{h}\, \xi_{n+1}^{m},
\end{equation}
for $n = 0, 1, \cdots, N-1$, where $\hat{v}$ denotes a pilot approximation of $v$ obtained during neural network training, 
and for any $n$ and $m$, the random variables $\xi_n^m$ are i.i.d. samples of $\xi$ satisfying the conditions in \eqref{eq_condi_xi}; see \cite[section 14.1]{Kloeden1992Numerical}.
It is important to note that in \eqref{eq_pathX}, the subscript of $\xi_{n+1}^{m}$ is $n+1$ rather than $n$. 
This ensures the independence between $X_n^m$ and $\xi_n^m$, in accordance with the condition \eqref{eq_jointpdf}.

% The sampling method~\eqref{eq_pathX} is derived for the linear case, but our numerical experiments indicate that it also performs well for the nonlinear case of \eqref{eq_pde}.
% In the nonlinear case, i.e., when $\dot{\delta} \neq 0$, the solution $p(t, x)$ to \eqref{eq_adjpde} is generally not a probability density function, 
% which makes the sampling procedure nontrivial; see \Cref{rem_nonlin_samp}.
% The development of improved sampling strategies for the nonlinear case is left for future work.

% \begin{remark}\label{rem_nonlin_samp}
%     For $\dot{\delta} \neq 0$, the solution $p(t, x)$ to \eqref{eq_adjpde} characterizes the density of a system of particles following a branching process: these particles evolve according to the forward SDE in \eqref{eq_bsde}, but are also subject to a birth-death mechanism at $(t, x)$ governed by $\dot{\delta}(t, x)$.
%     As indicated in \eqref{eq_dotdelta}, $\dot{\delta}$ also depends on the derivatives of the unknown solution $v$, which further complicates the sampling procedure.
% \end{remark}

\begin{remark}[Connection to SDE-based approaches]
    The sampling method~\eqref{eq_pathX} is widely adopted in SDE-based approaches for exploring the space $\R^d$; 
    see, e.g., \cite{weinan2017deep,han2018solving,raissi2018forwardbackward,Zhang2022FBSDE,beck2019deep,hure2020deep,germain2022Approximation,Zhou2021Actor,Hure2021Deep,Bachouch2022Deep,Nusken2023Interpolating}.
    Our analysis offers a theoretical justification for this sampling method from the perspective of error propagation.
\end{remark}

