%     (ii) taking the conditional expectation $\E{\,\cdot\,\vert X_0 = x_0}$ and $t = 0$ on both sides of the backward SDE in \eqref{eq_bsde};
%     (iii) noting that $x \mapsto p(t, x)$ is the PDF of $X_t$ governed by the forward SDE in \eqref{eq_bsde}.
