\subsection{Mini-batch estimation of the loss function}\label{sec_mini_batch}

Let $(X_n^m, \xi_n^m)$ for $n = 0, 1, \cdots, N$ and $m = 1, 2, \cdots, M$ be i.i.d. samples of $(X_n, \xi)$ generated by \eqref{eq_condi_xi} and \eqref{eq_pathX}.  
The loss function in \eqref{eq_minmax} can be estimated in an unbiased manner using its mini-batch version given by
\begin{align}
    \abs{L(v, \rho)}^2 &\approx L^{\top}(v, \rho; A_1) L(v, \rho; A_2),\label{eq_approxG2}\\
    L(\rho, v; A_i) &:= \frac{1}{\abs{A}} \sum_{(n, m) \in A} \rho(t_n, X_n^m) R(t_n, X_n^m, \xi_n^m; v) h, \quad i = 1, 2, \label{eq_defL}
\end{align}
where $\abs{A_i}$ denotes the number of elements in the index set $A_i$, and $h = T/N$ is the time step size.
The index sets $A_1$ and $A_2$ are constructed by 
\begin{equation}\label{eq_defA1A2}
\begin{aligned}
    &A_i = \mathrm{N}_i \times \mathrm{M}_i, \quad \mathrm{N}_i \subset \{0, 1, \cdots, N-1\}, \\ 
    &\mathrm{M}_i \subset \{1, 2, \cdots, M\}, \quad \mathrm{M}_1 \cap \mathrm{M}_2 = \emptyset
\end{aligned}
\end{equation}
for $i = 1, 2$. 
Here, inspired by \cite{Guo2022Monte,hu2024sdgd}, the disjointness between $\mathrm{M}_1$ and $\mathrm{M}_2$ is used to ensure the mini-batch estimation in \eqref{eq_approxG2} is unbiased. 
The sets $\mathrm{N}_1$ and $\mathrm{N}_2$ can be chosen randomly, wthout replacements, from $\{0, 1, \cdots, N-1\}$, or simply set to $\{0, 1, \cdots, N-1\}$ if $N$ is not too large. 

\begin{remark}
    The simulation of the sample paths $X_n^m$ in \eqref{eq_pathX} is sequential in time, which can be computationally expensive.
    However, since these samples are only used as spatial sampling points, it is not necessary to update them at every iteration.
    Instead, they can be generated offline and updated less frequently; for example, by updating the sample paths every $I_0$ iterations, where $I_0$ is a tunable hyperparameter.
\end{remark}

\subsection{Adversarial learning}

To approximate the functions $v$ and $\rho$ in \eqref{eq_minmax}, we introduce neural networks $v_{\theta}$ and $\rho_{\eta}$, parameterized by $\theta$ and $\eta$, respectively. 
To enforce the terminal condition $v(T, x) = g(x)$, $x \in \R^d$, the neural network $v_{\theta}$ can be constructed as
\begin{equation}\label{eq_netv}
    v_{\theta}(t, x) = \left\{
    \begin{aligned}
        \phi_{\theta}(t, x), \quad &0 \leq t \leq t_{N-1}, \;\;\;  x \in \R^d, \\
        g(x), \quad &t_{N-1} < t \leq T, \;\;\; x \in \R^d,
    \end{aligned}\right.
\end{equation}
where $\phi_{\theta}$ is a neural network parameterized by $\theta$.
The adversarial network $\rho_{\eta}$ plays the role of test functions in classical Galerkin methods for solving PDEs.
By our experiment results, $\rho_{\eta}$ is not necessarily to be very deep, but instead, it can be a shallow network with enough output dimensionality.
Following the multiscale neural network ideas in \cite{Liu2020Multi},
we consider a typical  $\rho_{\eta}$ given as
\begin{equation}\label{eq_defrhonet}
    \rho_{\eta}(t, x) = \sin \br{\Lambda \br{W_1 t + W_2 x + b }} \in \R^r, 
\end{equation}
where $\eta := (W_1, W_2, b) \in \R^r \times \R^{r\times d} \times \R^r$ is the trainable parameter; $\Lambda(\cdot)$ is a scale layer defined by 
\begin{equation*}
    \Lambda(y_1, y_2, \cdots, y_r) = \br{cy_1, 2cy_2, \cdots, rcy_r}^{\top} \in \R^r
\end{equation*}
for $y_1, y_2, \cdots, y_r \in \R$ and $c > 0$ is a non-trainable hyperparameter; 
$\sin(\cdot)$ is the activation function applied on the outputs of $\Lambda$ in an element-wise manner.

Following the adversarial training approach proposed by \cite{Zang2020Weak}, the minimax problem \eqref{eq_minmax} can be solved by alternately minimizing $L^{\top}(v_{\theta}, \rho_{\eta}; A_1) \cdot L(v_{\theta}, \rho_{\eta}; A_2)$ over $\theta$ and maximizing $L^{\top}(v_{\theta}, \rho_{\eta}; A_1) L(v_{\theta}, \rho_{\eta}; A_2)$ over $\eta$ through stochastic gradient algorithms.
The detailed training procedure is outlined in Algorithm \ref{alg_pde}.


\begin{algorithm}[t]
    \caption{DRDM for the quasilinear parabolic equation \eqref{eq_pde}}\label{alg_pde}
    \begin{algorithmic}[1]
        \Require 
        % $M$: total number of sample paths for exploring $\R^d$;
        $v_{\theta}$/$\rho_{\eta}$: neural networks parameterized by $\theta$/$\eta$;
        $\delta_{1}$/$\delta_{2}$: learning rate for $v_{\theta}$/$\rho_{\eta}$;
        $I$: maximum number of iterations;
        $J$/$K$: number of $\theta$/$\eta$ updates per iteration;
        $I_0$ and $r\%$: interval for updating pilot paths and the percentage of paths updated.

        \State Initialize $v_{\theta}$ and $\rho_{\eta}$
        \State Generate the samples $\{(X_n^{m}, \xi_n^{m}): 0 \leq n \leq N, 1 \leq m \leq M\}$ by \eqref{eq_condi_xi} and \eqref{eq_pathX} with $\hat{v} = v_{\theta}$
        \For{$i = 1, 2, \cdots, I-1$}

        \State Sample disjoint index subsets $A_1, A_2$ per \eqref{eq_defA1A2}

        \For{$j = 0, 1, \cdots ,J-1$}
        \State $\theta \leftarrow \theta - \delta_{1} \nabla_{\theta} \bbr{L^{\top}(v_{\theta}, \rho_{\eta}; A_1) L(v_{\theta}, \rho_{\eta}; A_2)}$ \Comment{$L$ is given by \eqref{eq_defL}}
        \EndFor
        \For{$k = 0, 1, \cdots, K-1$}
        \State $\eta \leftarrow \eta + \delta_{2} \nabla_{\eta} \bbr{L^{\top}(v_{\theta}, \rho_{\eta}; A_1) L(v_{\theta}, \rho_{\eta}; A_2)}$
        \EndFor

        \If{$i$ is divisible by $I_0$} 
        \State Update $r\%$ of the samples $\{X_n^m\}_{n=0}^N$ by \eqref{eq_pathX} with $\hat{v} = v_{\theta}$
        \EndIf

        \EndFor
        \Ensure $v_{\theta}$
    \end{algorithmic}
\end{algorithm}

\subsection{Extension to HJB equations}

We now consider the HJB equation, which is a typical high-dimensional PDE arising in dynamic programming for stochastic optimal control problems (SOCPs) \cite{Yong1999Stochastic}.
The HJB equation and its terminal conditions take the form
\begin{equation}\label{eq_hjb}
    \inf_{\kappa \in U} \bbr{\mathcal{D}^{\kappa} v(t, x) + c(t, x,\kappa)} = 0, \quad (t, x) \in [0, T) \times \R^d
\end{equation}
with a terminal condition $v(T, x) = g(x)$, $x \in \R^d$, 
where $U \subset \R^m$ is a given control set, and $\mathcal{D}^{\kappa}$ denotes the second-order differential operator parameterized by $\kappa \in U$, defined as
\begin{equation}
    \mathcal{D}^{\kappa} := \partial_t + \mu^{\top}(t, x, \kappa) \partial_x + \frac{1}{2} \mathrm{Tr}\rbr{\sigma(t, x, \kappa) \sigma(t, x, \kappa)^{\top} \partial_{xx}^2}.
\end{equation}
Here, the functions $\mu$, $\sigma$, and $c$ are defined on $[0, T) \times \R^d \times U$ and take values in $\R^d$, $\R^{d\times q}$, and $\R$, respectively.

To facilitate the application of the DRDM, we adopt the idea of policy improvement algorithm \cite{Al2022Extensions}, and decompose the HJB equation~\eqref{eq_hjb} into two subproblems:
\begin{gather}
    u(t, x) = \argmin_{\kappa \in U} \bbr{\mathcal{D}^{\kappa} v(t, x) + c(t, x, \kappa)}, \label{eq_utx}\\
    \mathcal{D}^u v(t, x) + c(t, x, u(t, x)) = 0, \label{eq_vtx} 
\end{gather}
for $(t, x) \in [0, T) \times \R^d$ with the shorthand $\mathcal{D}^u := \mathcal{D}^{u(t, x)}$.
In the context of SOCPs, the function $u$ denotes the optimal state-feedback control.

Applying the random difference approximation~\eqref{eq_rdo} to the operator $\mathcal{D}^u$ in \eqref{eq_utx} and \eqref{eq_vtx}, and then reformulating the resulting equations into weak forms as described in \cref{sec_galerkin}, we arrive at the following formulation for solving the HJB equation:
\begin{equation}\label{eq_wpmfhjb}
    \min_{v \in \mathcal{V}} \; \sup_{\rho \in \mathcal{T}} \abs{L(u, v, \rho)}^2,  \quad \min_{u \in \mathcal{U}_{\mathrm{ad}}} L(u, v, 1),
\end{equation}
where the sets $\mathcal{T}$ and $\mathcal{V}$ are given in \eqref{eq_defrho} and \eqref{eq1_defV}, respectively;
$\mathcal{U}_{\mathrm{ad}}$ denotes the set of admissible feedback controls defined by 
\begin{equation}\label{eq_defUad}
    \mathcal{U}_{\mathrm{ad}} := \bbr{u: [0, T] \times \R^d \to U: u \text{ is Borel measurable}};
\end{equation}
the loss function $L$ is then defined by
\begin{equation}\label{eq_defGhjb}
    L(u, v, \rho) := \int_0^{T-h} \E{\rho(t, X_t) R(t, X_t, \xi; u, v)} \di t
\end{equation}
with $R$ the residual function defined by
\begin{equation}\label{eq_defDelMuv}
\begin{aligned}
    R\br{t, x, z; u, v} :=\;& v\br{t+h, x + \mu(t, x, u(t, x)) h + \sigma(t, x, u(t, x)) \sqrt{h} z}\\
    & - v(t, x) + h c(t, x, u(t, x)). 
\end{aligned}
\end{equation}
The notation $1$ in $L(u, v, 1)$ denotes a constant test function with fixed output $1$.

Similar to \cref{sec_mini_batch}, for practical implementation, the loss function $L$ in \eqref{eq_defGhjb} is approximated by its mini-batch version, defined as
\begin{equation}\label{eq_defGhjbA}
    L(u, v, \rho; A_i) := \frac{h}{\abs{A_i}} \sum_{(n, m) \in A_i} \rho(t_n, X_n^m) R(t_n, X_n^m, \xi_n^m; u, v), \quad i = 1, 2,
\end{equation}
where $A_i$ are still given by \eqref{eq_defA1A2}, and $\{X_{n}^m\}_{n=0}^N$ are samples generated by
\begin{equation}\label{eq_defhatXpil0_hjb}
    X_{n+1}^m = X_n^m + \mu\br{t_n, X_n^m, \hat{u}(t_n, X_n^m)}\,h + \sigma\br{t_n, X_n^m, \hat{u}(t_n, X_n^m)}\,\sqrt{h}\,\xi_{n+1}^{m}
\end{equation}
for $n = 0, \cdots, N-1$ and $m = 1, \cdots, M$, with each $\xi_{n}^{m}$ drawn i.i.d. from $\mathrm{N}(0, I_q)$ and $\hat{u}$ a pilot approximation of $u$ derived during neural network training.
The details training procedure for solving the HJB equation~\eqref{eq_hjb} is summarized in \Cref{alg_amnet}.

\begin{algorithm}[t]
    \caption{DRDM for solving the HJB equation~\eqref{eq_hjb}}\label{alg_amnet}
    \begin{algorithmic}[1]
        \Require 
        $v_{\theta}$/$u_{\alpha}$/$\rho_{\eta}$: neural network parameterized by $\theta$/$\alpha$/$\eta$;
        $\delta_0$/$\delta_{1}$/$\delta_{2}$: learning rate for the network $v_{\theta}$/$u_{\alpha}$/$\rho_{\eta}$;
        $I$: maximum number of iterations;
        $J$/$K$: number of $(\theta, \alpha)$/$\eta$ updates per iteration;
        $I_0$ and $r\%$: interval for updating spatial samples and the percentage of samples updated.

        \State Initialize the networks $u_{\alpha}$, $v_{\theta}$ and $\rho_{\eta}$
        \State Generate the samples $\{(X_n^{m}, \xi_n^{m}): 0 \leq n \leq N, 1 \leq m \leq M\}$ by \eqref{eq_condi_xi} and \eqref{eq_defhatXpil0_hjb} with $\hat{u} = u_{\alpha}$
        \For{$i = 0, 1, \cdots, I-1$}
        \State Sample disjoint index subsets $A_1, A_2$ per \eqref{eq_defA1A2}
        \For{$j = 0, 1, \cdots ,J-1$}
        \Comment{$L$ is given by \eqref{eq_defGhjbA}}
        \State $\theta \leftarrow \theta - \delta_{0} \nabla_{\theta} \bbr{L^{\top}(u_{\alpha}, v_{\theta}, \rho_{\eta}; A_1) L(u_{\alpha}, v_{\theta}, \rho_{\eta}; A_2)}$ 
        \State $\alpha \leftarrow \alpha - \delta_{1} \nabla_{\alpha} L(u_{\alpha}, v_{\theta}, 1; A_1 \cup A_2)$
        \EndFor
        \For{$k = 0, 1, \cdots, K-1$}
        \State $\eta \leftarrow \eta + \delta_{2} \nabla_{\eta} \bbr{L^{\top}(u_{\alpha}, v_{\theta}, \rho_{\eta}; A_1) L(u_{\alpha}, v_{\theta}, \rho_{\eta}; A_2)}$
        \EndFor

        \If{$i$ is divisible by $I_0$} 
        \State Update $r\%$ of the samples $\{X_n^m\}_{n=0}^N$ by \eqref{eq_defhatXpil0_hjb} with $\hat{u}=u_{\alpha}$
        \EndIf

        \EndFor
        \Ensure $u_{\alpha}$ and $v_{\theta}$
    \end{algorithmic}
\end{algorithm}

\section{Numerical experiments}\label{sec_numexp}

In this section, we present numerical experiments to demonstrate the performance of the proposed DRDM in solving high-dimensional parabolic and HJB equations. 
Details of the experimental parameters and additional results are provided in the Supplementary Material.
In reporting the numerical results, the abbreviations ``RE'', ``SD'', ``vs'', and ``Iter.'' refer to ``relative error'', ``standard deviation'', ``versus'', and ``iteration'', respectively.

To visualize the numerical solutions, we plot the curves of both the numerical and exact solutions at $t = 0$ for $x$ lying on the curves $S_2$ and $S_3$ in $\R^d$, defined as
\begin{align}
    &S_2 := \bbr{s \B{1}_d: s \in [-1, 1]}, \quad \B{1}_d := (1, 1, \cdots, 1)^{\top} \in \R^{d}.\label{eq_defS2}\\
    &S_3 := \bbr{\B{l}(s): s \in [-1, 1]}, \quad \B{l}(s) := \vbr{\big}{l_1(s), l_2(s), \cdots, l_d(s)}^{\top} \in \R^d \label{eq_defS3}
\end{align}
where $l_i(s) := s \times \mathrm{sgn}\br{\sin(i)} + \cos(i + \pi s)$ and $\mathrm{sgn}(z) := -1, 0, 1$ for $z < 0$, $= 0$, and $> 0$, respectively. 
Here, $S_2$ is a straight line segment whose length grows with the dimension $d$, while $S_3$ is a curve that winds through the space $\R^d$. 

For the approximation $\hat{v}$ to the exact solution $v$, we define the relative $L^1$ and $L^{\infty}$ errors at time $t = t_n$ as follows:
\begin{align}
    \mathrm{RE}_1(t_n) &:= \vbr{\Big}{\sum_{x \in D_n} \abs{\widehat{v}\br{t_n, x} - v(t_n, x)}} \big/ \vbr{\Big}{\sum_{x \in D_n} \abs{v(t_n, x)}}, \label{eq_defRelL1}\\
    \mathrm{RE}_{\infty}(t_n) &:= \vbr{\Big}{\max_{x \in D_n} \abs{\widehat{v}\br{t_n, x} - v(t_n, x)}} \big/ \vbr{\Big}{\max_{x \in D_n} \abs{v(t_n, x)}},\label{eq_defRelLinf}
\end{align}
where $D_n = \{X_n^m\}_{m=1}^{\bar{M}}$ denotes the set of spatial points sampled according to \eqref{eq_pathX} for the quasilinear PDE~\eqref{eq_pde}, and \eqref{eq_defhatXpil0_hjb} for HJB equations.
Unless otherwise specified, $\mathrm{RE}_1$ and $\mathrm{RE}_{\infty}$ refer to the errors evaluated at $t = 0$.
The initial points $\{X_0^m\}_{m=1}^{\bar{M}}$ are chosen as uniformly spaced grid points along the curves $S_2$ and $S_3$. 
For evaluating the error trajectories $t_n \mapsto \mathrm{RE}_1(t_n)$ and $t_n \mapsto \mathrm{RE}_{\infty}(t_n)$ (see, e.g., the third row of \Cref{fig_HP9abcd}), we set $\bar{M} = 8$. 
For evaluating $\mathrm{RE}_1$ and $\mathrm{RE}_{\infty}$ as functions of the number of iterations (see, e.g., the fourth row of \Cref{fig_HP9abcd}), we use $\bar{M} = 1000$. 

