\section{Cole-Hopf transformation for HJB equations}\label{sec_constPDE}

We consider the PDE
\begin{equation}\label{eq_pde_ch}
    \mathcal{R}v(t, x) = 0, \quad (t, x) \in [0, T) \times \R^d.
\end{equation}
where $\mathcal{R}$ is a differential operator defined by
\begin{equation}\label{eq_defRv}
    \mathcal{R}v(t, x) := \br{\partial_t + \mu^{\top} \partial_x + \frac{1}{2} \mathrm{Tr}\rbr{\sigma \sigma^{\top} \partial_{xx}}} v(t, x) - \frac{c^2}{2} \abs{\sigma^{\top} \partial_x v}^2(t, x)
\end{equation}
with $\mu: [s, T] \times \R^d \to \R^d$ and $\sigma: [s, T] \times \R^d \to \R^{d \times d}$ being deterministic functions, and $c > 0$ is a constant.

Next, we derive the analytic solution of \eqref{eq_pde_ch} using the Cole-Hopf transformation. 
For $(s, x) \in [0, T) \times \R^d$, let $X: [s, T] \times \Omega \to \R^d$ be the solution to the following SDE:
\begin{equation}
    X_t = x + \int_s^t \mu(r, X_r) \di r + \int_s^t \sigma(r, X_r) \di W_r, \quad t \in [s, T]. 
\end{equation}
Define the process 
\begin{equation*}
    Y_t := \exp\br{-c^2 v(t, X_t)}, \quad t \in [s, T].
\end{equation*}
Direct calculations show that
\begin{equation*}
    \begin{aligned}
        \partial_{x_i} Y_t =\;& -c^2 Y_t \partial_{x_i} v(t, X_t), \\
        \partial_{x_j x_i}^2 Y_t =\;& -c^2 Y_t \partial_{x_j x_i}^2 v(t, X_t) + c^4 Y_t \partial_{x_i} v(t, X_t) \partial_{x_j} v(t, X_t), \\
        \mathrm{Tr}\rbr{\sigma\sigma^{\top} \partial_{xx}^2 Y_t} =\;& -c^2 Y_t \sum_{ijk} \sigma_{ij} \sigma_{kj} \partial_{x_i x_k}^2 v(t, X_t) \\
        &+ c^4 Y_t \sum_{ijk} \sigma_{ij} \sigma_{kj} \partial_{x_i} v(t, X_t) \partial_{x_k} v(t, X_t).
    \end{aligned}
\end{equation*}
Applying the It\^o formula \cite[Theorem 2.3.3]{Zhang2017Backward} to the process $t \mapsto Y_t$, and substituting the above derivative terms into the resulting equation, we obtain
\begin{equation}\label{eq_diYt}
    \di Y_t = -c^2 Y_t \mathcal{R}v(t, X_t) \di t + \bbr{\cdots} \di W_t, \quad t \in [s, T], 
\end{equation}
where $\mathcal{R}v(t, x)$ is given in \eqref{eq_defRv}. 
Substituting \eqref{eq_pde_ch} into \eqref{eq_diYt}, the first term on the right-hand side vanishes. 
Taking expectations on both sides of the resulting equation yields
\begin{equation}
    \E{Y_t} = \E{Y_T}, \sptext{i.e.,} v(t, x) = -\frac{1}{c^2}\ln\br{\E{\exp\br{-c^2 v(T, X_T)}}}. 
\end{equation}

\section{Parameter setting for numerical experiments}\label{sec_param_setting}

If no otherwise specified, we take $N = 100$ for all involved loss functions, and all the loss functions are minimized by the RMSProp algorithm. 
The learning rates of \Cref{alg_pde,alg_pde} are set to $\delta_0 = \delta_1 = 0.1 \delta_2 = 3 \times 10^{-3 - 2 i/I} \times d^{-r}$ for $i = 0, 1, \cdots, I-1$ with $r = 0.5$ for $d \leq 1,000$ and $r = 0.8$ for $d > 1,000$.
The inner iteration steps are $J = 2K = 2$.
The neural networks $u_{\alpha}$ and $v_{\theta}$ both consist of $6$ hidden layers with $\max\{100, d + 10\}$ ReLU units in each hidden layer.
The adversarial network $\rho_{\eta}$ is given by \eqref{eq_defrhonet} with the output dimensionality $r = 600$.
The start points $X_0^{(m)}$ of the sample paths in \eqref{eq_pathX} and \eqref{eq_defhatXpil0_hjb} are randomly taken from the set $D_0$ with replacement, where the total number of sample paths is set to $M = 10^4$.
The mini-batch sizes in \eqref{eq_defA1A2} are set to $\abs{\mathrm{M}_1} = \abs{\mathrm{M}_2} = 128$, $64$, and $32$ for $d \leq 1000$, $d = 2000$, and $d = 10^4$, respectively.
The index sets $\mathrm{N}_1$ and $\mathrm{N}_2$ are both fixed as $\bbr{0, 1, \cdots, N-1}$.
The interval $I_0$ for updating spatial samples is chosen as $M/(\abs{A_1} + \abs{A_2})$, and the percentage $r\%$ of samples updated is set to $20\%$.

All numerical experiments are conducted using Python 3.12 and PyTorch 2.7.0.
Unless otherwise specified, the algorithms are accelerated using Distributed Data Parallel (DDP)\footnote{\url{https://github.com/pytorch/tutorials/blob/main/intermediate_source/ddp_tutorial.rst}} on a compute node equipped with 8 NVIDIA A100-SXM4-80GB GPUs.
To further enhance computational efficiency and reduce GPU memory usage, the networks $u_{\alpha}$ and $v_{\theta}$ are trained using mixed precision, implemented via the Automatic Mixed Precision package\footnote{\url{https://docs.pytorch.org/docs/2.7/amp.html}}.

\section{Error estimates}\label{sec_theory}

In this section, we theoretically derive the convergence rate of the RDM~\eqref{eq_ER0} for a special case of the PDE~\eqref{eq_pde} where the operator $\mathcal{D}$ is linear.

\subsection{Local truncation error}

Our first result is presented in \Cref{thm_consist}, which shows that the local truncation error of 
the random difference approximation~\eqref{eq_rdo} is of first order uniformly for $(t, x) \in [0, T-h] \times \R^d$.

\begin{theorem}\label{thm_consist}
    Let $\mathcal{D}v$ and $\mathcal{D}_h v$ be given by \eqref{eq_defD} and \eqref{eq_rdo} respectively. 
    Under the regularity condition $v \in C_b^{2, 4}$, it holds that
    \begin{equation}
        \sup_{(t, x) \in [0, T-h] \times \R^d} \abs{\mathcal{D}_h v(t, x) - \mathcal{D}v(t, x)} \leq S h,
    \end{equation}  
    where $S := 2 S_v (1 + S_{\xi}) (1 + S_{\mu})^2 (1 + S_{\sigma})^4$ is a constant independent of $h$ with 
    \begin{align}
        &S_v := \sup_{(t,x) \in [0, T) \times \R^d}\sum_{\alpha \in \mathcal{M}_{2, 4}} \abs{D^{\alpha} v(t, x)}, \quad D^{\alpha} := \partial_t^{\alpha_0} \partial_{x_1}^{\alpha_1} \partial_{x_2}^{\alpha_2} \cdots \partial_{x_d}^{\alpha_d},\label{eq_defSv}\\
        &S_{\xi} := \max_{i,j,k,l=1, \cdots, q} \E{\abs{\xi_i \xi_j \xi_k \xi_l}}, \quad S_{\mu} := \sup_{(t, x, y) \in [0,T) \times \R^d \times \R} \bbr{\max_{i=1,\cdots, d} \abs{\mu_i (t, x, y)}}, \label{eq_defMmu}\\
        &S_{\sigma} := \sup_{(t, x, y) \in [0,T) \times \R^d \times \R} \vbr{\Big}{\max_{j=1,\cdots, q} \sum_{i = 1}^d + \max_{i=1,\cdots, d} \sum_{j = 1}^q} \abs{\sigma_{ij}(t, x, y)}. \label{eq_defMsgm}
    \end{align}
    In \eqref{eq_defSv}, $\mathcal{M}_{2, 4}$ is the set of multi-indices $\alpha = (\alpha_0, \alpha_1, \cdots, \alpha_d) \in \{0, 1, 2, \cdots\}^d$ satisfying $\alpha_0 \in \{1, 2\}$ and $\sum_{i=1}^d \alpha_i \in \{1, 2, 3, 4\}$.
\end{theorem}

\begin{proof}

    For $(t, x) \in [0, T) \times \R^d$, define $\bar{\mu} = \mu(t, x, v(t, x))$ and $\bar{\sigma} = \sigma(t, x, v(t, x))$. 
    In the remainder of this proof, we stipulate that the partial derivatives $\frac{\partial}{\partial t}$ and $\frac{\partial}{\partial x}$ do not act on the coefficients $\bar{\mu}$ and $\bar{\sigma}$.   
    Under the regularity condition $v \in C_b^{2, 4}$, and recalling the derivatives in \cref{sec_basic,sec_condiff}, the expansions in \Cref{eq_expandV,eq1_expandV,eq2_expandV} hold, where the remainder terms $O\br{h^2}$, $O(h^2)$, and $O(h)$ are respectively replaced by $R_1$, $R_2$, and $R_3$ given by
    \begin{equation}\label{eq_defR1R2R3}
    \begin{aligned}
        &R_1 := \frac{h^2}{4!} \E{\br{\xi^{\top} \frac{\partial}{\partial z}}^4 V(h, c_1 \sqrt{h}\xi)}, \\ 
        &R_2 := \frac{h^2}{2} \frac{\partial^2 V}{\partial s^2}(c_2 h, 0), \quad R_3 := h \sum_{i=1}^q \frac{\partial^3 V}{\partial z_i \partial z_i \partial s}(c_3 h, 0).
    \end{aligned}
    \end{equation}
    Here, $c_1$ is a random variable depending on $\sqrt{h}\xi$, while $c_2$ and $c_3$ are constants depending on $h$; all take values in $[0, 1]$. 
    Furthermore, \Cref{eq_rdo} can be rewritten as
    \begin{equation}\label{eq_expandV3}
        \mathcal{D}_h v(t, x) = \mathcal{D}v(t, x) + \frac{R_1 + R_2}{h} + \frac{1}{2} R_3.  
    \end{equation}
    We now proceed to estimate the remainder terms $R_1$, $R_2$, and $R_3$.

    To estimate $R_1$ in \eqref{eq_defR1R2R3}, we deduce
    \begin{equation}\label{eq_estR1}
    \begin{aligned}
        \abs{R_1} \leq\;& \frac{h^2}{4!} \E{\sum_{i,j,k,l=1}^q \abs{\xi_i \xi_j \xi_k \xi_l} \times \abs{\frac{\partial^4 V}{\partial {z_i} \partial {z_j} \partial {z_k} \partial {z_l}}(h, c_1 \sqrt{h}\xi)}} \\
        \leq\;& \frac{h^2}{4!} S_{\xi} \sup_{(s, z) \in [0, T) \times \R^q} \sum_{i,j,k,l=1}^q \abs{\frac{\partial^4 V}{\partial {z_i} \partial {z_j} \partial {z_k} \partial {z_l}}(s, z)} 
    \end{aligned}
    \end{equation}
    with the second inequality following from the Hölder inequality, and $S_{\xi}$ given in \eqref{eq_defMmu}.
    Recalling \eqref{eq_defVsz}, we can deduce 
    \begin{equation*}
        \sum_{i,j,k,l=1}^q \frac{\partial^4 V}{\partial {z_i} \partial {z_j} \partial {z_k} \partial {z_l}}(s, z) = \vbr{\Big}{\sum_{i = 1}^d \sum_{j=1}^q \bar{\sigma}_{ij} \frac{\partial}{\partial x_i}}^4 v(t + s, x + \bar{\mu} s + \bar{\sigma}_{ij} z)
    \end{equation*}
    with $\bar{\mu}_{ij} := \mu_{ij} (t, x, v(t, x))$ and $\bar{\sigma}_{ij} := \sigma_{ij}(t, x, v(t, x))$. 
    The above equation further implies 
    \begin{equation*}
        \sup_{(s, z) \in [0, T) \times \R^q} \sum_{i,j,k,l=1}^q \abs{\frac{\partial^4 V}{\partial {z_i} \partial {z_j} \partial {z_k} \partial {z_l}}(h, z)} \leq S_v S_{\sigma}^4
    \end{equation*}
    wtih $S_v$ and $S_{\sigma}$ given in \eqref{eq_defSv} and \eqref{eq_defMsgm}. 
    Inserting the above inequality into \eqref{eq_estR1}, we obtain
    \begin{equation}\label{eq2_estR1}
        \abs{R_1} \leq \frac{h^2}{4!} S_v S_{\xi} S_{\sigma}^4. 
    \end{equation}

    To estimate $R_2$ in \eqref{eq_defR1R2R3}, 
    we recall \eqref{eq_defVsz} and explicitly compute $\partial_s^2 V(s, 0)$ as follows: 
    \begin{equation*}
        \frac{\partial^2 V}{\partial s^2}(s, 0) = \br{\frac{\partial}{\partial t} + \bar{\mu}^{\top} \frac{\partial}{\partial x}}^2 v\br{t + s, x + \bar{\mu} s}.
    \end{equation*}
    Inserting the above equation into the second equation in \eqref{eq_defR1R2R3}, 
    we can obtain
    \begin{equation}\label{eq2_estR2}
        \abs{R_2} \leq \frac{h^2}{2} \sup_{s \in [0, T)} \abs{\partial_s^2 V(s, 0)} \leq \frac{h^2}{2} S_v (1 + S_{\mu})^2
    \end{equation}
    with $S_{\mu}$ given in \eqref{eq_defMmu}.

    To estimate $R_3$ in \eqref{eq_defR1R2R3}, we recall \eqref{eq_defVsz} to deduce  
    \begin{equation}
        \sum_{i=1}^q \frac{\partial^3 V}{\partial z_i \partial z_i \partial s}(s, 0) = \br{\frac{\partial}{\partial t} + \bar{\mu}^{\top} \frac{\partial}{\partial x}} \mathrm{Tr}\rbr{\bar{\sigma} \bar{\sigma}^{\top} \frac{\partial^2 v}{\partial x \partial x}} (t + s, x + \bar{\mu} s),
    \end{equation}
    which implies
    \begin{equation*}
        \abs{\sum_{i=1}^q \frac{\partial^3 V}{\partial z_i \partial z_i \partial s}(s, 0)} \leq S_v (1 + S_{\mu}) S_{\sigma}^2.
    \end{equation*}
    Inserting the above inequality into the third equation in \eqref{eq_defR1R2R3}, we obtain
    \begin{equation}\label{eq2_estR3}
        \abs{R_3} \leq h S_v (1 + S_{\mu}) S_{\sigma}^2.
    \end{equation}

    Combining \eqref{eq2_estR1}, \eqref{eq2_estR2}, and \eqref{eq2_estR3},
    we obtain 
    \begin{equation*}
        \abs{\frac{R_1 + R_2}{h} + \frac{1}{2} R_3} \leq 2 h S_v (1 + S_{\xi}) (1 + S_{\mu})^2 (1 + S_{\sigma})^4. 
    \end{equation*}
    Inserting the above inequality into \eqref{eq_expandV3}, we obtain the desired result. 

\end{proof}

\subsection{Global truncation error}

For the stability analysis, we introduce the following assumptions.

\begin{assumption}\label{assum_lipf}
    Assume that the function $f(t, x, y)$ in \eqref{eq_pde} is uniformly Lipschitz continuous in $y$, i.e., there exists a constant $C_0 > 0$ independent of $(t, x)$, such that
    \begin{equation}\label{eq_lipf}
        \abs{f(t, x, y_1) - f(t, x, y_2)} \leq C_0 \abs{y_1 - y_2}, \quad (t, x) \in [0, T] \times \R^d, \quad y_1, y_2 \in \R.   
    \end{equation}
\end{assumption}

\begin{assumption}\label{assum_linearDh}
    The function $\mu$ and $\sigma$ in \eqref{eq_defD} is independent of $v(t, x)$, namely, $\mu(t, x, y) = \mu(t, x)$ and $\sigma(t, x, y) = \sigma(t, x)$ for all $(t, x) \in [0, T] \times \R^d$ and $y \in \R$.
\end{assumption}

\Cref{assum_lipf} is standard in the numerical analysis of PDEs.
\Cref{assum_linearDh} simplifies the analysis by removing the nonlinearity from the differential operator $\mathcal{D}$.
To quantify the errors, for any function $u: [0, T] \times \R^d \to \R$ in $C_b^{1, 2}$, let $\mathbb{M}_n^p\rbr{u}$ denote the $p$-th moment of $u(t_n, X_{n})$, defined as
\begin{equation}\label{eq_defMtp}
    \mathbb{M}_n^p\rbr{u} := \int_{\R^d} \abs{u(t_n, x)}^p P_{X_{n}}\br{x} \di x, \quad p \geq 1,
\end{equation}
where $x \mapsto P_{X_n}\br{x}$ is the PDF of $X_{n}^m$ given by \eqref{eq_pathX}. 
Under \Cref{assum_linearDh}, this can be simplified as
\begin{equation}\label{eq_defXn}
    X_{n+1} = X_n + \mu(t_n, X_n) h + \sigma(t_n, X_n) \sqrt{h} \xi_n, \quad n = 0, 1, \cdots, N-1, 
\end{equation}
where $\xi_n$, $n = 0, 1, \cdots, N-1$, are i.i.d. samples of $\xi$ used in the definition of $\mathcal{D}_h$ in \eqref{eq_rdo}.

The following lemma establishes the stability of the formulation \eqref{eq_ER0}.

\begin{lemma}\label{lem_priest}
    Let \Cref{assum_lipf,assum_linearDh} hold, and $0 < h < \min\bbr{1, (2\sqrt{2} C_0)^{-1}}$ with $C_0$ given in \eqref{eq_lipf}.
    For any Borel measurable functions $v_1, v_2: [0, T] \times \R^d \to \R$, define the functions 
    \begin{equation}\label{eq_defRi}
        \Delta v(t, x) := v_1(t, x) - v_2(t, x), \quad \Delta R(t, x) := \E{R(t, x, \xi; v_1)} - \E{R(t, x, \xi; v_2)}
    \end{equation}
    with $R$ given in \eqref{eq_defR}.
    Then it holds that
    \begin{equation}\label{eq_estMn2Delv}
        \max_{0 \leq n\leq N-1} \mathbb{M}_n^2\rbr{\Delta v} \leq C_2 \exp\br{C_1 T} \bbr{\mathbb{M}_{N}^2\rbr{\Delta v} + \frac{T}{N}\sum_{n=0}^{N-1} \mathbb{M}_n^2\rbr{\Delta R}},
    \end{equation}
    where $C_1 := 2\br{1 + 2 C_0^2 + C_0/\sqrt{2}}$ and $C_2 := 2 (1 + C_1 (2\sqrt{2} C_0)^{-1})$. 
\end{lemma}

\begin{proof}
    Inserting \eqref{eq_defR} into the second equation in \eqref{eq_defRi}, we can obtain
    \begin{equation}\label{eq_DeltaR}
        \Delta R(t, x) = \frac{\Delta V_h(t, x) - \Delta v(t, x)}{h} - \Delta f(t, x),
    \end{equation}
    where $\Delta f(t, x) := f(t, x, v_1(t, x)) - f(t, x, v_2(t, x))$, and $\Delta V_h(t, x)$ is given by 
    \begin{equation}\label{eq_DelV}
        \Delta V_h(t, x) := \E{\Delta v(t + h, X_{t+h}^{t,x})}, \quad X_{s}^{t,x} := x + \mu(t, x) (s - t) + \sigma(t, x) \sqrt{s - t} \xi. 
    \end{equation}
    Then \eqref{eq_DeltaR} can be rewritten as
    \begin{equation}\label{eq_EDeltaV}
        \Delta v(t, x) = \Delta V_h(t, x) - h \Delta f(t, x) - h \Delta R(t, x).
    \end{equation}

    \subsubsection*{(i) Estimate of $\Delta v(t, x)$. }

    Squaring both sides of \eqref{eq_EDeltaV}, and using the inequality $(a + b)^2 \leq (1+h) a^2 + \br{1+h^{-1}} b^2$ for $a, b > 0$, we obtain
    \begin{align*}
        \abs{\Delta v(t, x)}^2 \leq\;& (1 + h) \abs{\Delta V_h(t, x)}^2 + 2\br{1 + h^{-1}} h^2 \bbr{\abs{\Delta R(t, x)}^2 + \abs{\Delta f(t, x)}^2}.
    \end{align*}
    Using \eqref{eq_lipf} to estimate $\Delta f(t, x)$ in the above inequality, we obtain
    \begin{equation*}
        \abs{\Delta v(t, x)}^2 \leq (1 + h) \bbr{\abs{\Delta V_h(t, x)}^2 + 2 h \abs{\Delta R(t, x)}^2 + 2 h C_0^2 \abs{\Delta v(t, x)}^2}.
    \end{equation*}
    Moving the last term to the left side of the above inequality, we have
    \begin{equation}\label{eq_ineq_1h}
        \bbr{1 - 2\br{1 + h} h C_0^2}\abs{\Delta v(t, x)}^2 \leq (1 + h) \bbr{\abs{\Delta V_h(t, x)}^2 + 2 h \abs{\Delta R(t, x)}^2}.
    \end{equation}
    Let $0 < h < (2\sqrt{2} C_0)^{-1}$, which ensures 
    \begin{equation}\label{eq_estCh}
        1 - 2\br{1 + h} h C_0^2 > \frac{1}{2} > 0, \quad \frac{1 + h}{1 - 2\br{1 + h} h C_0^2} \leq 1 + C_1 h
    \end{equation}
    with $C_1$ given in \Cref{lem_priest}.
    Then \eqref{eq_ineq_1h} leads to 
    \begin{align}
        \abs{\Delta v(t, x)}^2 \leq\;& \frac{1 + h}{1 - 2\br{1 + h} h C_0^2} \bbr{\abs{\Delta V_h(t, x)}^2 + 2 h \abs{\Delta R(t, x)}^2}, \notag\\
        \leq\;& (1 + C_1 h) \bbr{\abs{\Delta V_h(t, x)}^2 + 2 h \abs{\Delta R(t, x)}^2}, \label{eq_estDelv2}
    \end{align}
    where the second line follows from the second inequality in \eqref{eq_estCh}.

    \subsubsection*{(ii) Bounding $\mathbb{M}_n^2\rbr{\Delta v}$ by $\mathbb{M}_{n+1}^2\rbr{\Delta v}$. }

    Multiplying both sides of \eqref{eq_estDelv2} by $P_{X_t}(x)$, setting $t = t_n$, and integrating over $x \in \R^d$ yields
    \begin{equation}\label{eq_estMn2}
        \mathbb{M}_n^2\rbr{\Delta v} \leq (1 + C_1 h) \br{\mathbb{M}_n^2\rbr{\Delta V_h} + 2 h \mathbb{M}_n^2\rbr{\Delta R}},
    \end{equation}
    where $\mathbb{M}_n^2\rbr{\cdot}$ is defined in \eqref{eq_defMtp}. 
    To estimate $\mathbb{M}_n^2\rbr{\Delta V_h}$, by comparing \eqref{eq_defXn} and the second equation in \eqref{eq_DelV}, the conditional distribution of $X_{t_n + h}$ with respect to $X_n = x$ is identical to the distribution of $X_{t_{n+1}}^{t_n, x}$, which implies that
    \begin{equation}\label{eq_estMnp1}
    \begin{aligned}
        \mathbb{M}_n^2\rbr{\Delta V_h} =\;& \int_{\R^d} \Big| \E{\Delta v(t_{n+1}, X_{n+1}) \big\vert X_n = x} \Big|^2 P_{X_n}\br{x} \di x\\
        \leq\;& \int_{\R^d} \E{\abs{\Delta v(t_{n+1}, X_{n+1})}^2 \big\vert X_n = x} P_{X_n}\br{x} \di x\\
        =\;& \int_{\R^d} \int_{\R^d} \abs{\Delta v(t_{n+1}, z)}^2 P_{X_{n+1}}\br{z \,\vert X_n = x} P_{X_n}\br{x} \di z \di x\\
        =\;& \int_{\R^d} \abs{\Delta v(t_{n+1}, z)}^2  P_{X_{n+1}}\br{z}\di z\\
        =\;& \mathbb{M}_{n+1}^2\rbr{\Delta v},
    \end{aligned}
    \end{equation}
    where the second line follows from the Jensen inequality, and the function $P_{X_{n+1}}\br{\cdot \,\vert X_n = x}$ in the third line represents the conditional PDF of $X_{n+1}$ given $X_n = x$.
    Inserting \eqref{eq_estMnp1} into \eqref{eq_estMn2}, we obtain 
    \begin{equation}\label{eq_estMn2DelV}
        \mathbb{M}_n^2\rbr{\Delta v} \leq (1 + C_1 h) \br{\mathbb{M}_{n+1}^2\rbr{\Delta v} + 2 h \mathbb{M}_n^2\rbr{\Delta R}}.
    \end{equation}

    \subsubsection*{(iii) Estimate of $\mathbb{M}_n^2\rbr{\Delta v}$. }

    Let $0 \leq k \leq N-1$, and summary \eqref{eq_estMn2DelV} over $n = k, k+1, \cdots, N-1$, leading to
    \begin{equation*}
        \sum_{n=k}^{N-1} \mathbb{M}_n^2\rbr{\Delta v} \leq (1 + C_1 h) \br{\sum_{n=k+1}^{N} \mathbb{M}_{n}^2\rbr{\Delta v} + 2 h \sum_{n=k}^{N-1} \mathbb{M}_n^2\rbr{\Delta R}}.    
    \end{equation*}
    Canceling $\sum_{n=k+1}^{N-1} \mathbb{M}_n^2\rbr{\Delta v}$ on both sides, we obtain
    \begin{align}
        \mathbb{M}_k^2\rbr{\Delta v} \leq\;& C_1 h \sum_{n=k+1}^{N} \mathbb{M}_{n}^2\rbr{\Delta v} + \mathbb{M}_{N}^2\rbr{\Delta v} + 2 (1 + C_1 h) h \sum_{n=0}^{N-1} \mathbb{M}_n^2\rbr{\Delta R}
    \end{align}
    Applying the backward discrete Gronwall
    inequality \cite[Lemma 3]{zhao2010stable} to the preceding inequality, we obtain
    \begin{equation}
        \mathbb{M}_k^2\rbr{\Delta v} \leq \exp\bbr{C_1 T} \bbr{(1 + C_1 h)\mathbb{M}_{N}^2\rbr{\Delta v} + 2 (1 + C_1 h) h \sum_{n=0}^{N-1} \mathbb{M}_n^2\rbr{\Delta R}}.
    \end{equation}
    As the right-hand side is independent of $k$, \eqref{eq_estMn2Delv} follows.
\end{proof}

Combining \Cref{thm_consist} and \Cref{lem_priest}, we can obtain the following convergence result of the formulation \eqref{eq_ER0}.

\begin{theorem}\label{thm_convergence}
    Let \Cref{assum_lipf,assum_linearDh} hold, and $0 < h < \min\bbr{1, (2\sqrt{2} C_0)^{-1}}$ with $C_0$ given in \eqref{eq_lipf}. 
    Let $v$ be the solution to \eqref{eq_pde} with regularity $v \in C_b^{2, 4}$ on $[0, T) \times \R^d$, and let $v_{\theta}$ be a neural network approximation of $v$. 
    Then,
    \begin{equation}\label{eq_converge2}
        \max_{0 \leq n\leq N-1} \mathbb{M}_n^2\rbr{v - v_{\theta}} \leq 2 C_2 \exp\br{C_1 T} \bbr{\mathbb{M}_{N}^2\rbr{v - v_{\theta}} + L^2(v_{\theta}) + T S^2 h^2},
    \end{equation}
    where $\mathbb{M}_n^2\rbr{\cdot}$ is defined in \eqref{eq_defMtp}; $S$ is a constant given in \Cref{thm_consist}; $C_1$ and $C_2$ are constants from \Cref{lem_priest}; and $L^2(v_{\theta})$ is the mean square error of $v_{\theta}$ with respect to \eqref{eq_ER0}, i.e.,
    \begin{equation}\label{eq_defL2v}
        L^2(v_{\theta}) := \frac{T}{N}\sum_{n=0}^{N-1} \int_{\R^d} \abs{\E{R(t_n, x, \xi; v_{\theta})}}^2 P_{X_{n}}\br{x} \di x. 
    \end{equation}
\end{theorem}

\begin{proof}

    By applying \Cref{lem_priest} with $v_1 = v$ and $v_2 = v_{\theta}$, we obtain 
    \begin{equation}\label{eq_converge}
        \max_{0 \leq n\leq N-1} \mathbb{M}_n^2\rbr{v - v_{\theta}} \leq C_2 \exp\br{C_1 T} \bbr{\mathbb{M}_{N}^2\rbr{v - v_{\theta}} + 2 L^2(v) + 2 L^2(v_{\theta})},
    \end{equation}
    where the term $L^2(v) + L^2(v_{\theta})$ arises from \eqref{eq_defMtp} and the second term in \eqref{eq_defRi}. 
    To estimate $L^2(v)$, we substitute \eqref{eq_pde} into \eqref{eq_defR} to eliminate the term $f(t, x, v(t, x))$, yielding
    \begin{equation}\label{eq_ERtoDh}
        \E{R(t, x, \xi; v)} = \E{\frac{v(t + h, x + \xi_h) - v(t, x)}{h}} - \mathcal{D} v(t, x) = \mathcal{D}_h v(t, x) - \mathcal{D} v(t, x),
    \end{equation}
    where $\mathcal{D}_h$ is given by \eqref{eq_rdo}. 
    Applying \Cref{thm_consist} to estimate the right-side of \eqref{eq_ERtoDh}, we have
    \begin{equation*}
        \sup_{(t, x) \in [0, T-h] \times \R^d} \abs{\E{R(t, x, \xi; v)}} \leq S h
    \end{equation*}
    with $S$ a constant given in \Cref{thm_consist}. 
    Inserting the above inequality into \eqref{eq_defL2v}, we obtain $L^2(v) \leq S^2 h^2$.
    Inserting this estimate into \eqref{eq_converge}, we obtain the desired result.

\end{proof}

We have the following discussion on the three error terms on the right-side of \eqref{eq_converge2}:

\begin{itemize}
    \item The first term $\mathbb{M}_{N}^2\rbr{v - v_{\theta}}$ represents the error introduced from the terminal condition at $t = T$, which can be eliminated by properly designing the neural network $v_{\theta}$; see \eqref{eq_netv}.

    \item The second term $L^2(v_{\theta})$, defined by \eqref{eq_defL2v}, represents the mean squared residual of $v_{\theta}$ with respect to the formulation \eqref{eq_ER0}, weighted by $P_{X_{n}}\br{x}$. 
    This error can be effectively reduced by adversarially training the neural network $v_{\theta}$ according to \eqref{eq_minmax}. 

    \item The third term $T S^2 h^2$ corresponds to the truncation error arising from the random difference approximation~\eqref{eq_rdo}.
    This result indicates that our method achieves first-order accuracy in time.
    By comparison, related works such as \cite{weinan2017deep,han2018solving,raissi2018forwardbackward,hure2020deep,Zhou2021Actor,Zhang2022FBSDE} are limited by the strong convergence order of the Euler-Maruyama scheme for SDEs, which is $1/2$, as analyzed in \cite{han2018convergence,hure2020deep,germain2022Approximation} and verified numerically in \cite{Zhang2022FBSDE}.
\end{itemize}

