\begin{restatable}{proposition}{xmonotone}\label{prop:xmonotone}
%\begin{proposition}
%\label{prop:xmonotone}
For $i\in\{-t,\ldots, k\}$, $\pi^u_i$ and $\pi^{\ell}_i$ are $x$-monotone.
\end{restatable}
%\end{proposition}
\begin{proof}
This follows directly by construction since at each step we augment the path by adding to it, the left-adjacent neighbor to the current vertex of the path.
\end{proof}


The graph $G$ constructed by Algorithm \ref{alg:prim} do not cross. 
We say that two paths $\pi_1$ and
$\pi_2$ in $G$ \emph{cross} if there is an $x$-coordinate at which $\pi_1$
lies above $\pi_2$, and an $x$-coordinate at which $\pi_2$ lies above $\pi_1$.

\begin{restatable}{proposition}{obscor}\label{obs:cor}

%\begin{proposition}
%\label{obs:cor}
For $i\in\{-t,\ldots, k\}$, $\pi_i^l$ does not lie above $\pi^u_i$, and
$\pi^{\ell}_i$ and $\pi^u_i$ do not cross.
%\end{proposition}
\end{restatable}
\begin{proof}
Let $\pi^u_i=(q_0, q_1,\ldots, q_r)$ and $\pi^{\ell}_i=(q'_0,\ldots, q'_s)$, 
where $q_0=q'_0=p_i$. Since $q_1$ is the left-adjacent of $p_i$ in $\Slab(R,p)$
with highest $y$-coordinate and $q'_1$ is the left-adjacent point of $p_i$
with lowest $y$-coordinate, $y(q'_1)\le y(q_1)$. Thus, $\pi^{\ell}_i$ does not
lie above $\pi^u_i$ at $x(p_i)$. If at some $x$-coordinate $x'$,
$\pi^{\ell}_i$ lies above $\pi^{u}_i$, then the paths must have crossed to the right of $x'$.

Let $q_i=q'_j=q$ be a point of $P$ common to $\pi^u_i$ and $\pi^{\ell}_i$ lying
to the left of $p_i$. Again, since 
$q_{i+1}=\arg\max\{y(q''): q''\in\Slab(R,p)\cap P, x(q'')<x(q), \{q,q''\}\in E(G) \}$,
and $q'_{j+1} = \arg\min\{y(q''): q''\in\Slab(R,p)\cap P, x(q'')<x(q), \{q,q''\}\in E(G) \}$,
it follows that $y(q'_{j+1})\le y(q_{i+1})$. Hence, the paths do not cross, and since
$\pi^{\ell}_i$ does not lie above $\pi^u_i$ at $x(p_i)$, it does not do so at any $x$-coordinate
to the left of $p_i$ either.
%\ambar{The proof does not preclude $q'' = q$ (does it?). So then I do not understand what does ``the paths do not not cross'' mean.}\rajiv{added a definition above the lemma.}
%\ambar{Followup to RR: The proof now shows that $y(q'')\le y(q')$ when the paths meet. This does not seem to preclude the lower path from continuing upwards, and the upper from continuing downwards (of course this doesn't happen).}
\end{proof}


Recall that the left-neighbor of a point $q$ in a set $P'$ is the
point $p'=\argmax_{p''\in P'} x(p'')<x(q)$. The right-neighbor is
defined similarly. Note that the left and right neighbors are defined
geometrically, and they may not be adjacent to $q$ in the graph $G$.
For a point $q\in P$ and $i\in\{-t,\ldots, k\}$, 
we let $r_0$ and $r_1$ denote respectively,
the left- and right-neighbors of $q$ on $\pi^u_i$. 
Similarly, we let $r'_0$ and
$r'_1$ denote respectively, the left- and right-neighbors of $q$ on $\pi^{\ell}_i$.

\begin{restatable}{proposition}{below}\label{prop:below}
%\begin{proposition}
%\label{prop:below}
For $i\in\{-t,\ldots, k\}$ and $q\in P$, if $q$ lies above $\pi^u_i$, then 
$y(q)>\max\{y(r_0), y(r_1)\}$. 
Similarly, if $q$ lies below $\pi^{\ell}_i$, then
$y(q)<\min\{y(r'_0),y(r'_1)\}$.
%\end{proposition} 
\end{restatable}
\begin{proof}
We assume $q$ lies above $\pi^u_i$. The other case 
follows by an analogous argument. 
By Proposition \ref{prop:xmonotone}, since $\pi^u_i$
is $x$-monotone, it follows that $r_0$ and $r_1$ are
consecutive along $\pi^u_i$, and thus, $r_0r_1$ is a
valid Delaunay edge in $G$. 
If either $y(r_0)>y(q)>y(r_1)$, or $y(r_0)<y(q)<y(r_1)$, then
it contradicts the fact that $r_0r_1$ is Delaunay. Hence,
$y(q)>\max\{y(r_0),y(r_1)\}$ as $q$ lies above $\pi^u_i$.
%\karamjeet{Proof does not require this argument. $q$ may be anywhere above the upper path; maybe outside $R$.
%In the statement, $r_0,r_1$ are the left, right neighbours of $q$ geometrically, and not in the graph $G$.}
\end{proof}

We now show that the corridors constructed
satisfy the required conditions. The first condition below, follows directly from construction.

\begin{restatable}{lemma}{corridorun}\label{lem:corridor1}

%\begin{lemma}
%\label{lem:corridor1}
For $i\in\{-t,\ldots, k\}$, 
$\corridor_i\subseteq\Slab(R,p)$. \label{cond:c2}
%\end{lemma}
\end{restatable}

\begin{proof}
Follows directly by construction.
\end{proof}

Next, we show that for each strip, its corresponding corridor contains all its points,
that is all points in $P\cap \Strip_i$ are contained between the upper and lower
paths of $\corridor_i$.
Before we do that, we need the following two technical statements.


\begin{restatable}{proposition}{rightEdge}\label{prop:rightEdge}
%\begin{proposition}
%\label{prop:rightEdge}
Let $q,q'\in P$, with $x(q)<x(q')$ s.t. $qq'$ is Delaunay. If $qq'\not\in E(G)$,
then either $(i)$ $h(qq')$ pierces a rectangle,
or crosses an existing edge, or $(ii)$ $v(qq')$ pierces a rectangle. In particular, $v(qq')$ does not cross an existing edge.
%\end{proposition}
\end{restatable}
\begin{proof}
The points in $P$ are processed by Algorithm \ref{alg:prim} in increasing order of 
their $x$-coordinates, and when a point is being processed, 
we add edges of type \{$\upleft[0.2]$, $\leftup[0.2]\}$ to points to its left.
Therefore, while processing $q'$,
no edge from points of $P$ to the right of $q'$ have been added. Hence,
$v(qq')$ does cross an existing edge.
\end{proof}

\begin{restatable}{lemma}{vert}\label{lem:vert}

%\begin{lemma}
%\label{lem:vert}
For $i\in\{-t,\ldots, k\}$, 
let $q\in\Slab(R,p)\cap P$ s.t. $q$ lies above $\pi^u_i$. Let $q_1$ be the
right-neighbor of $q$ on $\pi^u_i$. If $qq_1$ is Delaunay but not valid, then
$v(qq_1)$ pierces a rectangle. In particular, $h(qq_1)$ does not pierce a rectangle
or cross an edge.
Similarly, let $q'\in \Slab(R,p)\cap P$ s.t. 
$q'$ lies below $\pi^{\ell}_i$,
$q'_1$ is the right-neighbor of $q'$ on $\pi^{\ell}_i$.
If $q'q'_1$ is Delaunay but not valid, then 
$v(q'q'_1)$ pierces a rectangle. In particular $h(q'q'_1)$ does not pierce a rectangle
or cross an edge.
%\end{lemma}
\end{restatable}
\begin{proof}
We prove the case when $q$ lies above $\pi^u_{i}$. The other case follows
by an analogous argument.
Since $qq_1$ is not valid, either the horizontal
segment of $qq_1$ pierces a rectangle, or crosses an existing edge; or
$v(qq_1)$ pierces a rectangle since by Proposition \ref{prop:rightEdge},
$v(qq_1)$ does not cross an existing edge.

Let $q_0$ be left-adjacent to $q_1$ on $\pi^{u}_i$.
By Proposition \ref{prop:below}, $y(q)>\max\{y(q_0),y(q_1)\}$.
Hence $qq_1$ is of type $\upleft[0.2]$.
Suppose $h(qq_1)$ pierces a rectangle or crosses
an edge of type $\upleft[0.2]$. Then, there is a point $z$ that lies below
the $h(qq_1)$. But, $z$ cannot lie below the $h(q_0q_1)$, 
as that contradicts the fact that $q_0q_1$ is valid.
Hence, $z$ lies above $h(q_0q_1)$. This implies that
$z$ lies either in $R(q_0q_1)$ (if $y(q_0)<y(q_1)$), or $z$ lies in $R(qq_1)$. 
If $z\in R(q_0q_1)$, it contradicts the fact that $q_0q_1$ is Delaunay. Also, $z\not\in R(qq_1)$, as $qq_1$ is Delaunay by assumption.
Therefore, $h(qq_1)$ does not pierce a rectangle,
or crosses an edge of type $\upleft[0.2]$. If 
$h(qq_1)$ crossed an edge $e$ of type $\leftup[0.2]$, then either $qq_1$ is not
Delaunay, violating our assumption, or $e$ is not Delaunay, a contradiction.
\end{proof}

