\begin{restatable}{lemma}{corridordeux}\label{lem:corridor2}
%\begin{lemma}
%\label{lem:corridor2}
For $i\in\{-t,\ldots, k\}$, $P_i\subseteq \corridor_i$, where $P_i = P\cap\Strip_i$.
%\end{lemma}
\end{restatable}
\begin{proof}
Suppose $P_i\setminus\corridor_i\neq\emptyset$. 
By Proposition \ref{obs:cor}, any such point either lies above $\pi^u_i$ or
below $\pi^{\ell}_i$. We assume the former. The latter
follows by an analogous argument.
%Instead of showing that $P_i\subseteq\corridor_i$, we show
%something stronger. 
Let
$P'_i = \{q\in \Slab(R,p): y(q)<y_+(\Strip_i)\mbox{ and } q \mbox{ lies above } \pi^u_i\}
$. It suffices to show that $P'_i=\emptyset$. For the sake of contradiction, suppose
$P'_i\neq\emptyset$.

We impose the following partial order on $P_i$: for $a,a'\in P_i$, $a\prec a'\Leftrightarrow
x(a)>x(a')\,\wedge\,y(a)<y(a')$. Let $q$ be a minimal element in
$P_i'$ according to $\prec$. In the following, when we refer to a minimal element, we impicitly
assume this partial order.

We show that there is a valid Delaunay edge between $q$ and a point $q'$ on $\pi^u_i$.
By assumption, $q$ lies above $\pi^u_i$. Let $q_0$ and $q_1$ denote, respectively,
the left- and right-neighbors of $q$ on $\pi^u_i$.

%contradicting the construction of $\pi^u_i$.

Since $q$ is minimal in $P'_i$, $qq_1$ is Delaunay. By Proposition \ref{prop:below},
it follows that $y(q)>y(q_0)$ and $y(q)>y(q_1)$. 
Since $q$ is not left-adjacent to $q_1$ on $\pi^u_i$, it implies $qq_1$ is not valid.

Since $qq_1$ is Delaunay but not valid, by Lemma \ref{lem:vert},
$v(qq_1)$ pierces a rectangle. Let $\mathcal{R}'$ denote the set of rectangles pierced by $qq_1$. 
Suppose $\exists R'\in\mathcal{R'}$ s.t. $R'[x(q_1),\min\{x(p), x_+(R')\}]\cap P=\emptyset$.
Then, we call $R'$ a \emph{bad} rectangle. Otherwise, we say that $R'$ is \emph{good}.
Now we split the proof into two cases depending on whether $\mathcal{R}'$ contains a bad
rectangle or not. In the two cases below, we use Proposition \ref{prop:xmonotone} 
that $\pi^u_i$ is $x$-monotone. 


\smallskip\noindent
{\bf Case 1. $\mathcal{R'}$ contains a bad rectangle.}
Let $R'\in\mathcal{R}'$ be a bad rectangle. 
First, observe that $x_+(R')>x(p)$ as otherwise, 
$R'$ is not pierced by $v(qq_1)$.
Now, suppose $y(p_i)>y_+(R')$, where $p_i$ is the rightmost point in $\Strip_i$. 
We have that $x(q_1)<x(p_i)$, both $p_i$ and $q_1$ lie on $\pi^u_i$ and, 
$\pi^u_i$ is $x$-monotone. But, this implies $\pi^u_i$ pierces $R'$. But this is impossible as by construction
$\pi^u_i$ consists of valid Delaunay edges. Hence, since $R'$ is bad, we can assume that $y(p_i)<y_-(R')$. 
But the definition of the upper barrier implies that 
$y_+(R')\ge y_+(\ub(p_i))$. Since $v(qq_1)$ pierces
$R'$, it implies $y(q)>y_+(R')$, and hence $y(q)>y_+(\ub(p_i))$.
But, this contradicts the assumption that $q\in\Strip_i$, since
by Proposition \ref{prop:strip}, $y_+(\ub(p_i))\ge y_+(\Strip_i)$
and hence $y(q)>y_+(\Strip_i)$.

\smallskip\noindent
{\bf Case 2. All rectangles in $\mathcal{R}'$ are good.} 
Let $R_1=\arg\max\{y_-(R'):R'\in\mathcal{R}'\}$.
Let $q_2$ be the leftmost point in $R_1$ s.t. $x(q_2)>x(q_1)$.
Since $q_2$ lies to the right, and below
$q$, $q_2\prec q$. Since $q$ is a minimal element in $P'_i$, 
it implies that $q_2$ lies on or below $\pi^u_i$. We claim that
$q_2$ cannot lie below $\pi^u_i$. Suppose it did. Let $q_2'$ be the left-neighbor
of $q_2$ on $\pi^u_i$. Then, $x(q_2')<x(q_2)$. 
Since $q_2$ is the leftmost point of $R_1$ to the
right of $v(qq_1)$, then either $y(q'_2)<y_-(R_1)$, or $y(q'_2)>y_+(R_1)$. However,
in either case, we obtain that $\pi^u_i$ must cross $R_1$ between $q_2$ and $q_1$,
which implies that $\pi^u_i$ pierces $R_1$, as $\pi^u_i$ is $x$-monotone, and
the edges in $\pi^u_i$ are of the form $\{\upleft[0.2],\leftup[0.2]\}$, a contradiction.

Since $q$ is minimal, $qq_2$ is Delaunay.
By Lemma \ref{lem:vert}, the only reason
$qq_2$ is not valid is that $v(qq_2)$ pierces a rectangle. But, any such rectangle
$R_2$
is also pierced by $v(qq_1)$, as $qq_2$ is Delaunay. But, this implies
$y_-(R_2)>y_-(R_1)$, contradicting the choice of $R_1$. Therefore, $qq_2$ is a valid
Delaunay edge. Now, the only reason that $q$ is not the left-adjacent point
of $q_2$ on $\pi^u_i$ then, is that $q'_2$, the left-adjacent point of $q_2$ on $\pi^u_i$
lies in $\Slab(R,p)$, but above $q$, 
i.e., $y(q'_2)>y(q)$, as the construction of $\pi^u_i$
dictates that we choose the left-adjacent point with highest $y$-coordinate
that lies in $\Slab(R,p)$. Showing that this leads to a contradiction completes
the proof.

So suppose $y(q'_2)>y(q)$, then $y(q'_2)>y_+(R_1)$. Further, 
by Proposition \ref{prop:deledges}, $x(q'_2)>x(q)$. Again this implies
the $x$-monotone curve $\pi^u_i$ cannot contain both $q'_2$ and $q_1$
without piercing $R_1$. Hence, $y(q'_2)<y_-(R_1)<y(q)$, but this contradicts
the choice of $q'_2$ as the left-adjacent point of $q_2$ on $\pi^u_i$ since $qq_2$ is a valid Delaunay edge with $y(q'_2)<y(q_2)<y(q)$.
See Figure \ref{fig:cases} for the different cases in this proof.
\end{proof}

The key property of a corridor is that if the upper or lower path of a corridor crosses a rectangle $R'$,
then there must be a point of $R'\cap P$ that lies on that path of the corridor. Using this, we can show
that any point in the strip has an adjacent point to its right in $G$ that lies in the corridor.
This implies that every point in a strip has a path to the rightmost point in the strip
that lies entirely in its corresponding corridor.

\begin{lemma}
\label{lem:corridor3}
For each $q\in \corridor_i$, there is a path $\pi(q,p_i)$ between $q$ and $p_i$ that lies in $\corridor_i$, 
where $p_i\in P_i$ is the rightmost point in $\Strip_i$.
\end{lemma}
\begin{proof}
If $q$ lies on the upper path $\pi^u_i$ or the lower path $\pi^{\ell}_i$
defining $\corridor_i$, the lemma is immediate. So we can assume by Proposition \ref{obs:cor} that
$q$ lies below $\pi^u_i$, and above $\pi^{\ell}_i$. Suppose the lemma is false. 
Let $q$ be the rightmost point of $\corridor_i$ that does not have a path to $p_i$ lying in $\corridor_i$.
To arrive at a contradiction, it is enough to show that $q$ is adjacent to a point $q'\in \corridor_i$ that
lies to the right of $q$. 

Starting from $\ell_q$, the vertical line through $q$, sweep to the right until the first point $r$ that lies on both $\pi^{u}_i$ and
$\pi^{\ell}_i$. Such a point exists since $p_i$ lies on both $\pi^{u}_i$ and $\pi^{\ell}_i$.
Let $Q'_i$ denote the set of points in $\corridor_i$ whose $x$-coordinates lie between $x(q)$ and $x(r)$.
This set is non-empty as it contains $q$ and $r$. 
Hence, either $Q^+_i = \{q'\in Q'_i: y(q')>y(q)\}\neq\emptyset$, or $Q^-_i=\{q'\in Q'_i:y(q')<y(q)\}\neq\emptyset$.
If both are non-empty, let $Q_i$ denote the set that contains a point with smallest $x$-coordinate. Otherwise,
we let $Q_i$ denote the unique non-empty set. Assume $Q_i=Q^+_i$. An analgous argument holds when $Q_i=Q^-_i$.

Define a partial order on $Q_i$, where for $a,b\in Q_i$, $a\prec b\Leftrightarrow x(a)<x(b) \mbox{ and } y(a)<y(b)$.
Let $Q^{\min}_i=(q_1,\ldots, q_t)$ denote the sequence of minimal elements of $Q_i$ ordered linearly such that $y(q_k)>y(q_j)$ for $k < j$. It follows that $x(q_k)<x(q_j)$ for $k<j$. Observe that $qq_i$ is Delaunay for $i=1,\ldots, t$ by the minimality of $q_i$.
Our goal is to show that $qq_i$ is a valid Delaunay edge for some $i\in\{1,\ldots, t\}$.
We start with the following claim that $v(qq_t)$ and $h(qq_1)$ do not pierce a rectangle in $\mathcal{R}$, 
or cross an edge of $G$. 

\begin{claim}
\label{claim:qqt}
$h(qq_1)$ does not pierce a rectangle in $\mathcal{R}$ or cross an edge of $G$, and
$v(qq_t)$ does not pierce a rectangle in $\mathcal{R}$ or cross an edge of $G$.
\end{claim}
\begin{proof}
%We prove the result for $v(qq_t)$.
%An analogous argument shows that $h(qq_1)$ does not pierce a rectangle or cross an edge of
%$G$. 
Suppose $h(qq_1)$ pierced a rectangle $R'$. Since $\pi^u_i$ consists of valid Delaunay
edges, and the choice of $Q_i$, $R'$ contains a point $a$ that lies in $\corridor_i$. Since
$h(qq_1)$ pierces $R'$, $x(q)<x(a)<x(q_1)$. If $y(a)<y(q_1)$, then it contradicts the fact that
$q_1$ is minimal, and if $y(a)>y(q_1)$, it contradicts the fact that $q_1$ is the minimal
element with highest $y$-coordinate. A similar argument shows that $h(qq_1)$ does not
cross an edge of $G$.

If $v(qq_t)$ pierced a rectangle $R'\in\mathcal{R}$,
then $R'$ has a point to the right of $v(qq_t)$. Further, by Proposition \ref{prop:xmonotone},
$\pi^u_i$ and $\pi^{\ell}_i$ are $x$-monotone paths and by construction, they consist
of valid Delaunay edges
meeting at $r$. 
If $r=q_t$ and $v(qq_t)$ pierced a rectangle, since $qq_t$ is Delaunay, and 
the edges are of type $\{\upleft[0.2],\leftup[0.2]\}$, it implies that
the left-adjacent point of $r$ on $\pi^u_{i}$ or $\pi^{\ell}_i$ is not a valid Delaunay edge. Hence,
we can assume $q_t\neq r$. Again, since the edges of $\pi^{u}_i$ and $\pi^{\ell}_i$ are valid Delaunay
edges, 
it implies that $R'$ has a point $a$ s.t. $x(q_t)<x(a)\le x(r)$, and $a$ lies in $\corridor_i$. 
Since $v(qq_t)$ pierces $R'$,
$y(a)<y(q_t)$. But this contradicts the fact that $q_t$ is the point in $Q^{\min}_i$ with the smallest $y$-coordinate.
Therefore, $v(qq_t)$ can not pierce any rectangle.
Since $qq_t$ is Delaunay, by Proposition \ref{prop:rightEdge}, $v(qq_t)$ does not cross an edge of $G$.
\end{proof}

We now define a point $x_1$ on the $x$-axis and a point $y_1$ on the $y$-axis as follows:
%
\begin{align*}
x_1 &= \min\left\{\{x_+(R'):R'\mbox{ pierced by } h(qq_t)\},\{v(e): e\mbox{ crosses } h(qq_t)\}\right\}\\
y_1 &= \min\left\{\{y_+(R'):R'\mbox{ pierced by } v(qq_1)\},\{h(e): e\mbox{ crosses } v(qq_1)\}\right\}
\end{align*}
%
By Claim \ref{claim:qqt} and the assumption that $qq_t$ and $qq_1$ are not valid edges, it follows that
$x_1$ and $y_1$ exist.  
We argue when $x_1$ and $y_1$ correspond to $x_+(R')$ and
$y_+(R'')$, respectively for rectangles $R',R''\in\mathcal{R}$. 
If they were instead defined by the vertical/horizontal side of edges, the arguments are similar.

