\begin{center}
\includegraphics[width=2.5in]{goodedge}
\caption{The edge $qq'$ is a valid Delaunay edge.}
\label{fig:godeedge}
\end{center}
\end{figure}

Observe that $x_-(R'')<x(q)$, while $x_-(R')>x(q)$, and $y_-(R'')>y(q)$ and $y_-(R')<y(q)$.
Now, from the fact that the rectangles are non-piercing, it implies that 
either $x_+(R'')<x_1$ or $y_+(R')<y_1$.
Suppose wlog, the former is true.
Since $R'$ is pierced by $h(qq_t)$ and $\pi^u_i$ consists of valid Delaunay edges, 
there are points in $R'$ that lie in $\corridor_i$, and these
points lie below $y_1$. 

Let $z$ denote the intersection of the vertical line through $x_1$ and the hoizontal line through
$y_1$. By the argument above, the rectangle with diagonal $qz$ contains points of $P$, and
hence a point $q'\in Q^{\min}_i$. We claim that $qq'$ is a valid Delaunay edge. To see this, 
note that $h(qq')$ does not pierce a rectangle in $\mathcal{R}$ as such a rectangle contradicts
the definition of $x_1$. If $v(qq')$ pierced a rectangle, such a rectangle $\tilde{R}$ must have
$y_+(\tilde{R})<y_1$, as $qq'$ is Delaunay. This contradicts the choice of $y_1$. 
Therefore, $qq'$ is a valid Delaunay edge.
\end{proof}


The lemma below follows the description in the proof strategy at the start of this section.


\begin{restatable}{lemma}{monpathslab}\label{lem:monpathslab}

%\begin{lemma}
%label{lem:monpathslab}
For a rectangle $R$ and point $p\in R$, after Algorithm~\ref{alg:prim} has processed point $p$,
the points in $\Slab(R,p)$ induce a connected subgraph, all of whose edges lie in $\Slab(R,p)$.
%\end{lemma}
\end{restatable}
\begin{proof}
Let $G[\Slab(R,p)]$ denote the induced subgraph of $G$ on the points in $\Slab(R,p)$.
By Condition (ii) of Lemma \ref{lem:strips}, 
since $\Slab(R,p)\subseteq \cup_{i=-t}^k \Strip_i$, each point in $P\cap\Slab(R,p)$ is contained in $\cup_{i=-t}^k\Strip_i$.
If the statement of the lemma does not hold, consider an extremal strip, i.e., the smallest positive index, or 
largest negative index of a strip such that it contains a point $q$ that does
not lie in the connected component of $G[\Slab(R,p)]$ containing $p$.
Assume without loss of generality that $i \ge 0$. An analogous argument holds
if $i < 0$.
By Lemma \ref{lem:corridor2}, $q\in\corridor_i$, and by Lemma \ref{lem:corridor3}, $q$ has a path $\pi_1$ to $p_i$, the rightmost point in 
$\corridor_i$ that lies entirely in $\corridor_i$. 
By Condition (ii) of Lemma \ref{lem:strips}, there is a point
$q'\in \Strip_i\cap\Strip_{i-1}\cap P$. By Lemma \ref{lem:corridor2},
$q'\in\corridor_i$, and by Lemma \ref{lem:corridor3}, there is a path
$\pi_2$ between $q'$ and $p_i$. Since $q'\in\Strip_{i-1}$, $q'$ lies in the
same connected component as $p$ in $G[\Slab(R,p)]$, and hence there is a path $\pi'$ from $q'$ to $p$ in $G[\Slab(R,p)]$. Concatenating $\pi_1, \pi_2$
and $\pi'$ we obtain a path $\pi$ from $q$ to $p$ that lies in $\Slab(R,p)$.
\end{proof}


We now argue that if $p$ is the rightmost point in a rectangle $R$, then $\Piece(R,p)$ consists of a single slab.

\begin{restatable}{lemma}{lastpt}\label{lem:lastpt}

%\begin{lemma}
%\label{lem:lastpt}
If $p$ is the last point in $R$ according to the x-coordinates of the points, then $\Piece(R,p)$ consists of a single slab.
%\end{lemma}
\end{restatable}
\begin{proof}
Assume for the sake of contradiction that $\upb(R,p)$ exists. By definition of $\upb(R,p)$,
there are two points $a,b\in \upb(R,p)$, such that $x(a) < x_-(R) < x(p) < x_+(R) < x(b)$, as $p$ is the last point in $R$.
But this implies $\upb(R,p)$ is pierced by $R$, a contradiction. Therefore, $\upb(R,p)$ does not exist. Similarly, $\lpb(R,p)$ does not exist,
and hence $\Piece(R,p)$ consists of a single slab.
\end{proof}

\begin{theorem}
\label{thm:mainthm}
Algorithm~\ref{alg:prim} constructs a planar support.
\end{theorem}
\begin{proof}
By construction, the edges of the graph $G$ constructed by Algorithm~\ref{alg:prim} are valid Delaunay edges of type $\{\upleft[0.2],\leftup[0.2]\}$. To obtain a plane embedding, we replace each edge $e=\{p,q\}$ by the diagonal of the
rectangle $R(pq)$ joining $p$ and $q$. We call these the \emph{diagonal edges}. It is clear that no diagonal edge
pierces a rectangle. If two diagonal edges cross, then it is easy to check that either the corresponding edges cross, 
or they are not Delaunay. 
For a rectangle $R\in\mathcal{R}$, let $p$ be the last point in $R$.
Lemma~\ref{lem:lastpt} implies that there is only one slab, namely $R$, and 
Lemma~\ref{lem:monpathslab} implies $\textsc{Slab}(R,p)$ is connected. Since $R$ was arbitrary, this implies
Algorithm~\ref{alg:prim} constructs a support. 
\end{proof}

