   \begin{definition}[\cite{chui1992}]\label{semi-orthogonal wavelet }
       A wavelet $\psi$  in $L^2 (\mathbb{R})$ is called a semi-orthogonal wavelet  if the Riesz basis $\left\{\w_{j,\2}\right\}$ it generates satisfies 
       \begin{equation*}\label{P3_W4}
           \langle \w_{j,\2}, \w_{l,m} \rangle = 0, \;\;\; j \neq l, \; j,\2, l, m \in \mathbb{Z}.
       \end{equation*}
   \end{definition}
   \section{ The Semi-orthogonal Tribonacci Wavelet} \label{TW}
The mother wavelet generates a family of functions through scaling  and shifting of itself, and these are referred to as wavelets. The discrete wavelet  family is presented in the following manner:  
 \begin{equation*}\label{P3_E7}
     \w _{\2, \3} (\z) =  |a_{0}| ^{\frac{\2}{2}} ~ \w ( a_{0} ^{\2} ~\z - \3 ~b_{0}),
 \end{equation*}
 in which $ \w _{\2, \3} (\z)$  serves as a wavelet basis in  $ L^{2} (\mathbb{R})$.

The SOTW are defined in the following manner:
 \begin{equation}\label{eq2_P3}
\w_{\3, m}(\z)=
    \begin{cases}
         2 ^{\frac{\2 - 1}{ 2}} \hat{\e}_{\g} (2^{\2 -1 } \z  - \3 +1 ) , & \text{if }  \frac{\3 -1 }{ 2^{\2 -1 }}  \leq \z < \frac{\3}{ 2^{\2 -1}} ,\\
        0, & \text{otherwise}, \\
    \end{cases}
\end{equation}
with
\begin{equation*}\label{P3_E8}
    \hat{\e}_{\g} ( \z ) =  \frac{1}{\sqrt{\Z_{\g}}} \e _{\g}(\z),
\end{equation*}
and 
\begin{equation*}\label{P3_E9}
    \Z _{\g} = \int_{0}^{1} \e _{\g}^{2} (\z) \,d\z.
\end{equation*}
Here, $ \frac{1}{\sqrt{\Z_{\g}}}$ is a  normalization factor, $\g = 0, 1, 2, \cdots, M - 1$ represents the order of the tribonacci polynomial $T_{\g} (\z)$,  $\2 = 1, 2, 3, \cdots$, and $\3 = 1, 2, 3, \cdots, 2^{\2 - 1}$. In this context, $\2$ signifies the resolution level, respectively. 

