\subsection{Function Approximation using SOTW}\label{FAUTW}
An arbitrary function  $\4(\z)  \in  L^{2} [0, 1] $ can be approximately expanded in the following way:
   \begin{eqnarray}
&& \label{eq4_P3}
      \4 (\z) \approx \sum_{\3 = 1}^{2^{\2 - 1}} \sum_{\g = 0}^{M - 1} \h_{\3, \g} \w _{\3, \g} (\z),\\
&& \label{P31_eq4}
       \4(\z)  \approx \sum_{\3 = 1}^{2^{\2 - 1}} [ \h_{\3, 0} \w_{\3, 0}+\h_{\3, 1} \w_{\3, 1}+ \cdots+ \h_{\3, M -1 } \w_{\3, M - 1}],\\
       && \label{P31_eq5}
       \4(\z)  \approx  \h_{1, 0} \w_{1, 0}+ \cdots+ \h_{1, M -1 } \w_{1, M - 1}+\cdots+ \h_{2^{\2-1}, 0} \w_{2^{\2 - 1}, 0}+ \cdots+\h_{2^{\2 - 1}, M -1 } \w_{2^{\2 - 1}, M - 1}.
       \end{eqnarray}
        To simplify the expression, we multiply the above equation \eqref{P31_eq5} by $\w_{\3, \g}(\z)$ and integrate between $0$ to $1$, where $\3 = 1, 2, 3, 4, \cdots, 2^{\2 - 1},$ $ \;m = 0, 1, 2, 3, \cdots, M - 1,$ then we get  $ 1 \times 2^{\2 -1} M$ vectors $G$ as follows:
      \begin{eqnarray}
    && G = \left[ \4_{\3, m} \right], \;\; \3 = 1, 2, 3, 4, \cdots, 2^{\2 - 1}, \;\;m = 0, 1, 2, 3, \cdots, M - 1,\\
    && \4_{\3, m} = \int_{0}^{1} \4(\z) \w_{\3, m}(\z) \,d\z.
  \end{eqnarray}
  Now, we define the vectors  $B$ and $\w (\z)$, each of size $ (1 \times 2^{\2 -1} M)$  which are given as follows:
\begin{eqnarray}
&& \label{eq5_P3}
B= [ \h _{1, 0}, \h_{1, 1}, \cdots , \h_{1, M -1}, \h_{2,0}, \h_{2,1}, \cdots, \h_{2, M-1}, \cdots, \h_{2^{\2-1},0}, \h_{2^{\2-1},1}, \h_{2^{\2-1},2}, \cdots, \h_{2^{\2-1},M-1}], \\
   &&  \w(\z) = [ \w _{1, 0}, \w_{1, 1}, \cdots , \w_{1, M -1}, \w_{2,0}, \cdots, \w_{2, M-1}, \cdots, \w_{2^{\2-1},0}, \w_{2^{\2-1},1}, \w_{2^{\2-1},2}, \cdots, \w_{2^{\2-1},M-1}].
\end{eqnarray}
In equation, \eqref{eq4_P3}, \eqref{P31_eq4}, \eqref{P31_eq5} and  \eqref{eq5_P3}, $\h_{ \3, m}$, $\3 = 1, 2, 3, \cdots $ 
 $2^{\2 - 1}$, $m = 0,1, 2, 3, 4, \cdots, M -1$ are the SOTW  expansion coefficient of the function $\4( \z )$ in the $ n^{th} $ subinterval  $ [\frac{ \3 - 1}{ 2^{\2 - 1}} , \frac{n}{2^{\2 - 1}} ]$. Using  \eqref{eq5_P3}, the vector coefficients  $ \h_{n, m}$ can be achieved as :
 \begin{align*}
     B = G D^{-1},
 \end{align*}
 where,
 \begin{eqnarray}
  && D = \langle \w, \w \rangle =  \int_{0}^{1} \w^{T}(\z)\w(\z)  \,d\z.
  \end{eqnarray}
