\section{Methodology }\label{Method}
This section presents the methodology for computing solution of  nonlinear singular  differential equation of the different form using the semi-orthogonal tribonacci wavelet collocation method (SOTWCM) combined with quasilinearization. Quasilinearization is first used to linearize the NSBVPs. The numerical solutions are then computed using SOTW, followed by the discritization via the collocation method. Additionally, we present the convergence analysis of the SOTW.
%detailed steps to compute  the numerical solution in algorithmic form. We also present the 
\subsection{Quasilinearization}\label{Quasilinrization}
The quasilinearization approach converts a nonlinear differential equations (DE) into a series of linear DE, with the solution determined as the limit of this series. For a comprehensive discussion on quasilinearization, one may refer to the work of \cite{verma2019} and \cite{mandelzweig2001}. Quasilinearization allows for the conversion of any nonlinear ordinary differential equation of the form 
\begin{equation}\label{P3_diffeqn1}
\1''(\z) + \frac{\alpha}{\z} \1' (\z) + g (\z, \1(\z)) = 0, \;\;\;\; 0 < \z  \leq 1, 
\end{equation}
subject to one of the specified boundary conditions:
\renewcommand{\labelenumi}{\alph{enumi})}
\begin{eqnarray}
%&& \label{P3_eqn2} \1'(0)= \7_1,~ \1(1)  =   \7_2, \\
&& \label{P3_eqn3} \1(0)  =  \7_1,~ \1(1) = \7_2, \\
&& \label{P3_eqn4} \1'(0)  =  \7_3, ~ m \1(1) +n \1'(1) = \7_4,
\end{eqnarray}
%where, $\alpha(\geq 0$) is the shape factor and $ \7_1,  \7_2, \7_3, \7_4, m$ and $n$ are arbitrary constants,\eqref{P3_diffeqn1}
into a sequence of linear DE. The \((r + 1)\)th iterative approximation \(\1_{\R+1}(\z)\) to the solution of \eqref{P3_diffeqn1}, subject to boundary conditions given by \eqref{P3_eqn3}, or \eqref{P3_eqn4}, is obtained by solving the associated linear DE. This process is formalized in the following theorem.
\begin{theorem}\label{theorem1}
Consider a function \( g(\z, \1(\z)) \) that is continuous in \( \z \) and twice continuously differentiable with respect to \( \1(\z) \). Let \( \1(\z) \) be the solution to the differential equation \eqref{P3_diffeqn1}, under the specified  boundary conditions \eqref{P3_eqn3}, or \eqref{P3_eqn4}. By using the quasilinearization technique, we describe the iterative scheme for solving the differential equation  \eqref{P3_diffeqn1} with the given boundary conditions through the following set of equations:
% Applying the quasilinearization technique, the iterative scheme for solving the differential equation \eqref{P3_diffeqn1} with the given boundary conditions is described by the following set of equations:
\begin{eqnarray}
&& \label{P3_eqn5} \1''_{\R +1}(\z) + \frac{\alpha}{\z} \1'_{\R+1}(\z) = - g (\z, \1_{\R}(\z)) + (\1_{\R+1} - \1_{\R}) \left( - g_{\1}(\z, \1_{\R}(\z)) \right),~ \R = 0,1,2,\cdots, \\
%&& \label{P3_eqn6} \1'_{\R +1}(0) = \7_1, \quad \1_{\R +1}(1) = \7_2, \\
&& \label{P3_eqn7} \1_{\R +1}(0) = \7_1, \quad \1_{\R +1}(1) = \7_2, \\
&& \label{P3_eqn8} \1'_{\R +1}(0) = \7_3, \quad m \1_{\R +1}(1) + n \1_{\R +1}'(1) = \7_4,
\end{eqnarray}
where $\alpha(\geq 0)$, $ \7_1, \7_2, \7_3, \7_4, m, $ and $n$ are arbitrary constants and $g_{\1}$ represents the partial derivative of the function $g$ with respect to $\1$. %For $\R = 0$, initial 
\end{theorem}

\begin{proof}\label{P3_E13}
The proof follows directly from the Taylor series expansion. 
\end{proof}
\subsection{The SOTWQCM}\label{SOTWQCM}
As a result of the aforementioned theorem, the DE \eqref{P3_diffeqn1} is obtained in its linearized form. We then apply the SOTW  collocation method to solve the linear differential equation \eqref{P3_eqn5}, subject to the one of the boundary conditions \eqref{P3_eqn7}, or \eqref{P3_eqn8}. The second order derivative present in the DE is approximated by the SOTW  basis as follows:
% \begin{align}\label{P3_eqn9}
%    \frac{d^{(n)} \1_{\R +1} (\z)}{d\z ^{n}}   \approx  \sum_{n = 1}^{2^{\2-1}}\sum_{m = 0}^{M-1} \h_{n,m}W_{n,m}(\z),
% \end{align}
 %integrating the above equation $(n$) times from $0$ to $\z$, to get the  solution of the differential equation. We now examine the case where \( n = 2 \),
\begin{align}\label{P3_eqn10}
    \1 '' _{\R+1 }(\z)  \approx  \sum_{n = 1}^{2^{\2-1}}\sum_{m = 0}^{M-1} \h_{n,m}\w_{n,m}(\z).
\end{align}
Integrating the  above equation  \eqref{P3_eqn10} two times from $0$ to $\z$, we get the  solution of the differential equation,
 \begin{eqnarray}
 %&& \\
\label{P3_eqn11} && \1 ' _{\R+1 }(\z) \approx  \1 ' _{\R+1 }(0)+ \sum_{n = 1}^{2^{\2-1}}\sum_{m = 0}^{M-1} \h_{n,m}\int_{0}^{\z} \w_{n,m}(\z)  \, d\z
,\\
\label{P3_eqn12} &&  \1  _{\R+1 }(\z) \approx   \1  _{\R+1 }(0)+ \z \1 ' _{\R+1 }(0)+ \sum_{n = 1}^{2^{\2-1}}\sum_{m = 0}^{M-1} \h_{n,m}\int_{0}^{\z} \int_{0}^{\z}\w_{n,m}(\z) \,d\z \, d\z,\\
\label{P3_equn1} &&  \1  _{\R+1 }(\z) \approx   \1  _{\R+1 }(0)+ \z \1 ' _{\R+1 }(0)+ \sum_{n = 1}^{2^{\2-1}}\sum_{m = 0}^{M-1} \h_{n,m} \, P^{2}\w _{\3, \g} (\z),\\
\label{P3_equn2} &&  \1  _{\R+1 }(\z) \approx    C_{T}(\z)+ \sum_{n = 1}^{2^{\2-1}}\sum_{m = 0}^{M-1} \h_{n,m} \, P^{2}\w _{\3, \g} (\z),
\end{eqnarray}
where $ C_{T}(\z)$ stands for the constants of integration, $ P^{2}\w _{\3, \g} (\z)$ represents the second order integration of the $\w _{\3, \g}(\z)$.

Based on the specific nature of the problem, one of the boundary conditions \eqref{P3_eqn7}, or \eqref{P3_eqn8} is used to determine the unknowns. The equations are discretized  by replacing $ \z$ with the collocation points defined as follows:
\begin{eqnarray} \label{collocation}
    \z_{l}= \frac{2l -1}{2^{\2}M}, \;\;\; l = 1, 2, 3, \cdots, (2^{\2-1}M),
\end{eqnarray}
 and substituting them into linearized  equation \eqref{P3_eqn5}. This leads to the following linear system of $ (2^{\2-1}M)$ algebraic equation with $ (2^{\2-1}M)$ unknowns:
 \begin{equation}\label{linear_system}
\begin{aligned}
&\x_{1} (\h _{1, 0}, \h_{1, 1}, \h_{1,2}, \cdots , \h_{1, M -1}, \h_{2,0}, \h_{2,1}, \cdots, \h_{2, M-1}, \cdots, \h_{2^{\2-1},0}, \h_{2^{\2-1},1}, \h_{2^{\2-1},2}, \cdots, \h_{2^{\2-1},M-1}) = 0, \\
&\x_{2} (\h _{1, 0}, \h_{1, 1}, \h_{1,2}, \cdots , \h_{1, M -1}, \h_{2,0}, \h_{2,1}, \cdots, \h_{2, M-1}, \cdots, \h_{2^{\2-1},0}, \h_{2^{\2-1},1}, \h_{2^{\2-1},2}, \cdots, \h_{2^{\2-1},M-1}) = 0, \\
&\vdots ~~~~~~~~~~~~~~~~~~~~\vdots ~~~~~~~~~~~~~~~~~~~~\vdots~~~~~~~~~~~~~~~~~~~~\vdots\\
&\x_{2^{\2-1}M} (\h _{1, 0}, \h_{1, 1}, \h_{1,2}, \cdots , \h_{1, M -1}, \h_{2,0}, \h_{2,1}, \cdots, \h_{2, M-1}, \cdots, \h_{2^{\2-1},0}, \h_{2^{\2-1},1}, \h_{2^{\2-1},2}, \cdots, \h_{2^{\2-1},M-1}) = 0. 
\end{aligned}
\end{equation}
By solving the above system of linear equations, we obtain the SOTW coefficients. These are then substituted back into the equation \eqref{P3_eqn12} to compute the numerical solution. The process is repeated  for $ \R = 1, 2, 3, \cdots$ until the desired accuracy is achieved.
\subsection{Convergence Analysis}\label{CGT}
 We present the following theorem to establish the convergence of the SOTWQCM for the given NSBVPs \eqref{P3_L1}. 
 %Let us consider the $2^{nd}$ order ordinary differential equation in general form as:
% \begin{equation}\label{de1}
%     G(\z, \1, \1',\1'') = 0.
% \end{equation}
Using SOTW collocation method, we have
 \begin{equation}\label{cgt1_P3}
        h(\z) = \1'' (\z)  =  \sum_{\3 = 1}^{\infty} \sum_{\g = 0}^{\infty} \h_{\3, \g} \w _{\3, \g} (\z).
    \end{equation}
  Integrating the above equation \eqref{cgt1_P3} two times, we get  
   \begin{equation}\label{cgt2_P3}
        \1 (\z)  =  \sum_{\3 = 1}^{\infty} \sum_{\g = 0}^{\infty} \h_{\3, \g} P^{2}\w _{\3, \g} (\z) + C_{T}(\z),
    \end{equation}
    where $C_{T}(\z)$ stands for the constants of integration, $ P^{2}\w _{\3, \g} (\z)$ represents the second order integration of the $\w _{\3, \g}(\z)$.
\begin{theorem}\label{P3_theorem}
    If a continuous function  $ h (\z) = \frac{d^2 \1 }{d\z^2}$  be a square integrable  function defined on the interval $[0,~ 1]$, such that  it is bounded  by $\beta$, i.e., $|h(\z)| \leq  \beta$, for every $\z \in [0,~ 1]. $ Then, the SOTW expansion of $ h(\z)$  in \eqref{eq4_P3}  converges.
\end{theorem}
\begin{proof}\label{P3_proof}
