%     \end{equation}
    In \eqref{cgt2_P3}, truncating the expansion, we have
     \begin{equation}\label{cgt3_P3}
        \1_{\2,\5}(\z)  =  \sum_{\3 = 1}^{2^{\2-1}} \sum_{\g = 0}^{M-1} \h_{\3, \g} P^{2}\w _{\3, \g} (\z) + C_{T}(\z).
    \end{equation}
    Now, we define the error  as follows:
    \begin{equation}\label{P3_cgt1}
\left|\6_{\2, \5}\right| \; =\left| \1(\z) - \1_{\2,\5}(\z)\right| =\;  \left| \sum_{\3 = 2^{\2}}^{\infty} \sum_{\g = \5}^{\infty} \h_{\3, \g} P^{2}\w _{\3, \g} (\z) \right|.
\end{equation}
The $L^{2}$-norm of the given  error function is defined as,
%Expanding the provided \( L^{2} \) norm, we obtain:
\begin{equation}\label{P3_cgt2}
\lVert \6_{\2, \5}\rVert_{2}^{2} \; =  \int_{0}^{1} \Big (\sum_{\3 =2^{\2} }^{\infty}  \sum_{\g = \5}^{\infty}   \h_{\3, \g} P^{2}\w _{\3, \g} (\z)\Big)^{2}\, d\z.
\end{equation}
After expanding above equation, we have
%Now, expanding the  above terms, we get,
\begin{equation}\label{P3_cgt3}
    \lVert \6_{\2, \5}\rVert_{2}^{2} \; =   \sum_{\3 = 2^{\2}}^{\infty}  \sum_{\g = \5}^{\infty} \sum_{\1 = 2^{\2}}^{\infty}  \sum_{\R = \5}^{\infty} \h_{\3, \g}  \h_{\1, \R} \int_{0}^{1}  P^{2}\w _{\3, \g}(\z) ~ P^{2}\w _{\1, \R}(\z) \;  d\z.
\end{equation}
Now, as $\z \in [0,~1],$ we have
\begin{eqnarray}
  && \label{P3_eq3}
     \left|  P^{2}\w _{\3, \g}(\z)  \right| \leq  \int_{0}^{\z}  \int_{0}^{\z} \w _{\3, \g}(\z)   d\z d\z,\\
       && \label{P3_eq4}
