     \end{eqnarray}
Now, by using equation  \eqref{eq2_P3}, we have
\begin{equation*}\label{P3_E14}
     \left|  P^{2}\w _{\3, \g}(\z)  \right| \leq  2^{\frac{\2 - 1}{2}}  \frac{1}{\sqrt{z_{\g}}}\int_{0}^{\z}  \int_{\frac{\3-1}{2^{\2-1}}}^{\frac{\3}{2^{\2-1}}} T_{\g}(2^{\2-1} \z - \3 +1) d\z d\z.
\end{equation*}
By using, change of variable, $2^{\2 -1} \z - \3 +1 = y$, and taking the  relation $ T_{\g}(y)=  \frac{T_{\g+1}'(y)}{\g+1}$, we get,
\begin{equation*}\label{P3_E114}
