\ENDWHILE

\end{algorithmic}
\end{algorithm}
%
\begin{equation}
    \bar{{ y}}^{\rm MF}_{mn}({\kappa_i},p) = {\bf a}^{\Htran}_{\rm R}(\hat{\theta}_{\kappa_i}[p]) \bar{{\bf y}}_{mn} ({\bf a}^{\Ttran}_{\rm T}(\hat{\theta}_{\kappa_i}[p]) {\bf x}_{mn} )^*,
