\section{The mathematical formulation and main results}\label{sec-main}
For $T>0$, let $\mcm = [0, T]\times \mbr^3$ and $(t, x), t\in [0, T], x\in \mbr^3$ be the local coordinates. Let  $g = -dt^2 + \sum_{i = 1}^3dx_i^2$ be the Minkowski metric on $\mcm$.  We study the problem for a 3D universe for physical relevance, but remark that our method applies to dimensions $n\geq 2.$ For $t\in \mbr,$ we denote $\mcm_t = \{t\}\times \mbr^3$.  Let $\mcb  = \{x\in \mbr^3: |x| < 1\}$ be the unit ball on $\mbr^3$. We consider null geodesics on $(\mcm, g)$ from $\mcm_0$ that meet $\mcb$ on $\mcm_T$. See Figure \ref{fig-setup}. This setup corresponds to making CMB observations near the Earth. It is convenient to parametrize the null geodesics using $y\in \mcb$ and $v\in \mbs^2$ as  
\beqq\label{eq-geo}
\gamma_{y, v}(t) = (t, y + tv - Tv), \quad t\in \mbr.
\eeqq
For $t\in [0, T]$, $\gamma_{y, v}(t)$ is contained in $\mcm$. Note that the set of such null geodesics can be identified with the set $\mcc = \mcb \times \mbs^2.$ For a scalar function $f$ in $\mcm$, we consider the light ray transform  of $f$ defined as   
\beqq\label{eq-lray}
Lf(y, v) = \int_{0}^{T}f(t, y+ tv - Tv) dt, 
\eeqq
which is a function on $\mcc.$  
\begin{figure}[t]
\centering
\includegraphics[scale = 0.5]{figs/fig-setup2.pdf}
\caption{The setup of the partial data problem. The marked set on $t = 0$ is the visible set in Theorem \ref{thm-main}.}
\label{fig-setup}
\end{figure}

We study $L$ acting on solutions to the Cauchy problem of wave equations on $\mcm$. 
 Denote $\square = \p_t^2 +   \lap $ where $\lap$ is the positive Laplacian on $\mbr^3,$ namely $\lap = \sum_{i = 1}^3 D_{x_i}^2, D_{x_i} = -\imath\frac{\p}{\p x_i}, \imath = \sqrt{-1}.$  Let 
 \beqq\label{eq-P}
 P(t, x, \p_t, D) = \square + a_0(t, x) \p_t + \sum_{j = 1}^3 a_j(t, x)D_j + b(t, x), 
 \eeqq
 where $a_j, b\in C^\infty.$   We consider the Cauchy problem
\beqq\label{eq-cau}
\begin{gathered}
P(t, x, \p_t, D)u(t, x) = 0, \ \  t > 0, x\in \mbr^3 \\
u(0, x) = f_1(x), \ \ \p_t u(0, x) = f_2(x).
\end{gathered}
\eeqq
It is well-known that under proper regularity assumptions on $f_1, f_2,$ there is a unique solution $u$. We study the inverse problem of recovering information of $f_1, f_2$ from $L u$. 

For the full data problem namely $\mcb = \mbr^3$, it was shown in \cite{VaWa} (see also \cite{Wan1}) that one can stably recover $f_1, f_2$ supported in a fixed compact set. The partial data problem we are considering is different and it is not always possible to recover $f_1, f_2$.  Consider the setup in Figure \ref{fig-setup}. Let $\mcb_{1+T} = \{x\in \mbr^3: |x| <1+ T\}$ on $\mcm_0$. If $f_1, f_2$ are supported outside of $\mcb_{1+T}$, by finite speed of propagation of \eqref{eq-cau}, we see that $\supp u$ does not meet any light rays that intersect $\mcb$ at $t = T$. So $Lu = 0$. Thus the best one can hope for is to recover $f_1, f_2$ in $\mcb_{1+T}.$


For $b>a>0$, we set 
\beq
\mcr_{a, b} = \{x\in \mbr^3: a< |x|< b\}. 
\eeq
We use the convention that if $a\leq 0$ then $\mcr_{a, b} = \mcb_{b}$. In this work, we show that Cauchy data supported in $\mcr_{T-1, T+1}$ can be stably recovered from the observation on $\mcb.$ 
\begin{theorem}\label{thm-main}
Let $s\geq 0$ be an integer. Suppose $f_1 \in H^{s+1}(\mbr^3), f_2\in H^{s}(\mbr^3)$ are compactly supported in $\mcr_{T-1, T+1}$. Then $f_1, f_2$ are uniquely determined by $Lu$. Moreover, we have the following stability estimates 
\beqq\label{eq-mainest}
\|f_1\|_{H^{s+1}} + \|f_2\|_{H^s} \leq C \|Lu\|_{H^{s+2}} 
\eeqq
where $C>0$ is uniform for $f_1, f_2$ supported in a fixed compact set of $\mcr_{T-1, T+1}$. 
 \end{theorem}

We have two immediate remarks. First, in view of the stability estimate \eqref{eq-mainest}, the result can be generalized to small metric perturbations as in \cite{VaWa}. Second, if the Cauchy data is supported in $\mcb_{T+1}$ but not necessarily in $\mcr_{T-1, T+1}$, our analysis can potentially tell what singularities (wave front sets) of the Cauchy data can possibly be recovered, see Section \ref{sec-pf1} especially the microlocal inversion formula \eqref{eq-q10}, \eqref{eq-q11}. We do not pursue it further in this paper. 

The rest of the paper is organized as follows. In Section \ref{sec-back}, we study the microlocal properties of the back-projection. In Section \ref{sec-pf1}, we construct the microlocal inversion for the back-projection. Then we prove Theorem \ref{thm-main} in Section \ref{sec-pf}. Finally, we conduct a numerical study in Section \ref{sec-num}, and conclusions are provided in Section \ref{sec-conc}. 


%====================================%
\section{Analysis of the backprojection}\label{sec-back} 
We start with the expression of the solution for the Cauchy problem \eqref{eq-cau}. It is well-known that one can find approximate solutions as oscillatory integrals, see for example \cite[Section 1, Chapter VI]{Tre}. Let $E_j(t), j = 1, 2$ be the fundamental solutions such that $P(t, x, \p_t, D)E_j(t) = 0$ for $t\in (0, T)$ and 
\beq
\begin{gathered} 
E_1(0) = \id, \quad \p_tE_1(0) = 0,   \\
E_2(0) = 0, \quad \p_t E_2(0) = \id,
\end{gathered}
\eeq
where $\id$ denotes the identity operator.  Then we can write the solution of \eqref{eq-cau} as $u(t, x) = E_1(t)f_1 + E_2(t)f_2$. In fact, $E_j(t), j = 1, 2$ are of the form  
\beqq\label{eq-fund}
\begin{gathered}
E_j(t) u(x) = E_j^+(t) u(x) + E_j^-(t)u(x)  + R_j(t)u(x)
\end{gathered}
\eeqq
where 
\beqq\label{eq-E}
\begin{gathered}
E_j^+(t)u(x) = (2\pi)^{-3} \int_{\mbr^3}\int_{\mbr^3} e^{\imath ((x-y)\cdot \xi + t |\xi|)} a_{j}^+(t, x, \xi) u(y) dy d\xi\\
E_j^-(t)u(x) =  (2\pi)^{-3} \int_{\mbr^3}\int_{\mbr^3} e^{\imath ((x-y)\cdot \xi - t |\xi|)} a_{j}^-(t, x, \xi)u(y) dy d\xi 
\end{gathered}
\eeqq
and $R_j(t), j = 1, 2$ are regularizing, see \cite[Chapter VI, (1.37)]{Tre}. Here, the phase function is derived from the principal part of $P(t, x, \p_t, D)$. The amplitudes $a_j^\pm$ have asymptotic summations of the form   
\beq
a_j^\pm(t, x, \xi) \sim \sum_{k = 0}^\infty a_{jk}^\pm(t, x, \xi),
\eeq
where each $a_{jk}^\pm$ is homogeneous of degree $-j-k$. They are determined via transport equations. Here, we recall the construction of the leading order terms for $k = 0$. They satisfy
\beqq\label{eq-trans}
\p_t a_{j0}^\pm \mp \sum_{l = 1}^3 \frac{\xi_l}{|\xi|}  \p_l a_{j0}^\pm \pm \frac{1}{2 } (a_0(t, x) + \sum_{l = 1}^3 a_l(t, x)\frac{\xi_l}{|\xi|}) a_{j0}^\pm = 0, 
\eeqq
see \cite[Chapter VI, (1.49)]{Tre}. The initial condition at $t = 0$ is given by (see \cite[Chapter VI, (1.53)]{Tre})
\beq
\begin{gathered}
(\imath |\xi|)^{j'-1} a_{j0}^+(0, x, \xi) +(- \imath |\xi|)^{j'-1} a_{j0}^-(0, x, \xi) = \delta_{jj'}, 
\end{gathered}
\eeq
where $j, j' = 1, 2$ and $\delta_{jj'}$  is the Kronecker delta function.  We find that 
\beq
a_{10}^\pm(0, x, \xi) = \ha, \quad a_{20}^\pm(0, x, \xi) = \pm\frac{1}{2\imath} |\xi|^{-1}.
\eeq
Then we can solve \eqref{eq-trans} with these initial conditions to get $a_{j0}^{^\pm}(t, x, \xi)$. In particular, we see that $a_{j0}^\pm$ are non-vanishing. 

To summarize, for $t>0$, $E^\pm_j(t)$ $\in I^{- j+1}(\mbr^3\times\mbr^3; (C^\pm)')$ are elliptic Fourier integral operators in H\"ormander's notation (see Definition 25.2.1 of \cite{Ho4}), where the canonical relations are 
\beqq\label{eq-cano0}
\begin{gathered}
C^\pm_t = \{(x, \eta; y, \xi) \in T^*\mbr^3 \backslash 0\times T^*\mbr^3\backslash 0:  x = y -  t (\pm \xi/|\xi|), \eta  = \xi\}. 
\end{gathered}
\eeqq
Finally, we write the approximate solution of \eqref{eq-cau}  as 
\beqq\label{eq-u}
u(t, x) = E_1^+(t)f_1 + E_1^-(t)f_1 + E_2^+(t)f_2 + E_2^-(t)f_2 + R_1(t)f_1 + R_2(t)f_2
\eeqq
where $t\geq 0$. \\


We analyze $Lu$ with $u$ in \eqref{eq-u}. It suffices to consider the operator $(L E_j^\pm), j = 1, 2$ defined by $(LE_j^\pm)f(x, v) =  L (E_j^{\pm}(t) f)(x, v)$ for a scalar function $f$ on $\mbr^3.$ In order to ``invert" the operators to get $f$, we use the idea of backprojection in X-ray tomography. In particular, we follow the approach of \cite{VaWa} to take the integral of the $v$ variable on $\mbs^2$.  For $h\in C^\infty(\mbr^3\times \mbs^2),$ we define 
\beq
I  h(x) = \int_{\mbs^2}  h(x, v) dv.
\eeq 
The main purpose of this section is to analyze the microlocal structure of $I L E^\pm_j$ and show that it can be decomposed into a sum of FIOs. The main results of this section are Lemma \ref{lm-b12} and \ref{lm-b34}. 

\begin{figure}[t]
\centering
\includegraphics[scale = 0.5]{figs/fig-pf.pdf}
\caption{Illustration of the modified light ray transform $L_\eps$. }
\label{fig-pf}
\end{figure}

To avoid some technicalities, we will use a subset of the light rays. For $\eps>0$ small, we consider the set $\mcb_{1-\eps} = \{y\in \mbr^3: |y|< 1-\eps\}$. Then we use the light rays that meet $\{T+\eps\}\times \mcb_{1-\eps}$, see Figure \ref{fig-pf}. We let $\phi_\eps$ be a smooth cut-off function on $\mbr^3$ such that $\supp \phi_\eps =  \overline \mcb_{1-\eps}$, $\phi_\eps>0$ on $\mcb_{1-\eps}$ and $\phi_\eps = 1$ on $\overline\mcb_{1-2\eps}$. Then we let $L_\eps = \phi_\eps L$ so that 
\beqq\label{eq-lraye}
L_\eps f(y, v) = \int_0^T \phi_\eps(y) f(t, y + tv - (T +\eps)v)dt, \quad y\in \mcb_{1}, v\in \mbs^2. 
\eeqq
Note that when $t = T$, $y+tv-(T+\eps)v = y- \eps v \in \mcb$ for $y\in \mcb_{1-\eps}.$ The role of   $\phi_\eps$ is to avoid the cut-off singularities at the boundary of $\mcb_1$. 

We now analyze $I  L_\eps E_1^+ $. In particular, we will find the integral kernel of the operator in the sense of distributions. Using \eqref{eq-E}, we have 
\beq
\begin{gathered}
 I L_\eps E_1^+ f(x) 
%= (2\pi)^{-3}  \int_{\mbs^2} \int_{0}^T\int_{\mbr^3}\int_{\mbr^3}  e^{\imath((x + tv - (T + \eps)v - y)\cdot \xi + t |\xi|)} a_1^+(t, x, \xi) \phi_\eps(x) f(y) dy d\xi dt dv\\
 = (2\pi)^{-3} \int_{\mbs^2} \int_{0}^T\int_{\mbr^3}\int_{\mbr^3}  e^{\imath(x - y)\cdot \xi} e^{\imath (t - T -\eps)v\cdot \xi} e^{\imath t |\xi|}a_1^+(t, x, \xi)   \phi_\eps(x) f(y) dy d\xi dt dv.  
  \end{gathered}
  \eeq
Note that for $t\in (0, T)$, $t - T - \eps < 0$. For $|\xi|$ large, the phase function
\beq
(t-T-\eps)v\cdot \xi = (t-T-\eps)|\xi| v\cdot(\xi/|\xi|)
\eeq
has non-degenerate critical points at $v = \pm \xi/|\xi|$, see e.g., \cite[(1.14)]{Mel}. We can perform the stationary phase method for the integration in $v$ to get $IL_\eps E_1^+ = B_{1, 1}^+ + B_{1, 2}^+ + R_1^+$ where $R_1^+$ is regularizing and   
  \beqq\label{eq-B1}
\begin{gathered}
 B_{1, 1}^+ f(x) =  (2\pi)^{-3} \int_{0}^T\int_{\mbr^3 } \int_{\mbr^3 }e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|}  b_{1, 1}^+(t, x, \xi)  \phi_\eps(x)  f(y) dy d\xi dt, \\
B_{1, 2}^+ f (x) = (2\pi)^{-3}  \int_{0}^T\int_{\mbr^3 } \int_{\mbr^3 }e^{\imath(x - y)\cdot \xi} e^{-\imath (T+\eps)|\xi|} e^{\imath 2 |\xi|t} b_{1, 2}^+(t, x, \xi)  \phi_\eps(x)   f(y) dy d\xi dt. 
\end{gathered}
\eeqq 
Here, $b_{1, k}^+, k = 1, 2$ are smooth functions supported away from $\xi = 0$. They have asymptotic summations of the form 
\beq
b_{1, k}^+(t, x, \xi) \sim \sum_{l = 1}^\infty |\xi|^{-l} b_{1, k; l}^+(t, x, \xi/|\xi|) 
\eeq
for $|\xi|$ large. The leading order terms are 
\beqq\label{eq-symb}
\begin{gathered}
 \sigma_{-1}(b_{1, 1}^+)(t, x, \xi) %= b_{1, 1; 1}^+(t, x, \xi) 
= C_1 \frac{1}{(t - T - \eps)|\xi|} a_{10}^+(t, x, \xi/|\xi|) =  \frac{C_1}{2(t - T - \eps)|\xi|}, \\
 \sigma_{-1}(b_{1, 2}^+)(t, x, \xi) %=  b_{1, 2; 1}^+(t, x, \xi) 
= C_2 \frac{1}{(t - T - \eps)|\xi|} a_{10}^{+}(t, x, -\xi/|\xi|) = \frac{C_2}{2(t - T - \eps)|\xi|}, 
\end{gathered}
\eeqq
where we used $\sigma_{-1}(\cdot)$ to denote the leading order term or the principal symbol of order $-1$, and $C_1, C_2$ come from the constants in the stationary phase argument, see  \cite[(1.14)]{Mel}. More explicitly,  
\beq
\begin{gathered}
C_1 =  e^{-\pi \imath/2} (2\pi)^2   =  -4\pi^2 \imath, \quad 
 C_2 =  e^{\pi \imath/2} (2\pi)^2   = 4\pi^2 \imath. 
 \end{gathered}
\eeq

Now we can write $B_{1,1}^+$ as 
\beqq\label{eq-B11}
\begin{gathered}
B_{1, 1}^+ f(x)    = (2\pi)^{-3}  \int_{\mbr^3}\int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|} \tilde b_{1, 1}^+(x, \xi)  f(y) dy d\xi  
\end{gathered}
\eeqq 
where 
\beq
\tilde b_{1, 1}^+(x, \xi) = \int_0^T  b_{1, 1}^+(t, x, \xi) \phi_\eps(x) dt
\eeq
is a symbol of order $-1$. The leading order term is given by
\beqq\label{eq-bplus-sym}
\sigma_{-1}(\tilde b_{1, 1}^+)(x, \xi) = |\xi|^{-1}\phi_\eps(x) \int_0^T  \frac{-4\pi^2\imath}{2(t - T - \eps)}  dt = (-2\pi^2\imath \ln\frac{\eps}{T+\eps}) |\xi|^{-1} \phi_\eps(x) 
\eeqq 
for $|\xi|$ large. 
We observe that  $B_{1, 1}^+$ is an Fourier integral operator of order $-1$ with canonical relation $C_{T+\eps}$. Hereafter, for $a\in \mbr$, we define 
\beq
\begin{gathered}
C_a = \{(x, \xi; y, \eta): \xi = \eta,  x= y - a \xi/|\xi|,  
x, y \in \mbr^3, \xi, \eta \in \mbr^3\backslash 0 \}. 
\end{gathered}
\eeq
In H\"ormander's notation, we can write $B_{1, 1}^+\in I^{-1}(\mbr^3\times \mbr^3; C_{T+\eps}')$. 


For $B_{1, 2}^+$ in \eqref{eq-B1}, we first compute  
\beq
\begin{gathered}
 \tilde b_{1, 2}^+(x, \xi) = \int_0^T e^{\imath 2 |\xi|t} b_{1, 2}^+(t, x, \xi)\phi_\eps(x) dt %= \int_0^T  \frac{1}{\imath 2 |\xi|^2}  b_{1, 2}^+(t, x, \xi)\phi_\eps(x) d e^{\imath 2 |\xi|t}\\
  =   \frac{1}{\imath 2 |\xi|}  b_{1, 2}^+(T, x, \xi)\phi_\eps(x) e^{\imath 2 |\xi|T} \\ -  \frac{1}{\imath 2 |\xi|}  b_{1, 2}^+(0, x, \xi)\phi_\eps(x)   -  \int_0^T  \frac{1}{\imath 2 |\xi|}  \p_t b_{1, 2}^+(t, x, \xi)\phi_\eps(x)  e^{\imath 2 |\xi|t} dt
\end{gathered}
\eeq
via integration by parts. This procedure can be continued to get 
\beq
 \tilde b_{1, 2}^+(x, \xi)  
  = \tilde b^+_{1, 2, 1}(x, \xi) + e^{\imath 2 |\xi|T} \tilde b_{1, 2, 2}^+(x, \xi)  
  \eeq
where $\tilde b^+_{1, 2, j}, j = 1, 2$ are symbols of order $-2$. In fact, we can find the leading order terms as
\beq
\begin{gathered}
\sigma_{-2}(\tilde b^+_{1, 2, 1})(x, \xi) = \frac{\pi^2}{(T+\eps)}|\xi|^{-2}\phi_\eps(x), \quad 
\sigma_{-2}(\tilde b^+_{1, 2, 2})(x, \xi) = -\frac{\pi^2}{\eps}|\xi|^{-2}\phi_\eps(x). 
\end{gathered}
\eeq
Therefore, we have 
\beq
\begin{gathered}
B_{1, 2}^+  f(x)   = (2\pi)^{-3}  \int_{\mbr^3}\int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{-\imath (T+\eps)|\xi|}   \tilde b_{1, 2, 1}^+(x, \xi)  f(y) dy d\xi\\ 
    + (2\pi)^{-3}  \int_{\mbr^3}\int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T-\eps)|\xi|}   \tilde b_{1, 2, 2}^+(x, \xi)   f(y) dy d\xi 
     = B_{1, 2, 1}^+f(x) + B_{1, 2, 2}^+f(x). 
\end{gathered}
\eeq 
We observe that the operators $B_{1, 2, k}^+, k = 1, 2$ are FIOs of order $-2$ with canonical relations  $C_{-T-\eps}$ and $C_{T-\eps}$. This completes the analysis for $IL_\eps E_1^+$. In particular, we decomposed the operator into a sum of FIOs. 

The analysis for $IL_\eps E_2^+$ is completely identical. The only difference is  the order and the symbol. We will not show the details. To summarize, we proved 
\begin{lemma}\label{lm-b12}
For $l = 1, 2$, we can write 
\beq
I L_\eps E_l^+ = B_{l, 1}^+ + B_{l, 2, 1}^+ + B_{l, 2, 2}^+ + R_l^+, 
\eeq
where $R_l^+$ are regularizing operators and the rest are Fourier integral operators 
\beq
\begin{gathered}
B_{l, 1}^+  \in I^{-1 - (l-1)}(\mbr^3\times \mbr^3; C'_{T+\eps}), \\
B_{l, 2, 1}^+ \in  I^{-2 - (l-1)}(\mbr^3\times \mbr^3; C'_{-T - \eps}),  \quad B_{l, 2, 2}^+ \in I^{-2 - (l-1)}(\mbr^3\times \mbr^3; C'_{T - \eps}). 
\end{gathered}
\eeq
Moreover,  
\begin{enumerate}
\item $B_{l, 1}^+, l = 1, 2$ can be written as an oscillatory integrals 
 \beq 
\begin{gathered}
B_{l, 1}^+ f(x)   = (2\pi)^{-3}  \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|} \tilde b_{l, 1}^+(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 1}^+$ are symbols of order $-1-(l-1)$. The principal symbols of $B_{l, 1}^+$ in this representation  are given by 
\beq
\begin{gathered}
\sigma_{-1}(B_{1, 1}^+)(x, y, \xi) = (-2\pi^2\imath \ln\frac{\eps}{T+\eps})  \phi_\eps(x) |\xi|^{-1},  \\
 \sigma_{-2}(B_{2, 1}^+)(x, y, \xi) = (-2\pi^2  \ln\frac{\eps}{T+\eps})  \phi_\eps(x)|\xi|^{-2}
\end{gathered}
\eeq
for $|\xi|$ large. 

\item  $B_{l, 2, 1}^+, l = 1, 2$ can be written as an oscillatory integrals 
 \beq 
\begin{gathered}
B_{l, 2, 1}^+ f(x)   = (2\pi)^{-3}  \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{-\imath (T+\eps)|\xi|} \tilde b_{l, 2, 1}^+(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 2, 1}^+$ are symbols of order $-2-(l-1)$. The principal symbols of $B_{l, 2, 1}^+$ in this representation  are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 1}^+)(x, y, \xi) =  \frac{\pi^2}{(T+\eps)}\phi_\eps(x)|\xi|^{-2},   \quad 
 \sigma_{-3}(B_{2, 2, 1}^+)(x, y, \xi) =  \frac{\pi^2}{\imath (T+\eps)} \phi_\eps(x) |\xi|^{-3}
\end{gathered}
\eeq  
for $|\xi|$ large. 


\item $B_{l, 2, 2}^+, l = 1, 2$ can be written as an oscillatory integrals 
 \beq 
\begin{gathered}
B_{l, 2, 2}^+ f(x)   = (2\pi)^{-3}  \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T-\eps)|\xi|} \tilde b_{l, 2, 1}^+(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 2, 2}^+$ are symbols of order $-2-(l-1)$. The  principal symbols of $B_{l, 2, 2}^+$ in this representation are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 2}^+)(x, y, \xi) =  -\frac{\pi^2}{\eps} \phi_\eps(x)  |\xi|^{-2},  \quad  
 \sigma_{-3}(B_{2, 2, 2}^+)(x, y, \xi) =  -\frac{\pi^2}{\eps\imath } \phi_\eps(x) |\xi|^{-3}
\end{gathered}
\eeq
for $|\xi|$ large. 

\end{enumerate}
\end{lemma}


We can obtain a similar decomposition for $I L_\eps E_j^- $ following the same type of calculation. Because the canonical relations are  different, we repeat some of the calculations. Consider $IL_\eps E_1^-$. We compute that   
\beq
\begin{gathered}
I L_\eps E_1^- f(x)  
 = (2\pi)^{-3} \int_{\mbs^2} \int_{0}^T\int_{\mbr^3}\int_{\mbr^3}  e^{\imath(x - y)\cdot \xi} e^{\imath (t - T -\eps)v\cdot \xi}  e^{-\imath t |\xi|}a_1^-(t, x, \xi)   \phi_\eps(x) f(y) dy d\xi dt dv. 
  \end{gathered}
  \eeq
Again, for $|\xi|$ large, we perform the stationary phase method for the integration in $v$ to get $IL_\eps E_1^- = B_{1, 1}^- + B_{1, 2}^-+ R_1^-$ where $R_1^-$ is regularizing and   
  \beqq\label{eq-B2}
\begin{gathered}
B_{1, 1}^- f (x) =   (2\pi)^{-3} \int_{0}^T\int_{\mbr^3 } \int_{\mbr^3 }e^{\imath(x - y)\cdot \xi} e^{-\imath(T+\eps)|\xi|}  b_{1, 1}^-(t, x, \xi)  \phi_\eps (x)   f(y) dy d\xi dt, \\
 B_{1, 2}^- f(x) =   (2\pi)^{-3}  \int_{0}^T\int_{\mbr^3 } \int_{\mbr^3 }e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|} e^{-\imath 2|\xi|t}   b_{1, 2}^-(t, x, \xi)  \phi_\eps(x)  f(y) dy d\xi dt. 
\end{gathered}
\eeqq 
Similarly, $b_{1, k}^-, k = 1, 2$ are smooth functions supported away from $\xi = 0$. They have asymptotic summations of the form 
\beq
b_{1, k}^-(t, x, \xi) \sim \sum_{l = 1}^\infty |\xi|^{-l} b_{1, k, l}^-(t, x, \xi/|\xi|) 
\eeq
for $|\xi|$ large. The leading order terms are 
\beqq\label{eq-symb}
\begin{gathered}
\sigma_{-1}(b_{1, 1})(t, x, \xi) %= b_{1, 1, 1}^-(t, x, \xi) 
= C_1 \frac{1}{(t - T - \eps)|\xi|}  a_{10}^-(t, x, \xi/|\xi|) = \frac{C_1}{2(t - T - \eps)|\xi|}, \\
\sigma_{-1}(b_{1, 2})(t, x, \xi) %= b_{1, 2, 1}^-(t, x, \xi) 
= C_2 \frac{1}{(t - T - \eps)|\xi|}  a_{10}^{-}(t, x, -\xi/|\xi|) =\frac{C_2}{2(t - T - \eps)|\xi|}. 
\end{gathered}
\eeqq
We integrate in $t$ in $B_{1,1}^-$ to get 
\beq
\begin{gathered}
B_{1, 1}^- f(x)    =  (2\pi)^{-3}  \int_{\mbr^3}\int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{-\imath (T+\eps)|\xi|} \tilde b_{1, 1}^-(x, \xi)  f(y) dy d\xi, 
\end{gathered}
\eeq 
where 
\beq
\tilde b_{1, 1}^-(x, \xi) = \int_0^T |\xi|^{-1} b_{1, 1}^-(t, x, \xi) \phi_\eps(x) dt
\eeq
is a symbol of order $-1$. For $B_{1, 2}^-$, we obtain via integration by parts that
\beq
\begin{gathered}
 \tilde b_{1, 2}^-(x, \xi) = \int_0^T e^{-\imath 2 |\xi|t}|\xi|^{-1}  b_{1, 2}^-(t, x, \xi)\phi_\eps(x) dt\\
 %= \int_0^T  \frac{1}{-\imath 2 |\xi|^2}  b_{1, 2}^-(t, x, \xi)\phi_\eps(x) d e^{-\imath 2 |\xi|t}\\
  =  \frac{1}{-\imath 2 |\xi|^2}  b_{1, 2}^-(T, x, \xi)\phi_\eps(x)  e^{-\imath 2 |\xi|T} -  \frac{1}{-\imath 2 |\xi|^2}  b_{1, 2}^-(0, x, \xi)\phi_\eps(x)  \\
  -  \int_0^T  \frac{1}{-\imath 2 |\xi|^2}  \p_t b_{1, 2}^-(t, x, \xi)\phi_\eps(x)  e^{-\imath 2 |\xi|t} dt. 
\end{gathered}
\eeq
The procedure can be continued  to yield
\beq
 \tilde b_{1, 2}^-(x, \xi)  
  = \tilde b^-_{1, 2, 1}(x, \xi) + e^{-\imath 2 |\xi|T} \tilde b_{1, 2, 2}^-(x, \xi), 
  \eeq
where $\tilde b^-_{1, 2, j}, j = 1, 2$ are symbols of order $-2$.   Therefore, we have 
\beq
\begin{gathered}
B_{1, 2}^-  f(x)   =  (2\pi)^{-3} \int_{\mbr^3}\int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{-\imath (T-\eps)|\xi|}   \tilde b_{1, 2, 1}^-(x, \xi)  f(y) dy d\xi\\ 
    +  (2\pi)^{-3} \int_{\mbr^3}\int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|}   \tilde b_{1, 2, 2}^-(x, \xi)   f(y) dy d\xi 
     = B_{1, 2, 1}^-f(x) + B_{1, 2, 2}^- f(x). 
\end{gathered}
\eeq 
To summarize, we proved 
\begin{lemma}\label{lm-b34}
For $l = 1, 2$, we can write 
\beq
IL_\eps E_l^- = B_{l, 1}^- + B_{l, 2, 1}^- + B_{l, 2, 2}^- + R_l^-, 
\eeq
where $R_l^-$ are regularizing operators and the rest are elliptic Fourier integral operators 
\beq
\begin{gathered}
B_{l, 1}^-  \in I^{-1 -(l-1)}(\mbr^3\times \mbr^3; C'_{-T-\eps}), \\
B_{l, 2, 1}^-  \in I^{-2-(l-1)}(\mbr^3\times \mbr^3; C'_{-T + \eps}), \quad B_{l, 2, 2}^- \in I^{-2-(l-1)}(\mbr^3\times \mbr^3; C'_{T + \eps}). 
\end{gathered}
\eeq
Moreover,  
\begin{enumerate}
\item $B_{l, 1}^-, l = 1, 2$ can be written as oscillatory integrals, 
 \beq 
\begin{gathered}
B_{l, 1}^- f(x)   =  (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{-\imath (T+\eps)|\xi|} \tilde b_{l, 1}^-(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 1}^-$ are symbols of order $-1-(l-1)$. The principal symbols of $B_{l, 1}^-$ in this representation are given by 
\beq
\begin{gathered}
\sigma_{-1}(B_{1, 1}^-)(x, y, \xi) = (-2\pi^2\imath \ln\frac{\eps}{T+\eps})  |\xi|^{-1} \phi_\eps(x), \\
 \sigma_{-2}(B_{2, 1}^-)(x, y, \xi) = (2\pi^2  \ln\frac{\eps}{T+\eps}) |\xi|^{-2} \phi_\eps(x), 
\end{gathered}
\eeq
for $|\xi|$ large. 
\item  $B_{l, 2, 1}^-, l = 1, 2$ can be written as oscillatory integrals, 
 \beq 
\begin{gathered}
B_{l, 2, 1}^- f(x)   =  (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (-T+\eps)|\xi|} \tilde b_{l, 2, 1}^-(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 2, 1}^-$ are symbols of order $-2-(l-1)$. The principal symbols of $B_{l, 2, 1}^-$ in this representation  are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 1}^-)(x, y, \xi) =  -\frac{\pi^2}{(T+\eps)} \phi_\eps(x) |\xi|^{-2},  \quad 
 \sigma_{-3}(B_{2, 2, 1}^-)(x, y, \xi) =   -\frac{\pi^2\imath }{(T+\eps)} \phi_\eps(x)|\xi|^{-3}, 
\end{gathered}
\eeq  
for $|\xi|$ large. 

\item $B_{l, 2, 2}^-, l = 1, 2$ can be written as an oscillatory integrals 
 \beq 
\begin{gathered}
B_{l, 2, 2}^- f(x)   = (2\pi)^{-3}  \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|} \tilde b_{l, 2, 1}^-(x, \xi) f(y)dy d\xi,   
\end{gathered}
\eeq
where $\tilde b_{l, 2, 2}^-$ are symbols of order $-2-(l-1)$. The  principal symbols of $B_{l, 2, 2}^-$ in this representation are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 2}^-)(x, y, \xi) =   \frac{\pi^2}{\eps}  \phi_\eps(x)  |\xi|^{-2},  \quad 
 \sigma_{-3}(B_{2, 2, 2}^-)(x, y, \xi) =   \frac{\pi^2\imath}{\eps} \phi_\eps(x) |\xi|^{-3}, 
\end{gathered}
\eeq
for $|\xi|$ large. 
\end{enumerate}
\end{lemma}

