\section{The microlocal inversion} \label{sec-pf1}
For $\eps>0$ small, we consider $I L_\eps u$ with $u$ in \eqref{eq-u}. We apply Lemma \ref{lm-b12} and \ref{lm-b34} and group the terms as follows,
\beqq\label{eq-IL}
\begin{gathered}
  I L_\eps u  
=  \tilde B_{1}^+ f_1 + \tilde B_{2}^+ f_2 
+  B_{1, 2, 2}^+ f_1 + B_{2, 2, 2}^+ f_2\\
+  \tilde B_{1}^- f_1 + \tilde B_{2}^- f_2
+  B_{1, 2, 1}^- f_1 + B_{2, 2, 1}^- f_2 
+ R_1 f_1 + R_2 f_2, 
\end{gathered}
\eeqq
where $R_1 = R_1^+ + R_1^-, R_2 = R_2^+ + R_2^-$ are regularizing operators and 
\beqq\label{eq-oplist0}
\begin{gathered}
\tilde B_1^+ =  B_{1, 1}^+  + B_{1, 2, 2}^- \in I^{-1}(\mbr^3\times \mbr^3; C'_{T+\eps}),\\
\tilde B_2^+  =   B_{2, 1}^+ + B_{2, 2, 2}^- \in I^{-2}(\mbr^3\times \mbr^3; C'_{T+\eps}),  \\
\tilde B_1^- =  B_{1, 1}^-   + B_{1, 2, 1}^+ \in I^{-1}(\mbr^3\times \mbr^3; C'_{-T-\eps}), \\
  \tilde B_2^-  =   B_{2, 1}^- + B_{2, 2, 1}^+ \in I^{-2}(\mbr^3\times \mbr^3; C'_{-T-\eps}). 
\end{gathered}
\eeqq
Also, $B_{1, 2, 2}^+ \in I^{-2}(\mbr^3\times \mbr^3; C'_{T-\eps}), B_{2, 2, 2}^+\in I^{-3}(\mbr^3\times \mbr^3; C'_{T-\eps})$ and $B_{1, 2, 1}^- \in I^{-2}(\mbr^3\times \mbr^3; C'_{-T+\eps}), B_{2, 2, 1}^-  \in I^{-3}(\mbr^3\times \mbr^3; C'_{-T+\eps})$. Note that the orders of these FIOs acting on $f_1, f_2$ are lower than those corresponding terms in \eqref{eq-oplist0}, even though the canonical relations are different.  
The operators appearing in \eqref{eq-IL} are FIOs of graph type. Hence in principle, we can use FIO calculus (see for instance \cite[Section 25.3]{Ho4}) to solve for $f_1, f_2.$ However, equation \eqref{eq-IL} alone is not enough to solve for both $f_1$ and $f_2$. We will obtain another equation by changing the back-projection operator $I$, similar to the approach in \cite{VaWa}. 

Let $\varphi$ be a function on $\mbs^2$. Then for $h\in C^\infty(\mbr^3\times \mbs^2),$ we define 
\beq
I^\varphi  h(x) = \int_{\mbs^2} \varphi(v) h(x, v) dv.
\eeq 
We consider the back-projection $I^\varphi L_\eps u$. Ideally, we would like to take an odd function $\varphi$ such that $\varphi(-v) = -\varphi(v), v\in \mbs^2$ but then $\varphi$ would vanish somewhere on $\mbs^2$ so we proceed as follows. Let $x = (x_1, x_2, x_3)$ be the coordinate for $\mbr^3$.  For $\delta >0$, let $\mcu_k = \{v: v = (x_1, x_2, x_3), \|x\| = 1, |x_k| > \delta/2\}, k = 1, 2, 3.$ For $\delta$ sufficiently small, $\mcu_k, k = 1, 2, 3$ form an open covering of $\mbs^2.$ Let $\chi_k(v), k = 1, 2, 3$ be a partition of unity subordinated to this covering and $\chi_k(v) = 1$ on $\mcv_k = \{v: v = (x_1, x_2, x_3), \|x\| = 1, |x_k| > \delta\}, k = 1, 2, 3.$ Here, by possibly taking $\delta$ smaller, we can assume that $\mcv_k$ also forms an open covering of $\mbs^2.$ 
For $v\in \mbs^2$, we let 
\beq
\varphi_{k}(v) =  \chi_k(x) x_k + 2, \quad k = 1, 2, 3. 
\eeq
Then $\varphi_{k}(v)\neq 0$ and $\varphi_{k}(-v) - \varphi_{k}(v) \neq 0$ for $v\in \mcu_k.$ We now analyze $I^{\varphi_k} L_\eps u$ as in Section \ref{sec-back}. By repeating the calculations in Lemma \ref{lm-b12} and \ref{lm-b34}, we have the following Lemmas
\ref{lm-b12new} and \ref{lm-b34new}. The proofs are omitted. 
\begin{lemma}\label{lm-b12new}
For $k = 1, 2, 3,$ and $l = 1, 2$, we can write 
\beq
I^{\varphi_k} L_\eps E_l^+ = B_{l, 1}^{\varphi_k, +} + B_{l, 2, 1}^{\varphi_k, +} + B_{l, 2, 2}^{\varphi_k, +} + R_l^{\varphi_k, +}, 
\eeq
where $R_l^{\varphi_k, +}$ are regularizing operators and the rest are Fourier integral operators 
\beq
\begin{gathered}
B_{l, 1}^{\varphi_k, +}  \in I^{-1 - (l-1)}(\mbr^3\times \mbr^3; C'_{T+\eps}), \\
B_{l, 2, 1}^{\varphi_k, +} \in  I^{-2 - (l-1)}(\mbr^3\times \mbr^3; C'_{-T - \eps}),  \quad B_{l, 2, 2}^{\varphi_k, +} \in I^{-2 - (l-1)}(\mbr^3\times \mbr^3; C'_{T - \eps}). 
\end{gathered}
\eeq
Moreover,  
\begin{enumerate}
\item $B_{l, 1}^{\varphi_k, +}, l = 1, 2$ can be written as oscillatory integrals,
 \beq 
\begin{gathered}
B_{l, 1}^{\varphi_k, +} f(x)   = (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|} \tilde b_{l, 1}^{\varphi_k, +}(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 1}^{\varphi_k, +}$ are symbols of order $-1-(l-1)$. The principal symbols of $B_{l, 1}^{\varphi_k, +}$ in this representation  are given by 
\beq
\begin{gathered}
\sigma_{-1}(B_{1, 1}^{\varphi_k, +})(x, \xi) = (-2\pi^2\imath \ln\frac{\eps}{T+\eps})  \phi_\eps(x) \varphi_k(-\xi/|\xi|) |\xi|^{-1}, \\
 \sigma_{-2}(B_{2, 1}^{\varphi_k, +})(x, \xi) = (-2\pi^2  \ln\frac{\eps}{T+\eps})   \phi_\eps(x)\varphi_k(-\xi/|\xi|)|\xi|^{-2}, 
\end{gathered}
\eeq
for $|\xi|$ large. 
\item  $B_{l, 2, 1}^{\varphi_k, +}, l = 1, 2$ can be written as oscillatory integrals,
 \beq 
\begin{gathered}
B_{l, 2, 1}^{\varphi_k, +} f(x)   =  (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{-\imath (T+\eps)|\xi|} \tilde b_{l, 2, 1}^{\varphi_k, +}(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 2, 1}^{\varphi_k, +}$ are symbols of order $-2-(l-1)$. The principal symbols of $B_{l, 2, 1}^{\varphi_k, +}$ in this representation  are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 1}^{\varphi_k, +})(x, y, \xi) =  -\frac{\pi^2}{(T+\eps)}  \phi_\eps(x) \varphi_k(\xi/|\xi|) |\xi|^{-2}, \\ 
 \sigma_{-3}(B_{2, 2, 1}^{\varphi_k, +})(x, y, \xi) =   -\frac{\pi^2}{\imath (T+\eps)}  \phi_\eps(x)  \varphi_k(\xi/|\xi|) |\xi|^{-3}
\end{gathered}
\eeq  
for $|\xi|$ large. 

\item $B_{l, 2, 2}^{\varphi_k, +}, l = 1, 2$ can be written as oscillatory integrals,
 \beq 
\begin{gathered}
B_{l, 2, 2}^{\varphi_k, +} f(x)   =  (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T-\eps)|\xi|} \tilde b_{l, 2, 1}^{\varphi_k, +}(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 2, 2}^{\varphi_k, +}$ are symbols of order $-2-(l-1)$. The  principal symbols of $B_{l, 2, 2}^{\varphi_k, +}$ in this representation are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 2}^{\varphi_k, +})(x, y, \xi) =  -\frac{\pi^2}{\eps} \phi_\eps(x)  \varphi_k(\xi/|\xi|) |\xi|^{-2}, \\ 
 \sigma_{-3}(B_{2, 2, 2}^{\varphi_k, +})(x, y, \xi) =   -\frac{\pi^2}{\imath \eps} \phi_\eps(x)  \varphi_k(\xi/|\xi|)|\xi|^{-3}
\end{gathered}
\eeq
for $|\xi|$ large. 

\end{enumerate}
\end{lemma}



\begin{lemma}\label{lm-b34new}
For $k = 1, 2, 3,$ and $l = 1, 2$, we can write 
\beq
I^{\varphi_k}L_\eps E_l^- = B_{l, 1}^{\varphi_k, -} + B_{l, 2, 1}^{\varphi_k, -} + B_{l, 2, 2}^{\varphi_k, -} + R_l^{\varphi_k, -}, 
\eeq
where $R_l^{\varphi_k, -}$ are regularizing operators and the rest are elliptic Fourier integral operators 
\beq
\begin{gathered}
B_{l, 1}^{\varphi_k, -}  \in I^{-1 -(l-1)}(\mbr^3\times \mbr^3; C'_{-T-\eps}), \\
B_{l, 2, 1}^{\varphi_k, -}  \in I^{-2-(l-1)}(\mbr^3\times \mbr^3; C'_{-T + \eps}), \quad B_{l, 2, 2}^{\varphi_k, -} \in I^{-2-(l-1)}(\mbr^3\times \mbr^3; C'_{T + \eps}). 
\end{gathered}
\eeq
Moreover,  
\begin{enumerate}
\item $B_{l, 1}^{\varphi_k, -}, l = 1, 2$ can be written as oscillatory integrals,
 \beq 
\begin{gathered}
B_{l, 1}^{\varphi_k, -} f(x)   =  (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{-\imath (T+\eps)|\xi|} \tilde b_{l, 1}^{\varphi_k, -}(x, \xi) f(y)dy d\xi,   
\end{gathered}
\eeq
where $\tilde b_{l, 1}^{\varphi_k, -}$ are symbols of order $-1-(l-1)$. The principal symbols of $B_{l, 1}^{\varphi_k, -}$ in this representation  are given by 
\beq
\begin{gathered}
\sigma_{-1}(B_{1, 1}^{\varphi_k, -})(x, y, \xi) =  (-2\pi^2\imath \ln\frac{\eps}{T+\eps})  |\xi|^{-1} \varphi_k(\xi/|\xi|)\phi_\eps(x), \\
 \sigma_{-2}(B_{2, 1}^{\varphi_k, -})(x, y, \xi) = (2\pi^2\ln\frac{\eps}{T+\eps})   |\xi|^{-2} \varphi_k(\xi/|\xi|)\phi_\eps(x),
\end{gathered}
\eeq
for $|\xi|$ large. 
\item  $B_{l, 2, 1}^{\varphi_k, -}, l = 1, 2$ can be written as oscillatory integrals, 
 \beq 
\begin{gathered}
B_{l, 2, 1}^{\varphi_k, -} f(x)   =  (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (-T+\eps)|\xi|} \tilde b_{l, 2, 1}^{\varphi_k, -}(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 2, 1}^{\varphi_k, -}$ are symbols of order $-2-(l-1)$. The principal symbols of $B_{l, 2, 1}^{\varphi_k, -}$ in this representation  are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 1}^{\varphi_k, -})(x, y, \xi) =   -\frac{\pi^2}{(T+\eps)} \phi_\eps(x) \varphi_k(-\xi/|\xi|)|\xi|^{-2},  \\ 
 \sigma_{-3}(B_{2, 2, 1}^{\varphi_k, -})(x, y, \xi) =    -\frac{\pi^2 \imath }{(T+\eps)} \phi_\eps(x)\varphi_k(-\xi/|\xi|)|\xi|^{-3},
\end{gathered}
\eeq  
for $|\xi|$ large. 

\item $B_{l, 2, 2}^{\varphi_k, -}, l = 1, 2$ can be written as oscillatory integrals, 
 \beq 
\begin{gathered}
B_{l, 2, 2}^{\varphi_k, -} f(x)   =  (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(x - y)\cdot \xi} e^{\imath (T+\eps)|\xi|} \tilde b_{l, 2, 1}^{\varphi_k, -}(x, \xi) f(y)dy d\xi, 
\end{gathered}
\eeq
where $\tilde b_{l, 2, 2}^{\varphi_k, -}$ are symbols of order $-2-(l-1)$. The  principal symbols of $B_{l, 2, 2}^{\varphi_k, -}$ in this representation are given by 
\beq
\begin{gathered}
\sigma_{-2}(B_{1, 2, 2}^{\varphi_k, -})(x, y, \xi) =  \frac{\pi^2}{\eps}  \phi_\eps(x)  \varphi_k(-\xi/|\xi|)|\xi|^{-2}, \\ 
 \sigma_{-3}(B_{2, 2, 2}^{\varphi_k, -})(x, y, \xi) =   \frac{\pi^2 \imath }{\eps}  \phi_\eps(x)\varphi_k(-\xi/|\xi|) |\xi|^{-3},
\end{gathered}
\eeq
for $|\xi|$ large. 
\end{enumerate}
\end{lemma}


Using Lemma \ref{lm-b12new} and \ref{lm-b34new}, we can write for $k = 1, 2, 3$ that 
\beqq\label{eq-ILk}
\begin{gathered}
  I^{\varphi_k} L_\eps u  
=  \tilde B_{1}^{\varphi_k, +} f_1 + \tilde B_{2}^{\varphi_k, +} f_2 
+  B_{1, 2, 2}^{\varphi_k, +} f_1 + B_{2, 2, 2}^{\varphi_k, +} f_2\\
+  \tilde B_{1}^{\varphi_k, -} f_1 + \tilde B_{2}^{\varphi_k, -} f_2
+  B_{1, 2, 1}^{\varphi_k, -} f_1 + B_{2, 2, 1}^{\varphi_k, -} f_2 
+ R_1^{\varphi_k} f_1 + R_2^{\varphi_k} f_2, 
\end{gathered}
\eeqq
where $R_1^{\varphi_k} = R_1^{\varphi_k, +} + R_1^{\varphi_k, -}, R_2^{\varphi_k} = R_2^{\varphi_k, +} + R_2^{\varphi_k, -}$ are regularizing operators and 
\beqq\label{eq-oplist}
\begin{gathered}
\tilde B_1^{\varphi_k, +} =  B_{1, 1}^{\varphi_k, +}  + B_{1, 2, 2}^{\varphi_k, -} \in I^{-1}(\mbr^3\times \mbr^3; C'_{T+\eps}),\\
\tilde B_2^{\varphi_k, +}  =   B_{2, 1}^{\varphi_k, +} + B_{2, 2, 2}^{\varphi_k, -} \in I^{-2}(\mbr^3\times \mbr^3; C'_{T+\eps}),  \\
\tilde B_1^{\varphi_k, -} =  B_{1, 1}^{\varphi_k, -}   + B_{1, 2, 1}^{\varphi_k, +} \in I^{-1}(\mbr^3\times \mbr^3; C'_{-T-\eps}), \\
  \tilde B_2^{\varphi_k, -}  =   B_{2, 1}^{\varphi_k, -} + B_{2, 2, 1}^{\varphi_k, +} \in I^{-2}(\mbr^3\times \mbr^3; C'_{-T-\eps}). 
\end{gathered}
\eeqq
Also, $B_{1, 2, 2}^{\varphi_k, +} \in I^{-2}(\mbr^3\times \mbr^3; C'_{T-\eps}), B_{2, 2, 2}^{\varphi_k, +}\in I^{-3}(\mbr^3\times \mbr^3; C'_{T-\eps})$ and $B_{1, 2, 1}^{\varphi_k, -} \in I^{-2}(\mbr^3\times \mbr^3; C'_{-T+\eps}), B_{2, 2, 1}^{\varphi_k, -}  \in I^{-3}(\mbr^3\times \mbr^3; C'_{-T+\eps})$. We note again that the orders of these FIOs acting on $f_1, f_2$ are lower than those corresponding terms in \eqref{eq-oplist}, even though the canonical relations are different.  
We sum the equations \eqref{eq-ILk} in $k$ to get 
\beqq\label{eq-ILnew}
\begin{gathered}
I^{\varphi} L_\eps u  
=  \tilde B_{1}^{\varphi, +} f_1 + \tilde B_{2}^{\varphi, +} f_2 
+  B_{1, 2, 2}^{\varphi, +} f_1 + B_{2, 2, 2}^{\varphi, +} f_2\\
+  \tilde B_{1}^{\varphi, -} f_1 + \tilde B_{2}^{\varphi, -} f_2
+  B_{1, 2, 1}^{\varphi, -} f_1 + B_{2, 2, 1}^{\varphi, -} f_2 
+ R_1^{\varphi} f_1 + R_2^{\varphi} f_2, 
\end{gathered}
\eeqq
where we let $\varphi = \sum_{k = 1}^3 \varphi_k$, and the terms are described as follows: 
\begin{enumerate}
\item $I^\varphi L_\eps u = \sum_{k = 1}^3  I^{\varphi_k} L_\eps u$. 

\item $\tilde B_{1}^{\varphi, +} = \sum_{k = 1}^3 \tilde B_{1}^{\varphi_k, +} \in I^{-1}(\mbr^3\times \mbr^3; C'_{T+\eps})$, $\tilde B_{2}^{\varphi_k, +} = \sum_{k = 1}^3 \tilde B_{2}^{\varphi_k, +} \in I^{-2}(\mbr^3\times \mbr^3; C'_{T+\eps}).$ Moreover, these operators can be expressed as in Lemma \ref{lm-b12new} and \ref{lm-b34new}.  The principal symbols of the operators are given by 
\beq
\begin{gathered}
\sigma_{-1}(\tilde B_{1}^{\varphi, +})(x, y, \xi) = (-2\pi^2\imath \ln\frac{\eps}{T+\eps})  \phi_\eps(x) \varphi(-\xi/|\xi|) |\xi|^{-1}, \\
 \sigma_{-2}(\tilde B_{2}^{\varphi, +})(x, y, \xi) = (-2\pi^2  \ln\frac{\eps}{T+\eps}) \phi_\eps(x) \varphi(-\xi/|\xi|)   |\xi|^{-2}, 
\end{gathered}
\eeq
for $|\xi|$ large. 
\item $\tilde B_1^{\varphi, -} = \sum_{k = 1}^3 \tilde B_1^{\varphi_k, -} \in I^{-1}(\mbr^3\times \mbr^3; C'_{-T-\eps}),$ $ \tilde B_2^{\varphi, -}  = \sum_{k = 1}^3  \tilde B_2^{\varphi_k, -} \in I^{-2}(\mbr^3\times \mbr^3; C'_{-T-\eps}).$
Moreover, these operators can be expressed as in Lemmas \ref{lm-b12new} and \ref{lm-b34new}. The principal symbols of the operators are given by 
\beq
\begin{gathered}
\sigma_{-1}(\tilde B_{1}^{\varphi, -})(x, y, \xi) =   (-2\pi^2\imath \ln\frac{\eps}{T+\eps})  |\xi|^{-1} \varphi(\xi/|\xi|) \phi_\eps(x),\\
 \sigma_{-2}(\tilde B_{2}^{\varphi, -})(x, y, \xi) =  (2\pi^2  \ln\frac{\eps}{T+\eps})   |\xi|^{-2}  \varphi(\xi/|\xi|) \phi_\eps(x), 
\end{gathered}
\eeq
for $|\xi|$ large. 
\item $B_{1, 2, 2}^{\varphi, +} = \sum_{k = 1}^3 B_{1, 2, 2}^{\varphi_k, +} \in I^{-2}(\mbr^3\times \mbr^3; C'_{T-\eps})$,  $B_{2, 2, 2}^{\varphi, +} = \sum_{k = 1}^3 B_{2, 2, 2}^{\varphi_k, +}\in I^{-3}(\mbr^3\times \mbr^3; C'_{T-\eps})$, $B_{1, 2, 1}^{\varphi, -} = \sum_{k = 1}^3 B_{1, 2, 1}^{\varphi_k, -} \in I^{-2}(\mbr^3\times \mbr^3; C'_{-T+\eps}),$  $B_{2, 2, 1}^{\varphi, -}  = \sum_{k = 1}^3 B_{2, 2, 1}^{\varphi_k, -}  \in I^{-3}(\mbr^3\times \mbr^3; C'_{-T+\eps})$.

\item $R_l^{\varphi} = \sum_{k = 1}^3 R_l^{\varphi_k}, l=1, 2$ are regularizing operators.  \\
\end{enumerate}


Now we are ready to solve for $f_1, f_2$ from \eqref{eq-IL} and \eqref{eq-ILnew} modulo more regular terms. Assume that $f_1, f_2$ are supported in $\mcr_{T-1+2\eps, T+1-2\eps}$ for $\eps>0$ small. 
First, we can find a parametrix $Q^+ \in I^{1}(\mbr^3\times \mbr^3; C_{-T-\eps})$ such that $Q^+ \circ \tilde B_{1}^+ = \id$ on $\mcr_{T- 1 + 2\eps, T+1-2\eps}$ modulo a regularizing operator.  Here, we used that $\phi_\eps = 1$ on $\mcb_{1-2\eps}$. Applying $Q^+$ to \eqref{eq-IL}, we get 
\beqq\label{eq-q1} 
\begin{gathered}
 Q^+ I L_\eps u  
%=  f_1 + Q \tilde B_{1}^- f_1 +  Q B_{1, 2, 2}^+ f_1 + Q B_{1, 2, 1}^- f_1 \\
%+ Q \tilde B_{2}^+ f_2  + Q B_{2, 2, 2}^+ f_2 + Q \tilde B_{2}^- f_2 + Q B_{2, 2, 1}^- f_2 
%+ Q R_1 f_1 + Q R_2 f_2\\
 =  f_1 + Q^+ \tilde B_{1}^- f_1  + Q^+ \tilde B_{2}^+ f_2  + Q^+ \tilde B_{2}^- f_2  + \mci^{-1}(f_1) +\mci^{-2}(f_2), 
\end{gathered}
\eeqq
where we have denoted by $\mci^{m}(f)$ a collection of FIOs acting on $f$ that are of order at most $m$ and with canonical relations of the type $C_a$ with some $a\in \mbr.$  The specific forms of these operators will not be important for the analysis below. 
Next, we find a parametrix $Q^{\varphi, +} \in I^{1}(\mbr^3\times \mbr^3; C_{-T-\eps})$ such that $Q^{\varphi, +} \circ \tilde B_{\varphi, 1}^+ = \id$ on $\mcr_{T- 1 + 2\eps, T+1-2\eps}$ modulo a regularizing operator.  Applying $Q^{\varphi, +}$ to \eqref{eq-ILnew}, we get 
\beqq\label{eq-q2}
\begin{gathered}
Q^{\varphi, +} I^{\varphi} L_\eps u  
%=    f_1 +   Q^\varphi \tilde B_{1}^{\varphi, -} f_1 + Q^\varphi B_{1, 2, 2}^{\varphi, +} f_1 + Q^\varphi B_{1, 2, 1}^{\varphi, -} f_1\\
% + Q^\varphi \tilde B_{2}^{\varphi, +} f_2  + Q^\varphi B_{2, 2, 2}^{\varphi, +} f_2 +  Q^\varphi \tilde B_{2}^{\varphi, -} f_2 + Q^\varphi B_{2, 2, 1}^{\varphi, -} f_2 
%+ Q^\varphi R_1^{\varphi} f_1 + Q^\varphi R_2^{\varphi} f_2\\
 = f_1 +   Q^{\varphi, +} \tilde B_{1}^{\varphi, -} f_1  
 + Q^{\varphi, +} \tilde B_{2}^{\varphi, +} f_2  
   + Q^{\varphi, +} \tilde B_{2}^{\varphi, -} f_2  +\mci^{-1}(f_1) +\mci^{-2}(f_2). 
\end{gathered}
\eeqq
From \eqref{eq-q1} and \eqref{eq-q2}, we get 
\beqq\label{eq-q3} 
\begin{gathered}
 Q^+ I L_\eps u  - Q^{\varphi, +} I^{\varphi} L_\eps u 
 =   (Q^+ \tilde B_{1}^- - Q^{\varphi, +} \tilde B_{1}^{\varphi, -} )f_1  \\
 + (Q^+ \tilde B_{2}^+ - Q^{\varphi, +} \tilde B_{2}^{\varphi, +} )f_2  + (Q^+ \tilde B_{2}^- - Q^{\varphi, +} \tilde B_{2}^{\varphi, -} )f_2  + \mci^{-1}(f_1) +\mci^{-2}(f_2). 
\end{gathered}
\eeqq
We note that $Q^+ \tilde B_{1}^- - Q^{\varphi, +} \tilde B_{1}^{\varphi, -} \in I^{0}(\mbr^3\times \mbr^3; C'_{-2T-2\eps})$, and it can  be written as an oscillatory integral 
 \beqq\label{eq-symcal}
\begin{gathered}
(Q^+ \tilde B_{1}^- - Q^{\varphi, +} \tilde B_{1}^{\varphi, -}) f(z)   = (2\pi)^{-3} \int_{\mbr^3 }   \int_{\mbr^3 } e^{\imath(z - y)\cdot \xi} e^{\imath (-2T-2\eps)|\xi|} a(y, \xi)f(y)dy d\xi, 
\end{gathered}
\eeqq
where the principle symbol (the leading order term of $a$) is 
\beq
\sigma_0(Q^+ \tilde B_{1}^- - Q^{\varphi, +} \tilde B_{1}^{\varphi, -})(y, \xi) = (1 - \varphi(\xi/|\xi|)/\varphi(-\xi/|\xi|)) 
\eeq
for $y + (T+\eps)\xi/|\xi|\in \mcb_{1-2\eps}$. Note that the principal symbol is non-vanishing. Next, $Q^+ \tilde B_{2}^+ - Q^{\varphi, +} \tilde B_{2}^{\varphi, +} \in I^{-1}(\mbr^3\times \mbr^3; C'_{0})$ but the principal symbol vanishes so the term actually belongs to $\mci^{-2}(f_2)$. Finally, 
$ Q^+ \tilde B_{2}^- - Q^{\varphi,+} \tilde B_{2}^{\varphi, -} \in I^{-1}(\mbr^3\times \mbr^3; C'_{-2T-2\eps})$, and a similar calculation as \eqref{eq-symcal} shows that the principal symbol is 
 \beq
\sigma_{-1} (Q^+ \tilde B_{2}^- - Q^{\varphi,+} \tilde B_{2}^{\varphi, -} )(y, \xi) = \imath(1 - \varphi(\xi/|\xi|)/\varphi(-\xi/|\xi|))|\xi|^{-1}
\eeq
for $y + (T+\eps)\xi/|\xi|\in \mcb_{1-2\eps}$. Now we let $W^+\in I^{0}(\mbr^3\times \mbr^3; C'_{2T+2\eps})$ be a parametrix of $Q^+ \tilde B_{2}^+ - Q^{\varphi, +} \tilde B_{2}^{\varphi, +}$ and we get from \eqref{eq-q3} that 
\beqq\label{eq-q4}
\begin{gathered}
W^+ Q^+ I L_\eps u  - W^+ Q^{\varphi, +} I^{\varphi} L_\eps u 
 =   f_1    +  U^+ f_2  + \mci^{-1}(f_1) +\mci^{-2}(f_2), 
\end{gathered}
\eeqq
where $U^+$ is a pseudo-differential operator of order $-1$ with principal symbol $\imath |\xi|^{-1}$ on $\mcr_{T-1+2\eps, T+1-2\eps}$. 


Next we find a parametrix $Q^- \in I^{2}(\mbr^3\times \mbr^3; C_{T+\eps})$ such that $Q^- \circ \tilde B_{2}^- = \id$ on $\mcr_{T- 1 + 2\eps, T+1-2\eps}$ modulo a regularizing operator.  Applying $Q^-$ to \eqref{eq-IL}, we get 
\beqq\label{eq-q5} 
\begin{gathered}
 Q^- I L_\eps u  
%=  f_1 + Q \tilde B_{1}^- f_1 +  Q B_{1, 2, 2}^+ f_1 + Q B_{1, 2, 1}^- f_1 \\
%+ Q \tilde B_{2}^+ f_2  + Q B_{2, 2, 2}^+ f_2 + Q \tilde B_{2}^- f_2 + Q B_{2, 2, 1}^- f_2 
%+ Q R_1 f_1 + Q R_2 f_2\\
 =  f_1 + Q^- \tilde B_{1}^+ f_1  + Q^- \tilde B_{2}^+ f_2  + Q^- \tilde B_{2}^- f_2  + \mci^{-1}(f_1) +\mci^{-2}(f_2). 
\end{gathered}
\eeqq
Now we find a parametrix $Q^{\varphi, -} \in I^{1}(\mbr^3\times \mbr^3; C_{T+\eps})$ such that $Q^{\varphi, -} \circ \tilde B_{\varphi, 1}^- = \id$ on $\mcr_{T- 1 + 2\eps, T+1-2\eps}$ modulo a regularizing operator.  Applying $Q^{\varphi, -}$ to \eqref{eq-ILnew}, we get 
\beqq\label{eq-q6}
\begin{gathered}
Q^{\varphi, -} I^{\varphi} L_\eps u  
%=    f_1 +   Q^\varphi \tilde B_{1}^{\varphi, -} f_1 + Q^\varphi B_{1, 2, 2}^{\varphi, +} f_1 + Q^\varphi B_{1, 2, 1}^{\varphi, -} f_1\\
% + Q^\varphi \tilde B_{2}^{\varphi, +} f_2  + Q^\varphi B_{2, 2, 2}^{\varphi, +} f_2 +  Q^\varphi \tilde B_{2}^{\varphi, -} f_2 + Q^\varphi B_{2, 2, 1}^{\varphi, -} f_2 
%+ Q^\varphi R_1^{\varphi} f_1 + Q^\varphi R_2^{\varphi} f_2\\
 = f_1 +   Q^{\varphi, -} \tilde B_{1}^{\varphi, +} f_1  
 + Q^{\varphi, -} \tilde B_{2}^{\varphi, +} f_2  
   + Q^{\varphi, -} \tilde B_{2}^{\varphi, -} f_2  +\mci^{-1}(f_1) +\mci^{-2}(f_2). 
\end{gathered}
\eeqq
From \eqref{eq-q5} and \eqref{eq-q6}, we get 
\beqq\label{eq-q7} 
\begin{gathered}
 Q^- I L_\eps u  - Q^{\varphi, -} I^{\varphi} L_\eps u 
 =   (Q^- \tilde B_{1}^+ - Q^{\varphi, -} \tilde B_{1}^{\varphi, +} )f_1  \\
 + (Q^- \tilde B_{2}^+ - Q^{\varphi, -} \tilde B_{2}^{\varphi, +} )f_2  + (Q^- \tilde B_{2}^- - Q^{\varphi, -} \tilde B_{2}^{\varphi, -} )f_2  + \mci^{-1}(f_1) +\mci^{-2}(f_2). 
\end{gathered}
\eeqq
We note that $Q^- \tilde B_{1}^+ - Q^{\varphi, -} \tilde B_{1}^{\varphi, +} \in I^{0}(\mbr^3\times \mbr^3; C'_{2T+2\eps})$. Writing the operator as in \eqref{eq-symcal}, we find that the principal symbol is 
\beq
\sigma_0( Q^- \tilde B_{1}^+ - Q^{\varphi, -} \tilde B_{1}^{\varphi, +}  )(y, \xi) = 1 - \varphi(\xi/|\xi|)/\varphi(-\xi/|\xi|)
\eeq
for $y - (T+\eps)\xi/|\xi|\in \mcb_{1-2\eps}$.  Also, $Q^- \tilde B_{2}^- - Q^{\varphi, -} \tilde B_{2}^{\varphi, -} \in I^{-1}(\mbr^3\times \mbr^3; C'_{0})$ but the principal symbol is $0$ so the term belongs to $\mci^{-2}(f_2)$. Finally, $ Q^- \tilde B_{2}^+ - Q^{\varphi,-} \tilde B_{2}^{\varphi, +} \in I^{-1}(\mbr^3\times \mbr^3; C'_{2T+2\eps})$ and the principal symbol is 
 \beq
\sigma_{-1}(Q^- \tilde B_{2}^+ - Q^{\varphi,-} \tilde B_{2}^{\varphi, +})(y, \xi) = -\imath (1 - \varphi(\xi/|\xi|)/\varphi(-\xi/|\xi|))|\xi|^{-1}
\eeq
for $y - (T+\eps)\xi/|\xi|\in \mcb_{1-2\eps}$.  Now we let $W^-\in I^{0}(\mbr^3\times \mbr^3; C'_{2T+2\eps})$ be a parametrix of $Q^- \tilde B_{2}^+ - Q^{\varphi, -} \tilde B_{2}^{\varphi, +}$ and we get from \eqref{eq-q7} that 
\beqq\label{eq-q8}
\begin{gathered}
W^- Q^- I L_\eps u  - W^- Q^{\varphi, -} I^{\varphi} L_\eps u 
 =   f_1    +  U^- f_2  + \mci^{-1}(f_1) +\mci^{-2}(f_2), 
\end{gathered}
\eeqq
where $U^-$ is a pseudo-differential operator of order $-1$ with principal symbol $-\imath|\xi|^{-1}$. 


Finally, from \eqref{eq-q4} and \eqref{eq-q8}, we get 
\beqq\label{eq-q9}
\begin{gathered}
W^+ Q^+ I L_\eps u  - W^+ Q^{\varphi, +} I^{\varphi} L_\eps u - W^- Q^- I L_\eps u  + W^- Q^{\varphi, -} I^{\varphi} L_\eps u \\
 =  ( U^+ - U^-) f_2  +\mci^{-1}(f_1) +\mci^{-2}(f_2). 
\end{gathered}
\eeqq
Because $U^+ - U^-$ is a pseudo-differential operator of order $-1$ with symbol $2\imath |\xi|^{-1}$. We can find a parametrix $S$ which is a pseudo-differential operator of order $1$ with symbol $(2\imath)^{-1}|\xi|$. Thus we get from \eqref{eq-q9} that 
 \beqq\label{eq-q10}
\begin{gathered}
  f_2  = SW^+ Q^+ I L_\eps u  - SW^+ Q^{\varphi, +} I^{\varphi} L_\eps u - SW^- Q^- I L_\eps u  \\
  + SW^- Q^{\varphi, -} I^{\varphi} L_\eps u + \mci^0(f_1) +  \mci^{-1}(f_2). 
\end{gathered}
\eeqq
Then we can use \eqref{eq-q8} and \eqref{eq-q10} to solve for $f_1$ as
 \beqq\label{eq-q11}
\begin{gathered}
f_1 = W^- Q^- I L_\eps u  - W^- Q^{\varphi, -} I^{\varphi} L_\eps u 
     -  U^- f_2  + \mci^{-1}(f_1) +\mci^{-2}(f_2)\\
      =  W^- Q^- I L_\eps u  - W^- Q^{\varphi, -} I^{\varphi} L_\eps u\\
       -  U^- (SW^+ Q^+ I L_\eps u  - SW^+ Q^{\varphi, +} I^{\varphi} L_\eps u - SW^- Q^- I L_\eps u) 
      + \mci^{-1}(f_1) +\mci^{-2}(f_2). 
\end{gathered}
\eeqq

This concludes the microlocal inversion. In particular, we have solved $f_1, f_2$ up to more regular terms. We remark that it is possible to use \eqref{eq-q10} and \eqref{eq-q11} to analyze what singularities (wave front sets) of $f_1, f_2$ can be reconstructed from $L_\eps u$, even if $f_1, f_2$ are not compactly supported in $\mcr_{T-1 + 2\eps, T+1-2\eps}$. But we will not pursue it here. 



 %%%%%%%%%%%%%%%%%%%%%%%%%
\section{Proof of Theorem \ref{thm-main}} \label{sec-pf}
We start with the Sobolev estimates for recovering $f_1, f_2$. We recall the mapping properties of FIOs of graph type on Sobolev spaces, see \cite[Section 25.3]{Ho4}. In particular, for $A\in I^\mu(\mbr^3\times \mbr^3; C'_a),$ where $a\in \mbr$, $\mu\in \mbr$, we have for $s\in \mbr$ that 
\beq
\|A f\|_{H^{s}(\mbr^3)} \leq C \|f\|_{H^{s+\mu}(\mbr^3)}
\eeq 
for some $C>0$. Hereafter, we use $C$ for a generic constant which could depend on $\eps$ but is uniform in $f_1, f_2$. 
In \eqref{eq-q10}, we recall that $S\in \Psi^{-1}(\mbr^3), W^\pm \in \mci^0$, and $Q^{\varphi, \pm}, Q^{\pm} \in \mci^1$. We get from \eqref{eq-q10} that 
\beq
\|f_2\|_{H^s} \leq C(\|IL_\eps u\|_{H^s} + \|I^\varphi L_\eps u\|_{H^s}) + C \|f_1\|_{H^s} + C\|f_2\|_{H^{s-1}}. 
\eeq
Similarly, in \eqref{eq-q11}, we know that $U^\pm \in \Psi^{-1}(\mbr^3)$. We get 
\beq
\|f_1\|_{H^s} \leq C(\|I L_\eps u\|_{H^{s+1}} + \|I^\varphi L_\eps u\|_{H^{s+1}} ) + C\|f_1\|_{H^{s-1}} + C\|f_2\|_{H^{s-2}}. 
\eeq 
From these two estimates,  we obtain that 
\beq
\|f_1\|_{H^{s+1}} + \|f_2\|_{H^{s}} \leq C (\|I L_\eps u\|_{H^{s+2}} + \|I^\varphi L_\eps u\|_{H^{s+2}} ) + C\|f_1\|_{H^{s}} + C\|f_2\|_{H^{s-1}}. 
\eeq
We observe that for $s + 2 \geq 0$ an integer, 
\beq
\|I L_\eps u\|_{H^{s+2}} \leq C \|L u\|_{H^{s+2}}, \quad \|I^\varphi L_\eps u\|_{H^{s+2}} \leq C \|L u\|_{H^{s+2}}, 
\eeq
which can be seen by directly estimating the integral in $I$ and $I^\varphi.$ 
Thus 
\beqq\label{eq-sob}
\|f_1\|_{H^{s+1}} + \|f_2\|_{H^{s}} \leq C \|L u\|_{H^{s+2}}   + C\|f_1\|_{H^{s}} + C\|f_2\|_{H^{s-1}}. 
\eeqq

Next, we remove the last two terms. We will need the following uniqueness result for the light ray transform with partial data. 
 \begin{lemma}\label{lm-inj}
 Let $u\in H^s(\mcm), s\geq 0$ and $Lu = 0$. Then $u = 0$ on the set 
 \beqq\label{eq-bcone}
 \{(t, x)\in \mcm :  T-t \leq |x| < T+ 1 - t \}.
 \eeqq
\end{lemma}
\bpf
Let $\phi(x)$ be the characteristic function of $\mcb$ in $\mbr^3$. Let $\chi(t)$ be the characteristic function of $[0, T]$ in $\mbr.$ We write  
\beq 
Lu(y, v) = \int_{\mbr}\chi(t)\phi(y)u(t, y+ tv - Tv) dt, 
\eeq
where $y\in \mbr^3, v\in \mbs^2.$ We follow the proof of the Fourier Slice Theorem to compute that 
\beqq\label{eq-A}
\begin{gathered}
0 = \int_{\mbr^3} e^{-\imath y \cdot \xi} Lu(y, v) dy = \int_{\mbr^3} e^{-\imath y \cdot \xi} \chi(t)\phi(y)u(t, y+ tv - Tv) dt dy\\
 =  \int_{\mbr^3} e^{-\imath (x - tv + Tv) \cdot \xi} \chi(t)\phi(x - tv + Tv)u(t, x) dt dx = e^{-\imath Tv\cdot \xi} \hat A(-v\cdot \xi, \xi), 
\end{gathered}
\eeqq
where $\hat A(\tau, \xi)$ is the Fourier transform of $A(t, x) = \chi(t)\phi(x - tv + Tv)u(t, x)$. Note that $A$ is compactly supported in $\mbr^{3+1}$ so $\hat A$ is analytic. We see from \eqref{eq-A} that $\hat A$ vanishes on some open set with non-empty interior. Thus $\hat A$ is identically zero. So we get  
$ \chi(t)\phi(x - tv + Tv)u(t, x) =0$ so $u$ vanishes on the set \eqref{eq-bcone}. 
\epf

\bpf[Proof of Theorem \ref{thm-main}]
Let $f_1 \in H^{s+1}, f_2\in H^{s}, s\geq 0$ be compactly supported in $\mcr_{T-1, T+1}$. Then there exists $\eps>0$ such that \eqref{eq-sob} holds with $C$ depending on $\eps$. We prove \eqref{eq-mainest}, that is, 
\beq
\|f_1\|_{H^{s+1}} + \|f_2\|_{H^s} \leq C \|Lu\|_{H^{s+2}}.
\eeq
By contradiction, we assume that for $n = 1, 2, \cdots,$ there are $f_1^n \in H^{s+1}, f_2^n \in H^{s}$ compactly supported in $\mcr_{T-1, T+1}$ such that $\|f_1\|_{H^{s+1}} = 1, \|f_2\|_{H^s} =1$, and 
\beqq\label{eq-con}
\|f_1^n\|_{H^{s+1}} + \|f_2^n\|_{H^s} \geq n \|Lu^n\|_{H^{s+2}}, 
\eeqq
where $u^n$ is the solution of \eqref{eq-cau} with Cauchy data $f_1^n, f_2^n.$ First, we note that on a fixed compact set, $H^{s+1}\times H^s$ is compactly embedded in $H^{s}\times H^{s-1}$. Thus by passing to a subsequence, we can assume that $(f_1^n, f_2^n)$ converges in $H^s\times H^{s-1}$, and it follows from \eqref{eq-sob} that $(f_1^n, f_2^n)$ converges to some $(f_1, f_2)$ in $H^{s+1}\times H^s.$ For the Cauchy problem \eqref{eq-cau}, we have the standard energy estimate
\beq
\|u\|_{H^{s+1}}\leq C(\|f_1\|_{H^{s+1}} + \|f_2\|_{H^s}).
\eeq
Therefore, $u^n$ converges to $u$ in $H^{s+1}$. We get from \eqref{eq-con} that $0 = \|Lu\|_{H^{s+2}} \geq \|Lu\|_{H^{s+1}}$. By Lemma \ref{lm-inj} and the finite speed of propagation for \eqref{eq-cau}, we deduce that $f_1 = f_2 = 0$. But this contradicts \eqref{eq-sob}. Thus, we proved \eqref{eq-mainest}, and this completes the proof of Theorem \ref{thm-main}. 
\epf



