\end{center}
\caption{Schematics of a triangular lattice with $J$ representing the Heisenberg exchange interaction, and ${D}_{ij}$ representing in-plane DMI vectors in directions perpendicular to bonds between neighboring $i$ and $j$ spin sites.}
\label{fig1}
