	\centerline{
		\includegraphics[width=0.35\textwidth]{figuras/grafo-vcg-exemplo1.pdf}
	}
	\caption{Grafo de restrições verticais para uma netlist, onde cada vértice representa uma net. No exemplo, a net relativa ao vértice 0 restringe de alguma forma o posicionamento de segmentos do vértice 2.}
	\label{fig:grafo-vcg-exemplo}
\end{figure}

\subsection{Algoritmo}

O Algoritmo \ref{alg-roteamento} é implementado como a principal rotina do programa, e tem a responsabilidade de receber uma estrutura de dados para uma lista de nets como entrada, já carregada por outras sub-rotinas do programa, retornando ao final uma lista de trilhas (tracklist), que nada mais é que um conjunto de listas ordenadas de segmentos. A ordem estabelecida, no caso destes segmentos, é a de um percurso possível para a corrente elétrica. Temos aqui a função NOVA-LINHA no algoritmo, que serve para escolher uma nova linha para posicionamento dos segmentos horizontais que, não entre em conflito com outros segmentos horizontais já posicionados, e que busque um melhor aproveitamento do espaço do canal.

\begin{algorithm}
	\caption{Gerar o roteamento para uma netlist.}
	\label{alg-roteamento}
	\begin{algorithmic}[1]
		\Statex
		\Require NL (lista de conjuntos de terminais conectados).
		\Ensure TL (lista de conjuntos de segmentos de reta respectivo a cada conjunto da lista NL de entrada).
		\Statex
		\Procedure{Rotear}{NL, TL, sucesso}
			\State MINLINHA = 1
			\State MAXLINHA = máx. núm. de linhas de grid
			\State MINCOLUNA = 0
			\State MAXCOLUNA = máx. núm. de colunas de grid
			\Statex
			\State vcg = obterVcg(NL)
			\State hcg = obterHcg(NL)
			\State info = obterInfo(NL)
			\Statex
			\ForAll{net in NL}
				\State esq(net) = terminal mais à esquerda na net
			\EndFor
			\Statex
			\State \Call{ORDENAR}{NL, esq(net)} \Comment{odenar NL por ordem de terminal mais à esquerda em cada conjunto}
			\Statex
			\State linha = MAXLINHA / 2
			\State coluna = 0
			\State camada = 0
			\State trilha = []
			\Statex
			\ForAll{net in NL}
				\State x0 = net.terminal[0].coluna
				\State y0 = net.terminal[0].linha
				\State xN = net.terminal[1].coluna
				\State yN = net.terminal[1].linha
				\Statex
				\If {terminais na mesma coluna}
					\State segmento = [camada, (x0, y0), (xN, yN) ]
					\State \Call{Anexa}{trilha, segmento}
				\Else
					\State segmento = [ (x0, y0), (x0, linha) ]
					\State \Call{Anexa}{trilha, camada, segmento}
					\State segmento = [ (x0, linha), (xN, linha) ]
					\State \Call{Anexa}{trilha, camada+1, segmento}
					\State segmento = [ (xN, linha), (xN, yN) ]
					\State \Call{Anexa}{trilha, camada, segmento}
					\State linha = NOVA-LINHA(vgc, hcg, info, TL)
					\If {linha == NIL}
						\State sucesso = False
						\State \Return
					\EndIf
				\EndIf
			\EndFor
			\Statex
			\State sucesso = True
			\State NL = trilha
			\Statex
		\EndProcedure

	\end{algorithmic}
\end{algorithm}

