    Next, call a block $b_i$ of $X^*$ \textit{overworked} if $|s_i| \geq (1+\alpha) m$. Call the rest of the blocks in $X^*$ \textit{good}. We have the following observations.
    \begin{obs}
        If $b_i$ is a bad block, then $\ed(b_i, s_i)=0$.
    \end{obs}
    \begin{proof}
    \renewcommand\qedsymbol{$\lrcorner$}
    This follows from the definition of a bad block. 
    \end{proof}
    \begin{obs}
        If a block $b_i$ is either overworked or good, then $\ed(b_i, s_i) \geq \alpha m$
    \end{obs}
    \begin{proof}
        \renewcommand\qedsymbol{$\lrcorner$}
        If $b_i$ is overworked, then $\ed(b_i, s_i) \geq |s_i| - |b_i| \geq \alpha m$. If $b_i$ is good, then since $|s_i|< (1+\alpha)m < 2m$, $s_i$ can intersect at most three consecutive blocks in $Y^*$. Let us call these blocks $b'_{i'-1}, b'_{i'}$ and $b'_{i'+1}$ for some $i'\in [p]$. By Remark~\ref{rem: three-distinct}, all three of these blocks are instantiations of distinct elements from $\mathcal{C}$. Now let $c_i, c_{i'-1}, c_{i'}, c_{i'+1}\in\mathcal{C}$ be strings such that $b_i, b'_{i'-1}, b'_{i'}, b'_{i'+1}$ are instantiations of $c_i, c_{i'-1}, c_{i'}, c_{i'+1}$, respectively.  If none of $c_{i'-1}, c_{i'}, c_{i'+1}$ are equal to $c_i$, then by Property~\ref{prop: full-block-distance-1} of misaligners, we have $\ed(b_i, s_i) \geq \alpha m$. Furthermore, if exactly one, say $c_{i'-1}$ is equal to $c_i$, then there does not exist $j\in[m]$ such that $\mathcal{A}^*$ aligns $b_i[j]$ to $b'_{i'-1}[j]$ since otherwise, by Observation~\ref{obs:bad-blocks} and our assumption on $\mathcal{A}^*$, $b_i$ would be a bad block. Therefore, we can apply Property~\ref{prop: full-block-distance-2} to get $\ed(b_i, s_i) \geq \alpha m$.
    \end{proof}
We also have the following observations regarding the first partial block $b_0$.
\begin{obs}
    If $b_1$ is a bad block, then $\ed(b_0, s_0) \geq \alpha |b_0|$
\end{obs}
\begin{proof}
\renewcommand\qedsymbol{$\lrcorner$}
    If $b_1$ is a bad block, then $b'_{0}\circ b'_1$ is a prefix of $s_0$. Since $\alpha<1$, $|s_0| \geq |b'_{0}\circ b'_1| \geq (1+\alpha)|b_0|$. So, $\ed(b_0, s_0) \geq |s_0|-|b_0| \geq \alpha b_0$.
\end{proof}
\begin{obs}
    If $b_1$ is not a bad block, then $\ed(b_0\circ b_1, s_0\circ s_1) \geq \alpha(|b_0|+|b_1|)$.
\end{obs}
\begin{proof}
\renewcommand\qedsymbol{$\lrcorner$}
    If $|s_0\circ s_1| \geq (1+\alpha)(|b_0|+ |b_1|)$, then we are done. If $|s_0\circ s_1| < (1+\alpha)(|b_0|+ |b_1|)$, then since $\alpha\leq \frac{1}{2}$, $s_0\circ s_1$ must be a prefix of $b'_{0}\circ b'_{1}\circ b'_2$. By Property~\ref{prop: boundary-blocks-1} of misaligners, it then follows that $\ed(b_0\circ b_1, s_0\circ s_1) \geq \alpha(|b_0|+|b_1|)$. 
\end{proof}
Similar statements for the final partial block $b_{p+1}$ also hold with essentially the same proofs.
\begin{obs}
    If $b_p$ is a bad block, then $\ed(b_{p+1}, s_{p+1}) \geq \alpha |b_{p+1}|$
\end{obs}
\begin{obs}
    If $b_p$ is not a bad block, then $\ed(b_p\circ b_{p+1}, s_p\circ s_{p+1}) \geq \alpha(|b_p|+|b_{p+1}|)$.
\end{obs}
We can now give a lower bound for $\cost(\mathcal{A}^*)$. We claim the following.
\begin{claim}
$\cost(\mathcal{A}^*) \geq (1-\varepsilon)\alpha |I|$
\end{claim}
\begin{proof}
    \renewcommand\qedsymbol{$\lrcorner$}
    We break it the proof into four cases depending on whether or not $b_1$ and $b_{p}$ are bad.

    \begin{itemize}
        \item \textbf{Case 1: Both $b_1$ and $b_p$ are bad.}

        In this case, we have:\allowdisplaybreaks
        \begin{align*}
            \cost(\mathcal{A}^*) &\geq \sum_{i=0}^{p+1}\ed(b_i, s_i)\\
            &= \ed(b_0, s_0) + \ed(b_{p+1}, s_{p+1}) + \sum_{i=1}^{p}\ed(b_i, s_i) \\
            &\geq \alpha|b_0| + \alpha|b_{p+1}| + \left(\sum_{\substack{{b_i \textnormal{ is bad}}\\{1\leq i \leq p}}}\ed(b_i, s_i) + \sum_{\substack{{b_i \textnormal{ is not bad}}\\{1\leq i \leq p}}}\ed(b_i, s_i)\right) \\
            &\geq \alpha(|b_0|+|b_{p+1}|) + (0 + (1-\varepsilon)p\alpha m)\\
            &\geq (1-\varepsilon)\alpha(|b_0|+|b_{p+1}|) + (1-\varepsilon)p\alpha m\\
            &= (1-\varepsilon)\alpha(|b_0|+|b_{p+1}|+pm)\\
            &= (1-\varepsilon)\alpha|I|
        \end{align*}
        \item \textbf{Case 2: $b_p$ is bad but $b_1$ is not.}

        In this case, we have:
        \begin{align*}
            \cost(\mathcal{A}^*) &\geq \sum_{i=0}^{p+1}\ed(b_i, s_i)\\
            &=\ed(b_0\circ b_1, s_0\circ s_1) + \ed(b_{p+1}, s_{p+1}) + \sum_{i=2}^{p}\ed(b_i, s_i)\\
            &\geq \alpha(|b_0|+|b_1|) + \alpha|b_{p+1}| + \left(\sum_{\substack{{b_i \textnormal{ is bad}}\\{2\leq i \leq p}}}\ed(b_i, s_i) + \sum_{\substack{{b_i \textnormal{ is not bad}}\\{2\leq i \leq p}}}\ed(b_i, s_i)\right) \\
            &\geq \alpha(|b_0|+b_{p+1}) + \alpha |b_1| + (0+((1-\varepsilon)p-1)\alpha m)\\
            & = \alpha(|b_0|+b_{p+1}) + (1-\varepsilon)p\alpha m\\
            &\geq (1-\varepsilon)\alpha(|b_0|+|b_{p+1}|) + (1-\varepsilon)p\alpha m\\
            &= (1-\varepsilon)\alpha(|b_0|+|b_{p+1}|+pm)\\
            &= (1-\varepsilon)\alpha|I|
        \end{align*}
        \item \textbf{Case 3: $b_1$ is bad but $b_p$ is not.}

        This case is essentially identical to Case 2.
        \item \textbf{Case 4: Neither $b_1$ nor $b_p$ are bad.}

        Again, we have:
        \begin{align*}
            \cost(\mathcal{A}^*) &\geq \sum_{i=0}^{p+1}\ed(b_i, s_i)\\
            &=\ed(b_0\circ b_1, s_0\circ s_1)+\ed(b_p\circ b_{p+1}, s_p\circ s_{p+1})+ \sum_{i=2}^{p-1}\ed(b_i, s_i)\\
            &\geq \alpha(|b_0|+|b_1|) +\alpha(|b_p|+|b_{p+1}|)+ \left(\sum_{\substack{{b_i \textnormal{ is bad}}\\{2\leq i \leq p-1}}}\ed(b_i, s_i) + \sum_{\substack{{b_i \textnormal{ is not bad}}\\{2\leq i \leq p-1}}}\ed(b_i, s_i)\right)\\
            &\geq \alpha(|b_0|+|b_1|) +\alpha(|b_p|+|b_{p+1}|) + (0+((1-\varepsilon)p-2)\alpha m)\\
            & = \alpha(|b_0|+|b_{p+1}|) + (1-\varepsilon)p\alpha m\\
            &\geq (1-\varepsilon)\alpha(|b_0|+|b_{p+1}|) + (1-\varepsilon)p\alpha m\\
            &= (1-\varepsilon)\alpha(|b_0|+|b_{p+1}|+pm)\\
            &= (1-\varepsilon)\alpha|I|
        \end{align*}
    \end{itemize}
\end{proof}
Now recall that we had $t\geq \frac{1}{(1-\varepsilon)\alpha -\frac{1}{3m-1}}$. Since $|I|\geq 3m-1$, this means $t\geq \frac{1}{(1-\varepsilon)\alpha -\frac{1}{|I|}}$. Multiplying and rearranging, we get:
\[\cost(\mathcal{A}^*) \geq (1-\varepsilon)\alpha |I| \geq \frac{|I|}{t} +1\]
Since $\frac{|I|}{t}+1$ is an upper bound on $\ham(X_{|I}, Y_{|I})$, $\cost(\mathcal{A}^*) < \ham(X_{|I}, Y_{|I})$ cannot hold, and hence $\cost(\mathcal{A}_{|I}) < \ham(X_{|I}, Y_{|I})$ cannot hold --- a contradiction!
\end{proof}



\section{An Explicit Constant Rate Embedding for Binary Strings}
\label{sec:explicit-const}

In this section, we give an isometric embedding of the Hamming metric into the edit metric with rate $\frac{1}{8}$ thus proving Theorem~\ref{cor:explicit}. The first step of the proof is showing the existence of a misaligner with a specific set of parameters.

\begin{lemma}
\label{lemma:misaligner-exists}
    A $(320, 676, 8, 0.1625)$-misaligner exists. 
\end{lemma}
\begin{proof}
We show the existence of a $(320, 676, 8, 0.1625)$-misaligner via a computer search. The elements of the misaligner and the code used to find them can be seen in \cite{Code}. A high-level description of the code can also be found in Appendix~\ref{sec:misaligner-code-description}.  
\end{proof}


%Code: \cite{code}

By Theorem~\ref{thm:main}, in order to obtain a rate $\frac{1}{8}$-isometric embedding from a $(320, 676, 8, 0.1625)$-misaligner, it suffices to have a $0.224$-locally self-matching string over an alphabet of size 676. Theorem~\ref{thm:lll-string} guarantees the existence of a $0.224$-locally self-matching string over an alphabet of size only 553. Thus, we are done with room to spare!

\begin{theorem}
    \label{thm:rate-1/8}
    For every positive integer $n$, there exists an isometric embedding $\varphi_n: \{0, 1\}^n \to \{0, 1\}^{8n}$ of the Hamming metric into the edit metric.
\end{theorem}



\section{Embeddings for Strings over Larger Alphabets}

\label{sec:close-to-1/3}

So far, we have focused entirely on finding the best possible rate of an isometric embedding that maps binary strings to binary strings. However, it is natural to ask what happens if we consider larger alphabets. Let $\Sigma$ be an arbitrary alphabet, and consider an isometric embedding $\varphi:\Sigma^n \to \Sigma^N$ of the Hamming metric into the edit metric.  What is the highest rate $\varphi$ could possibly have?

As in the binary case, we can try to tackle this question by using misaligners for larger alphabets. In fact, it is not hard to see that misaligners designed for the binary alphabet also function as misaligners for larger alphabets, without any loss in parameters. Therefore, increasing the alphabet size can only improve the achievable rate.

In this section, we show that even without relying on the full machinery of misaligners, one can obtain isometric embeddings with rates arbitrarily close to $\frac{1}{3}$ by making the alphabet large enough.

\begin{theorem}
\label{thm:rate-close-to-1/3}
    For any $\rho>0$, there exists an alphabet $\Sigma$ and a family of functions $\varphi_n:\Sigma^n\to\Sigma^N$ for each positive integer $n$ such that the following hold.
    \begin{enumerate}
        \item For every $n$, $\varphi_n$ is an isometric embedding of the Hamming metric into the edit metric, i.e., for all $x, y\in \Sigma^n$, we have $\ed\left(\varphi_n(x), \varphi_n(y)\right) = \ham(x, y)$.
        \item The rate of $\varphi_n$ is at least $\frac{1}{3}-\rho$, i.e., $\frac{n}{N}\geq \frac{1}{3}-\rho$.
    \end{enumerate}
\end{theorem}


\begin{proof}
Fix any $\rho>0$ and define $R:= \frac{1}{3}-\rho$. Let $\varepsilon := \frac{1-3R}{1-R}$ and $\varepsilon'=\frac{\varepsilon}{2}$. We will choose $\Sigma=\left[\left\lceil\frac{5e^2}{\varepsilon'^2}\right\rceil\right]$ as our alphabet.

Fix any positive integer $n$. Our embedding map $\varphi_n:\Sigma^n\to \Sigma^N$ is defined as follows. First, note that we may assume without loss of generality that $R$ is rational, so let $R=\frac{a}{b}$ for coprime positive integers $a$ and $b$. Define $q:= \lfloor\frac{b}{a}\rfloor$, $r:= b-aq$, and $m:= \lfloor\frac{n}{a}\rfloor$. 

Next, fix any $\varepsilon'$-locally self-matching string $w$ of length $n':=m(q-1+r)+(n-m)(q-1)$ over $\Sigma$. Since $R\leq \frac{1}{4}$, $\varepsilon'\leq \frac{1}{2}$ and by Theorem~\ref{thm:lll-string}, $\Sigma$ is large enough for such a string $w$ to always exist. 

Now, partition $w$ into $n$ contiguous substrings $w^{(1)}, w^{(2)}, \ldots , w^{(n)}$ so that every $a^{\text{th}}$ substring in this sequence has length $(q-1+r)$ while all other substrings have length $(q-1)$. Since $m=\lfloor\frac{n}{a}\rfloor$, exactly $m$ of the $w^{(i)}$'s have length $(q-1+r)$ while the remaining have length $(q-1)$. Thus, the total length of the $w^{(i)}$'s indeed sums to $m(q-1+r)+(n-m)(q-1)=n'$. 

Finally, given any $x\in \Sigma^n$, define $\varphi_n(x)\in\Sigma^N$ as follows.
\[\varphi_n(x)=x[1]\circ w^{(1)}\circ x[2]\circ w^{(2)}\circ \cdots x[n]\circ w^{(n)}\]

Let us first show that the rate of $\varphi_n$, which is given by the expression $\frac{n}{n+n'}$ is indeed at least $R$.
\allowdisplaybreaks
\begin{align*}
    \frac{n}{n+n'} & = \frac{n}{n+m(q-1+r)+(n-m)(q-1)}\\
    &=\frac{n}{m(q+r)+(n-m)q}\\
    &= \frac{n}{mr+nq}\\
    &= \frac{n}{\lfloor \frac{n}{a}\rfloor\cdot r + nq}\\
    &\geq \frac{n}{\frac{n}{a}\cdot r + nq}\\
    & = \frac{a}{r+aq}\\
    & = \frac{a}{b}\\
    & = R
\end{align*}
In fact, it is not hard to see that not only is the rate $R$ globally but also locally, i.e., for any substring of the output string, roughly an $R$-fraction of the symbols come from the input string. We will need the following observation later in our analysis.

\begin{obs}
    \label{obs:input-density}
    For all $x\in\Sigma^n$ and for all substrings $w'$ of $\varphi_n(x)$, the number of symbols in $w'$ coming from $x$ is at most $R|w'|+1$ and at least \(R|w'|-1\).
\end{obs}

Now, we show that $\varphi_n$ is indeed isometric for every positive integer $n$. Suppose not; then there exists a positive integer $n$ and $x, y\in \Sigma^n$ such that $\ed(\varphi_n(x), \varphi_n(y))<\ham(x, y)$. Let $X:=\varphi_n(x), Y:=\varphi_n(y)$, and $\mathcal{A}$ be any optimal edit distance alignment between $X$ and $Y$. Since $\ham(x, y) = \ham(X, Y)$, by assumption, we have $\cost(\mathcal{A}) < \ham(X, Y)$. Similar to the proof of Theorem~\ref{thm:main}, consider the partition of $[N]$ into alternating maximal vertical and maximal nowhere-vertical intervals under $\mathcal{A}$. By the same argument as in the proof of Theorem~\ref{thm:main}, there must exist a nowhere-vertical interval $I$ in this partition such that $\cost(\mathcal{A}_{|I}) < \ham(X_{|I}, Y_{|I})$. 

Call a symbol in $X$ or $Y$ \textit{frozen} if it comes from the locally self-matching string $w$, and \textit{mutable}, otherwise. We can assume without loss of generality that \(X_{|I}\) and \(Y_{|I}\) both start with mutable symbols; otherwise, we can modify \(\mathcal{A}\) by aligning the first symbols of \(X_{|I}\) and \(Y_{|I}\), producing a new alignment that can only be cheaper. By the same argument, we may assume that \(X_{|I}\) and \(Y_{|I}\) also end in mutable symbols.

Finally, let \(s\) be the string obtained from \(X_{|I}\) by removing all mutable symbols from \(X_{|I}\).  We will now show that $\cost(\mathcal{A}_{|I})<\ham(X_{|I}, Y_{|I})$ cannot hold by considering two cases based on the length of $I$.
\begin{itemize}
    \item \textbf{Case 1: $|I|< \frac{1}{1-R}\left(\frac{8}{\varepsilon}+1\right)$.}

    In this case, our construction of the $\frac{\varepsilon}{2}$-locally self-matching string $w$ ensures that every frozen symbol in \(X_{|I}\) is distinct and so, \(\slcs(s, s)=0\). Let \(k\) be the number of mutable symbols in \(X_{|I}\) (or equivalently \(Y_{|I}\)). We analyze two subcases.
    \begin{itemize}
        \item \textbf{Case 1a: \(|I|\) is a multiple of 3.}

        In this case, \(k\leq \frac{|I|}{3}\) since in every three consecutive symbols in \(X_{|I}\), at most one is mutable. Given \(\cost(\mathcal{A}_{|I}) <\ham(X_{|I}, Y_{|I}) \leq k\leq\frac{|I|}{3}\), we deduce that \(\slcs(X_{|I}, Y_{|I}) > \frac{2|I|}{3}\). However, this would mean \(\slcs(s, s)\geq \slcs(X_{|I}, Y_{|I}) - 2k >0\), which is a contradiction.

        \item  \textbf{Case 1b: \(|I|\) is not a multiple of 3.}

        \begin{sloppypar}

        In this case, \(k\leq \lfloor\frac{|I|}{3}\rfloor+1\). Once again, by assumption, we have \(\cost(\mathcal{A}_{|I}) <\ham(X_{|I}, Y_{|I}) \leq k\leq\left\lfloor\frac{|I|}{3}\right\rfloor+1\). So, \(\slcs(X_{|I}, Y_{|I}) > |I|-\left\lfloor\frac{|I|}{3}\right\rfloor-1\). We now make use of the fact that both the first and last symbols of \(X_{|I}\) and \(Y_{|I}\) are mutable. Because of this, the first symbols of \(X_{|I}\) and \(Y_{|I}\) cannot both participate in a nowhere-vertical common subsequence. The same is true for the last symbols of \(X_{|I}\) and \(Y_{|I}\). Thus, \(\slcs(s, s)\geq \slcs(X_{|I}, Y_{|I}) - 2k -2 >|I|-3\lfloor\frac{|I|}{3}\rfloor-1\geq 0\), again yielding a contradiction.
        \end{sloppypar}

    \end{itemize}

\item \textbf{Case 2: $|I|\geq \frac{1}{1-R}\left(\frac{8}{\varepsilon}+1\right)$.}

By Observation~\ref{obs:input-density}, $(1-R)|I|+1\geq |s| \geq (1-R)|I|-1$. Since $s$ is a substring of a $\frac{\varepsilon}{2}$-locally self-matching string, we must have
    \(
    \slcs(s, s) \leq \frac{\varepsilon}{2} |s|.
    \)
    Furthermore, since $|I| \geq \frac{1}{1-R}\left(\frac{8}{\varepsilon}+1\right)$, we have $|s| \geq (1-R)|I|-1 \geq \frac{8}{\varepsilon}$. And for any \(|s|\geq \frac{8}{\varepsilon}\), we must have \(\frac{\varepsilon}{2}|s| \leq \varepsilon|s|-4\). Consequently,
    \begin{align}
    \slcs(s, s) \leq \frac{\varepsilon}{2} |s| \leq \varepsilon|s|-4 \leq \varepsilon((1-R)|I|+1)-4 \leq \varepsilon(1-R)|I| - 3 \label{ineq:slcs-ub}
    \end{align}
    Meanwhile, since $\cost(\mathcal{A}_{|I}) < \ham(X_{|I}, Y_{|I}) \leq R|I| + 1$, it follows that
    \(
    \slcs(X_{|I}, Y_{|I}) > (1-R)|I| - 1.
    \)
    So, by the same argument as before,
    \begin{align}
    \slcs(s, s) > (1-R)|I| + 1 - 2(R|I| + 1) > (1-3R)|I| - 3 \label{ineq:slcs-lb}
    \end{align}
    Combining inequalities (\ref{ineq:slcs-ub}) and (\ref{ineq:slcs-lb}) yields:
    \[
    \varepsilon(1-R)|I| - 3 > (1-3R)|I| - 3,
    \]
    which simplifies to $\varepsilon > \frac{1-3R}{1-R}$, a contradiction.

\end{itemize}


\end{proof}

\begin{remark}
    Although Theorem~\ref{thm:rate-close-to-1/3} gives isometric embeddings with rates arbitrarily close to \(\frac{1}{3}\), these embeddings do not have the best rate vs. alphabet size tradeoff. In particular, Theorem~\ref{thm:rate-close-to-1/3} gives a rate \(\frac{1}{8}\) embedding over an alphabet of size 290. In contrast, Theorem~\ref{thm:rate-1/8} achieves the same rate using only a binary alphabet. Therefore, for a better rate-to-alphabet size tradeoff, one should opt for misaligner-based embeddings.
\end{remark}

\section{Embeddings without Interleaving?}
\label{sec:isometry-implies-interleaving}
For now, let us again return to considering only binary strings. Our embedding from Section~\ref{sec:embedding} is an example of what we might call an \textit{interleaved embedding}, where the output string is constructed by interleaving the input bits with sequences of bit strings that do not depend on the input. One might ask whether there exist isometric embeddings, potentially with better rates, that do not follow this interleaving framework. In this section, we show that the answer is no. In particular, we show that \textit{every} isometric embedding of the Hamming metric into the edit metric must be, in a sense, an interleaved embedding.

To prove this claim, one must formally define interleaved embeddings. Our definition is going to naturally extend the intuitive notion of interleaving input bits with fixed bit patterns by allowing two additional flexibilities. First, we will allow the input bits to appear \textit{out-of-order} --- e.g., the second input bit might appear after the first input bit in the output string. Second, we will allow some of the input bits to appear \textit{complemented} in the output string.
\begin{defi}[Interleaved Embedding]
\label{def:interleaved-embedding}
    A function $\varphi:\{0, 1\}^n \to \{0, 1\}^N$ with $N\geq n$ is called an {interleaved embedding} if there exist ---
    \begin{itemize}
        \item an injective function $\eta : [n] \to [N]$,
        \item a collection of functions $\pi_1, \pi_2, \ldots , \pi_n: \{0, 1\} \to \{0, 1\}$ such that for each $i\in[n]$, $\pi_i(b) =b $ or $\pi_i(x)=1-{b}$ for all $b\in \{0, 1\}$, and
        \item a fixed string $w\in \{0, 1\}^{N-n}$,
    \end{itemize}
    such that for all $x\in \{0, 1\}^n$, if $X=\varphi(x)$, then the following hold.
    \begin{itemize}
        \item For all $i\in [n]$, $X[\eta(i)]= \pi_i(x[i])$.
        \item Let $S\subseteq [N]$ be the set of indices that are not in the image of $\eta$, i.e., $S=\{j\in [N]: \nexists i \textnormal{ with } \eta(i) = j\}$. Then $X_{|S}=w$.
    \end{itemize}

\end{defi}
Definition~\ref{def:interleaved-embedding} captures all functions that interleave the input bits with sequences of fixed bit strings, following a Hamming distance preserving preprocessing of the input space. This preprocessing involves applying a fixed permutation to the input bits and flipping a chosen subset of them. We now show that this framework is expressive enough to represent all isometric embeddings of the Hamming metric into the edit metric.

\begin{theorem}
    \label{thm:isometry-implies-interleaving}
    If $\varphi: \{0, 1\}^n \to \{0, 1\}^N$ is an isometric embedding of the Hamming metric into the edit metric, then $\varphi$ is necessarily an interleaved embedding.
\end{theorem}
\begin{proof}
    Fix any arbitrary isometric embedding $\varphi:\{0, 1\}^n \to \{0, 1\}^N$ of the Hamming metric into the edit metric. We begin by setting up some notation. For each $x\in \{0, 1\}^n$ and $i\in [n]$, let us denote by $x^{\oplus i}$ the bit string obtained by flipping the $i^{\textnormal{th}}$ bit in $x$. Now fix any $x\in \{0, 1\}^n$ and $i\in [n]$. Since $\varphi$ is an isometric embedding of the Hamming metric into the edit metric, we have $\ed(\varphi(x), \varphi(x^{\oplus i})) = \ham(x, x^{\oplus i}) = 1$. It follows that there exists an index $k\in [N]$ such that $\varphi(x^{\oplus i}) = \varphi(x)^{\oplus k}$. We will denote this index $k$ by $\eta_{x}(i)$. In other words, $\eta_{x}(i)$ is the unique index at which we need to perform a bit-flip in $\varphi(x)$ to obtain $\varphi(x^{\oplus i})$. We first make the observation that flipping distinct bits in the input always affects distinct bits in the output, i.e., the function $\eta_x:[n]\to [N]$ is injective for all $x\in \{0, 1\}^n$.
    \begin{obs}
        \label{obs:different-direction-index}
        Let $i, j\in [n]$ such that $i\neq j$. Then for all $x\in \{0, 1\}^n$, we have $\eta_x(i) \neq \eta_x(j)$.
    \end{obs}
    \begin{proof}
     \renewcommand\qedsymbol{$\lrcorner$}
     Assume for the sake of contradiction that for some $x\in \{0, 1\}^n$, $\eta_x(i) = \eta_x(j)$. Then, we have, $2=\ham(x^{\oplus i}, x^{\oplus j}) = \ed(\varphi(x^{\oplus i}), \varphi(x^{\oplus j}))=\ed(\varphi(x)^{\oplus \eta_x(i)}, \varphi(x)^{\oplus \eta_x(j)}) = 0$, which is a contradiction. 
    \end{proof}
    The following observation is also almost immediate.
    \begin{obs}
        \label{obs:reflection-invariance}
        For every $i\in [n]$ and $x\in \{0, 1\}^n$, we have $\eta_x(i) = \eta_{x^{\oplus i}}(i)$.
    \end{obs}
    \begin{proof}
        \renewcommand\qedsymbol{$\lrcorner$}
        Assume for the sake of contradiction that $\alpha = \eta_x(i) \neq \eta_{x^{\oplus i}}(i) =\beta$ for some choice of $i\in [n]$ and $x\in \{0, 1\}^n$. Then we have ---
        \[\varphi(x) = \varphi\left(\left(x^{\oplus i}\right)^{\oplus i}\right) = \varphi\left(x^{\oplus i}\right)^{\oplus \beta}=\left(\varphi(x)^{\oplus \alpha}\right)^{\oplus \beta} \neq \varphi(x),\]
        which is a contradiction.
    \end{proof}
    The key insight in our proof is the observation that flipping the $i^{\textnormal{th}}$ bit of any input string for some fixed $i$ always affects the same bit in the output and is independent of the input string.
    \begin{lemma}
        \label{lemma:same-direction-index}
        Fix any $i\in [n]$ and $x\in \{0, 1\}^n$. Then for every $y\in \{0, 1\}^n$, we have $\eta_x(i) =\eta_y(i)$.
    \end{lemma}
    \begin{proof}
        \renewcommand{\qedsymbol}{$\lrcorner$}
        First, note that it suffices to prove the claim for all $y\in \{0, 1\}^n$ such that $y[i]=x[i]$ since by Observation~\ref{obs:reflection-invariance}, $\eta_y(i)=\eta_{y^{\oplus i}}(i)$ for every $y$. Therefore, in what follows, $y$ will always be a string such that $y[i]=x[i]$.

        Our proof is going to be by induction on the Hamming distance of $y$ from $x$. Clearly, the claim is true if $\ham(x, y)=0$. For the inductive hypothesis, assume that the claim is true for all $y\in \{0, 1\}^n$ such that $0\leq \ham(x, y) < d$. For the inductive step, let $y\in \{0, 1\}^n$ be a string such that $\ham(x, y)=d$. Then there exists $z\in \{0, 1\}^n$ such that $\ham(x, z)=d-1$ and $\ham(z, y)=1$. Indeed, we can choose $z$ to be the second-to-last vertex in any shortest path from $x$ to $y$ in the Boolean hypercube. By the inductive hypothesis, we have $\eta_x(i)=\eta_{z}(i)$. Therefore, it suffices to prove that $\eta_{z}(i)=\eta_y(i)$.

        \begin{figure}
            \centering
            \includegraphics[scale=1]{figures/cycle.pdf}
            \caption{A sequence of bit-flips that both starts and ends at $z$, and their corresponding effects on the image strings under $\varphi$. Any two consecutive arrows correspond to bit flips at distinct locations. Therefore, in order to cancel out all bit flips, non-consecutive arrows must correspond to bit flips at the same locations.}
            \label{fig:cycle}
        \end{figure}

        Assume otherwise. Since $x[i]=y[i]$ and $z$ is on a shortest path from $x$ to $y$, $z[i]=y[i]$. Then we must have $y=z^{\oplus j}$ for some $j\neq i$. Consider walking along the following cycle in the Boolean hypercube and observing the images of the encountered strings under $\varphi$ (see Figure~\ref{fig:cycle} for an illustration) ---
        \[z\xrightarrow{\phantom{aa} \oplus j\phantom{aaa}} y \xrightarrow{\phantom{aa} \oplus i \phantom{aaa}} y^{\oplus i} \xrightarrow{\phantom{aa} \oplus j \phantom{aaa}} z^{\oplus i} \xrightarrow{\phantom{aa} \oplus i \phantom{aaa}} z\]
        The images of these strings under $\varphi$ follow a corresponding cycle given by ---
        \begin{equation*}
            \varphi(z) \xrightarrow{\phantom{aa} \oplus \eta_z(j)\phantom{aaa}} \varphi(y) \xrightarrow{\phantom{aa} \oplus \eta_y(i) \phantom{aaa}} \varphi(y^{\oplus i})\xrightarrow{\phantom{aa} \oplus \eta_{y^{\oplus i}}(j) \phantom{aaa}} \varphi(z^{\oplus i}) \xrightarrow{\phantom{aa} \oplus \eta_{z^{\oplus i}}(i) \phantom{aaa}} \varphi(z),
        \end{equation*}
    and as a consequence, we have ---
    \begin{equation}
                \label{eq:cycle}
                \left(\left(\left(\left(\varphi(z)\right)^{\oplus \eta_z(j)}\right)^{\oplus \eta_y(i)}\right)^{\oplus \eta_{y^{\oplus i}}(j)}\right)^{\oplus\eta_{z^{\oplus i}}(i)}=\varphi(z).
    \end{equation}
    Furthermore, by a combination of Observations~\ref{obs:different-direction-index} and~\ref{obs:reflection-invariance}, we have $\eta_z(j)\neq \eta_y(i)$, $\eta_y(i)\neq \eta_{y^{\oplus i}}(j)$, and $\eta_{y^{\oplus i}}(j)\neq \eta_{z^{\oplus i}}(i)$. Therefore, if $\eta_z(i)\neq \eta_y(i)$, and consequently by Observation~\ref{obs:reflection-invariance}, $\eta_{z^{\oplus i}}(i) \neq \eta_y(i)$, then Equation~\ref{eq:cycle} cannot hold since there would be no way to cancel out all the bit-flips. Thus, we conclude that $\eta_z(i)=\eta_y(i)$. 
    \end{proof}

    Lemma~\ref{lemma:same-direction-index} tells us that the functions $\eta_x:[n]\to [N]$ are identical for all $x\in\{0, 1\}^n$. Therefore, we can drop the subscript and refer to this function as $\eta$. By Observation~\ref{obs:different-direction-index}, $\eta$ is injective. One way of interpreting Lemma~\ref{lemma:same-direction-index} is that regardless of the input string, as long as the location of the bit flip in the input is fixed, the location of the corresponding bit flip in the output is also fixed. We now argue something stronger --- regardless of the input string, as long as the location and \textit{direction}\footnote{There are two possible directions for a bit flip --- flipping a 0 to a 1, and flipping a 1 to a 0.} of the bit flip in the input is fixed, the location and direction of the corresponding bit flip in the output is also fixed.
    \begin{lemma}
        \label{lemma:location-and-direction}
        For all $x, y\in \{0, 1\}^n$ and $i\in [n]$, $\varphi(x)[\eta(i)]=\varphi(y)[\eta(i)]$ if and only if $x[i]=y[i]$. 
    \end{lemma}
    \begin{proof}
    \renewcommand{\qedsymbol}{$\lrcorner$}
        Consider any shortest sequence of bit flips that transforms $x$ into $y$. Such a sequence also specifies a unique sequence of bit flips transforming $\varphi(x)$ into $\varphi(y)$. If $x[i]=y[i]$, the $i^{\text{th}}$ bit of $x$ is never touched during the sequence. Since $\eta$ is injective, the $\eta(i)^{\text{th}}$ bit of $\varphi(x)$ is also never touched and $\varphi(x)[\eta(i)]=\varphi(y)[\eta(i)]$.

        Similarly, if $x[i]\neq y[i]$, any shortest sequence of bit flips transforming $x$ into $y$ must flip the $i^{\text{th}}$ bit exactly once. Since $\eta$ is injective, in the corresponding sequence transforming $\varphi(x)$ into $\varphi(y)$, the $\eta(i)^{\text{th}}$ bit is flipped exactly once. Therefore, $\varphi(x)[\eta(i)]\neq\varphi(y)[\eta(i)]$.  
    \end{proof}

    Now, for each $i\in[n]$, we define the function $\pi_i:\{0, 1\}\to \{0, 1\}$ as follows. Pick any arbitrary $x\in \{0, 1\}^n$. If $\varphi(x)[i]=x[i]$, we define $\pi_i(b):=b$ for all $b\in \{0, 1\}$. Otherwise, we define $\pi_i(b):= 1-b$ for all $b\in \{0, 1\}$. By Lemma~\ref{lemma:location-and-direction}, $\varphi(x)[\eta(i)]=\pi_i(x[i])$ for all $x\in \{0, 1\}^n$ and $i\in [n]$. The final piece of the proof is the following lemma.

    \begin{lemma}
        Let $S\subseteq[N]$ be the set of indices that are not in the image of $\eta$, i.e., $S=\{j\in [N]: \nexists i \textnormal{ with }\eta(i) =j\}$. Then for all $x, y\in \{0, 1\}^n$, we have $\varphi(x)_{|S}=\varphi(y)_{|S}$.
    \end{lemma}
    \begin{proof}
    \renewcommand{\qedsymbol}{$\lrcorner$}
        Assume for the sake of contradiction that there exist $x, y\in \{0, 1\}^n$ and $j\in S$ such that $\varphi(x)[j]\neq \varphi(y)[j]$. Consider any shortest sequence of bit flips transforming $x$ into $y$. Such a sequence also specifies a unique sequence of bit-flips transforming $\varphi(x)$ into $\varphi(y)$. This sequence only affects indices that are in the image of $\eta$. Since $j$ is not in the image of $\eta$, the $j^{\text{th}}$ bit of $\varphi(x)$ is never touched during this process. This means $\varphi(x)[j]=\varphi(y)[j]$, which is a contradiction.
    \end{proof}

    With this, we have now shown that $\varphi$ satisfies all the properties of an interleaved embedding and we are done.
\end{proof}

\subsection{Extending to Larger Alphabets}

\label{sec:isometry-implies-generalized-interleaved-embedding}

Even though Theorem~\ref{thm:isometry-implies-interleaving} is stated for embeddings of strings over the binary alphabet, a similar result holds true for larger alphabets as well. Let $\Sigma$ be any alphabet and consider any isometric embedding $\varphi:\Sigma^n\to \Sigma^N$ of the Hamming metric into the edit metric. We claim that even in this more general setting, $\varphi$ must, in some sense, be an interleaved embedding. 


To show this, we first need to define what it means for an embedding to be interleaved when working with a non-binary alphabet since Definition~\ref{def:interleaved-embedding} is specifically tailored to the binary case. However, finding the right generalization is not too difficult here. A closer look at Definition~\ref{def:interleaved-embedding} reveals that its dependence on the binary alphabet stems from the functions $\pi_i:\{0, 1\}\to \{0, 1\}$, where each $\pi_i$ either complements its input bit or leaves it unchanged. In the general setting, we simply require these functions to be \textit{permutations} of the alphabet, meaning that each $\pi_i:\Sigma\to\Sigma$ is a bijection that maps the alphabet onto itself.

\begin{defi}[Generalized Interleaved Embedding]
\label{def:generalized-interleaved-embedding}
    Let $\Sigma$ be an alphabet. A function $\varphi:\Sigma^n \to \Sigma^N$ with $N\geq n$ is called a {generalized interleaved embedding} if there exist ---
    \begin{itemize}
        \item an injective function $\eta : [n] \to [N]$,
        \item a collection of bijective functions $\pi_1, \pi_2, \ldots , \pi_n: \Sigma \to \Sigma$, and
        \item a fixed string $w\in \Sigma^{N-n}$,
    \end{itemize}
    such that for all $x\in\Sigma^n$, if $X=\varphi(x)$, then the following hold.
    \begin{itemize}
        \item For all $i\in [n]$, $X[\eta(i)]= \pi_i(x[i])$.
        \item Let $S\subseteq [N]$ be the set of indices that are not in the image of $\eta$, i.e., $S=\{j\in [N]: \nexists i \textnormal{ with } \eta(i) = j\}$. Then $X_{|S}=w$.
    \end{itemize}
\end{defi}

Note that Definition~\ref{def:generalized-interleaved-embedding} reduces to Definition~\ref{def:interleaved-embedding} in the case when $\Sigma=\{0, 1\}$. Therefore, from now on, when we refer to interleaved embeddings, we will mean functions defined in Definition~\ref{def:generalized-interleaved-embedding}.\footnote{In particular, we drop the word ``generalized''.} We are now ready to state the main result of this section in full generality.

\begin{theorem}
    \label{thm:isometry-implies-generalized-interleaving}
    Let $\Sigma$ be an alphabet and $\varphi:\Sigma^n\to \Sigma^N$ be an isometric embedding of the Hamming metric into the edit metric. Then $\varphi$ is an interleaved embedding.
\end{theorem}

The proof of Theorem~\ref{thm:isometry-implies-generalized-interleaving} is essentially the same as that of Theorem~\ref{thm:isometry-implies-interleaving}. The only difference is that we cannot argue using bit-flips anymore. However, this is not an issue. We now argue that as long as a single index is modified, regardless of \textit{how} it is changed, it always affects the same index at the output. 

More precisely, fix some $x\in \Sigma^n$, an index $i\in[n]$ and symbols $\sigma, \sigma'\in \Sigma$ different from $x[i]$. Let $y$ be the string obtained from $x$ by replacing the $i^{\text{th}}$ symbol by $\sigma$, and let $y'$ be the string obtained from $x$ by replacing the $i^{\text{th}}$ symbol by $\sigma'$. By a similar argument as in the binary case, there exists some $k\in [N]$ such that $\varphi(y)$ is obtained by changing the $k^{\text{th}}$ symbol of $\varphi(x)$. Similarly, there must also exist $k'\in[N]$ such that $\varphi(y')$ is obtained by changing the $k'^{\text{th}}$ symbol of $\varphi(x)$. Since $\ham(y, y')\leq 1$, if $k\neq k'$, then $\ed(\varphi(y), \varphi(y'))=2$, contradicting that $\varphi$ is isometric. Thus, we must have $k=k'$.

What this means is that as long as all other symbols remain fixed, any sequence of modifications to the $i^{\text{th}}$ symbol always affects the same index in $\varphi(x)$. The remainder of the proof would then proceed exactly as in Theorem~\ref{thm:isometry-implies-interleaving}.


\section{Upper Bounds on the Rate}
\label{sec:UpperBoundsOnTheRate}

In this section, we show that for every alphabet $\Sigma$, any isometric embedding $\varphi: \Sigma^n \to \Sigma^N$ of the Hamming metric into the edit metric must have rate bounded away from $\frac{1}{2}$, for sufficiently large $n$.

\begin{theorem}
    \label{thm:rate-upper-bound}
    For every alphabet $\Sigma$, there exists an integer $n_0$ such that every isometric embedding $\varphi: \Sigma^n \to \Sigma^N$ of the Hamming metric into the edit metric with $n\geq n_0$ must have rate at most $\frac{1}{2}-\frac{1}{16|\Sigma|}$. 
\end{theorem}
\begin{proof}
    Assume, for the sake of contradiction, that there exists an alphabet $\Sigma$ and an isometric embedding $\varphi:\Sigma^n \to \Sigma^N$ of the Hamming metric into the edit metric with rate equal to $\frac{1}{2}-\frac{1}{16|\Sigma|}+\rho$ for some constant $\rho >0$. We will show that this leads to a contradiction if $n$ is sufficiently large. In particular, we will show that for sufficiently large $n$, there exists a pair of strings $x^*, y^*\in \Sigma^n$ such that $\ed(\varphi(x^*), \varphi(y^*)) < \ham(x^*, y^*)$.

    In order to find such $x^*$ and $y^*$,  we will employ the probabilistic method. First, we will define a collection $\mathcal{C}$ of specially chosen triples $(x, y, \mathcal{A})$, where $x, y\in \Sigma^n$ and $\mathcal{A}$ is an edit distance alignment between $\varphi(x)$ and $\varphi(y)$. Then, we will pick a triple $(x, y, \mathcal{A})\in \mathcal{C}$ uniformly at random and show that the expected cost of $\mathcal{A}$ with respect to $\varphi(x)$ and $\varphi(y)$ is smaller than the minimum possible Hamming distance between $x$ and $y$. This will guarantee the existence of the desired $x^*$ and $y^*$. Details follow.

    Let $\Delta$ be a positive divisor of $N$ to be chosen later. The exact value of $\Delta$ will depend on $\rho$ but not $N$. Define $S_{\textnormal{shifts}} := \{-(\Delta-1), -(\Delta-2), \ldots , -1\}\cup \{1, 2, \ldots , (\Delta-1)\}$, and for any $\delta\in S_{\textnormal{shifts}}$, define $\mathcal{A}_\delta$ to be the following edit distance alignment between two length $N$ strings.
    \[\mathcal{A}_\delta := \{(i, i+\delta): \max\{1, 1-\delta\} \leq i\leq \min\{N-\delta, N\}\}\]
    In words, for any pair of length $N$ strings $X$ and $Y$, $\mathcal{A}_\delta$ aligns every symbol in $X$ to the $\delta^{\textnormal{th}}$ next symbol in $Y$. Now with each alignment $\mathcal{A}_\delta$ where $\delta \in S_{\textnormal{shifts}}$, we will associate a pair of strings $x_\delta, y_\delta \in \Sigma^n$. But before we describe $x_\delta$ and $y_\delta$, let us first recall some properties of interleaved embeddings. Since $\varphi$ is isometric, by Theorem~\ref{thm:isometry-implies-generalized-interleaving}, $\varphi$ is an interleaved embedding. Consequently, there exists $I_{\textnormal{frozen}}\subseteq [N]$ such that $\varphi(x)_{|I_{\textnormal{frozen}}}$ is the same string for all $x\in \Sigma^n$. Recalling Definition~\ref{def:generalized-interleaved-embedding}, $I_{\textnormal{frozen}}$ is simply the set of indices not in the image of $\eta$, the injective function associated with $\varphi$. Define $I_{\textnormal{mutable}} := [N]\setminus I_{\textnormal{frozen}}$. Note that for any $w\in \Sigma^{|I_{\textnormal{mutable}}|}$, we can always choose $x\in \Sigma^n$ such that $\varphi(x)_{|I_{\textnormal{mutable}}}$ is set to $w$. Furthermore, we can set each symbol independently since for all $i\in I_{\textnormal{mutable}}$ and $\sigma\in \Sigma$, there exist unique $j\in [n]$ and $\sigma'\in \Sigma$ such that $\varphi(x)[i] = \sigma$ if and only if $x[j]=\sigma'$. For every $x\in \Sigma^n$ and $i\in [N]$, let us call the symbol $\varphi(x)[i]$ \textit{mutable} if $i\in I_{\textnormal{mutable}}$ and \textit{frozen} otherwise.

    Given $\delta \in S_{\textnormal{shifts}}$, we choose a pair of strings $x_\delta, y_\delta\in \Sigma^n$ satisfying the following properties.
    \begin{itemize}
        \item $\ham(x_\delta, y_\delta) = n$,
        \item For each $i\in I_{\textnormal{mutable}}$ such that $i+\delta\in [N]$, we have $\varphi(x_\delta)[i] = \varphi(y_\delta)[i+\delta]$.
    \end{itemize}
    Essentially, what we want from $x_\delta$ and $y_\delta$ is that whenever some mutable symbol of $\varphi(x_\delta)$ is aligned with some (not necessarily mutable) symbol of $\varphi(y_\delta)$, then it should result in a match and not a substitution. We additionally want $x_\delta$ and $y_\delta$ to have the maximum possible Hamming distance. Note that such $x_\delta$ and $y_\delta$ can always be found. Specifically, for $\delta >0$, we can set $\varphi(x_\delta)[i]$ and $\varphi(y_\delta)[i]$ for $i\in I_{\textnormal{mutable}}$ in descending order of $i$.\footnote{Although we say we are setting \(\varphi(x_{\delta})[i]\) and \(\varphi(y_{\delta})[i]\), what we are actually setting are \(x_{\delta}[\eta^{-1}(i)]\) and \(y_{\delta}[\eta^{-1}(i)]\).} By doing so, every symbol in $\varphi(x_\delta)$ is aligned with some symbol (whether mutable or not) in $\varphi(y_\delta)$ that has already been set. During each iteration, we begin by setting $\varphi(x_\delta)[i]$ to match the symbol it is aligned with. Then we assign $\varphi(y_\delta)[i]$ a symbol different from $\varphi(x_\delta)[i]$, and move on to the next (smaller) value of $i$. This ensures that $x_\delta$ and $y_\delta$ meet the desired requirements. For $\delta<0$, we can follow a similar procedure but set $\varphi(x_\delta)[i]$ and $\varphi(y_\delta[i])$ in ascending order of $i$ instead. See Figure~\ref{fig:choosing-adversarial-strings} for an illustration of this process.

    \begin{figure}
        \centering
        \includegraphics[width=\linewidth]{figures/upperBounds.pdf}
        \caption{\(\eta\) is indicated by the matching colors. The red and purple symbols were set in previous iterations, and we now seek to set the green symbols. Specifically, we require the green symbol of \(\varphi(x_\delta)\) to be 0, while the green symbol of \(\varphi(y_\delta)\) must differ from that of \(\varphi(x_\delta)\). This can be achieved by appropriately setting the green symbols in \(x_\delta\) and \(y_\delta\).}
        \label{fig:choosing-adversarial-strings}
    \end{figure}

    We are now ready to describe the collection $\mathcal{C}$ alluded to earlier --- it consists of all triples of the form $(x_\delta, y_\delta, \mathcal{A}_\delta)$, where $\delta\in S_{\textnormal{shifts}}$. Let $\Tilde{\delta}$ be a uniformly random element of $S_{\textnormal{shifts}}$. The main step in the proof involves bounding the expected cost of $\mathcal{A}_{\Tilde{\delta}}$ with respect to $\varphi(x_{\Tilde{\delta}})$ and $\varphi(y_{\Tilde{\delta}})$.
    \begin{lemma}
        \label{lemma:expected-cost-bound}
        $\E\left[\cost_{\varphi(x_{\Tilde{\delta}})}^{\varphi(y_{\Tilde{\delta}})}\left(\mathcal{A}_{\Tilde{\delta}}\right)\right] < n$, for sufficiently large values of $n$.
    \end{lemma}
    \begin{proof}
        \renewcommand{\qedsymbol}{$\lrcorner$}
        For ease of notation, define $X := \varphi(x_{\Tilde{\delta}})$, $Y := \varphi(y_{\Tilde{\delta}})$, and $\mathcal{A} := \mathcal{A}_{\Tilde{\delta}}$. Furthermore, define $\varepsilon := \frac{1}{16|\Sigma|} -\rho$ so that the rate of $\varphi$ is $\frac{1}{2}-\varepsilon$. We will bound $\E[\cost_{X}^Y(\mathcal{A})]$ by individually bounding the expected number of insertions, deletions and substitutions. Bounding the first two is easy --- no matter what $\Tilde{\delta}$ is, the numbers of insertions or deletions are both always at most $(\Delta-1)$. For substitutions, note that for any $i\in I_{\textnormal{mutable}}$, $X[i]$ is by definition never substituted by $\mathcal{A}$ --- it is either matched or deleted. Therefore, in order to bound the expected number of substitutions, it suffices to only focus on the frozen symbols. Let us define an index $i\in I_{\textnormal{frozen}}$ to be \textit{good} if there exists $j\in I_{\textnormal{frozen}}$ such that $(i, j)\in \mathcal{A}$ and $X[i]=Y[j]$. Less formally, a good index is where a \textit{match} occurs between a pair of frozen symbols. Let $I_{\textnormal{good}}\subseteq I_{\textnormal{frozen}}$ be the set of all good indices. Clearly, the number of substitutions is upper bounded by $|I_{\textnormal{frozen}}|-|I_{\textnormal{good}}|$. Since $\varphi$ has rate $\frac{1}{2}-\varepsilon$, $|I_{\textnormal{frozen}}| = N\left(\frac{1}{2}+\varepsilon\right)$, and we have ---
        \[\E\left[\cost_X^Y(\mathcal{A})\right] \leq 2(\Delta -1) + N\left(\frac{1}{2}+\varepsilon\right)-\E\left[|I_{\textnormal{good}}|\right]\]
        Let $\mathbb{1}_{I_{\textnormal{good}}}:I_\textnormal{frozen}\to \{0, 1\}$ be the indicator function of $I_{\textnormal{good}}\subseteq I_\textnormal{frozen}$. By linearity of expectation, we have ---
        \[\E\left[|I_{\textnormal{good}}|\right] = \sum_{i\in I_\textnormal{frozen}}\mathbb{1}_{I_{\textnormal{good}}}(i)=\sum_{i\in I_\textnormal{frozen}}\Pr[i\in I_{\textnormal{good}}]\]
    So, we need to obtain a lower bound on the probability that an index is good. To do so, we partition $X$ and $Y$ into contiguous length-$\Delta$ substrings. For each $t\in [\frac{N}{\Delta}]$ and $\sigma\in \Sigma$, we define $c_{t, \sigma}$ to be the number of times symbol $\sigma$ appears as a frozen symbol in the $t^{\textnormal{th}}$ substring in this partition, i.e., 
    \[c_{t, \sigma} := \left|\{i\in [t(\Delta-1), t\Delta] : i\in I_\textnormal{frozen} \textnormal{ and } X[i]=Y[i]=\sigma\}\right|\]
    Next we make the following observation.
    \begin{obs}
        Let $i\in I_\textnormal{frozen}$ and let $t\in[\frac{N}{\Delta}]$ be such that $i\in [t(\Delta-1), t\Delta]$. Then we have ---
        \[\Pr[i\in I_{\textnormal{good}}] \geq \frac{1}{2}\cdot\frac{c_{t, X[i]}-1}{\Delta -1}\]
    \end{obs}
    \begin{proof}
        \renewcommand{\qedsymbol}{$\lrcorner$}
        We have ---
        \allowdisplaybreaks
        \begin{small}
        \begin{align*}
            \Pr[i\in I_{\textnormal{good}}] &\geq \Pr\left[\left(i+\Tilde{\delta}\in [t(\Delta-1), t\Delta] \right)\wedge \left(\left(i+\Tilde{\delta} \in I_\textnormal{frozen}\right) \wedge \left(X[i]=Y[i+\Tilde{\delta}]\right)\right)\right]\\
            &= \Pr\left[i+\Tilde{\delta}\in [t(\Delta-1), t\Delta]\right]\cdot \Pr\left[\left(i+\Tilde{\delta} \in I_\textnormal{frozen}\right) \wedge \left(X[i]=Y[i+\Tilde{\delta}]\right)\middle| i+\Tilde{\delta}\in [t(\Delta-1), t\Delta]\right]\\
            &= \frac{1}{2}\cdot\frac{c_{t, X[i]}-1}{\Delta -1}        \qedhere\\
        \end{align*}
                \end{small}
    \end{proof}
So, we can write ---
    \begin{equation}
    \label{ineq:rhs}
        \E\left[|I_{\textnormal{good}}|\right]\geq \frac{1}{2(\Delta-1)}\sum_{{t\in \left[\frac{N}{\Delta}\right]}}\sum_{{{\sigma\in \Sigma}}} c_{t, \sigma}(c_{t, \sigma}-1)
    \end{equation}
    The right hand side of~(\ref{ineq:rhs}) is minimized when $c_{t, \sigma}$'s are all the same and equal to $\frac{N(\frac{1}{2}+\varepsilon)}{\frac{N|\Sigma|}{\Delta}}=\frac{\Delta(\frac{1}{2}+\varepsilon)}{|\Sigma|}$. Furthermore, each $c_{t, \sigma}$ can be replaced with $\frac{\Delta}{2|\Sigma|}$ to obtain a value that is strictly smaller than the minimum value of the right hand side of (\ref{ineq:rhs}). Thus, we have ---
    \allowdisplaybreaks
    \begin{align*}
        \E\left[|I_{\textnormal{good}}|\right]&\geq \frac{1}{2(\Delta-1)}\sum_{{t\in \left[\frac{N}{\Delta}\right]}}\sum_{{{\sigma\in \Sigma}}} c_{t, \sigma}(c_{t, \sigma}-1)\\
        & > \frac{1}{2(\Delta -1)}\cdot\frac{N}{\Delta}\cdot|\Sigma|\cdot \frac{\Delta}{2|\Sigma|}\left(\frac{\Delta}{2|\Sigma|}-1\right)\\
        &\geq \frac{1}{2\Delta}\cdot \frac{N}{2}\left(\frac{\Delta}{2|\Sigma|}-1\right)\\
        & = N\left(\frac{1}{8|\Sigma|}-\frac{1}{4\Delta}\right),
    \end{align*}
    and thus, we have ---
    \[\E\left[\cost_X^Y(\mathcal{A})\right] < 2(\Delta -1) + N\left(\frac{1}{2}+\varepsilon\right)-N\left(\frac{1}{8|\Sigma|}-\frac{1}{4\Delta}\right)\]. Consequently, we have ---
    \begin{align*}\allowdisplaybreaks
        n-\E\left[\cost_X^Y(\mathcal{A})\right] & > n - 2(\Delta -1) + N\left(\frac{1}{2}+\varepsilon\right)-N\left(\frac{1}{8|\Sigma|}-\frac{1}{4\Delta}\right)\\
        &= N\left(\frac{1}{2}-\varepsilon\right) - 2(\Delta -1) + N\left(\frac{1}{2}+\varepsilon\right)-N\left(\frac{1}{8|\Sigma|}-\frac{1}{4\Delta}\right)\\
        &= N\left(-2\varepsilon + \frac{1}{8|\Sigma|}-\frac{1}{4\Delta}\right) + 2(\Delta -1)
    \end{align*}
    Now recall that we had $\varepsilon=\frac{1}{16|\Sigma|}-\rho$. Thus, if we choose $\Delta$ to be large enough such that $\frac{1}{8\Delta}<\rho$, we will have $\varepsilon < \frac{1}{16|\Sigma|}-\frac{1}{8\Delta}$ and,
    \begin{equation}
    \label{eq:cost-diff}
        n - \E\left[\cost_X^Y(\mathcal{A})\right] > \alpha N+2(\Delta-1),
    \end{equation}
    where $\alpha := -2\varepsilon + \frac{1}{8|\Sigma|}-\frac{1}{4\Delta} > 0$. Finally, we note that by making $n$ and, consequently, $N$ sufficiently large, one can make the right-hand side of (\ref{eq:cost-diff}) positive. The conclusion then follows.
    \end{proof}

    Lemma~\ref{lemma:expected-cost-bound} guarantees the existence of a triple $(x_\delta, y_\delta, \mathcal{A}_\delta)\in \mathcal{C}$ such that $\cost_{\varphi(x_\delta)}^{\varphi(y_\delta)}(\mathcal{A}_\delta) < \ham(x_\delta, y_\delta)$. However, this contradicts the assumption that $\varphi$ is an isometric embedding of the Hamming metric into the edit metric.
\end{proof}

We can further use Theorem~\ref{thm:rate-upper-bound} to immediately get an upper bound on the rate on any \(1\)-embedding.

\begin{theorem}
\label{thm:general-rate-upper-bound-non-isometric}
For every alphabet $\Sigma$, there exists an integer $n_0$ such that every $1$-embedding $\varphi: \Sigma^n \to \Sigma^N$ of the Hamming metric into the edit metric with $n\geq n_0$ must have rate at most $\frac{1}{2}$.
\end{theorem}

\begin{proof}

\begin{sloppypar}
If $\varphi$ is an isometric embedding than Theorem~\ref{thm:rate-upper-bound} implies a rate strictly less than $\frac{1}{2}$. It remains to prove the statement for the case where $\varphi$ is a non-isometric $1$-embedding with $\ed~(\varphi(x),~\varphi(y))=K~\cdot~\ham(x, y) $, for all $x,  y \in \{0, 1\}^n$ for some $K$ not equal to $1$. For two strings $x',y'$ with Hamming distance $1$ we have that $\ed~(\varphi(x'),~\varphi(y'))=K$ and therefore $K$ must be a positive integer and therefore at least two. The rate $n/N$ of $\varphi$ is furthermore at most $1/K$ because for any two strings $x'',y''$ of maximal Hamming distance $n$ it holds that $N \geq \ed~(\varphi(x''),~\varphi(y'')) = K \cdot n$. This shows that the rate of $\varphi$ is at most $\frac{1}{2}$. 

\end{sloppypar}
\end{proof}

\section{Breaking the Rate Barrier via Larger Output Alphabets}

\label{sec:close-to-1}

Up to this point, we have only considered embeddings where the input and output alphabets have the same size. Theorem~\ref{thm:rate-upper-bound} tells us that in this setting, the rate is necessarily bounded away from $\frac{1}{2}$. While this is the most natural setting, one can also consider embeddings with \textit{different-sized} input and output alphabets. It turns out that by expanding the output alphabet, it is possible to find isometric embeddings with rates \textit{arbitrarily close to 1}! However, before explaining how this is done, we must first refine the definition of rate for such embeddings. In the case where the input and output alphabets are of equal size, the rate is defined as the ratio of the input string’s length to the output string’s length. When using a larger output alphabet, the appropriate measure to consider instead is not length but the \textit{number of bits}. 

\begin{defi}
\label{def:rate}
    The rate of any map $\varphi:\Sigma_{\textnormal{in}}\to \Sigma_{\textnormal{out}}$ is the ratio $\frac{n\log|\sigmain|}{N\log|\sigmaout|}$.
\end{defi}

Recall the naive embedding from Section~\ref{sec:sync-proof-overview}, which inserts a new symbol after each input bit. For that embedding, we have $N=2n$, $\Sigma_{\text{in}} = \{0, 1\}$, and $\Sigma_{\text{out}} = \{0, 1, \dots, n+1\}$. Thus, even though $\frac{n}{N}$ is as large as $\frac{1}{2}$, the rate, as defined in Definition~\ref{def:rate}, is actually only $\Theta(\frac{1}{\log n})$. 


We are now ready to state the main result of this section.
\begin{theorem}
\label{thm:rate-close-to-1}
    For every $\rho>0$, there exist alphabets $\sigmain$, $\sigmaout$ and a family of functions $\varphi_n:\sigmain^n\to \sigmaout^{N}$ for each positive integer $n$ such that the following hold.
    \begin{enumerate}
        \item For every $n$, $\varphi_n$ is an isometric embedding of the Hamming metric into the edit metric, i.e., for all $x, y\in \sigmain^n$, we have $\ed(\varphi_n(x), \varphi_n(y))=\ham(x, y)$.
        \item The rate of $\varphi_n$ is at least $(1-\rho)$.
    \end{enumerate}
\end{theorem}

\noindent Before we prove Theorem~\ref{thm:rate-close-to-1}, we first make the following observation about locally self-matching strings.

\begin{obs}
\label{obs:lcs-implies-edit}
    Let $w$ be an $\varepsilon$-locally self matching string. Then for every substring $s$ of $w$, we have:
    \[\selfed(s, s) \geq (1-\varepsilon)|s|\]
\end{obs}
\begin{proof}
    Let $\mathcal{A}$ be an optimal nowhere-vertical edit distance alignment between $s$ and itself. We have:
    \[\selfed(s, s) =\cost_s^s(\mathcal{A})\geq|S_s^s(\mathcal{A})|+|D_s^s(\mathcal{A})|\geq |s|-\slcs(s, s)\geq (1-\varepsilon)|s|\qedhere\]
\end{proof}


\begin{proof}[Proof of Theorem~\ref{thm:rate-close-to-1}]
Fix any $\rho>0$. 
% We can only focus on the case when $\rho < \frac{7}{8}$ since if $\rho \geq \frac{7}{8}$, then by Theorem~\ref{thm:rate-1/8}, we already have a rate $\frac{1}{8}$ isometric embedding of the Hamming metric into the edit metric. So, assume that $\rho<\frac{7}{8}$. 
Define $m:=\left\lceil\frac{C(1-\rho)+1}{\rho}\right\rceil$, where $C\geq 1$ is a constant to be chosen later. Furthermore, let $\varepsilon :=\frac{1}{m}$ and $\varepsilon' = \frac{\varepsilon}{2}$. We will choose $\sigmain=\left[2^{\frac{1}{\varepsilon}\log(\frac{1}{\varepsilon})}\right]$ as our input alphabet. For our output alphabet, we choose $\sigmaout = \sigmain\times \Sigma'$, where $\Sigma':=\left[\frac{5e^2}{\varepsilon'^2}\right]$.

Fix any positive integer $n$ and define $N:= n+\left\lfloor\frac{n}{m-1}\right\rfloor$. Our embedding map $\varphi_n:\sigmain^n\to \sigmaout^N$ is defined as follows. First, we fix some $\varepsilon'$-locally self-matching string $w$ of length $N$ over the alphabet $\Sigma'$. Since $\varepsilon' \leq \frac{1}{2}$, by Theorem~\ref{thm:lll-string}, such a string $w$ always exists. We also fix some arbitrary symbol $\sigma\in \sigmain$. Next, given any $x\in \sigmain^n$, we construct $x_{\textnormal{padded}}\in \sigmain^N$ by inserting the symbol $\sigma$ after every $(m-1)$ symbols in $x$. Finally, we define $\varphi_n(x)\in \sigmaout^N$ to be the \textit{product} of the strings $x_{\textnormal{padded}}$ and $w$. In other words, we define:
\[\varphi_n(x):= (x_{\textnormal{padded}}[1], w[1])\circ (x_{\textnormal{padded}}[2], w[2])\circ \cdots \circ (x_{\textnormal{padded}}[N],w[N])\]
We first claim that if $C$ is appropriately chosen, then $\varphi_n$ indeed has rate at least $1-\rho$.
\begin{claim}
    If $C\geq 10$, then the rate of $\varphi_n$ is at least $1-\rho$.
\end{claim}
\begin{proof}
    \renewcommand{\qedsymbol}{$\lrcorner$}
    First note that $N=n+\left\lfloor\frac{n}{m-1}\right\rfloor \leq \frac{nm}{m-1}=\frac{n}{1-\varepsilon}$. Therefore, $\frac{n}{N}\geq 1-\varepsilon$. Furthermore, since $C\geq 1$ and $\rho<1$, $m=\left\lceil\frac{C(1-\rho)+1)}{\rho}\right\rceil \geq 2$. Consequently, $\varepsilon\leq \frac{1}{2}$ and we have $\log|\Sigma'|= \log\left(\frac{5e^2}{\varepsilon'^2}\right)=\log(20e^2)+2\log\left(\frac{1}{\varepsilon}\right) \leq C\log\left(\frac{1}{\varepsilon}\right)$ for all $\varepsilon\leq \frac{1}{2}$ if $C\geq 10$. Therefore, the rate of $\varphi_n$ is:
    \allowdisplaybreaks
    \begin{align*}
        \frac{n\log|\sigmain|}{N\log|\sigmaout|}&=\frac{n}{N}\cdot\frac{\log|\sigmain|}{\log|\sigmain|+\log|\Sigma'|}\\
        &\geq(1-\varepsilon)\cdot\frac{\log\left(2^{\frac{1}{\varepsilon}\log\left(\frac{1}{\varepsilon}\right)}\right)}{\log\left(2^{\frac{1}{\varepsilon}\log\left(\frac{1}{\varepsilon}\right)}\right)+C\log\left(\frac{1}{\varepsilon}\right)}\\
        &=(1-\varepsilon)\cdot \frac{\frac{1}{\varepsilon}\log\left(\frac{1}{\varepsilon}\right)}{\frac{1}{\varepsilon}\log\left(\frac{1}{\varepsilon}\right)+C\log\left(\frac{1}{\varepsilon}\right)}\\
        &=\frac{1-\varepsilon}{1+C\varepsilon}\\
        &=1-\frac{(C+1)\varepsilon}{1+C\varepsilon}\\
    \end{align*}
    Now recall that $\varepsilon\leq \frac{\rho}{C(1-\rho)+1}$, and so, $\rho \geq \frac{(C+1)\varepsilon}{1+C\varepsilon}$. The conclusion then follows.
\end{proof}
Next, we show that $\varphi_n$ is indeed isometric for every positive integer $n$. Suppose not; then there exists a positive integer $n$ and $x, y\in \sigmain^n$ such that $\ed(\varphi_n(x), \varphi_n(y))<\ham(x, y)$. Let $X:= \varphi_n(x)$, $Y:=\varphi_n(y)$, and $\mathcal{A}$ be any optimal edit distance alignment between $X$ and $Y$. Since $\ham(x, y)=\ham(X, Y)$, by assumption, we have $\cost(\mathcal{A}) <\ham(X, Y)$. Similar to the proof of Theorem~\ref{thm:main}, consider the partition of $[N]$ into alternating maximal vertical and maximal nowhere-vertical intervals under $\mathcal{A}$. By the same argument as in the proof of Theorem~\ref{thm:main}, there must exist a nowhere vertical interval $I$ in this partition such that $\cost(\mathcal{A}_{|I})<\ham(X_{|I}, Y_{|I})$. We first note 
 that $|I|\geq \frac{2}{\varepsilon}$. Suppose not. Then since $w$ is a $\frac{\varepsilon}{2}$-locally self-matching string, our construction forces $w_{|I}$ to have all distinct symbols. In this case, we have:
 \[\cost(\mathcal{A}_{|I})\geq \selfed(X_{|I}, Y_{|I}) \geq \selfed(w_{|I}, w_{|I}) = |I|+2 > \ham(X_{|I}, Y_{|I}).\]
 Therefore, we may assume that $|I|\geq \frac{2}{\varepsilon}$. But for any $|I|\geq \frac{2}{\varepsilon}$, we have $(1-\frac{\varepsilon}{2})|I| \geq (1-\varepsilon)|I|+1$. And since in $X$ and $Y$, every $(\frac{1}{\varepsilon})^{\text{th}}$ symbol is the same, $(1-\varepsilon)|I|+1 $ is an upper bound on $\ham(X_{|I}, Y_{|I})$.  Combining all this, we have:
 \[\cost(\mathcal{A}_{|I})\geq \selfed(X_{|I}, Y_{|I}) \geq \selfed(w_{|I}, w_{|I}) \geq \left(1-\frac{\varepsilon}{2}\right)|I| \geq  (1-\varepsilon)|I|+1 \geq \ham(X_{|I}, Y_{|I}),\]
 which is a contradiction.
\end{proof}


